# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 4 - Population Context and Control-Assurance Characterization
#
# Purpose:
#   Explain what is inside each Level-1 visibility population using the
#   already-certified IP-006 Control Assurance products.
#
# This cell DOES NOT create final healthy/unhealthy classifications.
#
# It answers:
#   1. What kinds of assets are in each population?
#   2. What network / operational / management context exists?
#   3. Which controls are actually applicable?
#   4. Which populations are already predominantly healthy?
#   5. Which populations contain adverse, identity, lifecycle, or
#      applicability conditions requiring deeper explanation?
#
# Safety:
#   - READ ONLY
#   - No Delta writes
#   - No source re-ingestion
#   - No new findings
#   - No assurance cases created
#   - No routing changes
#   - No classifications changed
# ============================================================================

from pyspark.sql import functions as F


# ---------------------------------------------------------------------------
# 1. Require prior diagnostic state
# ---------------------------------------------------------------------------

required_objects = [
    "asset_visibility_with_population_df",
    "visibility_population_summary_df",
    "TOTAL_ASSETS",
    "RCAIP_POST_SLUG",
    "RCAIP_RUN_ID",
    "get_rcaip_table",
]

missing_objects = [
    object_name
    for object_name in required_objects
    if object_name not in globals()
]

if missing_objects:
    raise RuntimeError(
        "Run Cells 1 through 3 first. Missing: "
        + " | ".join(missing_objects)
    )


# ---------------------------------------------------------------------------
# 2. Resolve certified IP-006 Control Assurance products
# ---------------------------------------------------------------------------

CONTROL_FEATURE_TABLE = get_rcaip_table(
    "IP006_CONTROL_ASSURANCE_FEATURE"
)

CONTROL_EVALUATION_TABLE = get_rcaip_table(
    "IP006_CONTROL_ASSURANCE_EVALUATION"
)


print("=" * 120)
print("RCAIP DIAG 001 - POPULATION CONTEXT / CONTROL ASSURANCE")
print("=" * 120)

print("Post:", RCAIP_POST_NAME)
print("Run ID:", RCAIP_RUN_ID)

print()
print(
    "Control Assurance Feature:",
    CONTROL_FEATURE_TABLE
)

print(
    "Control Assurance Evaluation:",
    CONTROL_EVALUATION_TABLE
)


# ---------------------------------------------------------------------------
# 3. Current Post/run helper
# ---------------------------------------------------------------------------

def diag_current_run(
    table_name
):

    df = spark.table(
        table_name
    )

    required_scope = {
        "post_slug",
        "rcaip_run_id",
        "asset_key",
    }

    missing_scope = (
        required_scope
        -
        set(
            df.columns
        )
    )

    if missing_scope:
        raise RuntimeError(
            table_name
            + " missing required scope fields: "
            + " | ".join(
                sorted(
                    missing_scope
                )
            )
        )

    return (
        df
        .filter(
            (
                F.lower(
                    F.trim(
                        F.col(
                            "post_slug"
                        )
                    )
                )
                ==
                F.lit(
                    str(
                        RCAIP_POST_SLUG
                    ).lower()
                )
            )
            &
            (
                F.col(
                    "rcaip_run_id"
                )
                ==
                F.lit(
                    RCAIP_RUN_ID
                )
            )
        )
    )


control_feature_df = diag_current_run(
    CONTROL_FEATURE_TABLE
)

control_evaluation_df = diag_current_run(
    CONTROL_EVALUATION_TABLE
)


# ---------------------------------------------------------------------------
# 4. Validate required Control Assurance fields
# ---------------------------------------------------------------------------

required_feature_fields = [
    "asset_key",
    "device_scope",
    "network_scope",
    "operational_boundary",
    "operational_boundary_confidence",
    "post_visibility_state",
    "printer_signature",
    "infrastructure_signature",
    "active_unresolved_ip_candidate",
    "active_unresolved_ip_observation_class",
    "overall_assurance_state",
    "overall_review_priority",
    "primary_routing_scope",
    "applicable_control_count",
    "applicability_review_count",
    "healthy_control_count",
    "missing_control_count",
    "not_reporting_control_count",
    "stale_reporting_control_count",
    "misconfigured_control_count",
    "noncompliant_control_count",
    "configuration_unknown_count",
    "source_unavailable_count",
    "identity_reconciliation_count",
    "evidence_only_relationship_count",
    "adverse_relationship_count",
]

required_evaluation_fields = [
    "asset_key",
    "tool_name",
    "control_role",
    "applicability_state",
    "presence_state",
    "reporting_state",
    "configuration_state",
    "assurance_state",
    "review_priority",
    "routing_scope",
]


missing_feature_fields = [
    column_name
    for column_name in required_feature_fields
    if column_name not in control_feature_df.columns
]

missing_evaluation_fields = [
    column_name
    for column_name in required_evaluation_fields
    if column_name not in control_evaluation_df.columns
]


if missing_feature_fields:
    raise RuntimeError(
        "Control Assurance Feature missing fields: "
        + " | ".join(
            missing_feature_fields
        )
    )

if missing_evaluation_fields:
    raise RuntimeError(
        "Control Assurance Evaluation missing fields: "
        + " | ".join(
            missing_evaluation_fields
        )
    )


# ---------------------------------------------------------------------------
# 5. Certify IP-006 grain
# ---------------------------------------------------------------------------

control_feature_rows = (
    control_feature_df.count()
)

control_feature_assets = (
    control_feature_df
    .select(
        "asset_key"
    )
    .distinct()
    .count()
)

control_evaluation_rows = (
    control_evaluation_df.count()
)

control_evaluation_assets = (
    control_evaluation_df
    .select(
        "asset_key"
    )
    .distinct()
    .count()
)

expected_evaluation_rows = (
    TOTAL_ASSETS
    *
    5
)


if control_feature_rows != TOTAL_ASSETS:
    raise RuntimeError(
        "Control Assurance Feature does not reconcile "
        "to the certified Asset Plane."
    )

if control_feature_assets != TOTAL_ASSETS:
    raise RuntimeError(
        "Control Assurance Feature asset-key grain mismatch."
    )

if control_evaluation_rows != expected_evaluation_rows:
    raise RuntimeError(
        "Control Assurance Evaluation does not equal "
        "Asset Plane x five tools."
    )

if control_evaluation_assets != TOTAL_ASSETS:
    raise RuntimeError(
        "Control Assurance Evaluation does not cover "
        "the complete Asset Plane."
    )


tool_coverage_df = (
    control_evaluation_df

    .groupBy(
        "tool_name"
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        )
    )

    .orderBy(
        "tool_name"
    )
)


invalid_tool_coverage_count = (
    tool_coverage_df

    .filter(
        F.col(
            "asset_count"
        )
        !=
        F.lit(
            TOTAL_ASSETS
        )
    )

    .count()
)


if invalid_tool_coverage_count != 0:
    raise RuntimeError(
        "One or more Control Assurance tools do not cover "
        "the complete certified Asset Plane."
    )


# ---------------------------------------------------------------------------
# 6. Population bridge
# ---------------------------------------------------------------------------

population_bridge_df = (
    asset_visibility_with_population_df

    .select(
        "asset_key",
        "population_id",
        "visibility_relationship_pattern",
        "current_observation_status",
        "lifecycle_reconciliation_status",
        "management_model",
        "management_owner",
        "identity_strength",
        "attribution_confidence",
        "attribution_conflict_flag",
        "is_ip_only_identity",
    )

    .distinct()
)


population_rank_df = (
    visibility_population_summary_df

    .select(
        "population_id",
        "population_rank",
    )
)


# ---------------------------------------------------------------------------
# 7. Select the Control Assurance context we need
# ---------------------------------------------------------------------------

control_context_df = (
    control_feature_df

    .select(
        "asset_key",
        "device_scope",
        "network_scope",
        "operational_boundary",
        "operational_boundary_confidence",
        "post_visibility_state",
        "printer_signature",
        "infrastructure_signature",
        "active_unresolved_ip_candidate",
        "active_unresolved_ip_observation_class",
        "overall_assurance_state",
        "overall_review_priority",
        "primary_routing_scope",
        "applicable_control_count",
        "applicability_review_count",
        "healthy_control_count",
        "missing_control_count",
        "not_reporting_control_count",
        "stale_reporting_control_count",
        "misconfigured_control_count",
        "noncompliant_control_count",
        "configuration_unknown_count",
        "source_unavailable_count",
        "identity_reconciliation_count",
        "evidence_only_relationship_count",
        "adverse_relationship_count",
    )
)


population_asset_context_df = (
    population_bridge_df

    .join(
        control_context_df,
        on="asset_key",
        how="inner"
    )

    .join(
        population_rank_df,
        on="population_id",
        how="left"
    )
)


# ---------------------------------------------------------------------------
# 8. Helper for boolean-like evidence
# ---------------------------------------------------------------------------

def truthy(
    column_name
):

    return (
        F.upper(
            F.trim(
                F.coalesce(
                    F.col(
                        column_name
                    ).cast(
                        "string"
                    ),
                    F.lit(
                        ""
                    )
                )
            )
        )
        .isin(
            "TRUE",
            "1",
            "Y",
            "YES"
        )
    )


# ---------------------------------------------------------------------------
# 9. One-row-per-population characterization
# ---------------------------------------------------------------------------

population_characterization_df = (
    population_asset_context_df

    .groupBy(
        "population_id",
        "population_rank",
        "visibility_relationship_pattern",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "current_observation_status"
                ).startswith(
                    "Active"
                ),
                1
            ).otherwise(
                0
            )
        ).alias(
            "currently_observed_asset_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "current_observation_status"
                )
                ==
                F.lit(
                    "Stale Historical Records Only"
                ),
                1
            ).otherwise(
                0
            )
        ).alias(
            "stale_only_asset_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "current_observation_status"
                )
                ==
                F.lit(
                    "No Current Evidence"
                ),
                1
            ).otherwise(
                0
            )
        ).alias(
            "no_current_evidence_asset_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "overall_assurance_state"
                )
                ==
                F.lit(
                    "HEALTHY"
                ),
                1
            ).otherwise(
                0
            )
        ).alias(
            "ip006_healthy_profile_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "overall_review_priority"
                )
                ==
                F.lit(
                    "HIGH"
                ),
                1
            ).otherwise(
                0
            )
        ).alias(
            "ip006_high_review_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "overall_review_priority"
                )
                ==
                F.lit(
                    "MEDIUM"
                ),
                1
            ).otherwise(
                0
            )
        ).alias(
            "ip006_medium_review_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "missing_control_count"
                )
                >
                0,
                1
            ).otherwise(
                0
            )
        ).alias(
            "assets_with_missing_control_state"
        ),

        F.sum(
            F.when(
                F.col(
                    "not_reporting_control_count"
                )
                >
                0,
                1
            ).otherwise(
                0
            )
        ).alias(
            "assets_with_not_reporting_state"
        ),

        F.sum(
            F.when(
                F.col(
                    "noncompliant_control_count"
                )
                >
                0,
                1
            ).otherwise(
                0
            )
        ).alias(
            "assets_with_noncompliant_state"
        ),

        F.sum(
            F.when(
                F.col(
                    "misconfigured_control_count"
                )
                >
                0,
                1
            ).otherwise(
                0
            )
        ).alias(
            "assets_with_misconfigured_state"
        ),

        F.sum(
            F.when(
                F.col(
                    "applicability_review_count"
                )
                >
                0,
                1
            ).otherwise(
                0
            )
        ).alias(
            "assets_needing_applicability_review"
        ),

        F.sum(
            F.when(
                F.col(
                    "identity_reconciliation_count"
                )
                >
                0,
                1
            ).otherwise(
                0
            )
        ).alias(
            "assets_needing_identity_reconciliation"
        ),

        F.sum(
            F.when(
                F.col(
                    "source_unavailable_count"
                )
                >
                0,
                1
            ).otherwise(
                0
            )
        ).alias(
            "assets_with_source_dependency"
        ),

        F.sum(
            F.when(
                truthy(
                    "active_unresolved_ip_candidate"
                ),
                1
            ).otherwise(
                0
            )
        ).alias(
            "active_unresolved_ip_count"
        ),

        F.sum(
            F.when(
                truthy(
                    "printer_signature"
                ),
                1
            ).otherwise(
                0
            )
        ).alias(
            "printer_signature_count"
        ),

        F.sum(
            F.when(
                truthy(
                    "infrastructure_signature"
                ),
                1
            ).otherwise(
                0
            )
        ).alias(
            "infrastructure_signature_count"
        ),

        F.sum(
            F.when(
                truthy(
                    "is_ip_only_identity"
                ),
                1
            ).otherwise(
                0
            )
        ).alias(
            "ip_only_identity_count"
        ),

        F.sum(
            F.when(
                truthy(
                    "attribution_conflict_flag"
                ),
                1
            ).otherwise(
                0
            )
        ).alias(
            "attribution_conflict_count"
        ),

        F.countDistinct(
            "device_scope"
        ).alias(
            "distinct_device_scopes"
        ),

        F.countDistinct(
            "network_scope"
        ).alias(
            "distinct_network_scopes"
        ),

        F.countDistinct(
            "operational_boundary"
        ).alias(
            "distinct_operational_boundaries"
        ),

        F.countDistinct(
            "management_model"
        ).alias(
            "distinct_management_models"
        ),

        F.concat_ws(
            " | ",
            F.sort_array(
                F.collect_set(
                    "device_scope"
                )
            )
        ).alias(
            "device_scopes"
        ),

        F.concat_ws(
            " | ",
            F.sort_array(
                F.collect_set(
                    "network_scope"
                )
            )
        ).alias(
            "network_scopes"
        ),

        F.concat_ws(
            " | ",
            F.sort_array(
                F.collect_set(
                    "management_model"
                )
            )
        ).alias(
            "management_models"
        ),

        F.concat_ws(
            " | ",
            F.sort_array(
                F.collect_set(
                    "overall_assurance_state"
                )
            )
        ).alias(
            "ip006_assurance_states"
        ),
    )

    .withColumn(
        "percent_of_asset_plane",
        F.round(
            (
                F.col(
                    "asset_count"
                )
                /
                F.lit(
                    TOTAL_ASSETS
                )
            )
            *
            100.0,
            2
        )
    )

    .orderBy(
        "population_rank"
    )
)


print()
print("=" * 120)
print("POPULATION CHARACTERIZATION")
print("=" * 120)
print(
    "One row per Level-1 visibility population."
)
print(
    "IP-006 health/review counts are diagnostic evidence, "
    "not the final RCAIP population decision."
)
print()

display(
    population_characterization_df
)


# ---------------------------------------------------------------------------
# 10. Context decomposition
#
# Shows what each visibility population actually contains.
# ---------------------------------------------------------------------------

population_context_detail_df = (
    population_asset_context_df

    .groupBy(
        "population_id",
        "population_rank",
        "visibility_relationship_pattern",
        "device_scope",
        "network_scope",
        "operational_boundary",
        "management_model",
        "management_owner",
        "overall_assurance_state",
        "overall_review_priority",
        "primary_routing_scope",
        "active_unresolved_ip_observation_class",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        )
    )

    .withColumn(
        "percent_of_asset_plane",
        F.round(
            (
                F.col(
                    "asset_count"
                )
                /
                F.lit(
                    TOTAL_ASSETS
                )
            )
            *
            100.0,
            2
        )
    )

    .orderBy(
        "population_rank",
        F.desc(
            "asset_count"
        ),
        "device_scope",
        "network_scope",
    )
)


print()
print("=" * 120)
print("POPULATION CONTEXT DECOMPOSITION")
print("=" * 120)
print(
    "This identifies the device/network/ownership/assurance "
    "subgroups inside each visibility population."
)
print()

display(
    population_context_detail_df
)


# ---------------------------------------------------------------------------
# 11. Per-population control relationship decomposition
#
# This lets us distinguish:
#
#   missing expected control
#   non-applicable control
#   applicability still unresolved
#   healthy control
#   stale reporting
#   enterprise source dependency
#   corroborating evidence only
#
# without treating source absence itself as a finding.
# ---------------------------------------------------------------------------

evaluation_population_bridge_df = (
    population_bridge_df

    .select(
        "asset_key",
        "population_id",
        "visibility_relationship_pattern",
    )
)


population_control_assurance_df = (
    control_evaluation_df

    .join(
        evaluation_population_bridge_df,
        on="asset_key",
        how="inner"
    )

    .join(
        population_rank_df,
        on="population_id",
        how="left"
    )

    .groupBy(
        "population_id",
        "population_rank",
        "visibility_relationship_pattern",
        "tool_name",
        "control_role",
        "applicability_state",
        "assurance_state",
        "review_priority",
        "routing_scope",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        )
    )

    .withColumn(
        "percent_of_population",
        F.round(
            (
                F.col(
                    "asset_count"
                )
                /
                F.sum(
                    "asset_count"
                ).over(
                    Window.partitionBy(
                        "population_id",
                        "tool_name"
                    )
                )
            )
            *
            100.0,
            2
        )
    )

    .orderBy(
        "population_rank",
        "tool_name",
        F.desc(
            "asset_count"
        ),
        "assurance_state",
    )
)


print()
print("=" * 120)
print("POPULATION CONTROL ASSURANCE")
print("=" * 120)
print(
    "This is the key applicability/control view: "
    "one aggregated row per population/tool/state."
)
print()

display(
    population_control_assurance_df
)


# ---------------------------------------------------------------------------
# 12. Certification
# ---------------------------------------------------------------------------

characterization_asset_total = (
    population_characterization_df

    .agg(
        F.sum(
            "asset_count"
        ).alias(
            "asset_count"
        )
    )

    .first()[
        "asset_count"
    ]
)


null_population_feature_count = (
    population_asset_context_df

    .filter(
        F.col(
            "population_id"
        ).isNull()
    )

    .count()
)


evaluation_with_population_count = (
    control_evaluation_df

    .join(
        evaluation_population_bridge_df,
        on="asset_key",
        how="inner"
    )

    .count()
)


if int(
    characterization_asset_total
) != TOTAL_ASSETS:

    raise RuntimeError(
        "Population characterization does not reconcile "
        "to the certified Asset Plane."
    )


if null_population_feature_count != 0:

    raise RuntimeError(
        "Control Assurance assets exist without "
        "diagnostic population assignment."
    )


if evaluation_with_population_count != expected_evaluation_rows:

    raise RuntimeError(
        "Population-to-control relationship join "
        "did not preserve all five-tool relationships."
    )


print()
print("=" * 120)
print("RCAIP DIAG 001 - CELL 4 CERTIFICATION")
print("=" * 120)

print("Status: PASS")
print("Post:", RCAIP_POST_NAME)
print("Run ID:", RCAIP_RUN_ID)

print(
    "Certified Asset Plane identities:",
    TOTAL_ASSETS
)

print(
    "Control Assurance Feature rows:",
    control_feature_rows
)

print(
    "Control Assurance Evaluation rows:",
    control_evaluation_rows
)

print(
    "Expected five-tool relationships:",
    expected_evaluation_rows
)

print(
    "Population characterization asset total:",
    int(
        characterization_asset_total
    )
)

print(
    "Control relationships retaining population ID:",
    evaluation_with_population_count
)

print(
    "Control assets without population ID:",
    null_population_feature_count
)

print(
    "Final healthy/unhealthy population decisions created: 0"
)

print(
    "Assurance cases created: 0"
)

print(
    "Customer routing changes: 0"
)

print(
    "Delta tables written: 0"
)

print()
print(
    "Next gate: classify each population as coherent baseline, "
    "lifecycle/data reconciliation, explanation required, or "
    "residual assurance concern; then perform targeted enrichment "
    "only where required."
)

print("=" * 120)

# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 5 - Lifecycle-Qualified Treatment Funnel
# Version: 1.1 - explicit relationship/context join boundary
#
# Purpose:
#   Reconstruct the D0033 workload-qualification layer across the complete
#   certified Asset Plane and its Control Assurance relationships.
#
# Key design:
#   The IP-006 Evaluation side is intentionally reduced to relationship-only
#   fields BEFORE joining Asset Plane context. This prevents duplicate context
#   columns such as current_observation_status from becoming ambiguous.
#
# Safety:
#   - READ ONLY
#   - No Delta writes
#   - No source re-ingestion
#   - No enterprise rediscovery
#   - No findings
#   - No assurance cases created
#   - No customer routing changed
# ============================================================================

from pyspark.sql import functions as F
from pyspark.sql.window import Window


# ---------------------------------------------------------------------------
# 1. Require prior diagnostic state
# ---------------------------------------------------------------------------

required_objects = [
    "population_asset_context_df",
    "control_evaluation_df",
    "visibility_population_summary_df",
    "TOTAL_ASSETS",
    "RCAIP_POST_NAME",
    "RCAIP_POST_SLUG",
    "RCAIP_RUN_ID",
]

missing_objects = [
    object_name
    for object_name in required_objects
    if object_name not in globals()
]

if missing_objects:
    raise RuntimeError(
        "Run Cells 1 through 4 first. Missing: "
        + " | ".join(missing_objects)
    )


# ---------------------------------------------------------------------------
# 2. Build one authoritative Asset Plane context row per asset
# ---------------------------------------------------------------------------

asset_context_for_qualification_df = (
    population_asset_context_df
    .select(
        "asset_key",
        "population_id",
        "population_rank",
        "visibility_relationship_pattern",
        "current_observation_status",
        "lifecycle_reconciliation_status",
        "management_model",
        "management_owner",
        "operational_boundary",
        "operational_boundary_confidence",
        "identity_strength",
        "attribution_confidence",
        "attribution_conflict_flag",
        "is_ip_only_identity",
        "active_unresolved_ip_candidate",
        "active_unresolved_ip_observation_class",
    )
    .distinct()
)


asset_context_count = asset_context_for_qualification_df.count()

asset_context_key_count = (
    asset_context_for_qualification_df
    .select("asset_key")
    .distinct()
    .count()
)


if asset_context_count != TOTAL_ASSETS:
    raise RuntimeError(
        "Qualification asset context does not equal "
        "the certified Asset Plane."
    )

if asset_context_key_count != TOTAL_ASSETS:
    raise RuntimeError(
        "Qualification asset context is not one row per asset_key."
    )


# ---------------------------------------------------------------------------
# 3. Establish current-evidence boundary
#
# Current evidence does NOT independently prove physical presence at Post.
# It means current certified evidence exists and requires interpretation.
# ---------------------------------------------------------------------------

asset_context_for_qualification_df = (
    asset_context_for_qualification_df
    .withColumn(
        "has_current_evidence",
        F.coalesce(
            F.col("current_observation_status").startswith("Active"),
            F.lit(False)
        )
    )
)


# ---------------------------------------------------------------------------
# 4. Derive diagnostic responsibility context
#
# This does NOT replace governed customer routing.
# ---------------------------------------------------------------------------

asset_context_for_qualification_df = (
    asset_context_for_qualification_df
    .withColumn(
        "responsibility_context",

        F.when(
            (
                F.upper(F.coalesce(F.col("management_owner"), F.lit("")))
                == F.lit("POST")
            )
            |
            (
                F.upper(F.coalesce(F.col("management_model"), F.lit("")))
                == F.lit("POST_MANAGED")
            )
            |
            (
                F.upper(F.coalesce(F.col("operational_boundary"), F.lit("")))
                == F.lit("POST_MANAGED")
            ),
            F.lit("POST")
        )

        .when(
            (
                F.upper(F.coalesce(F.col("management_owner"), F.lit("")))
                == F.lit("ENTERPRISE")
            )
            |
            (
                F.upper(F.coalesce(F.col("management_model"), F.lit("")))
                == F.lit("ENTERPRISE_MANAGED")
            )
            |
            (
                F.upper(F.coalesce(F.col("operational_boundary"), F.lit("")))
                == F.lit("ENTERPRISE_MANAGED_POST_OPERATED")
            ),
            F.lit("ENTERPRISE")
        )

        .when(
            F.upper(
                F.coalesce(
                    F.col("operational_boundary"),
                    F.lit("")
                )
            )
            == F.lit("ENTERPRISE_ATTRIBUTED_TO_POST"),
            F.lit("ENTERPRISE_ATTRIBUTION_REVIEW")
        )

        .otherwise(
            F.lit("UNRESOLVED")
        )
    )
)


# ---------------------------------------------------------------------------
# 5. IMPORTANT FIX:
#    Reduce Control Assurance Evaluation to relationship-only fields BEFORE
#    joining Asset Plane context.
#
# IP-006 Evaluation already contains several Asset Plane context columns.
# They are deliberately NOT carried through this boundary.
# ---------------------------------------------------------------------------

required_relationship_fields = [
    "asset_key",
    "tool_name",
    "control_role",
    "applicability_state",
    "presence_state",
    "reporting_state",
    "configuration_state",
    "assurance_state",
    "review_priority",
    "routing_scope",
]

missing_relationship_fields = [
    column_name
    for column_name in required_relationship_fields
    if column_name not in control_evaluation_df.columns
]

if missing_relationship_fields:
    raise RuntimeError(
        "Control Assurance Evaluation missing required relationship fields: "
        + " | ".join(missing_relationship_fields)
    )


relationship_input_df = (
    control_evaluation_df
    .select(
        *required_relationship_fields
    )
)


relationship_input_count = relationship_input_df.count()

EXPECTED_RELATIONSHIPS = TOTAL_ASSETS * 5


if relationship_input_count != EXPECTED_RELATIONSHIPS:
    raise RuntimeError(
        "Relationship-only Evaluation boundary does not equal "
        "Asset Plane x five tools."
    )


# ---------------------------------------------------------------------------
# 6. Join relationship evidence to authoritative Asset Plane context
#
# Because the Evaluation side now carries only relationship fields,
# all context field names are unambiguous.
# ---------------------------------------------------------------------------

qualified_relationship_base_df = (
    relationship_input_df
    .join(
        asset_context_for_qualification_df,
        on="asset_key",
        how="inner"
    )
)


qualified_relationship_count = qualified_relationship_base_df.count()


if qualified_relationship_count != EXPECTED_RELATIONSHIPS:
    raise RuntimeError(
        "Relationship qualification join lost or duplicated "
        "Control Assurance relationships."
    )


# ---------------------------------------------------------------------------
# 7. Relationship-state semantic families
#
# These are additive explanatory categories.
# Original assurance_state is preserved.
# ---------------------------------------------------------------------------

STRONG_ADVERSE_STATES = [
    "MISSING",
    "NONCOMPLIANT",
    "MISCONFIGURED",
]

REPORTING_CONCERN_STATES = [
    "PRESENT_NOT_REPORTING",
    "REPORTING_STALE",
    "PRESENT_REPORTING_CONFIGURATION_UNKNOWN",
]

CONTEXT_REVIEW_STATES = [
    "APPLICABILITY_REVIEW_REQUIRED",
    "IDENTITY_RECONCILIATION_REQUIRED",
]

BASELINE_OR_EVIDENCE_STATES = [
    "HEALTHY",
    "NOT_APPLICABLE",
    "EVIDENCE_CURRENT",
    "EVIDENCE_ABSENT",
    "EVIDENCE_STALE",
    "NO_APPLICABLE_CONTROL_CONFIRMED",
]


qualified_relationship_df = (
    qualified_relationship_base_df
    .withColumn(
        "relationship_semantic_class",

        F.when(
            F.col("assurance_state").isin(STRONG_ADVERSE_STATES),
            F.lit("STRONG_ADVERSE")
        )

        .when(
            F.col("assurance_state").isin(REPORTING_CONCERN_STATES),
            F.lit("REPORTING_OR_CONFIGURATION_CONCERN")
        )

        .when(
            F.col("assurance_state").isin(CONTEXT_REVIEW_STATES),
            F.lit("APPLICABILITY_OR_IDENTITY_REVIEW")
        )

        .when(
            F.col("assurance_state") == F.lit("SOURCE_UNAVAILABLE"),
            F.lit("PROGRAM_DEPENDENCY")
        )

        .when(
            F.col("assurance_state").isin(BASELINE_OR_EVIDENCE_STATES),
            F.lit("BASELINE_OR_EVIDENCE_CONTEXT")
        )

        .otherwise(
            F.lit("OTHER_ANALYTICAL_STATE")
        )
    )
)


# ---------------------------------------------------------------------------
# 8. D0033 relationship qualification
#
# Control state remains unchanged.
# Treatment describes what kind of work the evidence could become.
# ---------------------------------------------------------------------------

qualified_relationship_df = (
    qualified_relationship_df
    .withColumn(
        "qualified_treatment",

        # Baseline / evidence-only
        F.when(
            F.col("relationship_semantic_class")
            == F.lit("BASELINE_OR_EVIDENCE_CONTEXT"),
            F.lit("BASELINE_OR_EVIDENCE_CONTEXT")
        )

        # Enterprise-wide source dependency
        .when(
            F.col("relationship_semantic_class")
            == F.lit("PROGRAM_DEPENDENCY"),
            F.lit("PROGRAM_DEPENDENCY")
        )

        # No current evidence -> lifecycle/data reconciliation
        .when(
            ~F.col("has_current_evidence"),
            F.lit("LIFECYCLE_DATA_RECONCILIATION")
        )

        # Current applicability / identity uncertainty
        .when(
            F.col("relationship_semantic_class")
            == F.lit("APPLICABILITY_OR_IDENTITY_REVIEW"),
            F.lit("CURRENT_RCSO_CONTEXT_REVIEW")
        )

        # Current strong adverse - Post
        .when(
            (
                F.col("relationship_semantic_class")
                == F.lit("STRONG_ADVERSE")
            )
            &
            (
                F.col("responsibility_context")
                == F.lit("POST")
            ),
            F.lit("CURRENT_POST_CONTROL_ASSURANCE")
        )

        # Current strong adverse - Enterprise
        .when(
            (
                F.col("relationship_semantic_class")
                == F.lit("STRONG_ADVERSE")
            )
            &
            (
                F.col("responsibility_context")
                == F.lit("ENTERPRISE")
            ),
            F.lit("CURRENT_ENTERPRISE_CONTROL_ASSURANCE")
        )

        # Current strong adverse - enterprise attribution uncertain
        .when(
            (
                F.col("relationship_semantic_class")
                == F.lit("STRONG_ADVERSE")
            )
            &
            (
                F.col("responsibility_context")
                == F.lit("ENTERPRISE_ATTRIBUTION_REVIEW")
            ),
            F.lit("CURRENT_ENTERPRISE_ATTRIBUTION_REVIEW")
        )

        # Current strong adverse - unresolved owner
        .when(
            F.col("relationship_semantic_class")
            == F.lit("STRONG_ADVERSE"),
            F.lit("CURRENT_RCSO_ATTRIBUTION_REVIEW")
        )

        # Current reporting/configuration concern - Post
        .when(
            (
                F.col("relationship_semantic_class")
                == F.lit("REPORTING_OR_CONFIGURATION_CONCERN")
            )
            &
            (
                F.col("responsibility_context")
                == F.lit("POST")
            ),
            F.lit("CURRENT_POST_CONTROL_EVIDENCE_REVIEW")
        )

        # Current reporting/configuration concern - Enterprise
        .when(
            (
                F.col("relationship_semantic_class")
                == F.lit("REPORTING_OR_CONFIGURATION_CONCERN")
            )
            &
            (
                F.col("responsibility_context")
                == F.lit("ENTERPRISE")
            ),
            F.lit("CURRENT_ENTERPRISE_CONTROL_EVIDENCE_REVIEW")
        )

        # Current reporting concern - unresolved responsibility
        .when(
            F.col("relationship_semantic_class")
            == F.lit("REPORTING_OR_CONFIGURATION_CONCERN"),
            F.lit("CURRENT_RCSO_CONTROL_EVIDENCE_REVIEW")
        )

        .otherwise(
            F.lit("OTHER_ANALYTICAL_REVIEW")
        )
    )
)


# ---------------------------------------------------------------------------
# 9. Relationship-level D0033 summary
# ---------------------------------------------------------------------------

relationship_treatment_summary_df = (
    qualified_relationship_df
    .groupBy(
        "qualified_treatment"
    )
    .agg(
        F.count(F.lit(1)).alias(
            "relationship_count"
        ),
        F.countDistinct("asset_key").alias(
            "distinct_asset_count"
        )
    )
    .withColumn(
        "percent_of_all_relationships",
        F.round(
            (
                F.col("relationship_count")
                /
                F.lit(EXPECTED_RELATIONSHIPS)
            )
            * 100.0,
            2
        )
    )
    .orderBy(
        F.desc("relationship_count")
    )
)


print()
print("=" * 120)
print("D0033 RELATIONSHIP TREATMENT SUMMARY")
print("=" * 120)
print(
    "Relationship count and distinct-asset count are different "
    "measurement units."
)
print()

display(
    relationship_treatment_summary_df
)


# ---------------------------------------------------------------------------
# 10. Reconstruct example_post_a anchor conditions
#
# Counts are discovered from runtime data.
# Nothing here hard-codes expected example_post_a values.
# ---------------------------------------------------------------------------

anchor_condition_df = (
    qualified_relationship_df
    .filter(
        (
            (
                F.col("tool_name") == F.lit("MDE")
            )
            &
            (
                F.col("assurance_state").isin(
                    "PRESENT_NOT_REPORTING",
                    "MISSING"
                )
            )
        )
        |
        (
            (
                F.col("tool_name") == F.lit("INTUNE")
            )
            &
            (
                F.col("assurance_state")
                == F.lit("NONCOMPLIANT")
            )
        )
    )
)


anchor_condition_summary_df = (
    anchor_condition_df
    .groupBy(
        "tool_name",
        "assurance_state"
    )
    .agg(
        F.count(F.lit(1)).alias(
            "starting_relationship_count"
        ),

        F.countDistinct("asset_key").alias(
            "starting_asset_count"
        ),

        F.sum(
            F.when(
                F.col("has_current_evidence"),
                1
            ).otherwise(0)
        ).alias(
            "current_evidence_count"
        ),

        F.sum(
            F.when(
                ~F.col("has_current_evidence"),
                1
            ).otherwise(0)
        ).alias(
            "non_current_evidence_count"
        ),

        F.sum(
            F.when(
                F.col("qualified_treatment")
                == F.lit("CURRENT_POST_CONTROL_ASSURANCE"),
                1
            ).otherwise(0)
        ).alias(
            "current_post_control_count"
        ),

        F.sum(
            F.when(
                F.col("qualified_treatment")
                == F.lit("CURRENT_ENTERPRISE_CONTROL_ASSURANCE"),
                1
            ).otherwise(0)
        ).alias(
            "current_enterprise_control_count"
        ),

        F.sum(
            F.when(
                F.col("qualified_treatment")
                == F.lit("CURRENT_ENTERPRISE_ATTRIBUTION_REVIEW"),
                1
            ).otherwise(0)
        ).alias(
            "current_enterprise_attribution_review_count"
        ),

        F.sum(
            F.when(
                F.col("qualified_treatment")
                == F.lit("CURRENT_RCSO_ATTRIBUTION_REVIEW"),
                1
            ).otherwise(0)
        ).alias(
            "current_rcso_attribution_review_count"
        ),

        F.sum(
            F.when(
                F.col("qualified_treatment")
                == F.lit("LIFECYCLE_DATA_RECONCILIATION"),
                1
            ).otherwise(0)
        ).alias(
            "lifecycle_data_reconciliation_count"
        ),
    )
    .orderBy(
        "tool_name",
        "assurance_state"
    )
)


print()
print("=" * 120)
print("D0033 ANCHOR CONDITION FUNNEL")
print("=" * 120)

display(
    anchor_condition_summary_df
)


# ---------------------------------------------------------------------------
# 11. Anchor conditions by original visibility population
# ---------------------------------------------------------------------------

anchor_population_map_df = (
    anchor_condition_df
    .groupBy(
        "tool_name",
        "assurance_state",
        "population_id",
        "population_rank",
        "visibility_relationship_pattern",
        "qualified_treatment",
        "responsibility_context",
    )
    .agg(
        F.countDistinct("asset_key").alias(
            "asset_count"
        )
    )
    .orderBy(
        "tool_name",
        "assurance_state",
        F.desc("asset_count"),
        "population_rank",
    )
)


print()
print("=" * 120)
print("ANCHOR CONDITIONS BY VISIBILITY POPULATION")
print("=" * 120)

display(
    anchor_population_map_df
)


# ---------------------------------------------------------------------------
# 12. Collapse relationship treatments into flags per asset
#
# All context columns now come from one authoritative context source.
# No duplicate-column ambiguity exists at this boundary.
# ---------------------------------------------------------------------------

asset_treatment_flags_df = (
    qualified_relationship_df
    .groupBy(
        "asset_key",
        "population_id",
        "population_rank",
        "visibility_relationship_pattern",
        "has_current_evidence",
        "current_observation_status",
        "lifecycle_reconciliation_status",
        "responsibility_context",
        "management_model",
        "management_owner",
        "operational_boundary",
    )
    .agg(

        F.max(
            F.when(
                F.col("qualified_treatment")
                == F.lit("CURRENT_POST_CONTROL_ASSURANCE"),
                1
            ).otherwise(0)
        ).alias(
            "has_post_control_assurance"
        ),

        F.max(
            F.when(
                F.col("qualified_treatment")
                == F.lit("CURRENT_ENTERPRISE_CONTROL_ASSURANCE"),
                1
            ).otherwise(0)
        ).alias(
            "has_enterprise_control_assurance"
        ),

        F.max(
            F.when(
                F.col("qualified_treatment")
                == F.lit("CURRENT_ENTERPRISE_ATTRIBUTION_REVIEW"),
                1
            ).otherwise(0)
        ).alias(
            "has_enterprise_attribution_review"
        ),

        F.max(
            F.when(
                F.col("qualified_treatment")
                == F.lit("CURRENT_RCSO_ATTRIBUTION_REVIEW"),
                1
            ).otherwise(0)
        ).alias(
            "has_rcso_attribution_review"
        ),

        F.max(
            F.when(
                F.col("qualified_treatment")
                == F.lit("CURRENT_POST_CONTROL_EVIDENCE_REVIEW"),
                1
            ).otherwise(0)
        ).alias(
            "has_post_control_evidence_review"
        ),

        F.max(
            F.when(
                F.col("qualified_treatment")
                == F.lit("CURRENT_ENTERPRISE_CONTROL_EVIDENCE_REVIEW"),
                1
            ).otherwise(0)
        ).alias(
            "has_enterprise_control_evidence_review"
        ),

        F.max(
            F.when(
                F.col("qualified_treatment")
                == F.lit("CURRENT_RCSO_CONTROL_EVIDENCE_REVIEW"),
                1
            ).otherwise(0)
        ).alias(
            "has_rcso_control_evidence_review"
        ),

        F.max(
            F.when(
                F.col("qualified_treatment")
                == F.lit("CURRENT_RCSO_CONTEXT_REVIEW"),
                1
            ).otherwise(0)
        ).alias(
            "has_context_review"
        ),

        F.max(
            F.when(
                F.col("qualified_treatment")
                == F.lit("PROGRAM_DEPENDENCY"),
                1
            ).otherwise(0)
        ).alias(
            "has_program_dependency"
        ),

        F.max(
            F.when(
                F.col("qualified_treatment")
                == F.lit("BASELINE_OR_EVIDENCE_CONTEXT"),
                1
            ).otherwise(0)
        ).alias(
            "has_baseline_evidence"
        ),
    )
)


# ---------------------------------------------------------------------------
# 13. Detect multi-lane conditions
# ---------------------------------------------------------------------------

asset_treatment_flags_df = (
    asset_treatment_flags_df
    .withColumn(
        "strong_action_lane_count",

        F.col("has_post_control_assurance")
        +
        F.col("has_enterprise_control_assurance")
        +
        F.col("has_enterprise_attribution_review")
        +
        F.col("has_rcso_attribution_review")
    )
    .withColumn(
        "evidence_review_lane_count",

        F.col("has_post_control_evidence_review")
        +
        F.col("has_enterprise_control_evidence_review")
        +
        F.col("has_rcso_control_evidence_review")
    )
)


# ---------------------------------------------------------------------------
# 14. Assign one diagnostic treatment candidate per Asset Plane identity
#
# This is NOT assurance-case formation.
# ---------------------------------------------------------------------------

asset_treatment_candidate_df = (
    asset_treatment_flags_df
    .withColumn(
        "asset_treatment_candidate",

        # Non-current first
        F.when(
            ~F.col("has_current_evidence"),
            F.lit("NON_CURRENT_LIFECYCLE_DATA_RECONCILIATION")
        )

        # Multiple current adverse lanes
        .when(
            F.col("strong_action_lane_count") > 1,
            F.lit("CURRENT_MULTI_LANE_CONTROL_REVIEW")
        )

        # Current Post adverse condition
        .when(
            F.col("has_post_control_assurance") == 1,
            F.lit("CURRENT_POST_CONTROL_ASSURANCE")
        )

        # Current enterprise adverse condition
        .when(
            F.col("has_enterprise_control_assurance") == 1,
            F.lit("CURRENT_ENTERPRISE_CONTROL_ASSURANCE")
        )

        # Current enterprise-attribution uncertainty
        .when(
            F.col("has_enterprise_attribution_review") == 1,
            F.lit("CURRENT_ENTERPRISE_ATTRIBUTION_REVIEW")
        )

        # Current unresolved adverse ownership
        .when(
            F.col("has_rcso_attribution_review") == 1,
            F.lit("CURRENT_RCSO_ATTRIBUTION_REVIEW")
        )

        # Multiple evidence-review responsibility lanes
        .when(
            F.col("evidence_review_lane_count") > 1,
            F.lit("CURRENT_MULTI_LANE_EVIDENCE_REVIEW")
        )

        # Post evidence review
        .when(
            F.col("has_post_control_evidence_review") == 1,
            F.lit("CURRENT_POST_CONTROL_EVIDENCE_REVIEW")
        )

        # Enterprise evidence review
        .when(
            F.col("has_enterprise_control_evidence_review") == 1,
            F.lit("CURRENT_ENTERPRISE_CONTROL_EVIDENCE_REVIEW")
        )

        # RCSO unresolved evidence review
        .when(
            F.col("has_rcso_control_evidence_review") == 1,
            F.lit("CURRENT_RCSO_CONTROL_EVIDENCE_REVIEW")
        )

        # Applicability / identity context still unresolved
        .when(
            F.col("has_context_review") == 1,
            F.lit("CURRENT_APPLICABILITY_IDENTITY_REVIEW")
        )

        # Only enterprise source dependency remains
        .when(
            F.col("has_program_dependency") == 1,
            F.lit("PROGRAM_DEPENDENCY_ONLY")
        )

        # No current promoted concern
        .otherwise(
            F.lit("COHERENT_BASELINE")
        )
    )
)


# ---------------------------------------------------------------------------
# 15. Asset-level workload-qualification funnel
# ---------------------------------------------------------------------------

asset_treatment_funnel_df = (
    asset_treatment_candidate_df
    .groupBy(
        "asset_treatment_candidate"
    )
    .agg(
        F.countDistinct("asset_key").alias(
            "asset_count"
        )
    )
    .withColumn(
        "percent_of_asset_plane",
        F.round(
            (
                F.col("asset_count")
                /
                F.lit(TOTAL_ASSETS)
            )
            * 100.0,
            2
        )
    )
    .orderBy(
        F.desc("asset_count")
    )
)


print()
print("=" * 120)
print("ASSET VISIBILITY / WORKLOAD QUALIFICATION FUNNEL")
print("=" * 120)
print(
    "Each Asset Plane identity appears in exactly one diagnostic "
    "treatment candidate."
)
print(
    "This is NOT yet assurance-case compression."
)
print()

display(
    asset_treatment_funnel_df
)


# ---------------------------------------------------------------------------
# 16. Original visibility population -> treatment mix
# ---------------------------------------------------------------------------

population_treatment_mix_df = (
    asset_treatment_candidate_df
    .groupBy(
        "population_id",
        "population_rank",
        "visibility_relationship_pattern",
        "asset_treatment_candidate",
    )
    .agg(
        F.countDistinct("asset_key").alias(
            "asset_count"
        )
    )
    .withColumn(
        "percent_of_asset_plane",
        F.round(
            (
                F.col("asset_count")
                /
                F.lit(TOTAL_ASSETS)
            )
            * 100.0,
            2
        )
    )
    .orderBy(
        "population_rank",
        F.desc("asset_count")
    )
)


print()
print("=" * 120)
print("VISIBILITY POPULATION -> TREATMENT MIX")
print("=" * 120)

display(
    population_treatment_mix_df
)


# ---------------------------------------------------------------------------
# 17. Focused MDE MISSING map
#
# This identifies exactly which populations feed the next historical/
# rediscovery analysis.
# ---------------------------------------------------------------------------

mde_missing_population_df = (
    qualified_relationship_df
    .filter(
        (
            F.col("tool_name") == F.lit("MDE")
        )
        &
        (
            F.col("assurance_state") == F.lit("MISSING")
        )
    )
    .groupBy(
        "population_id",
        "population_rank",
        "visibility_relationship_pattern",
        "has_current_evidence",
        "responsibility_context",
        "qualified_treatment",
    )
    .agg(
        F.countDistinct("asset_key").alias(
            "asset_count"
        )
    )
    .orderBy(
        F.desc("asset_count"),
        "population_rank",
    )
)


print()
print("=" * 120)
print("MDE MISSING - VISIBILITY / LIFECYCLE MAP")
print("=" * 120)

display(
    mde_missing_population_df
)


# ---------------------------------------------------------------------------
# 18. Certification
# ---------------------------------------------------------------------------

asset_funnel_total = int(
    asset_treatment_funnel_df
    .agg(
        F.sum("asset_count").alias("asset_count")
    )
    .first()["asset_count"]
)


population_mix_total = int(
    population_treatment_mix_df
    .agg(
        F.sum("asset_count").alias("asset_count")
    )
    .first()["asset_count"]
)


anchor_relationship_total = (
    anchor_condition_df.count()
)


unqualified_relationship_count = (
    qualified_relationship_df
    .filter(
        F.col("qualified_treatment").isNull()
    )
    .count()
)


if asset_funnel_total != TOTAL_ASSETS:
    raise RuntimeError(
        "Asset treatment funnel does not reconcile "
        "to the certified Asset Plane."
    )


if population_mix_total != TOTAL_ASSETS:
    raise RuntimeError(
        "Population treatment mix does not reconcile "
        "to the certified Asset Plane."
    )


if unqualified_relationship_count != 0:
    raise RuntimeError(
        "One or more Control Assurance relationships "
        "did not receive a diagnostic treatment."
    )


print()
print("=" * 120)
print("RCAIP DIAG 001 - CELL 5 CERTIFICATION")
print("=" * 120)

print("Status: PASS")
print("Post:", RCAIP_POST_NAME)
print("Run ID:", RCAIP_RUN_ID)

print(
    "Certified Asset Plane identities:",
    TOTAL_ASSETS
)

print(
    "Certified Control Assurance relationships:",
    EXPECTED_RELATIONSHIPS
)

print(
    "Relationship-only Evaluation rows:",
    relationship_input_count
)

print(
    "Qualified Control Assurance relationships:",
    qualified_relationship_count
)

print(
    "Asset treatment funnel total:",
    asset_funnel_total
)

print(
    "Population treatment mix total:",
    population_mix_total
)

print(
    "D0033 anchor relationships:",
    anchor_relationship_total
)

print(
    "Relationships without treatment:",
    unqualified_relationship_count
)

print(
    "Final assurance cases created: 0"
)

print(
    "Final customer workload created: 0"
)

print(
    "Enterprise rediscovery performed: 0"
)

print(
    "Delta tables written: 0"
)

print()
print(
    "Next gate: perform targeted historical / identity enrichment "
    "only where it can materially change treatment, beginning with "
    "the MDE MISSING population."
)

print("=" * 120)

# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 6 - Current MDE-Missing Trusted-Name Qualification
# Version: 1.0
#
# Purpose:
#   Reconstruct the trusted-name prerequisite required for bounded enterprise
#   MDE rediscovery.
#
# Population:
#   - MDE assurance_state == MISSING
#   - current Asset Plane evidence only
#
# Method:
#   - Preserve the complete current MDE-MISSING population.
#   - Discover source-specific machine-name fields already carried by the
#     certified Scored Asset Plane.
#   - Exclude MDE itself from supporting-name evidence to avoid circularity.
#   - Normalize exact FULL and SHORT machine names.
#   - Require >=2 independent source families for a trusted search name.
#   - Do NOT use fuzzy matching.
#   - Do NOT use IP-only matching.
#
# Outputs:
#   - source_name_field_inventory_df
#   - mde_name_qualification_summary_df
#   - mde_name_population_summary_df
#   - mde_trusted_search_detail_df
#   - dominant_candidate_df
#
# Safety:
#   - READ ONLY
#   - No raw enterprise MDE search in this cell
#   - No original MDE classifications changed
#   - No assurance cases changed
#   - No customer routing changed
#   - No Delta writes
# ============================================================================

import re

from pyspark.sql import functions as F
from pyspark.sql import types as T


# ---------------------------------------------------------------------------
# 1. Require Cells 1-5
# ---------------------------------------------------------------------------

required_objects = [
    "qualified_relationship_df",
    "scored_df",
    "feature_df",
    "TOTAL_ASSETS",
    "RCAIP_POST_NAME",
    "RCAIP_POST_SLUG",
    "RCAIP_RUN_ID",
]

missing_objects = [
    object_name
    for object_name in required_objects
    if object_name not in globals()
]

if missing_objects:
    raise RuntimeError(
        "Run Cells 1 through 5 first. Missing: "
        + " | ".join(missing_objects)
    )


print("=" * 120)
print("RCAIP DIAG 001 - CURRENT MDE-MISSING TRUSTED-NAME QUALIFICATION")
print("=" * 120)
print("Post:", RCAIP_POST_NAME)
print("Run ID:", RCAIP_RUN_ID)


# ---------------------------------------------------------------------------
# 2. Reconstruct the complete MDE-MISSING relationship population
#
# There should be exactly one MDE relationship per affected asset.
# ---------------------------------------------------------------------------

mde_missing_relationship_df = (
    qualified_relationship_df

    .filter(
        (
            F.upper(
                F.trim(
                    F.col("tool_name")
                )
            )
            ==
            F.lit("MDE")
        )
        &
        (
            F.upper(
                F.trim(
                    F.col("assurance_state")
                )
            )
            ==
            F.lit("MISSING")
        )
    )

    .select(
        "asset_key",
        "population_id",
        "population_rank",
        "visibility_relationship_pattern",
        "has_current_evidence",
        "current_observation_status",
        "lifecycle_reconciliation_status",
        "responsibility_context",
        "qualified_treatment",
        "management_model",
        "management_owner",
        "operational_boundary",
    )
)


mde_missing_total_count = (
    mde_missing_relationship_df.count()
)

mde_missing_distinct_asset_count = (
    mde_missing_relationship_df
    .select("asset_key")
    .distinct()
    .count()
)


if (
    mde_missing_total_count
    !=
    mde_missing_distinct_asset_count
):
    raise RuntimeError(
        "MDE-MISSING relationship population is not "
        "one relationship per asset."
    )


mde_missing_current_df = (
    mde_missing_relationship_df

    .filter(
        F.col("has_current_evidence")
        ==
        F.lit(True)
    )

    .cache()
)


mde_missing_noncurrent_df = (
    mde_missing_relationship_df

    .filter(
        F.col("has_current_evidence")
        !=
        F.lit(True)
    )

    .cache()
)


mde_missing_current_count = (
    mde_missing_current_df.count()
)

mde_missing_noncurrent_count = (
    mde_missing_noncurrent_df.count()
)


if (
    mde_missing_current_count
    +
    mde_missing_noncurrent_count
    !=
    mde_missing_total_count
):
    raise RuntimeError(
        "Current/non-current MDE-MISSING partition "
        "does not reconcile."
    )


# ---------------------------------------------------------------------------
# 3. Add authoritative identity context from the Feature Mart
#
# Only fields not already present on the relationship population are selected.
# ---------------------------------------------------------------------------

preferred_identity_context_fields = [
    "host_key",
    "canonical_name",
    "canonical_serial",
    "canonical_ip",
    "device_family",
    "device_scope",
    "identity_basis",
    "identity_strength",
    "source_mask_raw",
    "source_mask_active",
    "source_mask_stale",
    "attribution_confidence",
    "attribution_conflict_flag",
]


available_identity_context_fields = [
    column_name
    for column_name in preferred_identity_context_fields
    if column_name in feature_df.columns
]


if "canonical_name" not in available_identity_context_fields:
    raise RuntimeError(
        "Feature Mart does not expose canonical_name."
    )


feature_identity_context_df = (
    feature_df

    .select(
        "asset_key",
        *available_identity_context_fields
    )
)


mde_missing_current_context_df = (
    mde_missing_current_df

    .join(
        feature_identity_context_df,
        on="asset_key",
        how="left"
    )
)


current_context_count = (
    mde_missing_current_context_df.count()
)

current_context_distinct_count = (
    mde_missing_current_context_df
    .select("asset_key")
    .distinct()
    .count()
)


if current_context_count != mde_missing_current_count:
    raise RuntimeError(
        "Current MDE-MISSING identity-context join "
        "changed the population size."
    )

if current_context_distinct_count != mde_missing_current_count:
    raise RuntimeError(
        "Current MDE-MISSING context is not one row per asset."
    )


# ---------------------------------------------------------------------------
# 4. Discover source-specific STRING machine-name fields in the Scored
#    Asset Plane.
#
# We intentionally exclude MDE fields. MDE is the source being rediscovered.
# Canonical name is useful context but is NOT counted as an independent source.
# ---------------------------------------------------------------------------

SOURCE_PREFIXES = {
    "CMDB": [
        "cmdb",
    ],
    "NMAP": [
        "nmap",
    ],
    "TENABLE": [
        "tenable",
    ],
    "INTUNE": [
        "intune",
    ],
    "QUALYS": [
        "qualys",
    ],
}


NAME_INDICATORS = [
    "hostname",
    "host_name",
    "hostnames",
    "device_name",
    "computer_name",
    "dns_name",
    "asset_name",
    "ci_name",
    "fqdn",
]


EXCLUDED_NAME_TERMS = [
    "location",
    "owner",
    "source_name",
    "post_name",
    "site_name",
    "group_name",
    "machine_group",
    "status",
    "state",
    "type_name",
    "category_name",
    "class_name",
    "manufacturer",
    "model_name",
    "user_name",
    "username",
    "department",
    "assignment",
]


def normalize_schema_name(
    column_name
):
    normalized = (
        str(column_name)
        .strip()
        .lower()
    )

    normalized = re.sub(
        r"[^a-z0-9]+",
        "_",
        normalized
    )

    normalized = re.sub(
        r"_+",
        "_",
        normalized
    )

    return normalized.strip("_")


def source_family_for_column(
    column_name
):
    normalized_name = normalize_schema_name(
        column_name
    )

    if any(
        excluded_term in normalized_name
        for excluded_term in EXCLUDED_NAME_TERMS
    ):
        return None

    has_name_semantics = (
        any(
            indicator in normalized_name
            for indicator in NAME_INDICATORS
        )
        or
        normalized_name.endswith("_name")
    )

    if not has_name_semantics:
        return None

    for source_family, prefixes in SOURCE_PREFIXES.items():

        for prefix in prefixes:

            if (
                normalized_name == prefix
                or
                normalized_name.startswith(
                    prefix + "_"
                )
                or
                (
                    "_" + prefix + "_"
                    in
                    "_" + normalized_name + "_"
                )
            ):
                return source_family

    return None


source_name_candidates = []


for schema_field in scored_df.schema.fields:

    if not isinstance(
        schema_field.dataType,
        T.StringType
    ):
        continue

    source_family = (
        source_family_for_column(
            schema_field.name
        )
    )

    if source_family is None:
        continue

    # Explicitly prevent MDE from becoming evidence for its own rediscovery.
    if source_family == "MDE":
        continue

    source_name_candidates.append(
        (
            source_family,
            schema_field.name,
        )
    )


source_name_candidates = sorted(
    set(
        source_name_candidates
    ),
    key=lambda item: (
        item[0],
        item[1]
    )
)


candidate_source_name_fields = [
    column_name
    for source_family, column_name
    in source_name_candidates
]


# ---------------------------------------------------------------------------
# 5. Build the current-MDE-missing scored slice
# ---------------------------------------------------------------------------

current_mde_missing_keys_df = (
    mde_missing_current_df

    .select(
        "asset_key"
    )

    .distinct()
)


if candidate_source_name_fields:

    current_scored_name_df = (
        scored_df

        .select(
            "asset_key",
            *candidate_source_name_fields
        )

        .join(
            current_mde_missing_keys_df,
            on="asset_key",
            how="inner"
        )
    )

else:

    current_scored_name_df = (
        current_mde_missing_keys_df
    )


# ---------------------------------------------------------------------------
# 6. Exact machine-name normalization
#
# Same conservative principles as the prior Gate 4D:
#   lower
#   trim
#   strip trailing $
#   strip trailing .
#   reject obvious non-machine placeholders
#   reject IPv4 values
#
# No fuzzy normalization is performed.
# ---------------------------------------------------------------------------

INVALID_MACHINE_NAMES = [
    "",
    "-",
    "na",
    "n/a",
    "none",
    "null",
    "unknown",
    "localhost",
]


IPV4_PATTERN = (
    r"^\d{1,3}"
    r"(\.\d{1,3}){3}$"
)


def normalize_machine_name(
    column_expression
):

    normalized = (
        F.lower(
            F.trim(
                column_expression.cast(
                    "string"
                )
            )
        )
    )

    normalized = (
        F.regexp_replace(
            normalized,
            r"\$$",
            ""
        )
    )

    normalized = (
        F.regexp_replace(
            normalized,
            r"\.$",
            ""
        )
    )

    valid_name = (
        normalized.isNotNull()
        &
        (
            F.length(
                normalized
            )
            >=
            F.lit(3)
        )
        &
        (
            ~normalized.isin(
                *INVALID_MACHINE_NAMES
            )
        )
        &
        (
            ~normalized.rlike(
                IPV4_PATTERN
            )
        )
    )

    return (
        F.when(
            valid_name,
            normalized
        )
    )


# ---------------------------------------------------------------------------
# 7. Profile candidate name fields across only the CURRENT MDE-MISSING
#    population.
# ---------------------------------------------------------------------------

field_inventory_rows = []


if source_name_candidates:

    field_metric_expressions = []

    for field_index, (
        source_family,
        column_name
    ) in enumerate(
        source_name_candidates
    ):

        normalized_value = (
            normalize_machine_name(
                F.col(column_name)
            )
        )

        field_metric_expressions.extend([
            F.count(
                normalized_value
            ).alias(
                f"nonblank_{field_index}"
            ),

            F.countDistinct(
                normalized_value
            ).alias(
                f"distinct_{field_index}"
            ),
        ])


    field_metric_row = (
        current_scored_name_df

        .agg(
            *field_metric_expressions
        )

        .first()
        .asDict()
    )


    for field_index, (
        source_family,
        column_name
    ) in enumerate(
        source_name_candidates
    ):

        field_inventory_rows.append(
            (
                source_family,
                column_name,
                int(
                    field_metric_row[
                        f"nonblank_{field_index}"
                    ]
                    or
                    0
                ),
                int(
                    field_metric_row[
                        f"distinct_{field_index}"
                    ]
                    or
                    0
                ),
            )
        )


field_inventory_schema = T.StructType([
    T.StructField(
        "source_family",
        T.StringType(),
        False
    ),
    T.StructField(
        "source_name_field",
        T.StringType(),
        False
    ),
    T.StructField(
        "current_mde_missing_assets_with_value",
        T.LongType(),
        False
    ),
    T.StructField(
        "distinct_normalized_values",
        T.LongType(),
        False
    ),
])


source_name_field_inventory_df = (
    spark.createDataFrame(
        field_inventory_rows,
        schema=field_inventory_schema
    )
)


print()
print("=" * 120)
print("CURRENT MDE-MISSING - SOURCE NAME FIELD COVERAGE")
print("=" * 120)
print(
    "Only non-MDE, source-specific STRING machine-name fields "
    "are eligible."
)
print()

display(
    source_name_field_inventory_df
    .orderBy(
        F.desc(
            "current_mde_missing_assets_with_value"
        ),
        "source_family",
        "source_name_field",
    )
)


# ---------------------------------------------------------------------------
# 8. Build FULL and SHORT exact-name evidence
#
# One source family gets one vote regardless of how many columns from that
# source happen to contain the same value.
# ---------------------------------------------------------------------------

name_token_schema = T.StructType([
    T.StructField(
        "asset_key",
        T.StringType(),
        False
    ),
    T.StructField(
        "source_family",
        T.StringType(),
        False
    ),
    T.StructField(
        "source_column",
        T.StringType(),
        False
    ),
    T.StructField(
        "match_type",
        T.StringType(),
        False
    ),
    T.StructField(
        "match_value",
        T.StringType(),
        False
    ),
])


name_token_evidence_df = None


for source_family, column_name in source_name_candidates:

    normalized_field_df = (
        current_scored_name_df

        .select(
            "asset_key",

            normalize_machine_name(
                F.col(column_name)
            ).alias(
                "_normalized_full_name"
            )
        )

        .withColumn(
            "_normalized_short_name",

            F.split(
                F.col(
                    "_normalized_full_name"
                ),
                r"\."
            ).getItem(0)
        )
    )


    full_token_df = (
        normalized_field_df

        .filter(
            F.col(
                "_normalized_full_name"
            ).isNotNull()
        )

        .select(
            "asset_key",

            F.lit(
                source_family
            ).alias(
                "source_family"
            ),

            F.lit(
                column_name
            ).alias(
                "source_column"
            ),

            F.lit(
                "FULL"
            ).alias(
                "match_type"
            ),

            F.col(
                "_normalized_full_name"
            ).alias(
                "match_value"
            ),
        )
    )


    short_token_df = (
        normalized_field_df

        .filter(
            F.col(
                "_normalized_short_name"
            ).isNotNull()
            &
            (
                F.length(
                    F.col(
                        "_normalized_short_name"
                    )
                )
                >=
                F.lit(3)
            )
        )

        .select(
            "asset_key",

            F.lit(
                source_family
            ).alias(
                "source_family"
            ),

            F.lit(
                column_name
            ).alias(
                "source_column"
            ),

            F.lit(
                "SHORT"
            ).alias(
                "match_type"
            ),

            F.col(
                "_normalized_short_name"
            ).alias(
                "match_value"
            ),
        )
    )


    source_tokens_df = (
        full_token_df
        .unionByName(
            short_token_df
        )
    )


    name_token_evidence_df = (
        source_tokens_df

        if name_token_evidence_df is None

        else

        name_token_evidence_df
        .unionByName(
            source_tokens_df
        )
    )


if name_token_evidence_df is None:

    name_token_evidence_df = (
        spark.createDataFrame(
            [],
            schema=name_token_schema
        )
    )


name_token_evidence_df = (
    name_token_evidence_df

    .dropDuplicates([
        "asset_key",
        "source_family",
        "source_column",
        "match_type",
        "match_value",
    ])

    .cache()
)


# ---------------------------------------------------------------------------
# 9. Measure independent-source support for each exact name
# ---------------------------------------------------------------------------

name_support_df = (
    name_token_evidence_df

    .groupBy(
        "asset_key",
        "match_type",
        "match_value",
    )

    .agg(
        F.countDistinct(
            "source_family"
        ).alias(
            "supporting_source_family_count"
        ),

        F.sort_array(
            F.collect_set(
                "source_family"
            )
        ).alias(
            "supporting_source_families"
        ),

        F.sort_array(
            F.collect_set(
                "source_column"
            )
        ).alias(
            "supporting_source_columns"
        ),
    )
)


trusted_name_support_df = (
    name_support_df

    .filter(
        F.col(
            "supporting_source_family_count"
        )
        >=
        F.lit(2)
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 10. Count supported FULL and SHORT candidates per asset
# ---------------------------------------------------------------------------

trusted_full_summary_df = (
    trusted_name_support_df

    .filter(
        F.col("match_type")
        ==
        F.lit("FULL")
    )

    .groupBy(
        "asset_key"
    )

    .agg(
        F.countDistinct(
            "match_value"
        ).alias(
            "trusted_full_name_count"
        ),

        F.sort_array(
            F.collect_set(
                "match_value"
            )
        ).alias(
            "trusted_full_names"
        ),
    )
)


trusted_short_summary_df = (
    trusted_name_support_df

    .filter(
        F.col("match_type")
        ==
        F.lit("SHORT")
    )

    .groupBy(
        "asset_key"
    )

    .agg(
        F.countDistinct(
            "match_value"
        ).alias(
            "trusted_short_name_count"
        ),

        F.sort_array(
            F.collect_set(
                "match_value"
            )
        ).alias(
            "trusted_short_names"
        ),
    )
)


# ---------------------------------------------------------------------------
# 11. Qualify the CURRENT MDE-MISSING assets
#
# Precedence:
#
#   1. Exactly one multi-source FULL name
#   2. Multiple multi-source FULL names -> analyst review
#   3. Exactly one multi-source SHORT name
#   4. Multiple multi-source SHORT names -> analyst review
#   5. Name exists but lacks independent source corroboration -> defer
#   6. No usable name -> no searchable name
# ---------------------------------------------------------------------------

mde_missing_name_qualification_df = (
    mde_missing_current_context_df

    .join(
        trusted_full_summary_df,
        on="asset_key",
        how="left"
    )

    .join(
        trusted_short_summary_df,
        on="asset_key",
        how="left"
    )

    .fillna({
        "trusted_full_name_count": 0,
        "trusted_short_name_count": 0,
    })

    .withColumn(
        "_canonical_name_normalized",

        normalize_machine_name(
            F.col(
                "canonical_name"
            )
        )
    )

    .withColumn(
        "name_qualification_class",

        F.when(
            F.col(
                "trusted_full_name_count"
            )
            ==
            F.lit(1),

            F.lit(
                "TRUSTED_MULTI_SOURCE_FULL_NAME"
            )
        )

        .when(
            F.col(
                "trusted_full_name_count"
            )
            >
            F.lit(1),

            F.lit(
                "REVIEW_MULTIPLE_MULTI_SOURCE_FULL_NAMES"
            )
        )

        .when(
            (
                F.col(
                    "trusted_full_name_count"
                )
                ==
                F.lit(0)
            )
            &
            (
                F.col(
                    "trusted_short_name_count"
                )
                ==
                F.lit(1)
            ),

            F.lit(
                "TRUSTED_MULTI_SOURCE_SHORT_NAME"
            )
        )

        .when(
            (
                F.col(
                    "trusted_full_name_count"
                )
                ==
                F.lit(0)
            )
            &
            (
                F.col(
                    "trusted_short_name_count"
                )
                >
                F.lit(1)
            ),

            F.lit(
                "REVIEW_MULTIPLE_MULTI_SOURCE_SHORT_NAMES"
            )
        )

        .when(
            F.col(
                "_canonical_name_normalized"
            ).isNotNull(),

            F.lit(
                "DEFER_NO_MULTI_SOURCE_NAME_SUPPORT"
            )
        )

        .otherwise(
            F.lit(
                "NO_SEARCHABLE_NAME"
            )
        )
    )

    .withColumn(
        "selected_match_type",

        F.when(
            F.col(
                "name_qualification_class"
            )
            ==
            F.lit(
                "TRUSTED_MULTI_SOURCE_FULL_NAME"
            ),
            F.lit(
                "FULL"
            )
        )

        .when(
            F.col(
                "name_qualification_class"
            )
            ==
            F.lit(
                "TRUSTED_MULTI_SOURCE_SHORT_NAME"
            ),
            F.lit(
                "SHORT"
            )
        )
    )

    .withColumn(
        "selected_match_value",

        F.when(
            F.col(
                "name_qualification_class"
            )
            ==
            F.lit(
                "TRUSTED_MULTI_SOURCE_FULL_NAME"
            ),

            F.element_at(
                F.col(
                    "trusted_full_names"
                ),
                1
            )
        )

        .when(
            F.col(
                "name_qualification_class"
            )
            ==
            F.lit(
                "TRUSTED_MULTI_SOURCE_SHORT_NAME"
            ),

            F.element_at(
                F.col(
                    "trusted_short_names"
                ),
                1
            )
        )
    )

    .withColumn(
        "normalized_search_full_name",

        F.when(
            F.col(
                "selected_match_type"
            )
            ==
            F.lit(
                "FULL"
            ),

            F.col(
                "selected_match_value"
            )
        )
    )

    .withColumn(
        "normalized_search_short_name",

        F.when(
            F.col(
                "selected_match_type"
            )
            ==
            F.lit(
                "FULL"
            ),

            F.split(
                F.col(
                    "selected_match_value"
                ),
                r"\."
            ).getItem(0)
        )

        .when(
            F.col(
                "selected_match_type"
            )
            ==
            F.lit(
                "SHORT"
            ),

            F.col(
                "selected_match_value"
            )
        )
    )

    .drop(
        "_canonical_name_normalized"
    )
)


# ---------------------------------------------------------------------------
# 12. Attach supporting-source evidence for the selected trusted token
# ---------------------------------------------------------------------------

selected_support_df = (
    trusted_name_support_df

    .select(
        F.col(
            "asset_key"
        ).alias(
            "_support_asset_key"
        ),

        F.col(
            "match_type"
        ).alias(
            "_support_match_type"
        ),

        F.col(
            "match_value"
        ).alias(
            "_support_match_value"
        ),

        "supporting_source_family_count",
        "supporting_source_families",
        "supporting_source_columns",
    )
)


qualified_alias = (
    mde_missing_name_qualification_df.alias(
        "q"
    )
)

support_alias = (
    selected_support_df.alias(
        "s"
    )
)


mde_missing_name_qualification_df = (
    qualified_alias

    .join(
        support_alias,

        (
            F.col(
                "q.asset_key"
            )
            ==
            F.col(
                "s._support_asset_key"
            )
        )
        &
        (
            F.col(
                "q.selected_match_type"
            )
            ==
            F.col(
                "s._support_match_type"
            )
        )
        &
        (
            F.col(
                "q.selected_match_value"
            )
            ==
            F.col(
                "s._support_match_value"
            )
        ),

        how="left"
    )

    .select(
        "q.*",

        F.col(
            "s.supporting_source_family_count"
        ).alias(
            "selected_name_source_family_count"
        ),

        F.col(
            "s.supporting_source_families"
        ).alias(
            "selected_name_source_families"
        ),

        F.col(
            "s.supporting_source_columns"
        ).alias(
            "selected_name_source_columns"
        ),
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 13. Qualification summary
# ---------------------------------------------------------------------------

qualification_denominator = max(
    mde_missing_current_count,
    1
)


mde_name_qualification_summary_df = (
    mde_missing_name_qualification_df

    .groupBy(
        "name_qualification_class"
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        )
    )

    .withColumn(
        "percent_of_current_mde_missing",
        F.round(
            (
                F.col(
                    "asset_count"
                )
                /
                F.lit(
                    qualification_denominator
                )
            )
            *
            100.0,
            2
        )
    )

    .orderBy(
        F.desc(
            "asset_count"
        )
    )
)


print()
print("=" * 120)
print("CURRENT MDE-MISSING - TRUSTED NAME QUALIFICATION")
print("=" * 120)

display(
    mde_name_qualification_summary_df
)


# ---------------------------------------------------------------------------
# 14. Show how name qualification maps to the existing visibility populations
# ---------------------------------------------------------------------------

mde_name_population_summary_df = (
    mde_missing_name_qualification_df

    .groupBy(
        "population_id",
        "population_rank",
        "visibility_relationship_pattern",
        "responsibility_context",
        "qualified_treatment",
        "name_qualification_class",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        )
    )

    .orderBy(
        "population_rank",
        F.desc(
            "asset_count"
        ),
        "name_qualification_class",
    )
)


print()
print("=" * 120)
print("CURRENT MDE-MISSING - NAME QUALIFICATION BY VISIBILITY POPULATION")
print("=" * 120)

display(
    mde_name_population_summary_df
)


# ---------------------------------------------------------------------------
# 15. Publish the exact bounded search population for the NEXT cell
# ---------------------------------------------------------------------------

mde_trusted_search_detail_df = (
    mde_missing_name_qualification_df

    .filter(
        F.col(
            "name_qualification_class"
        ).isin(
            "TRUSTED_MULTI_SOURCE_FULL_NAME",
            "TRUSTED_MULTI_SOURCE_SHORT_NAME",
        )
    )

    .select(
        "asset_key",
        "population_id",
        "population_rank",
        "visibility_relationship_pattern",
        "responsibility_context",
        "qualified_treatment",
        "canonical_name",
        *(
            [
                column_name
                for column_name in [
                    "canonical_ip",
                    "device_family",
                    "device_scope",
                    "identity_basis",
                    "identity_strength",
                    "source_mask_active",
                    "source_mask_stale",
                ]
                if column_name
                in mde_missing_name_qualification_df.columns
            ]
        ),
        "name_qualification_class",
        "normalized_search_full_name",
        "normalized_search_short_name",
        "selected_name_source_family_count",
        "selected_name_source_families",
        "selected_name_source_columns",
    )

    .orderBy(
        "population_rank",
        "canonical_name",
        "asset_key",
    )
)


print()
print("=" * 120)
print("CURRENT MDE-MISSING - TRUSTED ENTERPRISE SEARCH POPULATION")
print("=" * 120)
print(
    "These are the only assets authorized for the next exact-name "
    "enterprise MDE lookup."
)
print()

display(
    mde_trusted_search_detail_df
)


# ---------------------------------------------------------------------------
# 16. Publish a Gate-4D-compatible trusted-name object
#
# This intentionally recreates the core semantic contract of the earlier
# dominant_candidate_df without reusing any hidden example_post_a-specific count.
# ---------------------------------------------------------------------------

dominant_candidate_df = (
    mde_trusted_search_detail_df

    .select(
        "asset_key",

        F.col(
            "normalized_search_full_name"
        ).alias(
            "normalized_full_name"
        ),

        F.col(
            "normalized_search_short_name"
        ).alias(
            "normalized_short_name"
        ),

        F.col(
            "selected_name_source_families"
        ).alias(
            "supporting_source_families"
        ),

        F.col(
            "selected_name_source_columns"
        ).alias(
            "supporting_sources"
        ),
    )

    .dropDuplicates([
        "asset_key"
    ])

    .cache()
)


# ---------------------------------------------------------------------------
# 17. Structural certification
# ---------------------------------------------------------------------------

qualification_total = (
    mde_name_qualification_summary_df

    .agg(
        F.sum(
            "asset_count"
        ).alias(
            "asset_count"
        )
    )

    .first()[
        "asset_count"
    ]
)


qualification_total = int(
    qualification_total
    or
    0
)


assets_with_any_source_name = (
    name_token_evidence_df

    .select(
        "asset_key"
    )

    .distinct()

    .count()
)


trusted_search_count = (
    dominant_candidate_df.count()
)


trusted_search_distinct_count = (
    dominant_candidate_df

    .select(
        "asset_key"
    )

    .distinct()

    .count()
)


multiple_name_review_count = (
    mde_missing_name_qualification_df

    .filter(
        F.col(
            "name_qualification_class"
        ).startswith(
            "REVIEW_MULTIPLE"
        )
    )

    .count()
)


deferred_no_multisource_count = (
    mde_missing_name_qualification_df

    .filter(
        F.col(
            "name_qualification_class"
        )
        ==
        F.lit(
            "DEFER_NO_MULTI_SOURCE_NAME_SUPPORT"
        )
    )

    .count()
)


no_searchable_name_count = (
    mde_missing_name_qualification_df

    .filter(
        F.col(
            "name_qualification_class"
        )
        ==
        F.lit(
            "NO_SEARCHABLE_NAME"
        )
    )

    .count()
)


if qualification_total != mde_missing_current_count:
    raise RuntimeError(
        "Name qualification does not reconcile "
        "to current MDE-MISSING population."
    )


if trusted_search_count != trusted_search_distinct_count:
    raise RuntimeError(
        "Trusted enterprise-search population "
        "is not one row per asset."
    )


if (
    mde_missing_current_count
    +
    mde_missing_noncurrent_count
    !=
    mde_missing_total_count
):
    raise RuntimeError(
        "MDE-MISSING lifecycle partition failed final reconciliation."
    )


# ---------------------------------------------------------------------------
# 18. Final certification
# ---------------------------------------------------------------------------

print()
print("=" * 120)
print("RCAIP DIAG 001 - CELL 6 CERTIFICATION")
print("=" * 120)

print("Status: PASS")
print("Post:", RCAIP_POST_NAME)
print("Run ID:", RCAIP_RUN_ID)

print(
    "All MDE-MISSING relationships:",
    mde_missing_total_count
)

print(
    "Current MDE-MISSING relationships:",
    mde_missing_current_count
)

print(
    "Non-current MDE-MISSING relationships:",
    mde_missing_noncurrent_count
)

print(
    "Current MDE-MISSING context rows:",
    current_context_count
)

print(
    "Candidate non-MDE source-name fields discovered:",
    len(
        source_name_candidates
    )
)

print(
    "Current MDE-MISSING assets with any source-name evidence:",
    assets_with_any_source_name
)

print(
    "Trusted multi-source exact-name search candidates:",
    trusted_search_count
)

print(
    "Multiple supported-name review assets:",
    multiple_name_review_count
)

print(
    "Deferred - no multi-source name support:",
    deferred_no_multisource_count
)

print(
    "No searchable name:",
    no_searchable_name_count
)

print(
    "Name qualification population reconciliation:",
    qualification_total
)

print("Raw enterprise MDE rows searched:", 0)
print("Fuzzy matching performed:", "NO")
print("IP-only matching performed:", "NO")
print("Original MDE classifications changed:", "NO")
print("Assurance cases changed:", "NO")
print("Customer routing changed:", "NO")
print("Delta tables written:", 0)

print()
print(
    "Next gate: perform a bounded enterprise MDE lookup for ONLY "
    "the trusted multi-source exact-name candidates."
)

print("=" * 120)

# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 7 v2.0 - Enterprise MDE Identity Source Strategy Preflight
#
# Replaces:
#   Cell 7 v1.0 - Bounded Enterprise MDE Rediscovery
#
# Why v1 was rejected:
#   - The downstream raw-enterprise MDE lookup exhausted Spark resources.
#   - The approved RCAIP MDE normalizer contract prohibits a second
#     downstream raw-source join in production.
#   - Small Post candidate populations must not trigger repeated enterprise-
#     scale raw scans.
#
# Purpose:
#   Determine whether an existing enterprise/current MDE identity product can
#   support RCAIP rediscovery BEFORE designing any new source processing.
#
# Method:
#   1. Read current Post/run MDE_NORM only to recover governed source lineage.
#   2. Read the already-built Discovery 001 TABLE CATALOG.
#   3. Read the already-built Discovery 001 COLUMN CATALOG.
#   4. Identify MDE / Defender / DeviceInfo candidate products.
#   5. Characterize identity, temporal, MachineGroup, tag, and location fields.
#   6. Compare candidates with the source currently feeding MDE_NORM.
#
# IMPORTANT:
#   - NO enterprise source rows are read.
#   - NO raw MDE tables are loaded.
#   - NO candidate identity matching is performed.
#   - NO Cell 6 candidate population is required.
#   - NO Delta writes.
#
# Post-agnostic contract:
#   This source must run unchanged for the active RCAIP Post.
# ============================================================================

from functools import reduce

from pyspark.sql import functions as F
from pyspark.sql import types as T


# ---------------------------------------------------------------------------
# 1. Runtime validation
# ---------------------------------------------------------------------------

required_runtime_objects = [
    "RCAIP_CONFIG_000_READY",
    "RCAIP_POST_NAME",
    "RCAIP_POST_SLUG",
    "RCAIP_RESULTS_NAMESPACE",
    "RCAIP_RUN_ID",
    "RCAIP_TABLES",
    "RCAIP_TABLE_REGISTRY",
    "get_rcaip_table",
    "rcaip_table",
]


missing_runtime_objects = [
    object_name
    for object_name in required_runtime_objects
    if object_name not in globals()
]


if missing_runtime_objects:
    raise RuntimeError(
        "Cell 7 v2.0 requires Config 001 runtime. Missing: "
        + " | ".join(missing_runtime_objects)
    )


if not RCAIP_CONFIG_000_READY:
    raise RuntimeError(
        "Config 000 did not publish a ready runtime."
    )


if not callable(get_rcaip_table):
    raise TypeError(
        "get_rcaip_table must be callable."
    )


if not callable(rcaip_table):
    raise TypeError(
        "rcaip_table must be callable."
    )


print("=" * 120)
print("RCAIP DIAG 001 - CELL 7 v2.0")
print("ENTERPRISE MDE IDENTITY SOURCE STRATEGY PREFLIGHT")
print("=" * 120)
print("Post:", RCAIP_POST_NAME)
print("Post slug:", RCAIP_POST_SLUG)
print("Run ID:", RCAIP_RUN_ID)
print()


# ---------------------------------------------------------------------------
# 2. Resolve durable Discovery 001 metadata products
#
# These are Post-scoped metadata products created by Discovery 001.
# They describe enterprise tables and columns without requiring source-row
# reads in this diagnostic.
# ---------------------------------------------------------------------------

DISCOVERY_TABLE_CATALOG = rcaip_table(
    "discovery_001_table_catalog"
)

DISCOVERY_COLUMN_CATALOG = rcaip_table(
    "discovery_001_column_catalog"
)


for metadata_table in [
    DISCOVERY_TABLE_CATALOG,
    DISCOVERY_COLUMN_CATALOG,
]:
    if not spark.catalog.tableExists(metadata_table):
        raise RuntimeError(
            "Required Discovery 001 metadata product does not exist: "
            + metadata_table
        )


table_catalog_df = (
    spark.table(
        DISCOVERY_TABLE_CATALOG
    )
)


column_catalog_df = (
    spark.table(
        DISCOVERY_COLUMN_CATALOG
    )
)


table_catalog_count = (
    table_catalog_df.count()
)


column_catalog_count = (
    column_catalog_df.count()
)


# ---------------------------------------------------------------------------
# 3. Resolve current Post/run MDE_NORM
#
# MDE_NORM is intentionally small and Post-scoped.
# We use it ONLY to recover governed raw-source lineage.
# ---------------------------------------------------------------------------

MDE_NORM_TABLE = get_rcaip_table(
    "MDE_NORM"
)


if not spark.catalog.tableExists(
    MDE_NORM_TABLE
):
    raise RuntimeError(
        "MDE_NORM does not exist: "
        + MDE_NORM_TABLE
    )


mde_norm_columns = set(
    spark.table(
        MDE_NORM_TABLE
    ).columns
)


required_mde_norm_columns = {
    "post_slug",
    "rcaip_run_id",
    "raw_source_table",
}


missing_mde_norm_columns = sorted(
    required_mde_norm_columns
    -
    mde_norm_columns
)


if missing_mde_norm_columns:
    raise RuntimeError(
        "MDE_NORM is missing required lineage columns: "
        + " | ".join(
            missing_mde_norm_columns
        )
    )


mde_norm_current_df = (
    spark.table(
        MDE_NORM_TABLE
    )

    .filter(
        (
            F.lower(
                F.trim(
                    F.col(
                        "post_slug"
                    )
                )
            )
            ==
            F.lit(
                str(
                    RCAIP_POST_SLUG
                ).strip().lower()
            )
        )
        &
        (
            F.col(
                "rcaip_run_id"
            )
            ==
            F.lit(
                RCAIP_RUN_ID
            )
        )
    )
)


mde_norm_current_count = (
    mde_norm_current_df.count()
)


if mde_norm_current_count == 0:
    raise RuntimeError(
        "Current Post/run MDE_NORM contains zero rows."
    )


mde_raw_lineage_rows = (
    mde_norm_current_df

    .select(
        F.trim(
            F.col(
                "raw_source_table"
            )
        ).alias(
            "raw_source_table"
        )
    )

    .filter(
        F.col(
            "raw_source_table"
        ).isNotNull()
        &
        (
            F.length(
                F.col(
                    "raw_source_table"
                )
            )
            >
            F.lit(0)
        )
    )

    .distinct()

    .collect()
)


mde_raw_lineage_sources = sorted({
    row[
        "raw_source_table"
    ]
    for row in mde_raw_lineage_rows
})


if not mde_raw_lineage_sources:
    raise RuntimeError(
        "Current MDE_NORM contains no governed raw_source_table lineage."
    )


# ---------------------------------------------------------------------------
# 4. Inventory any MDE / Defender-related Config 001 registry bindings
#
# Pure Python inspection of the already-loaded Config 001 registry.
# ---------------------------------------------------------------------------

MDE_SEARCH_MARKERS = [
    "mde",
    "defender",
    "deviceinfo",
    "device_info",
    "machinegroup",
    "machine_group",
    "advancedhunting",
    "advanced_hunting",
]


registry_candidate_rows = []


for (
    logical_name,
    registry_entry,
) in RCAIP_TABLE_REGISTRY.items():

    registry_entry = dict(
        registry_entry
    )

    searchable_registry_text = " ".join([
        str(
            logical_name
            or
            ""
        ),

        str(
            registry_entry.get(
                "physical_table_name"
            )
            or
            ""
        ),

        str(
            registry_entry.get(
                "scope"
            )
            or
            ""
        ),

        str(
            registry_entry.get(
                "layer"
            )
            or
            ""
        ),

        str(
            registry_entry.get(
                "domain"
            )
            or
            ""
        ),

        str(
            registry_entry.get(
                "source_name"
            )
            or
            ""
        ),

        str(
            registry_entry.get(
                "source_system"
            )
            or
            ""
        ),

        str(
            registry_entry.get(
                "description"
            )
            or
            ""
        ),
    ]).lower()


    if any(
        marker in searchable_registry_text
        for marker in MDE_SEARCH_MARKERS
    ):

        registry_candidate_rows.append(
            (
                str(
                    logical_name
                ),

                str(
                    registry_entry.get(
                        "physical_table_name"
                    )
                    or
                    ""
                ),

                str(
                    registry_entry.get(
                        "scope"
                    )
                    or
                    ""
                ),

                str(
                    registry_entry.get(
                        "layer"
                    )
                    or
                    ""
                ),

                str(
                    registry_entry.get(
                        "domain"
                    )
                    or
                    ""
                ),

                str(
                    registry_entry.get(
                        "description"
                    )
                    or
                    ""
                ),
            )
        )


registry_schema = T.StructType([
    T.StructField(
        "logical_name",
        T.StringType(),
        False,
    ),

    T.StructField(
        "physical_table_name",
        T.StringType(),
        False,
    ),

    T.StructField(
        "scope",
        T.StringType(),
        False,
    ),

    T.StructField(
        "layer",
        T.StringType(),
        False,
    ),

    T.StructField(
        "domain",
        T.StringType(),
        False,
    ),

    T.StructField(
        "description",
        T.StringType(),
        False,
    ),
])


mde_registry_candidates_df = (
    spark.createDataFrame(
        registry_candidate_rows,
        schema=registry_schema,
    )

    .orderBy(
        "logical_name"
    )
)


registry_candidate_count = (
    mde_registry_candidates_df.count()
)


print("=" * 120)
print("MDE / DEFENDER CONFIG 001 REGISTRY CANDIDATES")
print("=" * 120)

display(
    mde_registry_candidates_df
)


# ---------------------------------------------------------------------------
# 5. Identify MDE / Defender candidate tables from durable Discovery metadata
# ---------------------------------------------------------------------------

searchable_table_columns = [
    column_name
    for column_name in [
        "catalog_name",
        "schema_name",
        "table_name",
        "full_table_name",
        "primary_domain",
        "secondary_domain",
        "recommended_work_package",
        "recommended_rcaip_use",
        "asset_identifier_columns",
        "timestamp_columns",
        "post_mapping_columns",
        "security_control_columns",
    ]
    if column_name
    in table_catalog_df.columns
]


if not searchable_table_columns:
    raise RuntimeError(
        "Discovery 001 table catalog exposes no searchable metadata columns."
    )


table_search_text = F.lower(
    F.concat_ws(
        " ",
        *[
            F.coalesce(
                F.col(
                    column_name
                ).cast(
                    "string"
                ),
                F.lit(
                    ""
                )
            )
            for column_name
            in searchable_table_columns
        ]
    )
)


mde_marker_conditions = [
    table_search_text.contains(
        marker
    )
    for marker in MDE_SEARCH_MARKERS
]


mde_candidate_filter = reduce(
    lambda left_condition, right_condition:
        left_condition
        |
        right_condition,

    mde_marker_conditions
)


mde_metadata_table_df = (
    table_catalog_df

    .filter(
        mde_candidate_filter
    )

    .dropDuplicates([
        "full_table_name"
    ])

    .cache()
)


mde_metadata_table_count = (
    mde_metadata_table_df.count()
)


if mde_metadata_table_count == 0:
    raise RuntimeError(
        "Discovery 001 metadata contains no MDE / Defender candidate tables."
    )


# ---------------------------------------------------------------------------
# 6. Restrict column metadata to candidate MDE tables
# ---------------------------------------------------------------------------

mde_candidate_table_names_df = (
    mde_metadata_table_df

    .select(
        "full_table_name"
    )

    .distinct()
)


mde_candidate_columns_df = (
    column_catalog_df

    .join(
        F.broadcast(
            mde_candidate_table_names_df
        ),
        on="full_table_name",
        how="inner",
    )

    .withColumn(
        "_column_norm",

        F.lower(
            F.regexp_replace(
                F.col(
                    "column_name"
                ),
                r"[^a-zA-Z0-9]+",
                ""
            )
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 7. Define reusable MDE identity-field semantics
#
# These are source-field semantics, not Post-specific logic.
# ---------------------------------------------------------------------------

DEVICE_ID_NAMES = [
    "deviceid",
]


AAD_DEVICE_ID_NAMES = [
    "aaddeviceid",
]


HARDWARE_UUID_NAMES = [
    "hardwareuuid",
]


DEVICE_NAME_NAMES = [
    "devicename",
    "dvchostname",
    "hostname",
]


MACHINE_GROUP_NAMES = [
    "machinegroup",
]


TEMPORAL_PRIORITY_NAMES = [
    "lastseentime",
    "lastseen",
    "lastseendatetime",
    "timestamp",
    "timegenerated",
    "eventtime",
]


TAG_MARKERS = [
    "tag",
]


LOCATION_MARKERS = [
    "site",
    "location",
    "machinegroup",
]


# ---------------------------------------------------------------------------
# 8. Characterize candidate tables from metadata only
# ---------------------------------------------------------------------------

mde_field_profile_df = (
    mde_candidate_columns_df

    .groupBy(
        "full_table_name"
    )

    .agg(
        F.max(
            F.when(
                F.col(
                    "_column_norm"
                ).isin(
                    DEVICE_ID_NAMES
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "has_device_id"
        ),

        F.max(
            F.when(
                F.col(
                    "_column_norm"
                ).isin(
                    AAD_DEVICE_ID_NAMES
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "has_aad_device_id"
        ),

        F.max(
            F.when(
                F.col(
                    "_column_norm"
                ).isin(
                    HARDWARE_UUID_NAMES
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "has_hardware_uuid"
        ),

        F.max(
            F.when(
                F.col(
                    "_column_norm"
                ).isin(
                    DEVICE_NAME_NAMES
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "has_device_name"
        ),

        F.max(
            F.when(
                F.col(
                    "_column_norm"
                ).isin(
                    MACHINE_GROUP_NAMES
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "has_machine_group"
        ),

        F.max(
            F.when(
                (
                    F.col(
                        "_column_norm"
                    ).isin(
                        TEMPORAL_PRIORITY_NAMES
                    )
                )
                |
                (
                    F.upper(
                        F.coalesce(
                            F.col(
                                "is_timestamp"
                            ),
                            F.lit(
                                "N"
                            )
                        )
                    )
                    ==
                    F.lit(
                        "Y"
                    )
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "has_temporal_evidence"
        ),

        F.max(
            F.when(
                reduce(
                    lambda left_condition, right_condition:
                        left_condition
                        |
                        right_condition,

                    [
                        F.col(
                            "_column_norm"
                        ).contains(
                            marker
                        )
                        for marker
                        in TAG_MARKERS
                    ]
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "has_tag_evidence"
        ),

        F.max(
            F.when(
                reduce(
                    lambda left_condition, right_condition:
                        left_condition
                        |
                        right_condition,

                    [
                        F.col(
                            "_column_norm"
                        ).contains(
                            marker
                        )
                        for marker
                        in LOCATION_MARKERS
                    ]
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "has_location_or_group_evidence"
        ),

        F.concat_ws(
            ", ",

            F.sort_array(
                F.collect_set(
                    F.when(
                        F.col(
                            "_column_norm"
                        ).isin(
                            DEVICE_ID_NAMES
                            +
                            AAD_DEVICE_ID_NAMES
                            +
                            HARDWARE_UUID_NAMES
                            +
                            DEVICE_NAME_NAMES
                        ),

                        F.col(
                            "column_name"
                        )
                    )
                )
            )
        ).alias(
            "identity_columns"
        ),

        F.concat_ws(
            ", ",

            F.sort_array(
                F.collect_set(
                    F.when(
                        (
                            F.col(
                                "_column_norm"
                            ).isin(
                                TEMPORAL_PRIORITY_NAMES
                            )
                        )
                        |
                        (
                            F.upper(
                                F.coalesce(
                                    F.col(
                                        "is_timestamp"
                                    ),
                                    F.lit(
                                        "N"
                                    )
                                )
                            )
                            ==
                            F.lit(
                                "Y"
                            )
                        ),

                        F.col(
                            "column_name"
                        )
                    )
                )
            )
        ).alias(
            "temporal_columns"
        ),

        F.concat_ws(
            ", ",

            F.sort_array(
                F.collect_set(
                    F.when(
                        F.col(
                            "_column_norm"
                        ).contains(
                            "machinegroup"
                        ),

                        F.col(
                            "column_name"
                        )
                    )
                )
            )
        ).alias(
            "machine_group_columns"
        ),

        F.concat_ws(
            ", ",

            F.sort_array(
                F.collect_set(
                    F.when(
                        F.col(
                            "_column_norm"
                        ).contains(
                            "tag"
                        ),

                        F.col(
                            "column_name"
                        )
                    )
                )
            )
        ).alias(
            "tag_columns"
        ),
    )
)


# ---------------------------------------------------------------------------
# 9. Registry physical-table lookup
# ---------------------------------------------------------------------------

registry_by_physical_df = (
    mde_registry_candidates_df

    .filter(
        F.length(
            F.trim(
                F.col(
                    "physical_table_name"
                )
            )
        )
        >
        F.lit(0)
    )

    .withColumn(
        "_physical_table_norm",

        F.lower(
            F.trim(
                F.col(
                    "physical_table_name"
                )
            )
        )
    )

    .groupBy(
        "_physical_table_norm"
    )

    .agg(
        F.concat_ws(
            ", ",

            F.sort_array(
                F.collect_set(
                    "logical_name"
                )
            )
        ).alias(
            "config001_logical_names"
        )
    )
)


# ---------------------------------------------------------------------------
# 10. Combine table metadata + field profile + registry + current lineage
# ---------------------------------------------------------------------------

current_raw_source_norms = [
    str(
        raw_source
    ).strip().lower()
    for raw_source in mde_raw_lineage_sources
]


mde_identity_source_candidates_df = (
    mde_metadata_table_df

    .join(
        mde_field_profile_df,
        on="full_table_name",
        how="left",
    )

    .withColumn(
        "_full_table_name_norm",

        F.lower(
            F.trim(
                F.col(
                    "full_table_name"
                )
            )
        )
    )

    .join(
        registry_by_physical_df,

        F.col(
            "_full_table_name_norm"
        )
        ==
        F.col(
            "_physical_table_norm"
        ),

        how="left",
    )

    .drop(
        "_physical_table_norm"
    )

    .fillna({
        "has_device_id": 0,
        "has_aad_device_id": 0,
        "has_hardware_uuid": 0,
        "has_device_name": 0,
        "has_machine_group": 0,
        "has_temporal_evidence": 0,
        "has_tag_evidence": 0,
        "has_location_or_group_evidence": 0,
        "identity_columns": "",
        "temporal_columns": "",
        "machine_group_columns": "",
        "tag_columns": "",
        "config001_logical_names": "",
    })

    .withColumn(
        "is_current_mde_norm_raw_source",

        F.when(
            F.col(
                "_full_table_name_norm"
            ).isin(
                current_raw_source_norms
            ),

            F.lit(
                "YES"
            )
        )

        .otherwise(
            F.lit(
                "NO"
            )
        )
    )

    .withColumn(
        "identity_preflight_score",

        (
            F.col(
                "has_device_id"
            )
            *
            F.lit(5)
        )
        +
        (
            F.col(
                "has_aad_device_id"
            )
            *
            F.lit(4)
        )
        +
        (
            F.col(
                "has_hardware_uuid"
            )
            *
            F.lit(3)
        )
        +
        (
            F.col(
                "has_device_name"
            )
            *
            F.lit(5)
        )
        +
        (
            F.col(
                "has_machine_group"
            )
            *
            F.lit(2)
        )
        +
        (
            F.col(
                "has_temporal_evidence"
            )
            *
            F.lit(4)
        )
        +
        (
            F.col(
                "has_tag_evidence"
            )
            *
            F.lit(1)
        )
        +
        (
            F.col(
                "has_location_or_group_evidence"
            )
            *
            F.lit(1)
        )
    )

    .withColumn(
        "size_gib",

        F.when(
            F.col(
                "size_in_bytes"
            ).isNotNull(),

            F.round(
                F.col(
                    "size_in_bytes"
                )
                /
                F.lit(
                    1024.0
                    *
                    1024.0
                    *
                    1024.0
                ),
                3,
            )
        )
    )

    .orderBy(
        F.desc(
            "identity_preflight_score"
        ),

        F.desc(
            "is_current_mde_norm_raw_source"
        ),

        "full_table_name",
    )

    .cache()
)


mde_identity_candidate_count = (
    mde_identity_source_candidates_df.count()
)


# ---------------------------------------------------------------------------
# 11. Current governed MDE_NORM lineage summary
# ---------------------------------------------------------------------------

lineage_schema = T.StructType([
    T.StructField(
        "mde_norm_table",
        T.StringType(),
        False,
    ),

    T.StructField(
        "current_post_run_normalized_rows",
        T.LongType(),
        False,
    ),

    T.StructField(
        "raw_source_table",
        T.StringType(),
        False,
    ),
])


mde_norm_lineage_summary_df = (
    spark.createDataFrame(
        [
            (
                str(
                    MDE_NORM_TABLE
                ),
                int(
                    mde_norm_current_count
                ),
                str(
                    raw_source
                ),
            )
            for raw_source
            in mde_raw_lineage_sources
        ],
        schema=lineage_schema,
    )
)


print()
print("=" * 120)
print("CURRENT MDE_NORM - GOVERNED SOURCE LINEAGE")
print("=" * 120)

display(
    mde_norm_lineage_summary_df
)


# ---------------------------------------------------------------------------
# 12. Ranked candidate source summary
# ---------------------------------------------------------------------------

candidate_display_columns = [
    column_name
    for column_name in [
        "full_table_name",
        "catalog_name",
        "schema_name",
        "table_name",
        "is_current_mde_norm_raw_source",
        "config001_logical_names",

        "identity_preflight_score",

        "has_device_id",
        "has_aad_device_id",
        "has_hardware_uuid",
        "has_device_name",
        "has_machine_group",
        "has_temporal_evidence",
        "has_tag_evidence",
        "has_location_or_group_evidence",

        "identity_columns",
        "temporal_columns",
        "machine_group_columns",
        "tag_columns",

        "column_count",
        "num_files",
        "size_gib",
        "table_format",
        "detail_status",

        "primary_domain",
        "candidate_priority",
        "candidate_score",
        "recommended_work_package",
        "recommended_rcaip_use",
    ]
    if column_name
    in mde_identity_source_candidates_df.columns
]


print()
print("=" * 120)
print("ENTERPRISE MDE IDENTITY SOURCE CANDIDATES - METADATA ONLY")
print("=" * 120)

display(
    mde_identity_source_candidates_df

    .select(
        *candidate_display_columns
    )
)


# ---------------------------------------------------------------------------
# 13. Relevant field detail
#
# Display only identity / temporal / group / tag / mapping-oriented columns.
# Still Discovery 001 metadata only.
# ---------------------------------------------------------------------------

relevant_column_condition = (
    F.col(
        "_column_norm"
    ).isin(
        DEVICE_ID_NAMES
        +
        AAD_DEVICE_ID_NAMES
        +
        HARDWARE_UUID_NAMES
        +
        DEVICE_NAME_NAMES
        +
        MACHINE_GROUP_NAMES
        +
        TEMPORAL_PRIORITY_NAMES
    )
    |
    F.col(
        "_column_norm"
    ).contains(
        "tag"
    )
    |
    F.col(
        "_column_norm"
    ).contains(
        "site"
    )
    |
    F.col(
        "_column_norm"
    ).contains(
        "location"
    )
    |
    (
        F.upper(
            F.coalesce(
                F.col(
                    "is_asset_identifier"
                ),
                F.lit(
                    "N"
                )
            )
        )
        ==
        F.lit(
            "Y"
        )
    )
    |
    (
        F.upper(
            F.coalesce(
                F.col(
                    "is_timestamp"
                ),
                F.lit(
                    "N"
                )
            )
        )
        ==
        F.lit(
            "Y"
        )
    )
    |
    (
        F.upper(
            F.coalesce(
                F.col(
                    "is_post_mapping"
                ),
                F.lit(
                    "N"
                )
            )
        )
        ==
        F.lit(
            "Y"
        )
    )
)


mde_identity_field_detail_df = (
    mde_candidate_columns_df

    .filter(
        relevant_column_condition
    )

    .select(
        "full_table_name",
        "ordinal_position",
        "column_name",
        "data_type",
        "rcaip_roles",
        "is_asset_identifier",
        "is_timestamp",
        "is_post_mapping",
    )

    .orderBy(
        "full_table_name",
        "ordinal_position",
    )
)


relevant_field_count = (
    mde_identity_field_detail_df.count()
)


print()
print("=" * 120)
print("ENTERPRISE MDE CANDIDATE - IDENTITY / TEMPORAL FIELD DETAIL")
print("=" * 120)

display(
    mde_identity_field_detail_df
)


# ---------------------------------------------------------------------------
# 14. Certification metrics
# ---------------------------------------------------------------------------

candidates_with_device_id = (
    mde_identity_source_candidates_df

    .filter(
        F.col(
            "has_device_id"
        )
        ==
        F.lit(1)
    )

    .count()
)


candidates_with_device_name = (
    mde_identity_source_candidates_df

    .filter(
        F.col(
            "has_device_name"
        )
        ==
        F.lit(1)
    )

    .count()
)


candidates_with_temporal = (
    mde_identity_source_candidates_df

    .filter(
        F.col(
            "has_temporal_evidence"
        )
        ==
        F.lit(1)
    )

    .count()
)


candidates_with_identity_and_time = (
    mde_identity_source_candidates_df

    .filter(
        (
            F.col(
                "has_device_name"
            )
            ==
            F.lit(1)
        )
        &
        (
            F.col(
                "has_temporal_evidence"
            )
            ==
            F.lit(1)
        )
        &
        (
            (
                F.col(
                    "has_device_id"
                )
                ==
                F.lit(1)
            )
            |
            (
                F.col(
                    "has_aad_device_id"
                )
                ==
                F.lit(1)
            )
            |
            (
                F.col(
                    "has_hardware_uuid"
                )
                ==
                F.lit(1)
            )
        )
    )

    .count()
)


current_raw_source_matches = (
    mde_identity_source_candidates_df

    .filter(
        F.col(
            "is_current_mde_norm_raw_source"
        )
        ==
        F.lit(
            "YES"
        )
    )

    .count()
)


