# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 9 - Durable MDE Rediscovery Resolution and Cohort Profile
# Version: 1.0
#
# Purpose:
#   Adopt the existing current-run durable MDE rediscovery products as the
#   analytical authority and determine what they already establish about the
#   MDE-MISSING population.
#
# Questions:
#   1. Which assets were eligible/searched?
#   2. How many have enterprise MDE name evidence?
#   3. How many resolve to durable MDE identities?
#   4. How much evidence is current, stale, or historical?
#   5. Where do collisions or ambiguous identities remain?
#   6. What explanatory cohorts already exist in the durable enrichment?
#
# IMPORTANT:
#   This cell DOES NOT create a new rediscovery classification.
#   It profiles classifications and evidence already persisted by RCAIP.
#
# Existing routing/treatment fields are retained as prior analytical context
# only. They are NOT accepted here as final customer routing.
#
# Architecture:
#   Durable RCAIP products only.
#   No raw enterprise MDE.
#   No Cell 6 rebuild.
#   Post-agnostic source.
#
# Safety:
#   - READ ONLY
#   - No raw enterprise source scans
#   - No identity matching
#   - No fuzzy matching
#   - No IP-only matching
#   - No original classification changes
#   - No assurance cases created
#   - No routing changes
#   - No Delta writes
# ============================================================================

from pyspark.sql import functions as F


# ---------------------------------------------------------------------------
# 1. Runtime validation
# ---------------------------------------------------------------------------

REQUIRED_RUNTIME_OBJECTS = [
    "RCAIP_CONFIG_000_READY",
    "RCAIP_POST_NAME",
    "RCAIP_POST_SLUG",
    "RCAIP_RUN_ID",
    "RCAIP_TABLES",
    "get_rcaip_table",
]


missing_runtime_objects = [
    name
    for name in REQUIRED_RUNTIME_OBJECTS
    if name not in globals()
]


if missing_runtime_objects:
    raise RuntimeError(
        "Cell 9 requires Config 001 runtime. Missing: "
        + " | ".join(missing_runtime_objects)
    )


if not RCAIP_CONFIG_000_READY:
    raise RuntimeError(
        "Config 000 did not publish a ready runtime."
    )


# ---------------------------------------------------------------------------
# 2. Resolve durable MDE rediscovery products
# ---------------------------------------------------------------------------

SEARCH_INPUT_TABLE = get_rcaip_table(
    "IP006_MDE_REDISCOVERY_SEARCH_INPUT"
)

ENTITY_EVIDENCE_TABLE = get_rcaip_table(
    "IP006_MDE_REDISCOVERY_ENTITY_EVIDENCE"
)

ENRICHMENT_TABLE = get_rcaip_table(
    "IP006_MDE_REDISCOVERY_ENRICHMENT"
)


for required_table in [
    SEARCH_INPUT_TABLE,
    ENTITY_EVIDENCE_TABLE,
    ENRICHMENT_TABLE,
]:
    if not spark.catalog.tableExists(required_table):
        raise RuntimeError(
            "Required durable MDE rediscovery table is unavailable: "
            + required_table
        )


# ---------------------------------------------------------------------------
# 3. Exact current Post/run slices
# ---------------------------------------------------------------------------

def current_runtime_slice(table_name):

    source_df = spark.table(
        table_name
    )

    required_columns = {
        "post_slug",
        "rcaip_run_id",
    }

    missing_columns = (
        required_columns
        -
        set(source_df.columns)
    )

    if missing_columns:
        raise RuntimeError(
            table_name
            + " is missing runtime provenance columns: "
            + " | ".join(
                sorted(
                    missing_columns
                )
            )
        )

    return (
        source_df

        .filter(
            (
                F.lower(
                    F.trim(
                        F.col(
                            "post_slug"
                        )
                    )
                )
                ==
                F.lit(
                    str(
                        RCAIP_POST_SLUG
                    ).strip().lower()
                )
            )
            &
            (
                F.col(
                    "rcaip_run_id"
                )
                ==
                F.lit(
                    RCAIP_RUN_ID
                )
            )
        )
    )


search_input_df = (
    current_runtime_slice(
        SEARCH_INPUT_TABLE
    )
    .cache()
)


entity_evidence_df = (
    current_runtime_slice(
        ENTITY_EVIDENCE_TABLE
    )
    .cache()
)


enrichment_df = (
    current_runtime_slice(
        ENRICHMENT_TABLE
    )
    .cache()
)


# ---------------------------------------------------------------------------
# 4. Required durable enrichment contract
# ---------------------------------------------------------------------------

REQUIRED_ENRICHMENT_COLUMNS = [
    "asset_key",

    "search_eligibility_class",
    "search_eligible",
    "search_attempted",

    "enterprise_mde_name_evidence_found",

    "authoritative_match_tier",
    "durable_identity_class",

    "resolved_mde_entity_count",
    "current_mde_entity_count",
    "stale_mde_entity_count",
    "historical_mde_entity_count",

    "rediscovery_current_indicated",
    "rediscovery_stale_indicated",
    "rediscovery_historical_indicated",

    "latest_rediscovered_mde_recency",

    "rediscovery_visibility_class",
    "rediscovery_analytical_interpretation",
    "rediscovery_review_required",

    "candidate_aad_device_id_collision",
    "candidate_hardware_uuid_collision",

    "full_aad_device_id_convergence",
    "partial_aad_device_id_convergence",

    "full_durable_lineage",
    "partial_durable_lineage",

    "selected_source_family_count",

    "management_owner",
    "lifecycle_case_state",

    "case_treatment",
    "case_primary_customer",

    "review_priority",

    "original_classification_preserved",
    "priority_changed",

    "fuzzy_matching_allowed",
    "ip_only_matching_allowed",
    "identity_matching_mode",
]


missing_enrichment_columns = [
    column_name
    for column_name in REQUIRED_ENRICHMENT_COLUMNS
    if column_name not in enrichment_df.columns
]


if missing_enrichment_columns:
    raise RuntimeError(
        "Durable MDE enrichment contract is missing columns: "
        + " | ".join(
            missing_enrichment_columns
        )
    )


REQUIRED_ENTITY_COLUMNS = [
    "asset_key",
    "mde_entity_id",
    "mde_entity_resolution_state",
    "entity_match_basis",
    "latest_mde_timestamp",
]


missing_entity_columns = [
    column_name
    for column_name in REQUIRED_ENTITY_COLUMNS
    if column_name not in entity_evidence_df.columns
]


if missing_entity_columns:
    raise RuntimeError(
        "Durable MDE entity-evidence contract is missing columns: "
        + " | ".join(
            missing_entity_columns
        )
    )


# ---------------------------------------------------------------------------
# 5. Exact population reconciliation
# ---------------------------------------------------------------------------

search_rows = (
    search_input_df.count()
)

search_asset_keys = (
    search_input_df
    .select(
        "asset_key"
    )
    .distinct()
    .count()
)


search_duplicate_assets = (
    search_input_df

    .groupBy(
        "asset_key"
    )

    .count()

    .filter(
        F.col(
            "count"
        )
        >
        F.lit(
            1
        )
    )

    .count()
)


enrichment_rows = (
    enrichment_df.count()
)

enrichment_asset_keys = (
    enrichment_df
    .select(
        "asset_key"
    )
    .distinct()
    .count()
)


enrichment_duplicate_assets = (
    enrichment_df

    .groupBy(
        "asset_key"
    )

    .count()

    .filter(
        F.col(
            "count"
        )
        >
        F.lit(
            1
        )
    )

    .count()
)


search_missing_from_enrichment = (
    search_input_df

    .select(
        "asset_key"
    )

    .distinct()

    .join(
        enrichment_df
        .select(
            "asset_key"
        )
        .distinct(),

        on="asset_key",
        how="left_anti",
    )

    .count()
)


unexpected_enrichment_assets = (
    enrichment_df

    .select(
        "asset_key"
    )

    .distinct()

    .join(
        search_input_df
        .select(
            "asset_key"
        )
        .distinct(),

        on="asset_key",
        how="left_anti",
    )

    .count()
)


entity_evidence_rows = (
    entity_evidence_df.count()
)


entity_evidence_asset_keys = (
    entity_evidence_df

    .select(
        "asset_key"
    )

    .distinct()

    .count()
)


distinct_entity_ids = (
    entity_evidence_df

    .select(
        "mde_entity_id"
    )

    .filter(
        F.col(
            "mde_entity_id"
        ).isNotNull()
    )

    .distinct()

    .count()
)


# ---------------------------------------------------------------------------
# 6. Core resolution metrics
# ---------------------------------------------------------------------------

resolution_metrics_row = (
    enrichment_df

    .agg(

        F.count(
            F.lit(1)
        ).alias(
            "mde_missing_assets"
        ),

        F.sum(
            F.when(
                F.col(
                    "search_eligible"
                )
                ==
                F.lit(True),

                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "search_eligible_assets"
        ),

        F.sum(
            F.when(
                F.col(
                    "search_attempted"
                )
                ==
                F.lit(True),

                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "search_attempted_assets"
        ),

        F.sum(
            F.when(
                F.col(
                    "enterprise_mde_name_evidence_found"
                )
                ==
                F.lit(True),

                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_enterprise_mde_name_evidence"
        ),

        F.sum(
            F.when(
                F.coalesce(
                    F.col(
                        "resolved_mde_entity_count"
                    ),
                    F.lit(0)
                )
                >
                F.lit(0),

                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_resolved_mde_entity"
        ),

        F.sum(
            F.when(
                F.coalesce(
                    F.col(
                        "current_mde_entity_count"
                    ),
                    F.lit(0)
                )
                >
                F.lit(0),

                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_current_mde_entity"
        ),

        F.sum(
            F.when(
                F.coalesce(
                    F.col(
                        "stale_mde_entity_count"
                    ),
                    F.lit(0)
                )
                >
                F.lit(0),

                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_stale_mde_entity"
        ),

        F.sum(
            F.when(
                F.coalesce(
                    F.col(
                        "historical_mde_entity_count"
                    ),
                    F.lit(0)
                )
                >
                F.lit(0),

                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_historical_mde_entity"
        ),

        F.sum(
            F.when(
                F.col(
                    "rediscovery_review_required"
                )
                ==
                F.lit(True),

                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "rediscovery_review_required_assets"
        ),

        F.sum(
            F.when(
                F.col(
                    "full_durable_lineage"
                )
                ==
                F.lit(True),

                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "full_durable_lineage_assets"
        ),

        F.sum(
            F.when(
                F.col(
                    "partial_durable_lineage"
                )
                ==
                F.lit(True),

                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "partial_durable_lineage_assets"
        ),

        F.sum(
            F.when(
                F.col(
                    "candidate_aad_device_id_collision"
                )
                ==
                F.lit(True),

                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "aad_device_id_collision_assets"
        ),

        F.sum(
            F.when(
                F.col(
                    "candidate_hardware_uuid_collision"
                )
                ==
                F.lit(True),

                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "hardware_uuid_collision_assets"
        ),
    )

    .collect()[0]
)


resolution_metrics_df = spark.createDataFrame([
    resolution_metrics_row.asDict()
])


print("=" * 120)
print("MDE REDISCOVERY - CORE RESOLUTION METRICS")
print("=" * 120)

display(
    resolution_metrics_df
)


# ---------------------------------------------------------------------------
# 7. Search eligibility profile
# ---------------------------------------------------------------------------

mde_search_eligibility_profile_df = (
    enrichment_df

    .groupBy(
        "search_eligibility_class",
        "search_eligible",
        "search_attempted",
        "identity_matching_mode",
    )

    .agg(
        F.count(
            F.lit(1)
        ).alias(
            "assets"
        )
    )

    .orderBy(
        F.desc(
            "assets"
        ),
        "search_eligibility_class",
    )
)


print()
print("=" * 120)
print("MDE REDISCOVERY - SEARCH ELIGIBILITY")
print("=" * 120)

display(
    mde_search_eligibility_profile_df
)


# ---------------------------------------------------------------------------
# 8. Durable identity / authoritative match profile
# ---------------------------------------------------------------------------

mde_identity_resolution_profile_df = (
    enrichment_df

    .groupBy(
        "enterprise_mde_name_evidence_found",
        "authoritative_match_tier",
        "durable_identity_class",
    )

    .agg(
        F.count(
            F.lit(1)
        ).alias(
            "assets"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "resolved_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "resolved_entity_relationships"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "current_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "current_entities"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "stale_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "stale_entities"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "historical_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "historical_entities"
        ),
    )

    .orderBy(
        F.desc(
            "assets"
        ),
        "authoritative_match_tier",
        "durable_identity_class",
    )
)


print()
print("=" * 120)
print("MDE REDISCOVERY - DURABLE IDENTITY RESOLUTION")
print("=" * 120)

display(
    mde_identity_resolution_profile_df
)


# ---------------------------------------------------------------------------
# 9. Temporal / visibility profile
# ---------------------------------------------------------------------------

mde_temporal_visibility_profile_df = (
    enrichment_df

    .groupBy(
        "rediscovery_visibility_class",
        "latest_rediscovered_mde_recency",
        "rediscovery_current_indicated",
        "rediscovery_stale_indicated",
        "rediscovery_historical_indicated",
    )

    .agg(
        F.count(
            F.lit(1)
        ).alias(
            "assets"
        )
    )

    .orderBy(
        F.desc(
            "assets"
        ),
        "rediscovery_visibility_class",
    )
)


print()
print("=" * 120)
print("MDE REDISCOVERY - TEMPORAL / VISIBILITY PROFILE")
