# ---------------------------------------------------------------------------
# 11. Entity-evidence resolution state and match basis
#
# The runtime rows are evidence relationships, not runtime assets.
# This identifies why that relationship population is large.
# ---------------------------------------------------------------------------

mde_entity_resolution_state_df = (
    entity_evidence_df

    .groupBy(
        "mde_entity_resolution_state",
        "entity_match_basis",
    )

    .agg(
        F.count(
            F.lit(1)
        ).alias(
            "evidence_rows"
        ),

        F.countDistinct(
            "asset_key"
        ).alias(
            "assets"
        ),

        F.countDistinct(
            "mde_entity_id"
        ).alias(
            "distinct_mde_entities"
        ),
    )

    .orderBy(
        F.desc(
            "assets"
        ),
        F.desc(
            "evidence_rows"
        ),
    )
)


print()
