# ---------------------------------------------------------------------------
# 14. Natural explanatory signatures
#
# This is deliberately NOT a case classification.
#
# It groups assets that already share the same persisted rediscovery evidence.
# The next gate will determine which signatures are decision-equivalent and
# may legitimately compress into one assurance case.
# ---------------------------------------------------------------------------

mde_explanatory_signature_df = (
    enrichment_df

    .groupBy(
        "search_eligibility_class",
        "enterprise_mde_name_evidence_found",
        "authoritative_match_tier",
        "durable_identity_class",
        "rediscovery_visibility_class",
        "latest_rediscovered_mde_recency",
        "rediscovery_review_required",
        "rediscovery_analytical_interpretation",
        "management_owner",
        "lifecycle_case_state",
    )

    .agg(
        F.count(
            F.lit(1)
        ).alias(
            "assets"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "resolved_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "resolved_entities"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "current_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "current_entities"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "stale_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "stale_entities"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "historical_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "historical_entities"
        ),
    )

    .orderBy(
        F.desc(
            "assets"
        )
    )
)


