# ---------------------------------------------------------------------------
# 10. Identity lineage + temporal + name continuity profile
# ---------------------------------------------------------------------------

mde_residual_lineage_profile_df = (
    mde_explanation_detail_df

    .groupBy(
        "durable_identity_class",
        "durable_lineage_evidence_pattern",

        "authoritative_match_tier",

        "rediscovery_temporal_pattern",
        "latest_rediscovered_mde_recency",

        "current_vs_historical_name_relationship",

        "full_durable_lineage",
        "partial_durable_lineage",
    )

    .agg(
        F.count(
            F.lit(1)
        ).alias(
            "assets"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "resolved_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "resolved_entities"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "stale_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "stale_entities"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "historical_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "historical_entities"
        ),
    )

    .orderBy(
        F.desc("assets"),
        "durable_identity_class",
    )
)


