current_entity_violations = (
    mde_explanation_detail_df

    .filter(
        F.coalesce(
            F.col(
                "current_mde_entity_count"
            ),
            F.lit(0)
        )
        !=
        F.lit(0)
    )

    .count()
)


non_applicable_violations = (
    mde_explanation_detail_df

    .filter(
        ~F.col(
            "ca_mde_applicability_state"
        ).startswith(
            "APPLICABLE"
        )
    )

    .count()
)


non_enterprise_owner_violations = (
    mde_explanation_detail_df

    .filter(
        ~(
            (
                F.col(
                    "ca_management_model"
                )
                ==
                F.lit(
                    "ENTERPRISE_MANAGED"
                )
            )
            |
            (
                F.col(
                    "ca_management_owner"
                )
                ==
                F.lit(
                    "ENTERPRISE"
                )
            )
        )
    )

    .count()
)


full_hw_convergence_assets = (
    mde_explanation_detail_df

    .filter(
        F.coalesce(
            F.col(
                "full_hardware_uuid_convergence"
            ),
            F.lit(False)
        )
        ==
        F.lit(True)
    )

    .count()
)


single_resolved_entity_assets = (
    mde_explanation_detail_df

    .filter(
        F.coalesce(
            F.col(
                "resolved_mde_entity_count"
            ),
            F.lit(0)
        )
        ==
        F.lit(1)
    )

    .count()
)


exact_full_name_assets = (
    mde_explanation_detail_df

    .filter(
        F.col(
            "current_vs_historical_name_relationship"
        )
        ==
        F.lit(
            "EXACT_FULL_NAME_CONTINUITY"
        )
    )

    .count()
)


exact_short_name_assets = (
    mde_explanation_detail_df

    .filter(
        F.col(
            "current_vs_historical_name_relationship"
        )
        ==
        F.lit(
            "EXACT_SHORT_NAME_CONTINUITY"
        )
    )

    .count()
)


name_variant_assets = (
    mde_explanation_detail_df

    .filter(
        F.col(
            "current_vs_historical_name_relationship"
        )
        ==
        F.lit(
            "NAME_CHANGED_OR_VARIANT"
        )
    )

    .count()
)


machine_group_present_assets = (
    mde_explanation_detail_df

    .filter(
        F.col(
            "latest_rediscovered_mde_machine_group"
        ).isNotNull()
        &
        (
            F.length(
                F.trim(
                    F.col(
                        "latest_rediscovered_mde_machine_group"
                    )
                )
            )
            >
            0
        )
    )

    .count()
)


existing_resolution_signal_count = (
    mde_explanation_detail_df

    .select(
        "final_resolution_signal"
    )

    .distinct()

    .count()
)


