# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 14 - Deterministic Enterprise MDE Assurance-Case Formation
# Version: 1.1
#
# Purpose:
#   Convert ONLY the owner-qualified current enterprise MDE residual
#   population into the smallest defensible deterministic assurance-case set.
#
# Governing principles:
#   - Identity/lifecycle qualification occurs before case formation.
#   - Customer routing occurs before workload counting.
#   - One coherent condition + one coherent treatment = one case.
#   - Supporting related assets are evidence, not automatically case members.
#   - No Post-specific counts, names, CIDRs, or grouping thresholds.
#
# Important:
#   This cell forms DIAGNOSTIC CASE CANDIDATES in memory.
#   It does NOT write production case tables.
#
# Version 1.1 fix:
#   - Explicitly aliases/selects shared identity-token join columns.
#   - Removes ambiguous identity_value reference from v1.0.
#
# Safety:
#   - Durable RCAIP products only
#   - No raw enterprise scans
#   - No new identity matching
#   - No fuzzy matching
#   - No IP-only matching
#   - No findings / tickets / remediation
#   - No Delta writes
# ============================================================================

from functools import reduce

from pyspark.sql import functions as F


# ---------------------------------------------------------------------------
# 1. Runtime validation
# ---------------------------------------------------------------------------

REQUIRED_RUNTIME_OBJECTS = [
    "RCAIP_CONFIG_000_READY",
    "RCAIP_POST_NAME",
    "RCAIP_POST_SLUG",
    "RCAIP_RUN_ID",
    "get_rcaip_table",
]


missing_runtime_objects = [
    name
    for name in REQUIRED_RUNTIME_OBJECTS
    if name not in globals()
]


if missing_runtime_objects:
    raise RuntimeError(
        "Cell 14 requires Config 001 runtime. Missing: "
        + " | ".join(missing_runtime_objects)
    )


if not RCAIP_CONFIG_000_READY:
    raise RuntimeError(
        "Config 000 did not publish a ready runtime."
    )


# ---------------------------------------------------------------------------
# 2. Resolve durable inputs
# ---------------------------------------------------------------------------

REDISCOVERY_TABLE = get_rcaip_table(
    "IP006_MDE_REDISCOVERY_ENRICHMENT"
)


CONTROL_TABLE = get_rcaip_table(
    "IP006_CONTROL_ASSURANCE_EVALUATION"
)


for table_name in [
    REDISCOVERY_TABLE,
    CONTROL_TABLE,
]:
    if not spark.catalog.tableExists(table_name):
        raise RuntimeError(
            "Required durable RCAIP product unavailable: "
            + table_name
        )


rediscovery_source_df = spark.table(
    REDISCOVERY_TABLE
)


control_source_df = spark.table(
    CONTROL_TABLE
)


# ---------------------------------------------------------------------------
# 3. Required schema contracts
# ---------------------------------------------------------------------------

REDISCOVERY_REQUIRED_COLUMNS = {
    "asset_key",
    "post_slug",
    "rcaip_run_id",

    "canonical_name",
    "canonical_serial",
    "canonical_ip",

    "lifecycle_case_state",
    "management_owner",
    "operational_boundary",

    "mde_entity_ids",
    "hardware_uuid_values",
    "aad_device_id_values",
    "merge_target_device_id_values",

    "resolved_mde_entity_count",
    "current_mde_entity_count",
    "stale_mde_entity_count",
    "historical_mde_entity_count",

    "latest_rediscovered_mde_recency",

    "durable_identity_class",

    "latest_rediscovered_mde_entity_id",
    "latest_rediscovered_mde_device_name",
    "latest_rediscovered_mde_machine_group",
    "latest_rediscovered_mde_os_platform",

    "final_resolution_signal",

    "rediscovery_visibility_class",

    "original_classification_preserved",
    "assurance_case_changed",
    "routing_changed",
    "priority_changed",

    "fuzzy_matching_allowed",
    "ip_only_matching_allowed",
}


CONTROL_REQUIRED_COLUMNS = {
    "asset_key",
    "post_slug",
    "rcaip_run_id",

    "tool_name",

    "device_family",
    "device_scope",
    "device_family_confidence",

    "network_scope",

    "operational_boundary",
    "operational_boundary_confidence",

    "management_model",
    "management_owner",

    "identity_basis",
    "identity_strength",

    "source_mask_active",

    "visibility_class",
    "post_visibility_state",

    "attribution_confidence",
    "attribution_conflict_flag",

    "applicability_state",
}


missing_rediscovery_columns = sorted(
    REDISCOVERY_REQUIRED_COLUMNS
    -
    set(rediscovery_source_df.columns)
)


missing_control_columns = sorted(
    CONTROL_REQUIRED_COLUMNS
    -
    set(control_source_df.columns)
)


if missing_rediscovery_columns:
    raise RuntimeError(
        "MDE rediscovery enrichment missing required columns: "
        + " | ".join(missing_rediscovery_columns)
    )


if missing_control_columns:
    raise RuntimeError(
        "MDE Control Assurance evaluation missing required columns: "
        + " | ".join(missing_control_columns)
    )


# ---------------------------------------------------------------------------
# 4. Current Post/run slices
# ---------------------------------------------------------------------------

def runtime_slice(df):

    return (
        df

        .filter(
            (
                F.lower(
                    F.trim(
                        F.col(
                            "post_slug"
                        )
                    )
                )
                ==
                F.lit(
                    str(
                        RCAIP_POST_SLUG
                    ).strip().lower()
                )
            )
            &
            (
                F.col(
                    "rcaip_run_id"
                )
                ==
                F.lit(
                    RCAIP_RUN_ID
                )
            )
        )
    )


rediscovery_df = (
    runtime_slice(
        rediscovery_source_df
    )
    .cache()
)


mde_control_df = (
    runtime_slice(
        control_source_df
    )

    .filter(
        F.upper(
            F.trim(
                F.col(
                    "tool_name"
                )
            )
        )
        ==
        F.lit(
            "MDE"
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 5. Structural certification
# ---------------------------------------------------------------------------

rediscovery_rows = (
    rediscovery_df.count()
)


rediscovery_assets = (
    rediscovery_df

    .select(
        "asset_key"
    )

    .distinct()

    .count()
)


rediscovery_duplicate_assets = (
    rediscovery_df

    .groupBy(
        "asset_key"
    )

    .count()

    .filter(
        F.col(
            "count"
        )
        >
        F.lit(1)
    )

    .count()
)


if rediscovery_rows == 0:
    raise RuntimeError(
        "Current-run MDE rediscovery enrichment contains zero rows."
    )


if rediscovery_rows != rediscovery_assets:
    raise RuntimeError(
        "Durable rediscovery is not one row per asset_key."
    )


if rediscovery_duplicate_assets != 0:
    raise RuntimeError(
        "Durable rediscovery contains duplicate asset_key values."
    )


mde_control_rows = (
    mde_control_df.count()
)


mde_control_assets = (
    mde_control_df

    .select(
        "asset_key"
    )

    .distinct()

    .count()
)


mde_control_duplicate_assets = (
    mde_control_df

    .groupBy(
        "asset_key"
    )

    .count()

    .filter(
        F.col(
            "count"
        )
        >
        F.lit(1)
    )

    .count()
)


if mde_control_rows != mde_control_assets:
    raise RuntimeError(
        "MDE Control Assurance is not one row per asset_key."
    )


if mde_control_duplicate_assets != 0:
    raise RuntimeError(
        "MDE Control Assurance contains duplicate asset_key values."
    )


# ---------------------------------------------------------------------------
# 6. Compact MDE Control Assurance context
# ---------------------------------------------------------------------------

mde_context_df = (
    mde_control_df

    .select(
        "asset_key",

        F.col(
            "device_family"
        ).alias(
            "ca_device_family"
        ),

        F.col(
            "device_scope"
        ).alias(
            "ca_device_scope"
        ),

        F.col(
            "device_family_confidence"
        ).alias(
            "ca_device_family_confidence"
        ),

        F.col(
            "network_scope"
        ).alias(
            "ca_network_scope"
        ),

        F.col(
            "operational_boundary"
        ).alias(
            "ca_operational_boundary"
        ),

        F.col(
            "operational_boundary_confidence"
        ).alias(
            "ca_operational_boundary_confidence"
        ),

        F.col(
            "management_model"
        ).alias(
            "ca_management_model"
        ),

        F.col(
            "management_owner"
        ).alias(
            "ca_management_owner"
        ),

        F.col(
            "identity_basis"
        ).alias(
            "ca_identity_basis"
        ),

        F.col(
            "identity_strength"
        ).alias(
            "ca_identity_strength"
        ),

        F.col(
            "source_mask_active"
        ).alias(
            "ca_source_mask_active"
        ),

        F.col(
            "visibility_class"
        ).alias(
            "ca_visibility_class"
        ),

        F.col(
            "post_visibility_state"
        ).alias(
            "ca_post_visibility_state"
        ),

        F.col(
            "attribution_confidence"
        ).alias(
            "ca_attribution_confidence"
        ),

        F.col(
            "attribution_conflict_flag"
        ).alias(
            "ca_attribution_conflict_flag"
        ),

        F.col(
            "applicability_state"
        ).alias(
            "ca_mde_applicability_state"
        ),
    )
)


# ---------------------------------------------------------------------------
# 7. Attach certified MDE context
# ---------------------------------------------------------------------------

base_df = (
    rediscovery_df

    .join(
        mde_context_df,
        on="asset_key",
        how="inner",
    )

    .cache()
)


base_rows = (
    base_df.count()
)


if base_rows != rediscovery_rows:
    raise RuntimeError(
        "Joining MDE Control Assurance changed the durable rediscovery "
        "population: "
        + str(rediscovery_rows)
        + " -> "
        + str(base_rows)
    )


# ---------------------------------------------------------------------------
# 8. Reconstruct Cell 12/13 residual boundary
#
# No example_post_a counts are hard-coded.
#
# Residual requirements:
#   - currently observed
#   - only stale/historical rediscovered MDE
#   - no current MDE entity
#   - MDE applicable
#   - usable identity
#   - no attribution conflict
#   - high-confidence operational boundary
#   - enterprise managed / owned
# ---------------------------------------------------------------------------

residual_df = (
    base_df

    .filter(
        F.col(
            "lifecycle_case_state"
        )
        ==
        F.lit(
            "CURRENTLY_OBSERVED"
        )
    )

    .filter(
        F.col(
            "rediscovery_visibility_class"
        ).isin(
            "STALE_REDISCOVERY",
            "HISTORICAL_REDISCOVERY",
        )
    )

    .filter(
        F.coalesce(
            F.col(
                "current_mde_entity_count"
            ),
            F.lit(0),
        )
        ==
        F.lit(0)
    )

    .filter(
        F.col(
            "ca_mde_applicability_state"
        ).startswith(
            "APPLICABLE"
        )
    )

    .filter(
        ~F.col(
            "ca_identity_strength"
        ).isin(
            "WEAK",
            "UNKNOWN",
        )
    )

    .filter(
        F.coalesce(
            F.col(
                "ca_attribution_conflict_flag"
            ),
            F.lit(False),
        )
        ==
        F.lit(False)
    )

    .filter(
        F.col(
            "ca_operational_boundary_confidence"
        )
        ==
        F.lit(
            "HIGH"
        )
    )

    .filter(
        (
            F.col(
                "ca_management_model"
            )
            ==
            F.lit(
                "ENTERPRISE_MANAGED"
            )
        )
        |
        (
            F.col(
                "ca_management_owner"
            )
            ==
            F.lit(
                "ENTERPRISE"
            )
        )
    )

    .cache()
)


residual_count = (
    residual_df.count()
)


residual_distinct_assets = (
    residual_df

    .select(
        "asset_key"
    )

    .distinct()

    .count()
)


residual_duplicate_assets = (
    residual_df

    .groupBy(
        "asset_key"
    )

    .count()

    .filter(
        F.col(
            "count"
        )
        >
        F.lit(1)
    )

    .count()
)


if residual_count != residual_distinct_assets:
    raise RuntimeError(
        "Residual MDE candidate boundary is not one row per asset."
    )


if residual_duplicate_assets != 0:
    raise RuntimeError(
        "Residual MDE candidate boundary contains duplicate asset keys."
    )


# ---------------------------------------------------------------------------
# 9. Reconstruct existing durable cross-asset identity relationships
#
# IMPORTANT:
#   This is NOT new identity matching.
#
#   These arrays were already produced by the durable rediscovery layer.
#   Cell 14 only determines whether the same already-governed durable identity
#   value appears against more than one RCAIP asset_key.
# ---------------------------------------------------------------------------

IDENTITY_ARRAYS = [
    (
        "MDE_ENTITY_ID",
        "mde_entity_ids",
    ),
    (
        "HARDWARE_UUID",
        "hardware_uuid_values",
    ),
    (
        "AAD_DEVICE_ID",
        "aad_device_id_values",
    ),
    (
        "MERGE_TARGET_DEVICE_ID",
        "merge_target_device_id_values",
    ),
]


def identity_token_df(
    df,
    identity_type,
    source_column,
):

    return (
        df

        .select(
            "asset_key",

            F.explode_outer(
                F.col(
                    source_column
                )
            ).alias(
                "identity_value"
            ),
        )

        .filter(
            F.col(
                "identity_value"
            ).isNotNull()
        )

        .withColumn(
            "identity_value",

            F.trim(
                F.col(
                    "identity_value"
                ).cast(
                    "string"
                )
            )
        )

        .filter(
            F.length(
                F.col(
                    "identity_value"
                )
            )
            >
            F.lit(0)
        )

        .withColumn(
            "identity_type",

            F.lit(
                identity_type
            )
        )

        .withColumn(
            "identity_value_norm",

            F.lower(
                F.trim(
                    F.col(
                        "identity_value"
                    )
                )
            )
        )

        .select(
            "asset_key",
            "identity_type",
            "identity_value",
            "identity_value_norm",
        )

        .dropDuplicates([
            "asset_key",
            "identity_type",
            "identity_value_norm",
        ])
    )


identity_frames = [
    identity_token_df(
        rediscovery_df,
        identity_type,
        source_column,
    )

    for (
        identity_type,
        source_column,
    )
    in IDENTITY_ARRAYS
]


identity_tokens_df = reduce(
    lambda left_df, right_df:
        left_df.unionByName(
            right_df
        ),

    identity_frames,
).cache()


identity_token_relationship_count = (
    identity_tokens_df.count()
)


# ---------------------------------------------------------------------------
# 10. Profile durable identity values across asset keys
# ---------------------------------------------------------------------------

shared_token_df = (
    identity_tokens_df

    .groupBy(
        "identity_type",
        "identity_value_norm",
    )

    .agg(
        F.first(
            "identity_value",
            ignorenulls=True,
        ).alias(
            "shared_identity_value"
        ),

        F.countDistinct(
            "asset_key"
        ).alias(
            "related_asset_count"
        ),

        F.sort_array(
            F.collect_set(
                "asset_key"
            )
        ).alias(
            "related_asset_keys"
        ),
    )

    .filter(
        F.col(
            "related_asset_count"
        )
        >
        F.lit(1)
    )

    .cache()
)


shared_identity_token_count = (
    shared_token_df.count()
)


# ---------------------------------------------------------------------------
# 11. Explicitly join shared identities back to asset keys
#
# Version 1.1:
#   Use aliases and explicit projection so identity_value exists only once
#   downstream. This fixes the AMBIGUOUS_REFERENCE failure in v1.0.
# ---------------------------------------------------------------------------

shared_relationship_df = (
    identity_tokens_df.alias(
        "token"
    )

    .join(
        shared_token_df.alias(
            "shared"
        ),

        (
            F.col(
                "token.identity_type"
            )
            ==
            F.col(
                "shared.identity_type"
            )
        )
        &
        (
            F.col(
                "token.identity_value_norm"
            )
            ==
            F.col(
                "shared.identity_value_norm"
            )
        ),

        how="inner",
    )

    .select(
        F.col(
            "token.asset_key"
        ).alias(
            "asset_key"
        ),

        F.col(
            "token.identity_type"
        ).alias(
            "identity_type"
        ),

        F.col(
            "token.identity_value_norm"
        ).alias(
            "identity_value_norm"
        ),

        F.col(
            "shared.shared_identity_value"
        ).alias(
            "shared_identity_value"
        ),

        F.col(
            "shared.related_asset_count"
        ).alias(
            "related_asset_count"
        ),

        F.col(
            "shared.related_asset_keys"
        ).alias(
            "related_asset_keys"
        ),
    )
)


# ---------------------------------------------------------------------------
# 12. Asset-level shared durable identity summary
# ---------------------------------------------------------------------------

asset_shared_identity_df = (
    shared_relationship_df

    .groupBy(
        "asset_key"
    )

    .agg(
        F.concat_ws(
            ",",

            F.sort_array(
                F.collect_set(
                    "identity_type"
                )
            )
        ).alias(
            "shared_identity_types"
        ),

        F.concat_ws(
            " || ",

            F.sort_array(
                F.collect_set(
                    F.concat(
                        F.col(
                            "identity_type"
                        ),

                        F.lit(
                            ":"
                        ),

                        F.col(
                            "shared_identity_value"
                        )
                    )
                )
            )
        ).alias(
            "shared_identity_values"
        ),

        F.max(
            F.col(
                "related_asset_count"
            )
        ).alias(
            "maximum_related_assets"
        ),
    )
)


# ---------------------------------------------------------------------------
# 13. Attach cross-asset identity context to residual population
# ---------------------------------------------------------------------------

residual_with_identity_df = (
    residual_df

    .join(
        asset_shared_identity_df,
        on="asset_key",
        how="left",
    )

    .fillna({
        "shared_identity_types": "",
        "shared_identity_values": "",
        "maximum_related_assets": 0,
    })

    .cache()
)


residual_with_identity_rows = (
    residual_with_identity_df.count()
)


if residual_with_identity_rows != residual_count:
    raise RuntimeError(
        "Shared-identity enrichment changed residual population: "
        + str(residual_count)
        + " -> "
        + str(residual_with_identity_rows)
    )


# ---------------------------------------------------------------------------
# 14. Deterministic case-rule assignment
#
# PRECEDENCE:
#
#   1. Cross-asset durable identity reuse
#   2. Stale full durable lineage
#   3. Stale single-entity rediscovery
#   4. Historical single-entity rediscovery
#   5. Model review
#
# OS, MachineGroup, hostname prefix, Post name, and raw member count do NOT
# determine case identity because they do not materially alter treatment.
#
# A future Post may produce an evidence combination not represented here.
# Such rows go to MODEL REVIEW rather than being forced into a example_post_a-derived
# category.
# ---------------------------------------------------------------------------

case_member_df = (
    residual_with_identity_df

    .withColumn(
        "case_rule_key",

        F.when(
            F.length(
                F.trim(
                    F.col(
                        "shared_identity_types"
                    )
                )
            )
            >
            F.lit(0),

            F.concat(
                F.lit(
                    "MDE_CROSS_ASSET_IDENTITY_REUSE::"
                ),

                F.col(
                    "shared_identity_types"
                ),
            )
        )

        .when(
            F.col(
                "final_resolution_signal"
            )
            ==
            F.lit(
                "REDISCOVERED_STALE_FULL_DURABLE_LINEAGE"
            ),

            F.lit(
                "MDE_STALE_FULL_DURABLE_LINEAGE"
            )
        )

        .when(
            F.col(
                "final_resolution_signal"
            )
            ==
            F.lit(
                "REDISCOVERED_STALE_EXACT_SINGLE_ENTITY"
            ),

            F.lit(
                "MDE_STALE_SINGLE_ENTITY_NO_CURRENT_VISIBILITY"
            )
        )

        .when(
            F.col(
                "final_resolution_signal"
            )
            ==
            F.lit(
                "REDISCOVERED_HISTORICAL_EXACT_SINGLE_ENTITY"
            ),

            F.lit(
                "MDE_HISTORICAL_SINGLE_ENTITY_NO_CURRENT_VISIBILITY"
            )
        )

        .otherwise(
            F.lit(
                "MDE_CASE_MODEL_REVIEW_REQUIRED"
            )
        )
    )


    # -----------------------------------------------------------------------
    # Case family
    # -----------------------------------------------------------------------

    .withColumn(
        "case_family",

        F.when(
            F.col(
                "case_rule_key"
            ).startswith(
                "MDE_CROSS_ASSET_IDENTITY_REUSE"
            ),

            F.lit(
                "MDE_IDENTITY_LIFECYCLE_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "case_rule_key"
            )
            ==
            F.lit(
                "MDE_STALE_FULL_DURABLE_LINEAGE"
            ),

            F.lit(
                "MDE_IDENTITY_LIFECYCLE_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "case_rule_key"
            ).isin(
                "MDE_STALE_SINGLE_ENTITY_NO_CURRENT_VISIBILITY",
                "MDE_HISTORICAL_SINGLE_ENTITY_NO_CURRENT_VISIBILITY",
            ),

            F.lit(
                "MDE_CURRENT_VISIBILITY_RECONCILIATION"
            )
        )

        .otherwise(
            F.lit(
                "MODEL_REVIEW"
            )
        )
    )


    # -----------------------------------------------------------------------
    # Relationship outcome
    # -----------------------------------------------------------------------

    .withColumn(
        "relationship_outcome",

        F.when(
            F.col(
                "case_rule_key"
            ).startswith(
                "MDE_CROSS_ASSET_IDENTITY_REUSE"
            ),

            F.concat(
                F.lit(
                    "CROSS_ASSET_DURABLE_IDENTITY_REUSE:"
                ),

                F.col(
                    "shared_identity_types"
                ),
            )
        )

        .when(
            F.col(
                "case_rule_key"
            )
            ==
            F.lit(
                "MDE_STALE_FULL_DURABLE_LINEAGE"
            ),

            F.lit(
                "STALE_MULTI_ENTITY_DURABLE_LINEAGE_NO_CURRENT_MDE"
            )
        )

        .when(
            F.col(
                "case_rule_key"
            )
            ==
            F.lit(
                "MDE_STALE_SINGLE_ENTITY_NO_CURRENT_VISIBILITY"
            ),

            F.lit(
                "STALE_SINGLE_ENTITY_MDE_HISTORY_NO_CURRENT_MDE"
            )
        )

        .when(
            F.col(
                "case_rule_key"
            )
            ==
            F.lit(
                "MDE_HISTORICAL_SINGLE_ENTITY_NO_CURRENT_VISIBILITY"
            ),

            F.lit(
                "HISTORICAL_SINGLE_ENTITY_MDE_HISTORY_NO_CURRENT_MDE"
            )
        )

        .otherwise(
            F.lit(
                "MODEL_REVIEW_REQUIRED"
            )
        )
    )


    # -----------------------------------------------------------------------
    # Case class
    # -----------------------------------------------------------------------

    .withColumn(
        "case_class",

        F.when(
            F.col(
                "case_rule_key"
            )
            !=
            F.lit(
                "MDE_CASE_MODEL_REVIEW_REQUIRED"
            ),

            F.lit(
                "ENTERPRISE_RECONCILIATION_REFERRAL"
            )
        )

        .otherwise(
            F.lit(
                "MODEL_REVIEW"
            )
        )
    )


    # -----------------------------------------------------------------------
    # Primary customer
    #
    # These residual members are already certified enterprise-managed.
    # This is routing of the residual condition, not reassignment of the
    # underlying asset.
    # -----------------------------------------------------------------------

    .withColumn(
        "primary_customer",

        F.when(
            F.col(
                "case_rule_key"
            )
            !=
            F.lit(
                "MDE_CASE_MODEL_REVIEW_REQUIRED"
            ),

            F.lit(
                "ENTERPRISE_SERVICE_OWNER"
            )
        )

        .otherwise(
            F.lit(
                "RCAIP_ENGINEERING"
            )
        )
    )


    # -----------------------------------------------------------------------
    # Recommended treatment
    # -----------------------------------------------------------------------

    .withColumn(
        "recommended_treatment",

        F.when(
            F.col(
                "case_rule_key"
            ).startswith(
                "MDE_CROSS_ASSET_IDENTITY_REUSE"
            ),

            F.lit(
                "Reconcile shared Defender durable identity lineage across "
                "asset identities; determine whether the shared relationship "
                "reflects expected device lifecycle behavior or an enterprise "
                "identity/control-record discrepancy."
            )
        )

        .when(
            F.col(
                "case_rule_key"
            )
            ==
            F.lit(
                "MDE_STALE_FULL_DURABLE_LINEAGE"
            ),

            F.lit(
                "Review the multiple stale or historical Defender entities "
                "that converge on durable hardware identity and determine why "
                "no current Defender entity represents the currently managed "
                "endpoint."
            )
        )

        .when(
            F.col(
                "case_rule_key"
            )
            ==
            F.lit(
                "MDE_STALE_SINGLE_ENTITY_NO_CURRENT_VISIBILITY"
            ),

            F.lit(
                "Validate current Defender enrollment or reporting for the "
                "enterprise-managed endpoint and reconcile the remaining stale "
                "Defender identity record."
            )
        )

        .when(
            F.col(
                "case_rule_key"
            )
            ==
            F.lit(
                "MDE_HISTORICAL_SINGLE_ENTITY_NO_CURRENT_VISIBILITY"
            ),

            F.lit(
                "Reconcile historical Defender identity with the currently "
                "managed endpoint and determine whether current Defender "
                "coverage is expected, missing, or superseded by lifecycle "
                "change."
            )
        )

        .otherwise(
            F.lit(
                "RCAIP model review required before customer treatment."
            )
        )
    )


    # -----------------------------------------------------------------------
    # Residual concern
    # -----------------------------------------------------------------------

    .withColumn(
        "residual_concern",

        F.when(
            F.col(
                "case_rule_key"
            ).startswith(
                "MDE_CROSS_ASSET_IDENTITY_REUSE"
            ),

            F.lit(
                "Current applicable enterprise-managed endpoint lacks current "
                "MDE evidence while durable MDE identity evidence is shared "
                "across multiple RCAIP asset identities."
            )
        )

        .when(
            F.col(
                "case_rule_key"
            )
            ==
            F.lit(
                "MDE_STALE_FULL_DURABLE_LINEAGE"
            ),

            F.lit(
                "Current applicable enterprise-managed endpoint lacks current "
                "MDE evidence despite a strong multi-entity durable historical "
                "MDE lineage."
            )
        )

        .when(
            F.col(
                "case_rule_key"
            )
            ==
            F.lit(
                "MDE_STALE_SINGLE_ENTITY_NO_CURRENT_VISIBILITY"
            ),

            F.lit(
                "Current applicable enterprise-managed endpoint has only stale "
                "single-entity MDE evidence and no current MDE representation."
            )
        )

        .when(
            F.col(
                "case_rule_key"
            )
            ==
            F.lit(
                "MDE_HISTORICAL_SINGLE_ENTITY_NO_CURRENT_VISIBILITY"
            ),

            F.lit(
                "Current applicable enterprise-managed endpoint has only "
                "historical single-entity MDE evidence and no current MDE "
                "representation."
            )
        )

        .otherwise(
            F.lit(
                "Residual evidence combination requires RCAIP model review."
            )
        )
    )


    # -----------------------------------------------------------------------
    # Priority basis
    #
    # This is explanatory basis only. This diagnostic does not assign a new
    # severity or operational priority.
    # -----------------------------------------------------------------------

    .withColumn(
        "priority_basis",

        F.when(
            F.col(
                "case_rule_key"
            ).startswith(
                "MDE_CROSS_ASSET_IDENTITY_REUSE"
            ),

            F.lit(
                "Current applicable enterprise endpoint with no current MDE "
                "plus cross-asset durable identity reuse."
            )
        )

        .when(
            F.col(
                "case_rule_key"
            )
            !=
            F.lit(
                "MDE_CASE_MODEL_REVIEW_REQUIRED"
            ),

            F.lit(
                "Current applicable enterprise endpoint with no current MDE "
                "after governed enterprise rediscovery."
            )
        )

        .otherwise(
            F.lit(
                "Model review required."
            )
        )
    )


    # -----------------------------------------------------------------------
    # Case formation eligibility
    # -----------------------------------------------------------------------

    .withColumn(
        "case_formation_eligible",

        F.col(
            "case_rule_key"
        )
        !=
        F.lit(
            "MDE_CASE_MODEL_REVIEW_REQUIRED"
        )
    )


    # -----------------------------------------------------------------------
    # Deterministic case signature
    #
    # Includes only characteristics material to common explanation/treatment.
    #
    # Deliberately excludes:
    #   - Post name
    #   - hostname prefix
    #   - OS version
    #   - MachineGroup
    #   - member count
    #
    # Post/run are used only when producing the run-scoped case_id below.
    # -----------------------------------------------------------------------

    .withColumn(
        "case_signature",

        F.concat_ws(
            " | ",

            F.col(
                "case_family"
            ),

            F.col(
                "relationship_outcome"
            ),

            F.coalesce(
                F.col(
                    "ca_device_scope"
                ),
                F.lit(
                    "UNKNOWN_DEVICE_SCOPE"
                )
            ),

            F.coalesce(
                F.col(
                    "ca_mde_applicability_state"
                ),
                F.lit(
                    "UNKNOWN_APPLICABILITY"
                )
            ),

            F.col(
                "primary_customer"
            ),

            F.col(
                "recommended_treatment"
            ),

            F.col(
                "priority_basis"
            ),
        )
    )


    # -----------------------------------------------------------------------
    # Stable run-scoped case ID
    # -----------------------------------------------------------------------

    .withColumn(
        "case_id",

        F.when(
            F.col(
                "case_formation_eligible"
            ),

            F.concat(
                F.lit(
                    "MDE-"
                ),

                F.substring(
                    F.sha2(
                        F.concat_ws(
                            "||",

                            F.lit(
                                str(
                                    RCAIP_POST_SLUG
                                ).strip().lower()
                            ),

                            F.lit(
                                RCAIP_RUN_ID
                            ),

                            F.col(
                                "case_signature"
                            ),
                        ),
                        256,
                    ),
                    1,
                    12,
                ),
            )
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 15. Candidate enterprise case summary
# ---------------------------------------------------------------------------

mde_enterprise_case_summary_df = (
    case_member_df

    .filter(
        F.col(
            "case_formation_eligible"
        )
        ==
        F.lit(True)
    )

    .groupBy(
        "case_id",
        "case_rule_key",
        "case_family",
        "case_class",
        "primary_customer",
        "relationship_outcome",
        "residual_concern",
        "recommended_treatment",
        "priority_basis",
        "ca_device_scope",
        "ca_mde_applicability_state",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "affected_assets"
        ),

        F.countDistinct(
            "canonical_serial"
        ).alias(
            "distinct_serials"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "resolved_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "resolved_mde_entities"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "stale_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "stale_mde_entities"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "historical_mde_entity_count"
                ),
                F.lit(0)
            )
        ).alias(
            "historical_mde_entities"
        ),

        F.concat_ws(
            ", ",

            F.sort_array(
                F.collect_set(
                    "latest_rediscovered_mde_recency"
                )
            )
        ).alias(
            "rediscovery_recency"
        ),

        F.concat_ws(
            ", ",

            F.sort_array(
                F.collect_set(
                    "ca_source_mask_active"
                )
            )
        ).alias(
            "active_source_patterns"
        ),

        F.concat_ws(
            ", ",

            F.sort_array(
                F.collect_set(
                    "ca_post_visibility_state"
                )
            )
        ).alias(
            "visibility_states"
        ),

        F.concat_ws(
            ", ",

            F.sort_array(
                F.collect_set(
                    "ca_attribution_confidence"
                )
            )
        ).alias(
            "attribution_confidence_states"
        ),

        F.concat_ws(
            ", ",

            F.sort_array(
                F.collect_set(
                    F.when(
                        F.length(
                            F.trim(
                                F.col(
                                    "shared_identity_types"
                                )
                            )
                        )
                        >
                        F.lit(0),

                        F.col(
                            "shared_identity_types"
                        )
                    )
                )
            )
        ).alias(
            "shared_identity_types"
        ),

        F.max(
            F.col(
                "maximum_related_assets"
            )
        ).alias(
            "max_assets_related_by_shared_identity"
        ),

        F.sort_array(
            F.collect_set(
                "asset_key"
            )
        ).alias(
            "case_member_asset_keys"
        ),
    )

    .orderBy(
        F.desc(
            "affected_assets"
        ),
        "case_rule_key",
    )

    .cache()
)


