#   They are NOT automatically residual case members because they did not
#   necessarily survive the same current-control qualification gates.
# ---------------------------------------------------------------------------

case_shared_identity_support_df = (
    shared_relationship_df.alias(
        "relationship"
    )

    .join(
        case_member_df

        .filter(
            F.col(
                "case_formation_eligible"
            )
            ==
            F.lit(True)
        )

        .select(
            "case_id",
            "asset_key",
        )

        .alias(
            "case_member"
        ),

        F.col(
            "relationship.asset_key"
        )
        ==
        F.col(
            "case_member.asset_key"
        ),

        how="inner",
    )

    .select(
        F.col(
            "case_member.case_id"
        ).alias(
            "case_id"
        ),

        F.col(
            "relationship.asset_key"
        ).alias(
            "case_member_asset_key"
        ),

        F.col(
            "relationship.identity_type"
        ).alias(
            "identity_type"
        ),

        F.col(
            "relationship.shared_identity_value"
        ).alias(
            "shared_identity_value"
        ),

        F.col(
            "relationship.related_asset_count"
        ).alias(
            "related_asset_count"
        ),

        F.col(
            "relationship.related_asset_keys"
        ).alias(
            "related_asset_keys"
        ),
    )

    .dropDuplicates([
        "case_id",
        "case_member_asset_key",
        "identity_type",
        "shared_identity_value",
    ])

    .orderBy(
        "case_id",
        "identity_type",
        "shared_identity_value",
        "case_member_asset_key",
    )
)


