# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 17 - Tenable UUID Identity Reconciliation
# Version: 1.0
#
# Purpose:
#   Correct the source-field semantics exposed by Cell 16 and reconcile the
#   active unresolved-IP population using durable Tenable host UUID evidence.
#
# Key lesson from prior gate:
#   A field named dvc_hostname must not automatically be treated as endpoint
#   identity. Its actual cardinality/discrimination must be tested first.
#
# This cell:
#   1. profiles Tenable dvc_hostname semantics;
#   2. explicitly excludes non-discriminating dvc_hostname values from
#      identity reasoning;
#   3. groups unresolved IP observations by Tenable host UUID;
#   4. identifies UUID groups that also contain an existing stronger RCAIP
#      asset identity;
#   5. identifies multiple IP asset_keys representing the same Tenable UUID;
#   6. preserves remaining unique UUID identities for the next gate.
#
# IMPORTANT:
#   - Tenable host UUID is source-local durable identity evidence.
#   - Same UUID does NOT automatically authorize an Asset Plane merge.
#   - No asset_key is changed.
#   - No source record is deleted or suppressed.
#   - No case or customer routing is created.
#
# Post-agnostic:
#   - no example_post_a hostname values
#   - no example_post_a IP values
#   - no example_post_a counts
#   - field semantics are derived from current-run data
#
# Safety:
#   - READ ONLY
#   - durable RCAIP products only
#   - no raw enterprise source scans
#   - no new cross-source identity matching
#   - no findings
#   - no tickets
#   - no remediation
#   - no Delta writes
# ============================================================================

from pyspark.sql import functions as F


# ---------------------------------------------------------------------------
# 1. Runtime validation
# ---------------------------------------------------------------------------

REQUIRED_RUNTIME_OBJECTS = [
    "RCAIP_CONFIG_000_READY",
    "RCAIP_POST_NAME",
    "RCAIP_POST_SLUG",
    "RCAIP_RUN_ID",
    "get_rcaip_table",
]


missing_runtime_objects = [
    name
    for name in REQUIRED_RUNTIME_OBJECTS
    if name not in globals()
]


if missing_runtime_objects:
    raise RuntimeError(
        "Cell 17 requires Config 001 runtime. Missing: "
        + " | ".join(missing_runtime_objects)
    )


if not RCAIP_CONFIG_000_READY:
    raise RuntimeError(
        "Config 000 did not publish a ready runtime."
    )


# ---------------------------------------------------------------------------
# 2. Resolve durable products
# ---------------------------------------------------------------------------

CONTROL_FEATURE_TABLE = get_rcaip_table(
    "IP006_CONTROL_ASSURANCE_FEATURE"
)


TENABLE_NORM_TABLE = get_rcaip_table(
    "TENABLE_NORM"
)


for table_name in [
    CONTROL_FEATURE_TABLE,
    TENABLE_NORM_TABLE,
]:
    if not spark.catalog.tableExists(table_name):
        raise RuntimeError(
            "Required durable RCAIP product unavailable: "
            + table_name
        )


feature_source_df = spark.table(
    CONTROL_FEATURE_TABLE
)


tenable_source_df = spark.table(
    TENABLE_NORM_TABLE
)


# ---------------------------------------------------------------------------
# 3. Required contracts
# ---------------------------------------------------------------------------

REQUIRED_FEATURE_COLUMNS = {
    "asset_key",
    "post_slug",
    "rcaip_run_id",

    "canonical_name",
    "canonical_serial",
    "canonical_ip",

    "device_family",
    "device_scope",
    "device_family_confidence",

    "network_scope",

    "operational_boundary",
    "operational_boundary_confidence",

    "management_model",
    "management_owner",

    "identity_basis",
    "identity_strength",

    "source_mask_raw",
    "source_mask_active",
    "source_mask_stale",

    "current_observation_status",

    "visibility_evidence_count",
    "visibility_class",
    "post_visibility_state",

    "attribution_confidence",
    "attribution_conflict_flag",

    "active_unresolved_ip_candidate",
    "active_unresolved_ip_observation_class",

    "acr_band",
}


REQUIRED_TENABLE_COLUMNS = {
    "asset_key",
    "post_slug",
    "rcaip_run_id",

    "host_key",

    "tenable_present",

    "ip_address",
    "dns_name",
    "tenable_dvc_hostname",
    "tenable_host_uuid",

    "tenable_acr_score",
    "tenable_key_drivers",
    "tenable_organization_name",

    "tenable_event_time",

    "last_observed_timestamp",
    "days_since_observed",
    "observation_age_bucket",
    "is_stale_90",
}


missing_feature_columns = sorted(
    REQUIRED_FEATURE_COLUMNS
    -
    set(feature_source_df.columns)
)


missing_tenable_columns = sorted(
    REQUIRED_TENABLE_COLUMNS
    -
    set(tenable_source_df.columns)
)


if missing_feature_columns:
    raise RuntimeError(
        "Control Assurance Feature missing columns: "
        + " | ".join(missing_feature_columns)
    )


if missing_tenable_columns:
    raise RuntimeError(
        "TENABLE_NORM missing columns: "
        + " | ".join(missing_tenable_columns)
    )


# ---------------------------------------------------------------------------
# 4. Runtime scoping
# ---------------------------------------------------------------------------

def runtime_slice(df):

    return (
        df

        .filter(
            (
                F.lower(
                    F.trim(
                        F.col("post_slug")
                    )
                )
                ==
                F.lit(
                    str(
                        RCAIP_POST_SLUG
                    ).strip().lower()
                )
            )
            &
            (
                F.col("rcaip_run_id")
                ==
                F.lit(RCAIP_RUN_ID)
            )
        )
    )


feature_df = (
    runtime_slice(
        feature_source_df
    )
    .cache()
)


tenable_df = (
    runtime_slice(
        tenable_source_df
    )
    .cache()
)


# ---------------------------------------------------------------------------
# 5. Certify durable grains
# ---------------------------------------------------------------------------

feature_rows = (
    feature_df.count()
)


feature_distinct_assets = (
    feature_df
    .select("asset_key")
    .distinct()
    .count()
)


tenable_rows = (
    tenable_df.count()
)


tenable_distinct_assets = (
    tenable_df
    .select("asset_key")
    .distinct()
    .count()
)


tenable_duplicate_asset_keys = (
    tenable_df

    .groupBy("asset_key")

    .count()

    .filter(
        F.col("count") > 1
    )

    .count()
)


if feature_rows != feature_distinct_assets:
    raise RuntimeError(
        "Control Assurance Feature is not one row per asset_key."
    )


if tenable_rows != tenable_distinct_assets:
    raise RuntimeError(
        "TENABLE_NORM is not one row per asset_key."
    )


if tenable_duplicate_asset_keys != 0:
    raise RuntimeError(
        "TENABLE_NORM contains duplicate asset keys."
    )


# ---------------------------------------------------------------------------
# 6. Helpers
# ---------------------------------------------------------------------------

IPV4_LIKE_REGEX = (
    r"^[0-9]{1,3}"
    r"(\.[0-9]{1,3}){3}$"
)


def nonblank(column_name):

    return (
        F.col(column_name).isNotNull()
        &
        (
            F.length(
                F.trim(
                    F.col(
                        column_name
                    ).cast("string")
                )
            )
            >
            F.lit(0)
        )
    )


def normalize_text(column_name):

    return (
        F.lower(
            F.trim(
                F.col(
                    column_name
                ).cast("string")
            )
        )
    )


def normalize_hostname(column_name):

    value = normalize_text(
        column_name
    )

    value = F.regexp_replace(
        value,
        r"\$$",
        "",
    )

    value = F.regexp_replace(
        value,
        r"\.$",
        "",
    )

    return value


# ---------------------------------------------------------------------------
# 7. Reconstruct active unresolved-IP population
# ---------------------------------------------------------------------------

candidate_df = (
    feature_df

    .filter(
        F.coalesce(
            F.col(
                "active_unresolved_ip_candidate"
            ),
            F.lit(False)
        )
        ==
        F.lit(True)
    )

    .select(
        "asset_key",

        "canonical_name",
        "canonical_serial",
        "canonical_ip",

        "device_family",
        "device_scope",
        "device_family_confidence",

        "network_scope",

        "operational_boundary",
        "operational_boundary_confidence",

        "management_model",
        "management_owner",

        "identity_basis",
        "identity_strength",

        "source_mask_raw",
        "source_mask_active",
        "source_mask_stale",

        "current_observation_status",

        "visibility_evidence_count",
        "visibility_class",
        "post_visibility_state",

        "attribution_confidence",
        "attribution_conflict_flag",

        "active_unresolved_ip_observation_class",

        "acr_band",
    )

    .cache()
)


candidate_count = (
    candidate_df.count()
)


candidate_distinct_assets = (
    candidate_df
    .select("asset_key")
    .distinct()
    .count()
)


candidate_duplicate_assets = (
    candidate_df

    .groupBy("asset_key")

    .count()

    .filter(
        F.col("count") > 1
    )

    .count()
)


if candidate_count == 0:
    raise RuntimeError(
        "Cell 17 found no active unresolved-IP population."
    )


if candidate_count != candidate_distinct_assets:
    raise RuntimeError(
        "Active unresolved-IP population is not one row per asset."
    )


# ---------------------------------------------------------------------------
# 8. Profile dvc_hostname semantics across the ENTIRE normalized Tenable
#    population.
#
# A source field must demonstrate discriminatory behavior before RCAIP treats
# it as asset identity evidence.
# ---------------------------------------------------------------------------

tenable_dvc_profile_input_df = (
    tenable_df

    .filter(
        nonblank(
            "tenable_dvc_hostname"
        )
    )

    .withColumn(
        "dvc_hostname_norm",

        normalize_hostname(
            "tenable_dvc_hostname"
        )
    )
)


dvc_nonblank_rows = (
    tenable_dvc_profile_input_df.count()
)


dvc_value_profile_df = (
    tenable_dvc_profile_input_df

    .groupBy(
        "dvc_hostname_norm"
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.first(
            "tenable_dvc_hostname",
            ignorenulls=True,
        ).alias(
            "observed_value"
        ),
    )

    .orderBy(
        F.desc(
            "asset_count"
        ),
        "observed_value",
    )
)


dvc_distinct_values = (
    dvc_value_profile_df.count()
)


dvc_max_asset_count_row = (
    dvc_value_profile_df

    .agg(
        F.max(
            "asset_count"
        ).alias(
            "max_asset_count"
        )
    )

    .first()
)


dvc_max_assets_per_value = (
    int(
        dvc_max_asset_count_row[
            "max_asset_count"
        ]
    )
    if (
        dvc_max_asset_count_row
        and
        dvc_max_asset_count_row[
            "max_asset_count"
        ]
        is not None
    )
    else 0
)


if dvc_nonblank_rows == 0:

    dvc_hostname_semantics = (
        "NO_DVC_HOSTNAME_EVIDENCE"
    )


elif (
    dvc_distinct_values == 1
    and
    dvc_max_assets_per_value
    ==
    dvc_nonblank_rows
):

    dvc_hostname_semantics = (
        "NON_DISCRIMINATING_CONSTANT_SOURCE_CONTEXT"
    )


elif dvc_max_assets_per_value > 1:

    dvc_hostname_semantics = (
        "REUSED_SOURCE_FIELD_NOT_SAFE_AS_DURABLE_IDENTITY"
    )


else:

    dvc_hostname_semantics = (
        "DISCRIMINATING_CANDIDATE_FIELD_REQUIRES_SEMANTIC_VALIDATION"
    )


print("=" * 120)
print("TENABLE DVC_HOSTNAME - FIELD SEMANTICS PROFILE")
print("FIELD NAME ALONE DOES NOT ESTABLISH ASSET IDENTITY")
print("=" * 120)

print(
    "Current-run Tenable rows:",
    tenable_rows
)

print(
    "Rows with dvc_hostname:",
    dvc_nonblank_rows
)

print(
    "Distinct dvc_hostname values:",
    dvc_distinct_values
)

print(
    "Maximum assets sharing one dvc_hostname:",
    dvc_max_assets_per_value
)

print(
    "Derived dvc_hostname semantics:",
    dvc_hostname_semantics
)

print(
    "dvc_hostname used for Cell 17 identity reconciliation:",
    "NO"
)

display(
    dvc_value_profile_df.limit(20)
)


# ---------------------------------------------------------------------------
# 9. Compact candidate Tenable evidence
# ---------------------------------------------------------------------------

tenable_candidate_context_df = (
    tenable_df

    .select(
        "asset_key",

        F.col(
            "host_key"
        ).alias(
            "tenable_host_key"
        ),

        F.col(
            "ip_address"
        ).alias(
            "tenable_ip"
        ),

        F.col(
            "dns_name"
        ).alias(
            "tenable_dns_name"
        ),

        F.col(
            "tenable_dvc_hostname"
        ).alias(
            "tenable_dvc_hostname"
        ),

        F.col(
            "tenable_host_uuid"
        ).alias(
            "tenable_host_uuid"
        ),

        F.col(
            "tenable_acr_score"
        ).alias(
            "tenable_acr_score"
        ),

        F.col(
            "tenable_key_drivers"
        ).alias(
            "tenable_key_drivers"
        ),

        F.col(
            "tenable_organization_name"
        ).alias(
            "tenable_organization_name"
        ),

        F.col(
            "tenable_event_time"
        ).alias(
            "tenable_event_time"
        ),

        F.col(
            "last_observed_timestamp"
        ).alias(
            "tenable_last_observed_timestamp"
        ),

        F.col(
            "days_since_observed"
        ).alias(
            "tenable_days_since_observed"
        ),

        F.col(
            "observation_age_bucket"
        ).alias(
            "tenable_observation_age_bucket"
        ),

        F.col(
            "is_stale_90"
        ).alias(
            "tenable_is_stale_90"
        ),
    )
)


candidate_evidence_df = (
    candidate_df

    .join(
        tenable_candidate_context_df,
        on="asset_key",
        how="left",
    )

    .withColumn(
        "tenable_uuid_norm",

        F.when(
            nonblank(
                "tenable_host_uuid"
            ),

            normalize_text(
                "tenable_host_uuid"
            )
        )
    )

    .withColumn(
        "tenable_identity_group_key",

        F.when(
            F.col(
                "tenable_uuid_norm"
            ).isNotNull(),

            F.concat(
                F.lit(
                    "TENABLE_UUID::"
                ),

                F.col(
                    "tenable_uuid_norm"
                )
            )
        )

        .otherwise(
            F.concat(
                F.lit(
                    "NO_UUID::"
                ),

                F.col(
                    "asset_key"
                )
            )
        )
    )

    .cache()
)


candidate_missing_tenable_context = (
    candidate_evidence_df

    .filter(
        F.col(
            "tenable_ip"
        ).isNull()
        &
        F.col(
            "tenable_host_uuid"
        ).isNull()
    )

    .count()
)


candidate_host_uuid_count = (
    candidate_evidence_df

    .filter(
        F.col(
            "tenable_uuid_norm"
        ).isNotNull()
    )

    .count()
)


candidate_missing_host_uuid_count = (
    candidate_count
    -
    candidate_host_uuid_count
)


candidate_distinct_host_uuid_count = (
    candidate_evidence_df

    .filter(
        F.col(
            "tenable_uuid_norm"
        ).isNotNull()
    )

    .select(
        "tenable_uuid_norm"
    )

    .distinct()

    .count()
)


# ---------------------------------------------------------------------------
# 10. Build Asset Plane context for every current Tenable asset
# ---------------------------------------------------------------------------

asset_identity_context_df = (
    feature_df

    .select(
        "asset_key",

        F.col(
            "canonical_name"
        ).alias(
            "related_canonical_name"
        ),

        F.col(
            "canonical_serial"
        ).alias(
            "related_canonical_serial"
        ),

        F.col(
            "canonical_ip"
        ).alias(
            "related_canonical_ip"
        ),

        F.col(
            "identity_basis"
        ).alias(
            "related_identity_basis"
        ),

        F.col(
            "identity_strength"
        ).alias(
            "related_identity_strength"
        ),

        F.col(
            "source_mask_raw"
        ).alias(
            "related_source_mask_raw"
        ),

        F.col(
            "source_mask_active"
        ).alias(
            "related_source_mask_active"
        ),

        F.col(
            "source_mask_stale"
        ).alias(
            "related_source_mask_stale"
        ),

        F.col(
            "management_model"
        ).alias(
            "related_management_model"
        ),

        F.col(
            "management_owner"
        ).alias(
            "related_management_owner"
        ),

        F.col(
            "current_observation_status"
        ).alias(
            "related_current_observation_status"
        ),
    )
)


# ---------------------------------------------------------------------------
# 11. Profile every current normalized Tenable host UUID
# ---------------------------------------------------------------------------

tenable_uuid_member_df = (
    tenable_df

    .filter(
        nonblank(
            "tenable_host_uuid"
        )
    )

    .withColumn(
        "tenable_uuid_norm",

        normalize_text(
            "tenable_host_uuid"
        )
    )

    .select(
        "asset_key",
        "tenable_host_uuid",
        "tenable_uuid_norm",
        "ip_address",
        "dns_name",
    )

    .join(
        asset_identity_context_df,
        on="asset_key",
        how="left",
    )

    .withColumn(
        "stronger_non_ip_asset_identity",

        (
            F.coalesce(
                F.col(
                    "related_identity_basis"
                ),
                F.lit(
                    "UNKNOWN"
                )
            )
            !=
            F.lit(
                "IP"
            )
        )
        &
        ~F.coalesce(
            F.col(
                "related_identity_strength"
            ),
            F.lit(
                "UNKNOWN"
            )
        ).isin(
            "WEAK",
            "UNKNOWN",
        )
    )

    .cache()
)


tenable_uuid_profile_df = (
    tenable_uuid_member_df

    .groupBy(
        "tenable_uuid_norm"
    )

    .agg(
        F.first(
            "tenable_host_uuid",
            ignorenulls=True,
        ).alias(
            "tenable_host_uuid"
        ),

        F.countDistinct(
            "asset_key"
        ).alias(
            "all_tenable_asset_key_count"
        ),

        F.sort_array(
            F.collect_set(
                "asset_key"
            )
        ).alias(
            "all_tenable_asset_keys"
        ),

        F.sum(
            F.when(
                F.col(
                    "stronger_non_ip_asset_identity"
                ),
                F.lit(1),
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "stronger_non_ip_asset_count"
        ),

        F.sort_array(
            F.collect_set(
                F.when(
                    F.col(
                        "stronger_non_ip_asset_identity"
                    ),

                    F.col(
                        "asset_key"
                    )
                )
            )
        ).alias(
            "stronger_non_ip_asset_keys"
        ),

        F.sort_array(
            F.collect_set(
                F.when(
                    F.col(
                        "stronger_non_ip_asset_identity"
                    ),

                    F.col(
                        "related_canonical_name"
                    )
                )
            )
        ).alias(
            "stronger_non_ip_asset_names"
        ),

        F.sort_array(
            F.collect_set(
                F.when(
                    F.col(
                        "stronger_non_ip_asset_identity"
                    ),

                    F.col(
                        "related_identity_basis"
                    )
                )
            )
        ).alias(
            "stronger_identity_bases"
        ),

        F.sort_array(
            F.collect_set(
                F.when(
                    F.col(
                        "stronger_non_ip_asset_identity"
                    ),

                    F.col(
                        "related_source_mask_active"
                    )
                )
            )
        ).alias(
            "stronger_asset_active_source_masks"
        ),
    )
)


# ---------------------------------------------------------------------------
# 12. Candidate population at Tenable UUID identity grain
# ---------------------------------------------------------------------------

candidate_group_seed_df = (
    candidate_evidence_df

    .groupBy(
        "tenable_identity_group_key",
        "tenable_uuid_norm",
    )

    .agg(
        F.first(
            "tenable_host_uuid",
            ignorenulls=True,
        ).alias(
            "candidate_tenable_host_uuid"
        ),

        F.countDistinct(
            "asset_key"
        ).alias(
            "candidate_asset_key_count"
        ),

        F.sort_array(
            F.collect_set(
                "asset_key"
            )
        ).alias(
            "candidate_asset_keys"
        ),

        F.sort_array(
            F.collect_set(
                "canonical_ip"
            )
        ).alias(
            "candidate_ip_addresses"
        ),

        F.sort_array(
            F.collect_set(
                "source_mask_raw"
            )
        ).alias(
            "candidate_source_masks_raw"
        ),

        F.sort_array(
            F.collect_set(
                "source_mask_stale"
            )
        ).alias(
            "candidate_source_masks_stale"
        ),
    )
)


candidate_uuid_group_df = (
    candidate_group_seed_df

    .join(
        tenable_uuid_profile_df,
        on="tenable_uuid_norm",
        how="left",
    )

    .withColumn(
        "all_tenable_asset_key_count",

        F.coalesce(
            F.col(
                "all_tenable_asset_key_count"
            ),

            F.col(
                "candidate_asset_key_count"
            )
        )
    )

    .withColumn(
        "stronger_non_ip_asset_count",

        F.coalesce(
            F.col(
                "stronger_non_ip_asset_count"
            ),
            F.lit(0)
        )
    )

    .withColumn(
        "tenable_uuid_reconciliation_class",

        F.when(
            F.col(
                "tenable_uuid_norm"
            ).isNull(),

            F.lit(
                "NO_TENABLE_HOST_UUID"
            )
        )

        .when(
            F.col(
                "stronger_non_ip_asset_count"
            )
            >
            F.lit(0),

            F.lit(
                "UUID_LINKS_EXISTING_DURABLE_ASSET"
            )
        )

        .when(
            F.col(
                "candidate_asset_key_count"
            )
            >
            F.lit(1),

            F.lit(
                "UUID_COLLAPSES_MULTIPLE_IP_ASSET_KEYS"
            )
        )

        .when(
            F.col(
                "all_tenable_asset_key_count"
            )
            >
            F.col(
                "candidate_asset_key_count"
            ),

            F.lit(
                "UUID_REUSE_WITHOUT_STRONGER_IDENTITY_REQUIRES_REVIEW"
            )
        )

        .otherwise(
            F.lit(
                "UNIQUE_TENABLE_UUID_NO_EXISTING_ASSET_LINK"
            )
        )
    )

    .withColumn(
        "tenable_uuid_next_gate",

        F.when(
            F.col(
                "tenable_uuid_reconciliation_class"
            )
            ==
            F.lit(
                "UUID_LINKS_EXISTING_DURABLE_ASSET"
            ),

            F.lit(
                "VALIDATE_EXISTING_ASSET_UUID_LINK"
            )
        )

        .when(
            F.col(
                "tenable_uuid_reconciliation_class"
            )
            ==
            F.lit(
                "UUID_COLLAPSES_MULTIPLE_IP_ASSET_KEYS"
            ),

            F.lit(
                "TREAT_AS_ONE_TENABLE_IDENTITY_FOR_FURTHER_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "tenable_uuid_reconciliation_class"
            )
            ==
            F.lit(
                "UNIQUE_TENABLE_UUID_NO_EXISTING_ASSET_LINK"
            ),

            F.lit(
                "NORMALIZED_CROSS_SOURCE_IDENTITY_ENRICHMENT"
            )
        )

        .when(
            F.col(
                "tenable_uuid_reconciliation_class"
            )
            ==
            F.lit(
                "NO_TENABLE_HOST_UUID"
            ),

            F.lit(
                "NETWORK_ENUMERATION_OR_EXPLANATION"
            )
        )

        .otherwise(
            F.lit(
                "IDENTITY_MODEL_REVIEW"
            )
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 13. Reconciliation summary
# ---------------------------------------------------------------------------

tenable_uuid_reconciliation_summary_df = (
    candidate_uuid_group_df

    .groupBy(
        "tenable_uuid_reconciliation_class",
        "tenable_uuid_next_gate",
    )

    .agg(
        F.count(
            F.lit(1)
        ).alias(
            "tenable_identity_groups"
        ),

        F.sum(
            F.col(
                "candidate_asset_key_count"
            )
        ).alias(
            "candidate_asset_rows"
        ),

        F.sum(
            F.col(
                "stronger_non_ip_asset_count"
            )
        ).alias(
            "existing_stronger_asset_links"
        ),
    )

    .orderBy(
        F.desc(
            "candidate_asset_rows"
        ),
        "tenable_uuid_reconciliation_class",
    )
)


print()
print("=" * 120)
print("ACTIVE UNRESOLVED IP - TENABLE UUID RECONCILIATION SUMMARY")
print("IDENTITY GROUPS - NOT CASES / NOT ASSET MERGES")
print("=" * 120)

display(
    tenable_uuid_reconciliation_summary_df
)


