# ---------------------------------------------------------------------------

existing_asset_uuid_link_df = (
    candidate_uuid_group_df

    .filter(
        F.col(
            "tenable_uuid_reconciliation_class"
        )
        ==
        F.lit(
            "UUID_LINKS_EXISTING_DURABLE_ASSET"
        )
    )

    .select(
        "candidate_tenable_host_uuid",
        "candidate_asset_key_count",
        "candidate_asset_keys",
        "candidate_ip_addresses",

        "all_tenable_asset_key_count",
        "all_tenable_asset_keys",

        "stronger_non_ip_asset_count",
        "stronger_non_ip_asset_keys",
        "stronger_non_ip_asset_names",
        "stronger_identity_bases",
        "stronger_asset_active_source_masks",

        "tenable_uuid_next_gate",
    )

    .orderBy(
        "candidate_tenable_host_uuid"
    )
)


existing_asset_link_group_count = (
    existing_asset_uuid_link_df.count()
)


if existing_asset_link_group_count > 0:

    print()
