# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 20 - Tenable Identity / IP Explanatory Cohort Compression
# Version: 1.0
#
# Purpose:
#   Compress the linked portion of the active unresolved-IP population into
#   deterministic EXPLANATORY RECONCILIATION COHORTS while preserving the
#   truly no-link Tenable identities for the next device/network-context gate.
#
# This cell distinguishes:
#
#   A. RCAIP engineering identity-model conditions
#      - one Tenable UUID already represented by a stronger Asset Plane identity
#
#   B. Enterprise reconciliation conditions
#      - same IP / different current Tenable UUID
#      - same IP / different stale Tenable UUID
#      - stronger target now reporting a different current IP
#      - stronger target carrying stale Tenable evidence at another IP
#      - multi-target IP assignment ambiguity
#      - non-current inventory relationships
#
#   C. Still-unresolved Tenable identities
#      - no stronger source-local UUID relationship
#      - no stronger exact-IP Asset Plane relationship
#
# IMPORTANT:
#   - These are explanatory cohorts, NOT assurance cases.
#   - Provisional treatment lane is NOT final customer routing.
#   - No asset identities are merged.
#   - No asset_key is changed.
#   - IP evidence is not authoritative identity.
#   - tenable_dvc_hostname is NOT used.
#   - MDE public IP is NOT used.
#
# Post-agnostic:
#   - no example_post_a counts
#   - no example_post_a IPs
#   - no example_post_a names
#   - no Post-specific behavioral branches
#
# Safety:
#   - READ ONLY
#   - durable RCAIP products only
#   - no raw enterprise source scans
#   - no findings
#   - no tickets
#   - no remediation
#   - no Delta writes
# ============================================================================

from pyspark.sql import functions as F


# ---------------------------------------------------------------------------
# 1. Runtime validation
# ---------------------------------------------------------------------------

REQUIRED_RUNTIME_OBJECTS = [
    "RCAIP_CONFIG_000_READY",
    "RCAIP_POST_NAME",
    "RCAIP_POST_SLUG",
    "RCAIP_RUN_ID",
    "get_rcaip_table",
]


missing_runtime_objects = [
    name
    for name in REQUIRED_RUNTIME_OBJECTS
    if name not in globals()
]


if missing_runtime_objects:
    raise RuntimeError(
        "Cell 20 requires Config 001 runtime. Missing: "
        + " | ".join(missing_runtime_objects)
    )


if not RCAIP_CONFIG_000_READY:
    raise RuntimeError(
        "Config 000 did not publish a ready runtime."
    )


# ---------------------------------------------------------------------------
# 2. Resolve durable products
# ---------------------------------------------------------------------------

CONTROL_FEATURE_TABLE = get_rcaip_table(
    "IP006_CONTROL_ASSURANCE_FEATURE"
)


TENABLE_NORM_TABLE = get_rcaip_table(
    "TENABLE_NORM"
)


SCORED_ASSET_TABLE = get_rcaip_table(
    "ASSET_RECONCILIATION_SCORED"
)


for table_name in [
    CONTROL_FEATURE_TABLE,
    TENABLE_NORM_TABLE,
    SCORED_ASSET_TABLE,
]:
    if not spark.catalog.tableExists(table_name):
        raise RuntimeError(
            "Required durable RCAIP product unavailable: "
            + table_name
        )


feature_source_df = spark.table(
    CONTROL_FEATURE_TABLE
)


tenable_source_df = spark.table(
    TENABLE_NORM_TABLE
)


scored_source_df = spark.table(
    SCORED_ASSET_TABLE
)


# ---------------------------------------------------------------------------
# 3. Required contracts
# ---------------------------------------------------------------------------

REQUIRED_FEATURE_COLUMNS = {
    "asset_key",
    "post_slug",
    "rcaip_run_id",

    "canonical_name",
    "canonical_serial",
    "canonical_ip",

    "device_family",
    "device_scope",

    "network_scope",

    "operational_boundary",
    "operational_boundary_confidence",

    "management_model",
    "management_owner",

    "identity_basis",
    "identity_strength",

    "source_mask_raw",
    "source_mask_active",
    "source_mask_stale",

    "current_observation_status",
    "visibility_evidence_count",
    "post_visibility_state",

    "attribution_confidence",
    "attribution_conflict_flag",

    "active_unresolved_ip_candidate",

    "acr_band",
}


REQUIRED_TENABLE_COLUMNS = {
    "asset_key",
    "post_slug",
    "rcaip_run_id",

    "ip_address",
    "dns_name",
    "tenable_host_uuid",

    "tenable_acr_score",
    "tenable_key_drivers",
    "tenable_organization_name",

    "tenable_event_time",
    "last_observed_timestamp",
    "days_since_observed",
    "observation_age_bucket",
    "is_stale_90",
}


REQUIRED_SCORED_COLUMNS = {
    "asset_key",
    "post_slug",
    "rcaip_run_id",

    "cmdb_present",
    "cmdb_name",
    "cmdb_fqdn",
    "cmdb_ip",
    "cmdb_serial_number",
    "cmdb_most_recent_discovery",

    "nmap_present",
    "nmap_ip",
    "nmap_hostname",
    "nmap_last_observed_timestamp",
    "nmap_active",
    "nmap_stale",

    "qualys_present",
    "qualys_ip",
    "qualys_asset_name",
    "qualys_bios_serial_number",
    "qualys_inventory_last_updated_on",
    "qualys_active",
    "qualys_stale",
}


missing_feature_columns = sorted(
    REQUIRED_FEATURE_COLUMNS
    -
    set(feature_source_df.columns)
)


missing_tenable_columns = sorted(
    REQUIRED_TENABLE_COLUMNS
    -
    set(tenable_source_df.columns)
)


missing_scored_columns = sorted(
    REQUIRED_SCORED_COLUMNS
    -
    set(scored_source_df.columns)
)


if missing_feature_columns:
    raise RuntimeError(
        "Control Assurance Feature missing columns: "
        + " | ".join(missing_feature_columns)
    )


if missing_tenable_columns:
    raise RuntimeError(
        "TENABLE_NORM missing columns: "
        + " | ".join(missing_tenable_columns)
    )


if missing_scored_columns:
    raise RuntimeError(
        "ASSET_RECONCILIATION_SCORED missing columns: "
        + " | ".join(missing_scored_columns)
    )


# ---------------------------------------------------------------------------
# 4. Runtime scoping
# ---------------------------------------------------------------------------

def runtime_slice(df):

    return (
        df

        .filter(
            (
                F.lower(
                    F.trim(
                        F.col("post_slug")
                    )
                )
                ==
                F.lit(
                    str(
                        RCAIP_POST_SLUG
                    ).strip().lower()
                )
            )
            &
            (
                F.col("rcaip_run_id")
                ==
                F.lit(RCAIP_RUN_ID)
            )
        )
    )


feature_df = (
    runtime_slice(
        feature_source_df
    )
    .cache()
)


tenable_df = (
    runtime_slice(
        tenable_source_df
    )
    .cache()
)


scored_df = (
    runtime_slice(
        scored_source_df
    )
    .cache()
)


# ---------------------------------------------------------------------------
# 5. Grain certification
# ---------------------------------------------------------------------------

feature_rows = feature_df.count()

feature_assets = (
    feature_df
    .select("asset_key")
    .distinct()
    .count()
)


tenable_rows = tenable_df.count()

tenable_assets = (
    tenable_df
    .select("asset_key")
    .distinct()
    .count()
)


scored_rows = scored_df.count()

scored_assets = (
    scored_df
    .select("asset_key")
    .distinct()
    .count()
)


if feature_rows != feature_assets:
    raise RuntimeError(
        "Control Assurance Feature is not one row per asset."
    )


if tenable_rows != tenable_assets:
    raise RuntimeError(
        "TENABLE_NORM is not one row per asset."
    )


if scored_rows != scored_assets:
    raise RuntimeError(
        "ASSET_RECONCILIATION_SCORED is not one row per asset."
    )


# ---------------------------------------------------------------------------
# 6. Helpers
# ---------------------------------------------------------------------------

def nonblank(col_expr):

    return (
        col_expr.isNotNull()
        &
        (
            F.length(
                F.trim(
                    col_expr.cast("string")
                )
            )
            >
            F.lit(0)
        )
    )


def normalized(col_expr):

    return (
        F.lower(
            F.trim(
                col_expr.cast("string")
            )
        )
    )


def stale_flag_true(col_expr):

    return (
        F.upper(
            F.trim(
                F.coalesce(
                    col_expr.cast("string"),
                    F.lit("")
                )
            )
        )
        .isin(
            "Y",
            "YES",
            "TRUE",
            "1",
        )
    )


# ---------------------------------------------------------------------------
# 7. Reconstruct active unresolved-IP candidate population
# ---------------------------------------------------------------------------

candidate_feature_df = (
    feature_df

    .filter(
        F.coalesce(
            F.col(
                "active_unresolved_ip_candidate"
            ),
            F.lit(False)
        )
        ==
        F.lit(True)
    )

    .select(
        "asset_key",

        "canonical_name",
        "canonical_serial",
        "canonical_ip",

        "device_family",
        "device_scope",

        "network_scope",

        "operational_boundary",
        "operational_boundary_confidence",

        "management_model",
        "management_owner",

        "identity_basis",
        "identity_strength",

        "source_mask_raw",
        "source_mask_active",
        "source_mask_stale",

        "current_observation_status",
        "visibility_evidence_count",
        "post_visibility_state",

        "attribution_confidence",
        "attribution_conflict_flag",

        "acr_band",
    )
)


candidate_tenable_df = (
    tenable_df

    .select(
        "asset_key",

        F.col(
            "ip_address"
        ).alias(
            "candidate_tenable_ip"
        ),

        F.col(
            "tenable_host_uuid"
        ).alias(
            "candidate_tenable_uuid"
        ),

        F.col(
            "tenable_acr_score"
        ).alias(
            "candidate_tenable_acr_score"
        ),

        F.col(
            "tenable_key_drivers"
        ).alias(
            "candidate_tenable_key_drivers"
        ),

        F.col(
            "tenable_organization_name"
        ).alias(
            "candidate_tenable_organization_name"
        ),

        F.col(
            "tenable_event_time"
        ).alias(
            "candidate_tenable_event_time"
        ),

        F.col(
            "last_observed_timestamp"
        ).alias(
            "candidate_tenable_last_observed"
        ),

        F.col(
            "days_since_observed"
        ).alias(
            "candidate_tenable_age_days"
        ),

        F.col(
            "observation_age_bucket"
        ).alias(
            "candidate_tenable_age_bucket"
        ),

        F.col(
            "is_stale_90"
        ).alias(
            "candidate_tenable_stale_90"
        ),
    )
)


candidate_member_df = (
    candidate_feature_df

    .join(
        candidate_tenable_df,
        on="asset_key",
        how="left",
    )

    .withColumn(
        "candidate_uuid_norm",

        F.when(
            nonblank(
                F.col(
                    "candidate_tenable_uuid"
                )
            ),

            normalized(
                F.col(
                    "candidate_tenable_uuid"
                )
            )
        )
    )

    .withColumn(
        "candidate_ip",

        F.coalesce(
            F.col(
                "canonical_ip"
            ),
            F.col(
                "candidate_tenable_ip"
            )
        )
    )

    .withColumn(
        "candidate_ip_norm",

        normalized(
            F.col(
                "candidate_ip"
            )
        )
    )

    .withColumn(
        "tenable_identity_group_key",

        F.when(
            F.col(
                "candidate_uuid_norm"
            ).isNotNull(),

            F.concat(
                F.lit(
                    "TENABLE_UUID::"
                ),

                F.col(
                    "candidate_uuid_norm"
                )
            )
        )

        .otherwise(
            F.concat(
                F.lit(
                    "NO_UUID::"
                ),

                F.col(
                    "asset_key"
                )
            )
        )
    )

    .cache()
)


candidate_count = (
    candidate_member_df.count()
)


candidate_distinct_assets = (
    candidate_member_df

    .select(
        "asset_key"
    )

    .distinct()

    .count()
)


candidate_missing_tenable_context = (
    candidate_member_df

    .filter(
        F.col(
            "candidate_tenable_ip"
        ).isNull()
        &
        F.col(
            "candidate_tenable_uuid"
        ).isNull()
    )

    .count()
)


if candidate_count == 0:
    raise RuntimeError(
        "Cell 20 found no active unresolved-IP population."
    )


if candidate_count != candidate_distinct_assets:
    raise RuntimeError(
        "Active unresolved-IP population is not one row per asset."
    )


# ---------------------------------------------------------------------------
# 8. Full Asset Plane target identity context
# ---------------------------------------------------------------------------

asset_identity_context_df = (
    feature_df

    .select(
        "asset_key",

        F.col(
            "canonical_name"
        ).alias(
            "target_canonical_name"
        ),

        F.col(
            "canonical_serial"
        ).alias(
            "target_canonical_serial"
        ),

        F.col(
            "canonical_ip"
        ).alias(
            "target_canonical_ip"
        ),

        F.col(
            "identity_basis"
        ).alias(
            "target_identity_basis"
        ),

        F.col(
            "identity_strength"
        ).alias(
            "target_identity_strength"
        ),

        F.col(
            "source_mask_raw"
        ).alias(
            "target_source_mask_raw"
        ),

        F.col(
            "source_mask_active"
        ).alias(
            "target_source_mask_active"
        ),

        F.col(
            "source_mask_stale"
        ).alias(
            "target_source_mask_stale"
        ),

        F.col(
            "current_observation_status"
        ).alias(
            "target_current_observation_status"
        ),

        F.col(
            "visibility_evidence_count"
        ).alias(
            "target_visibility_evidence_count"
        ),

        F.col(
            "management_model"
        ).alias(
            "target_management_model"
        ),

        F.col(
            "management_owner"
        ).alias(
            "target_management_owner"
        ),

        F.col(
            "post_visibility_state"
        ).alias(
            "target_post_visibility_state"
        ),

        F.col(
            "attribution_confidence"
        ).alias(
            "target_attribution_confidence"
        ),
    )

    .withColumn(
        "target_stronger_non_ip_identity",

        (
            F.coalesce(
                F.col(
                    "target_identity_basis"
                ),
                F.lit(
                    "UNKNOWN"
                )
            )
            !=
            F.lit(
                "IP"
            )
        )
        &
        F.coalesce(
            F.col(
                "target_identity_strength"
            ),
            F.lit(
                "UNKNOWN"
            )
        ).isin(
            "STRONG",
            "MODERATE",
        )
    )
)


# ---------------------------------------------------------------------------
# 9. Source-local Tenable UUID profile
#
# Establish whether candidate UUIDs already occur against stronger Asset Plane
# identities. These are RCAIP source-normalization / identity-model conditions,
# not enterprise customer cases.
# ---------------------------------------------------------------------------

all_tenable_uuid_member_df = (
    tenable_df

    .filter(
        nonblank(
            F.col(
                "tenable_host_uuid"
            )
        )
    )

    .select(
        "asset_key",

        F.col(
            "tenable_host_uuid"
        ).alias(
            "tenable_host_uuid"
        ),

        normalized(
            F.col(
                "tenable_host_uuid"
            )
        ).alias(
            "uuid_norm"
        ),

        F.col(
            "ip_address"
        ).alias(
            "tenable_ip"
        ),
    )

    .join(
        asset_identity_context_df,
        on="asset_key",
        how="left",
    )

    .withColumn(
        "stronger_non_ip_identity",

        (
            F.coalesce(
                F.col(
                    "target_identity_basis"
                ),
                F.lit(
                    "UNKNOWN"
                )
            )
            !=
            F.lit(
                "IP"
            )
        )
        &
        F.coalesce(
            F.col(
                "target_identity_strength"
            ),
            F.lit(
                "UNKNOWN"
            )
        ).isin(
            "STRONG",
            "MODERATE",
        )
    )

    .cache()
)


uuid_profile_df = (
    all_tenable_uuid_member_df

    .groupBy(
        "uuid_norm"
    )

    .agg(
        F.first(
            "tenable_host_uuid",
            ignorenulls=True,
        ).alias(
            "profile_tenable_host_uuid"
        ),

        F.countDistinct(
            "asset_key"
        ).alias(
            "all_uuid_asset_count"
        ),

        F.countDistinct(
            F.when(
                F.col(
                    "stronger_non_ip_identity"
                ),

                F.col(
                    "asset_key"
                )
            )
        ).alias(
            "stronger_uuid_asset_count"
        ),

        F.sort_array(
            F.collect_set(
                F.when(
                    F.col(
                        "stronger_non_ip_identity"
                    ),

                    F.col(
                        "asset_key"
                    )
                )
            )
        ).alias(
            "stronger_uuid_asset_keys"
        ),

        F.sort_array(
            F.collect_set(
                F.when(
                    F.col(
                        "stronger_non_ip_identity"
                    ),

                    F.col(
                        "target_canonical_name"
                    )
                )
            )
        ).alias(
            "stronger_uuid_asset_names"
        ),

        F.sort_array(
            F.collect_set(
                F.when(
                    F.col(
                        "stronger_non_ip_identity"
                    ),

                    F.col(
                        "target_source_mask_active"
                    )
                )
            )
        ).alias(
            "stronger_uuid_active_source_masks"
        ),
    )
)


# ---------------------------------------------------------------------------
# 10. Candidate population at Tenable UUID identity grain
# ---------------------------------------------------------------------------

candidate_group_df = (
    candidate_member_df

    .groupBy(
        "tenable_identity_group_key",
        "candidate_uuid_norm",
    )

    .agg(
        F.first(
            "candidate_tenable_uuid",
            ignorenulls=True,
        ).alias(
            "candidate_tenable_uuid"
        ),

        F.countDistinct(
            "asset_key"
        ).alias(
            "candidate_asset_count"
        ),

        F.sort_array(
            F.collect_set(
                "asset_key"
            )
        ).alias(
            "candidate_asset_keys"
        ),

        F.sort_array(
            F.collect_set(
                "candidate_ip"
            )
        ).alias(
            "candidate_ips"
        ),
    )

    .join(
        uuid_profile_df,

        F.col(
            "candidate_uuid_norm"
        )
        ==
        F.col(
            "uuid_norm"
        ),

        how="left",
    )

    .drop(
        "uuid_norm"
    )

    .fillna({
        "all_uuid_asset_count": 0,
        "stronger_uuid_asset_count": 0,
    })

    .withColumn(
        "source_local_uuid_class",

        F.when(
            F.col(
                "stronger_uuid_asset_count"
            )
            >
            F.lit(0),

            F.lit(
                "UUID_LINKS_EXISTING_DURABLE_ASSET"
            )
        )

        .when(
            F.col(
                "candidate_asset_count"
            )
            >
            F.lit(1),

            F.lit(
                "UUID_COLLAPSES_MULTIPLE_IP_ASSET_KEYS"
            )
        )

        .otherwise(
            F.lit(
                "UNIQUE_TENABLE_UUID_NO_EXISTING_ASSET_LINK"
            )
        )
    )

    .cache()
)


candidate_group_count = (
    candidate_group_df.count()
)


candidate_group_member_count = (
    candidate_group_df

    .agg(
        F.sum(
            "candidate_asset_count"
        ).alias(
            "member_count"
        )
    )

    .first()[
        "member_count"
    ]
)


candidate_group_member_count = int(
    candidate_group_member_count
    or
    0
)


# ---------------------------------------------------------------------------
# 11. RCAIP-engineering source-local UUID cohort assignment
# ---------------------------------------------------------------------------

source_local_link_df = (
    candidate_group_df

    .filter(
        F.col(
            "source_local_uuid_class"
        )
        ==
        F.lit(
            "UUID_LINKS_EXISTING_DURABLE_ASSET"
        )
    )

    .withColumn(
        "explanation_family",

        F.lit(
            "SOURCE_LOCAL_IDENTITY_MODEL_RECONCILIATION"
        )
    )

    .withColumn(
        "explanation_class",

        F.when(
            F.col(
                "stronger_uuid_asset_count"
            )
            ==
            F.lit(1),

            F.lit(
                "TENABLE_UUID_ALREADY_REPRESENTED_BY_STRONGER_ASSET"
            )
        )

        .otherwise(
            F.lit(
                "TENABLE_UUID_LINKS_MULTIPLE_STRONGER_ASSETS_REVIEW"
            )
        )
    )

    .withColumn(
        "provisional_treatment_lane",

        F.lit(
            "RCAIP_ENGINEERING"
        )
    )

    .withColumn(
        "recommended_treatment",

        F.when(
            F.col(
                "stronger_uuid_asset_count"
            )
            ==
            F.lit(1),

            F.lit(
                "Review Asset Plane Tenable identity precedence so an IP-keyed "
                "observation carrying a Tenable host UUID already represented "
                "by one stronger asset identity does not become a separate "
                "analytical asset without explicit lifecycle justification."
            )
        )

        .otherwise(
            F.lit(
                "Review source-local Tenable UUID semantics and Asset Plane "
                "identity precedence because one UUID relates to multiple "
                "stronger Asset Plane identities."
            )
        )
    )

    .withColumn(
        "cohort_status",

        F.when(
            F.col(
                "stronger_uuid_asset_count"
            )
            ==
            F.lit(1),

            F.lit(
                "RECONCILIATION_PATTERN_SUPPORTED"
            )
        )

        .otherwise(
            F.lit(
                "MODEL_REVIEW_REQUIRED"
            )
        )
    )

    .withColumn(
        "evidence_source_family_sets",

        F.lit(
            "TENABLE_HOST_UUID"
        )
    )

    .withColumn(
        "cohort_signature",

        F.concat_ws(
            " | ",

            F.col(
                "explanation_family"
            ),

            F.col(
                "explanation_class"
            ),

            F.col(
                "provisional_treatment_lane"
            ),

            F.col(
                "evidence_source_family_sets"
            ),
        )
    )

    .select(
        F.col(
            "tenable_identity_group_key"
        ).alias(
            "analysis_subject_key"
        ),

        "candidate_tenable_uuid",
        "candidate_asset_count",
        "candidate_asset_keys",
        "candidate_ips",

        F.col(
            "stronger_uuid_asset_count"
        ).alias(
            "target_asset_count"
        ),

        F.col(
            "stronger_uuid_asset_keys"
        ).alias(
            "target_asset_keys"
        ),

        F.col(
            "stronger_uuid_asset_names"
        ).alias(
            "target_names"
        ),

        "evidence_source_family_sets",

        "explanation_family",
        "explanation_class",

        "provisional_treatment_lane",
        "recommended_treatment",

        "cohort_status",
        "cohort_signature",
    )

    .cache()
)


source_local_link_group_count = (
    source_local_link_df.count()
)


# ---------------------------------------------------------------------------
# 12. Remaining groups after source-local UUID reconciliation
# ---------------------------------------------------------------------------

remaining_group_df = (
    candidate_group_df

    .filter(
        F.col(
            "source_local_uuid_class"
        )
        !=
        F.lit(
            "UUID_LINKS_EXISTING_DURABLE_ASSET"
        )
    )

    .cache()
)


remaining_group_count = (
    remaining_group_df.count()
)


remaining_candidate_member_df = (
    candidate_member_df

    .join(
        F.broadcast(
            remaining_group_df

            .select(
                "tenable_identity_group_key"
            )
        ),

        on="tenable_identity_group_key",
        how="inner",
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 13. Build stronger exact-IP Asset Plane evidence
#
# Exact IP remains relationship/corroboration evidence only.
# ---------------------------------------------------------------------------

cmdb_ip_evidence_df = (
    scored_df

    .filter(
        F.col(
            "cmdb_present"
        )
        ==
        F.lit(
            "Y"
        )
    )

    .filter(
        nonblank(
            F.col(
                "cmdb_ip"
            )
        )
    )

    .select(
        F.col(
            "asset_key"
        ).alias(
            "target_asset_key"
        ),

        F.lit(
            "CMDB"
        ).alias(
            "evidence_source_family"
        ),

        F.col(
            "cmdb_ip"
        ).alias(
            "evidence_ip"
        ),

        normalized(
            F.col(
                "cmdb_ip"
            )
        ).alias(
            "evidence_ip_norm"
        ),

        F.col(
            "cmdb_most_recent_discovery"
        ).cast(
            "timestamp"
        ).alias(
            "evidence_timestamp"
        ),

        F.lit(
            "INVENTORY"
        ).alias(
            "evidence_state"
        ),
    )
)


nmap_ip_evidence_df = (
    scored_df

    .filter(
        F.col(
            "nmap_present"
        )
        ==
        F.lit(
            "Y"
        )
    )

    .filter(
        nonblank(
            F.col(
                "nmap_ip"
            )
        )
    )

    .select(
        F.col(
            "asset_key"
        ).alias(
            "target_asset_key"
        ),

        F.lit(
            "NMAP"
        ).alias(
            "evidence_source_family"
        ),

        F.col(
            "nmap_ip"
        ).alias(
            "evidence_ip"
        ),

        normalized(
            F.col(
                "nmap_ip"
            )
        ).alias(
            "evidence_ip_norm"
        ),

        F.col(
            "nmap_last_observed_timestamp"
        ).cast(
            "timestamp"
        ).alias(
            "evidence_timestamp"
        ),

        F.when(
            F.col(
                "nmap_active"
            )
            ==
            F.lit(1),

            F.lit(
                "CURRENT"
            )
        )

        .when(
            F.col(
                "nmap_stale"
            )
            ==
            F.lit(1),

            F.lit(
                "STALE"
            )
        )

        .otherwise(
            F.lit(
                "PRESENT_UNRESOLVED"
            )
        ).alias(
            "evidence_state"
        ),
    )
)


qualys_ip_evidence_df = (
    scored_df

    .filter(
        F.col(
            "qualys_present"
        )
        ==
        F.lit(
            "Y"
        )
    )

    .filter(
        nonblank(
            F.col(
                "qualys_ip"
            )
        )
    )

    .select(
        F.col(
            "asset_key"
        ).alias(
            "target_asset_key"
        ),

        F.lit(
            "QUALYS"
        ).alias(
            "evidence_source_family"
        ),

        F.col(
            "qualys_ip"
        ).alias(
            "evidence_ip"
        ),

        normalized(
            F.col(
                "qualys_ip"
            )
        ).alias(
            "evidence_ip_norm"
        ),

        F.col(
            "qualys_inventory_last_updated_on"
        ).cast(
            "timestamp"
        ).alias(
            "evidence_timestamp"
        ),

        F.when(
            F.col(
                "qualys_active"
            )
            ==
            F.lit(1),

            F.lit(
                "CURRENT"
            )
        )

        .when(
            F.col(
                "qualys_stale"
            )
            ==
            F.lit(1),

            F.lit(
                "STALE"
            )
        )

        .otherwise(
            F.lit(
                "PRESENT_UNRESOLVED"
            )
        ).alias(
            "evidence_state"
        ),
    )
)


exact_ip_evidence_df = (
    cmdb_ip_evidence_df

    .unionByName(
        nmap_ip_evidence_df
    )

    .unionByName(
        qualys_ip_evidence_df
    )

    .join(
        asset_identity_context_df,

        F.col(
            "target_asset_key"
        )
        ==
        F.col(
            "asset_key"
        ),

        how="left",
    )

    .drop(
        "asset_key"
    )

    .filter(
        F.col(
            "target_stronger_non_ip_identity"
        )
        ==
        F.lit(True)
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 14. Target Tenable context
# ---------------------------------------------------------------------------

target_tenable_df = (
    tenable_df

    .select(
        F.col(
            "asset_key"
        ).alias(
            "target_asset_key"
        ),

        F.col(
            "tenable_host_uuid"
        ).alias(
            "target_tenable_uuid"
        ),

        F.col(
            "ip_address"
        ).alias(
            "target_tenable_ip"
        ),

        F.col(
            "last_observed_timestamp"
        ).alias(
            "target_tenable_last_observed"
        ),

        F.col(
            "days_since_observed"
        ).alias(
            "target_tenable_age_days"
        ),

        F.col(
            "observation_age_bucket"
        ).alias(
            "target_tenable_age_bucket"
        ),

        F.col(
            "is_stale_90"
        ).alias(
            "target_tenable_stale_90"
        ),
    )

    .withColumn(
        "target_tenable_uuid_norm",

        F.when(
            nonblank(
                F.col(
                    "target_tenable_uuid"
                )
            ),

            normalized(
                F.col(
                    "target_tenable_uuid"
                )
            )
        )
    )

    .withColumn(
        "target_tenable_ip_norm",

        F.when(
            nonblank(
                F.col(
                    "target_tenable_ip"
                )
            ),

            normalized(
                F.col(
                    "target_tenable_ip"
                )
            )
        )
    )
)


# ---------------------------------------------------------------------------
# 15. Candidate -> stronger-target exact-IP relationships
# ---------------------------------------------------------------------------

candidate_exact_ip_df = (
    remaining_candidate_member_df.alias(
        "candidate"
    )

    .join(
        exact_ip_evidence_df.alias(
            "evidence"
        ),

        (
            F.col(
                "candidate.candidate_ip_norm"
            )
            ==
            F.col(
                "evidence.evidence_ip_norm"
            )
        )
        &
        (
            F.col(
                "candidate.asset_key"
            )
            !=
            F.col(
                "evidence.target_asset_key"
            )
        ),

        how="inner",
    )

    .select(
        F.col(
            "candidate.tenable_identity_group_key"
        ).alias(
            "tenable_identity_group_key"
        ),

        F.col(
            "candidate.candidate_uuid_norm"
        ).alias(
            "candidate_uuid_norm"
        ),

        F.col(
            "candidate.candidate_tenable_uuid"
        ).alias(
            "candidate_tenable_uuid"
        ),

        F.col(
            "candidate.asset_key"
        ).alias(
            "candidate_asset_key"
        ),

        F.col(
            "candidate.candidate_ip"
        ).alias(
            "candidate_ip"
        ),

        F.col(
            "candidate.candidate_ip_norm"
        ).alias(
            "candidate_ip_norm"
        ),

        F.col(
            "evidence.target_asset_key"
        ).alias(
            "target_asset_key"
        ),

        F.col(
            "evidence.target_canonical_name"
        ).alias(
            "target_canonical_name"
        ),

        F.col(
            "evidence.target_canonical_serial"
        ).alias(
            "target_canonical_serial"
        ),

        F.col(
            "evidence.target_identity_basis"
        ).alias(
            "target_identity_basis"
        ),

        F.col(
            "evidence.target_identity_strength"
        ).alias(
            "target_identity_strength"
        ),

        F.col(
            "evidence.target_source_mask_active"
        ).alias(
            "target_source_mask_active"
        ),

        F.col(
            "evidence.target_source_mask_stale"
        ).alias(
            "target_source_mask_stale"
        ),

        F.col(
            "evidence.target_visibility_evidence_count"
        ).alias(
            "target_visibility_evidence_count"
        ),

        F.col(
            "evidence.target_management_model"
        ).alias(
            "target_management_model"
        ),

        F.col(
            "evidence.target_management_owner"
        ).alias(
            "target_management_owner"
        ),

        F.col(
            "evidence.evidence_source_family"
        ).alias(
            "evidence_source_family"
        ),

        F.col(
            "evidence.evidence_timestamp"
        ).alias(
            "evidence_timestamp"
        ),

        F.col(
            "evidence.evidence_state"
        ).alias(
            "evidence_state"
        ),
    )

    .dropDuplicates([
        "tenable_identity_group_key",
        "candidate_asset_key",
        "candidate_ip_norm",
        "target_asset_key",
        "evidence_source_family",
    ])

    .join(
        target_tenable_df,
        on="target_asset_key",
        how="left",
    )

    .withColumn(
        "target_tenable_present",

        F.col(
            "target_tenable_uuid"
        ).isNotNull()
        |
        F.col(
            "target_tenable_ip"
        ).isNotNull()
    )

    .withColumn(
        "target_uuid_matches_candidate",

        F.col(
            "candidate_uuid_norm"
        ).isNotNull()
        &
        F.col(
            "target_tenable_uuid_norm"
        ).isNotNull()
        &
        (
            F.col(
                "candidate_uuid_norm"
            )
            ==
            F.col(
                "target_tenable_uuid_norm"
            )
        )
    )

    .withColumn(
        "target_tenable_ip_matches_candidate",

        F.col(
            "target_tenable_ip_norm"
        ).isNotNull()
        &
        (
            F.col(
                "target_tenable_ip_norm"
            )
            ==
            F.col(
                "candidate_ip_norm"
            )
        )
    )

    .withColumn(
        "target_tenable_currentish",

        F.col(
            "target_tenable_present"
        )
        &
        ~stale_flag_true(
            F.col(
                "target_tenable_stale_90"
            )
        )
    )

    .withColumn(
        "target_current_by_asset_plane",

        F.coalesce(
            F.col(
                "target_visibility_evidence_count"
            ),
            F.lit(0)
        )
        >
        F.lit(0)
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 16. Collapse to one row per candidate-group / target asset
# ---------------------------------------------------------------------------

candidate_target_df = (
    candidate_exact_ip_df

    .groupBy(
        "tenable_identity_group_key",

        "candidate_uuid_norm",
        "candidate_tenable_uuid",

        "target_asset_key",
        "target_canonical_name",
        "target_canonical_serial",

        "target_identity_basis",
        "target_identity_strength",

        "target_source_mask_active",
        "target_source_mask_stale",

        "target_visibility_evidence_count",

        "target_management_model",
        "target_management_owner",

        "target_tenable_present",
        "target_tenable_uuid",
        "target_tenable_ip",

        "target_tenable_last_observed",
        "target_tenable_age_days",
        "target_tenable_age_bucket",
        "target_tenable_stale_90",
    )

    .agg(
        F.countDistinct(
            "candidate_asset_key"
        ).alias(
            "candidate_member_count"
        ),

        F.sort_array(
            F.collect_set(
                "candidate_asset_key"
            )
        ).alias(
            "candidate_asset_keys"
        ),

        F.sort_array(
            F.collect_set(
                "candidate_ip"
            )
        ).alias(
            "candidate_ips"
        ),

        F.sort_array(
            F.collect_set(
                "evidence_source_family"
            )
        ).alias(
            "evidence_source_families"
        ),

        F.sort_array(
            F.collect_set(
                "evidence_state"
            )
        ).alias(
            "evidence_states"
        ),

        F.max(
            F.when(
                F.col(
                    "target_uuid_matches_candidate"
                ),
                F.lit(1),
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "_same_uuid"
        ),

        F.max(
            F.when(
                F.col(
                    "target_tenable_ip_matches_candidate"
                ),
                F.lit(1),
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "_same_tenable_ip"
        ),

        F.max(
            F.when(
                F.col(
                    "target_tenable_currentish"
                ),
                F.lit(1),
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "_target_tenable_currentish"
        ),

        F.max(
            F.when(
                F.col(
                    "target_current_by_asset_plane"
                ),
                F.lit(1),
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "_target_current"
        ),
    )

    .withColumn(
        "target_uuid_matches_candidate",

        F.col(
            "_same_uuid"
        )
        ==
        F.lit(1)
    )

    .withColumn(
        "target_tenable_ip_matches_candidate",

        F.col(
            "_same_tenable_ip"
        )
        ==
        F.lit(1)
    )

    .withColumn(
        "target_tenable_currentish",

        F.col(
            "_target_tenable_currentish"
        )
        ==
        F.lit(1)
    )

    .withColumn(
        "target_current_by_asset_plane",

        F.col(
            "_target_current"
        )
        ==
        F.lit(1)
    )

    .drop(
        "_same_uuid",
        "_same_tenable_ip",
        "_target_tenable_currentish",
        "_target_current",
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 17. Target-level primitive relationship classification
#
# No class here is itself an assurance case.
# ---------------------------------------------------------------------------

candidate_target_df = (
    candidate_target_df

    .withColumn(
        "target_relationship_class",

        F.when(
            F.col(
                "target_uuid_matches_candidate"
            ),

            F.lit(
                "SAME_TENABLE_UUID"
            )
        )

        .when(
            F.col(
                "target_tenable_present"
            )
            &
            F.col(
                "target_tenable_ip_matches_candidate"
            )
            &
            F.col(
                "target_tenable_currentish"
            ),

            F.lit(
                "SAME_IP_DIFFERENT_CURRENT_TENABLE_UUID"
            )
        )

        .when(
            F.col(
                "target_tenable_present"
            )
            &
            F.col(
                "target_tenable_ip_matches_candidate"
            ),

            F.lit(
                "SAME_IP_DIFFERENT_STALE_TENABLE_UUID"
            )
        )

        .when(
            F.col(
                "target_tenable_present"
            )
            &
            ~F.col(
                "target_tenable_ip_matches_candidate"
            )
            &
            F.col(
                "target_tenable_currentish"
            ),

            F.lit(
                "TARGET_CURRENT_TENABLE_DIFFERENT_IP"
            )
        )

        .when(
            F.col(
                "target_tenable_present"
            )
            &
            ~F.col(
                "target_tenable_ip_matches_candidate"
            ),

            F.lit(
                "TARGET_STALE_TENABLE_DIFFERENT_IP"
            )
        )

        .when(
            F.col(
                "target_current_by_asset_plane"
            ),

            F.lit(
                "CURRENT_TARGET_WITHOUT_TENABLE_IP_RELATIONSHIP"
            )
        )

        .otherwise(
            F.lit(
                "NONCURRENT_INVENTORY_IP_RELATIONSHIP"
            )
        )
    )
)


# ---------------------------------------------------------------------------
# 18. Compress target relationships to Tenable identity-group grain
# ---------------------------------------------------------------------------

ip_group_profile_df = (
    candidate_target_df

    .groupBy(
        "tenable_identity_group_key",
        "candidate_uuid_norm",
        "candidate_tenable_uuid",
    )

    .agg(
        F.countDistinct(
            "target_asset_key"
        ).alias(
            "target_asset_count"
        ),

        F.sort_array(
            F.collect_set(
                "target_asset_key"
            )
        ).alias(
            "target_asset_keys"
        ),

        F.sort_array(
            F.collect_set(
                "target_canonical_name"
            )
        ).alias(
            "target_names"
        ),

        F.concat_ws(
            " || ",

            F.sort_array(
                F.collect_set(
                    F.concat_ws(
                        "+",
                        F.sort_array(
                            F.col(
                                "evidence_source_families"
                            )
                        )
                    )
                )
            )
        ).alias(
            "evidence_source_family_sets"
        ),

        F.sum(
            F.when(
                F.col(
                    "target_current_by_asset_plane"
                ),
                F.lit(1),
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "current_target_count"
        ),

        F.sum(
            F.when(
                ~F.col(
                    "target_current_by_asset_plane"
                ),
                F.lit(1),
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "noncurrent_target_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "target_relationship_class"
                )
                ==
                F.lit(
                    "SAME_IP_DIFFERENT_CURRENT_TENABLE_UUID"
                ),

                F.lit(1),
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "same_ip_different_current_uuid_target_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "target_relationship_class"
                )
                ==
                F.lit(
                    "SAME_IP_DIFFERENT_STALE_TENABLE_UUID"
                ),

                F.lit(1),
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "same_ip_different_stale_uuid_target_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "target_relationship_class"
                )
                ==
                F.lit(
                    "TARGET_CURRENT_TENABLE_DIFFERENT_IP"
                ),

                F.lit(1),
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "current_target_different_ip_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "target_relationship_class"
                )
                ==
                F.lit(
                    "TARGET_STALE_TENABLE_DIFFERENT_IP"
                ),

                F.lit(1),
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "stale_target_different_ip_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "target_relationship_class"
                )
                ==
                F.lit(
                    "CURRENT_TARGET_WITHOUT_TENABLE_IP_RELATIONSHIP"
                ),

                F.lit(1),
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "current_target_without_tenable_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "target_relationship_class"
                )
                ==
                F.lit(
                    "NONCURRENT_INVENTORY_IP_RELATIONSHIP"
                ),

                F.lit(1),
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "noncurrent_inventory_target_count"
        ),

        F.sort_array(
            F.collect_set(
                "target_relationship_class"
            )
        ).alias(
            "target_relationship_classes"
        ),
    )

    .join(
        remaining_group_df

        .select(
            "tenable_identity_group_key",
            "candidate_asset_count",
            "candidate_asset_keys",
            "candidate_ips",
            "source_local_uuid_class",
        ),

        on="tenable_identity_group_key",
        how="left",
    )

    .cache()
)


ip_linked_group_count = (
    ip_group_profile_df.count()
)


# ---------------------------------------------------------------------------
# 19. Assign enterprise explanatory reconciliation cohorts
#
# Precedence:
#   1. Multiple stronger target identities
#   2. Same IP / different current Tenable UUID
#   3. Same IP / different stale Tenable UUID
#   4. Current target Tenable at another IP
#   5. Stale target Tenable at another IP
#   6. Current stronger target with no Tenable relationship
#   7. Non-current inventory relationship
#   8. Model review
#
# Multi-target groups intentionally share one treatment family when their
# evidence-source family set is the same. Member-level composition is retained.
# ---------------------------------------------------------------------------

ip_cohort_assignment_df = (
    ip_group_profile_df

    .withColumn(
        "explanation_family",

        F.lit(
            "ENTERPRISE_IDENTITY_AND_LIFECYCLE_RECONCILIATION"
        )
    )

    .withColumn(
        "explanation_class",

        F.when(
            F.col(
                "target_asset_count"
            )
            >
            F.lit(1),

            F.lit(
                "MULTI_TARGET_IP_ASSIGNMENT_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "same_ip_different_current_uuid_target_count"
            )
            >
            F.lit(0),

            F.lit(
                "CURRENT_TENABLE_IP_IDENTITY_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "same_ip_different_stale_uuid_target_count"
            )
            >
            F.lit(0),

            F.lit(
                "STALE_TENABLE_IP_IDENTITY_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "current_target_different_ip_count"
            )
            >
            F.lit(0),

            F.lit(
                "CURRENT_TARGET_INVENTORY_IP_REASSIGNMENT"
            )
        )

        .when(
            F.col(
                "stale_target_different_ip_count"
            )
            >
            F.lit(0),

            F.lit(
                "STALE_TENABLE_TARGET_INVENTORY_IP_REASSIGNMENT"
            )
        )

        .when(
            F.col(
                "current_target_without_tenable_count"
            )
            >
            F.lit(0),

            F.lit(
                "CURRENT_TARGET_INVENTORY_IP_VALIDATION"
            )
        )

        .when(
            F.col(
                "noncurrent_inventory_target_count"
            )
            >
            F.lit(0),

            F.lit(
                "NONCURRENT_INVENTORY_IP_LIFECYCLE_RECONCILIATION"
            )
        )

        .otherwise(
            F.lit(
                "LINKED_RELATIONSHIP_MODEL_REVIEW_REQUIRED"
            )
        )
    )

    .withColumn(
        "provisional_treatment_lane",

        F.when(
            F.col(
                "explanation_class"
            )
            ==
            F.lit(
                "MULTI_TARGET_IP_ASSIGNMENT_RECONCILIATION"
            ),

            F.lit(
                "ENTERPRISE_DATA_AND_SERVICE_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "explanation_class"
            ).isin(
                "CURRENT_TENABLE_IP_IDENTITY_RECONCILIATION",
                "STALE_TENABLE_IP_IDENTITY_RECONCILIATION",
            ),

            F.lit(
                "ENTERPRISE_SERVICE_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "explanation_class"
            )
            ==
            F.lit(
                "CURRENT_TARGET_INVENTORY_IP_REASSIGNMENT"
            ),

            F.lit(
                "ENTERPRISE_DATA_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "explanation_class"
            )
            ==
            F.lit(
                "STALE_TENABLE_TARGET_INVENTORY_IP_REASSIGNMENT"
            ),

            F.lit(
                "ENTERPRISE_DATA_AND_SERVICE_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "explanation_class"
            ).isin(
                "CURRENT_TARGET_INVENTORY_IP_VALIDATION",
                "NONCURRENT_INVENTORY_IP_LIFECYCLE_RECONCILIATION",
            ),

            F.lit(
                "ENTERPRISE_DATA_RECONCILIATION"
            )
        )

        .otherwise(
            F.lit(
                "RCAIP_ENGINEERING_REVIEW"
            )
        )
    )

    .withColumn(
        "recommended_treatment",

        F.when(
            F.col(
                "explanation_class"
            )
            ==
            F.lit(
                "MULTI_TARGET_IP_ASSIGNMENT_RECONCILIATION"
            ),

            F.lit(
                "Reconcile the shared IP assignment across the stronger "
                "enterprise asset identities and Tenable identities. Determine "
                "which records are current, historical, duplicated, or stale "
                "before any identity consolidation."
            )
        )

        .when(
            F.col(
                "explanation_class"
            )
            ==
            F.lit(
                "CURRENT_TENABLE_IP_IDENTITY_RECONCILIATION"
            ),

            F.lit(
                "Reconcile multiple current or recent Tenable UUID identities "
                "observed for the same IP and determine whether the condition "
                "reflects expected IP reuse, source lifecycle, or duplicate "
                "enterprise service identity."
            )
        )

        .when(
            F.col(
                "explanation_class"
            )
            ==
            F.lit(
                "STALE_TENABLE_IP_IDENTITY_RECONCILIATION"
            ),

            F.lit(
                "Reconcile the current Tenable identity against the stale "
                "Tenable identity historically associated with the same IP."
            )
        )

        .when(
            F.col(
                "explanation_class"
            )
            ==
            F.lit(
                "CURRENT_TARGET_INVENTORY_IP_REASSIGNMENT"
            ),

            F.lit(
                "Reconcile inventory IP assignment because the stronger target "
                "asset is currently represented by Tenable at a different IP."
            )
        )

        .when(
            F.col(
                "explanation_class"
            )
            ==
            F.lit(
                "STALE_TENABLE_TARGET_INVENTORY_IP_REASSIGNMENT"
            ),

            F.lit(
                "Reconcile inventory and Tenable lifecycle because the stronger "
                "target has stale Tenable evidence at another IP while the "
                "candidate is currently observed at the inventory-associated IP."
            )
        )

        .when(
            F.col(
                "explanation_class"
            )
            ==
            F.lit(
                "CURRENT_TARGET_INVENTORY_IP_VALIDATION"
            ),

            F.lit(
                "Validate whether the inventory IP relationship remains valid "
                "for the stronger currently observed asset before using the IP "
                "as identity evidence."
            )
        )

        .when(
            F.col(
                "explanation_class"
            )
            ==
            F.lit(
                "NONCURRENT_INVENTORY_IP_LIFECYCLE_RECONCILIATION"
            ),

            F.lit(
                "Reconcile stale or retired inventory assignment because the "
                "inventory asset has no current observation while a different "
                "Tenable identity is currently using the associated IP."
            )
        )

        .otherwise(
            F.lit(
                "RCAIP model review required before customer treatment."
            )
        )
    )

    .withColumn(
        "cohort_status",

        F.when(
            F.col(
                "explanation_class"
            )
            ==
            F.lit(
                "LINKED_RELATIONSHIP_MODEL_REVIEW_REQUIRED"
            ),

            F.lit(
                "MODEL_REVIEW_REQUIRED"
            )
        )

        .otherwise(
            F.lit(
                "RECONCILIATION_PATTERN_SUPPORTED"
            )
        )
    )

    .withColumn(
        "cohort_signature",

        F.concat_ws(
            " | ",

            F.col(
                "explanation_family"
            ),

            F.col(
                "explanation_class"
            ),

            F.col(
                "provisional_treatment_lane"
            ),

            F.coalesce(
                F.col(
                    "evidence_source_family_sets"
                ),
                F.lit(
                    "UNKNOWN_SOURCE_FAMILY"
                )
            ),
        )
    )

    .select(
        F.col(
            "tenable_identity_group_key"
        ).alias(
            "analysis_subject_key"
        ),

        "candidate_tenable_uuid",
        "candidate_asset_count",
        "candidate_asset_keys",
        "candidate_ips",

        "target_asset_count",
        "target_asset_keys",
        "target_names",

        "evidence_source_family_sets",

        "explanation_family",
        "explanation_class",

        "provisional_treatment_lane",
        "recommended_treatment",

        "cohort_status",
        "cohort_signature",
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 20. Combine engineering + enterprise linked cohort assignments
# ---------------------------------------------------------------------------

linked_cohort_assignment_df = (
    source_local_link_df

    .unionByName(
        ip_cohort_assignment_df
    )

    .withColumn(
        "cohort_id",

        F.concat(
            F.lit(
                "VIS-"
            ),

            F.substring(
                F.sha2(
                    F.concat_ws(
                        "||",

                        F.lit(
                            str(
                                RCAIP_POST_SLUG
                            ).strip().lower()
                        ),

                        F.lit(
                            RCAIP_RUN_ID
                        ),

                        F.col(
                            "cohort_signature"
                        ),
                    ),
                    256,
                ),
                1,
                12,
            ),
        )
    )

    .cache()
)


linked_group_count = (
    linked_cohort_assignment_df

    .select(
        "analysis_subject_key"
    )

    .distinct()

    .count()
)


linked_assignment_rows = (
    linked_cohort_assignment_df.count()
)


duplicate_linked_group_assignments = (
    linked_cohort_assignment_df

    .groupBy(
        "analysis_subject_key"
    )

    .agg(
        F.countDistinct(
            "cohort_id"
        ).alias(
            "cohort_count"
        )
    )

    .filter(
        F.col(
            "cohort_count"
        )
        >
        F.lit(1)
    )

    .count()
)


# ---------------------------------------------------------------------------
# 21. Explanatory cohort summary
# ---------------------------------------------------------------------------

explanatory_cohort_summary_df = (
    linked_cohort_assignment_df

    .groupBy(
        "cohort_id",

        "cohort_status",

        "explanation_family",
        "explanation_class",

        "provisional_treatment_lane",
        "recommended_treatment",

        "evidence_source_family_sets",
    )

    .agg(
        F.countDistinct(
            "analysis_subject_key"
        ).alias(
            "tenable_identity_groups"
        ),

        F.sum(
            "candidate_asset_count"
        ).alias(
            "candidate_asset_rows"
        ),

        F.sum(
            "target_asset_count"
        ).alias(
            "related_stronger_asset_relationships"
        ),

        F.sort_array(
            F.collect_set(
                "analysis_subject_key"
            )
        ).alias(
            "member_identity_groups"
        ),
    )

    .orderBy(
        "cohort_status",
        "provisional_treatment_lane",
        F.desc(
            "tenable_identity_groups"
        ),
        "explanation_class",
    )
)


print("=" * 120)
print("LINKED TENABLE IDENTITIES - EXPLANATORY COHORT SUMMARY")
