# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 21 - No-Link Tenable Device / Network Context Qualification
# Version: 1.0
#
# Purpose:
#   Analyze ONLY the Tenable source-local identities that remain unexplained
#   after:
#
#       1. source-local Tenable UUID reconciliation; and
#       2. stronger exact-IP Asset Plane corroboration.
#
# This cell qualifies the remaining identities using EXISTING evidence:
#
#   - Tenable device-type key-driver hints
#   - Tenable ACR context
#   - Tenable observation recency
#   - current/stale Asset Plane context
#   - certified Nmap collection-target membership
#   - actual Nmap observation state
#
# Important:
#   A Tenable key-driver device type is a SOURCE-DERIVED HINT.
#   It does not silently rewrite RCAIP device_family/device_scope.
#
#   Nmap target membership means the address was within an intended certified
#   collection target. Lack of an Nmap observation does NOT prove absence.
#
# This cell DOES NOT:
#   - create assurance cases
#   - perform final customer routing
#   - merge identities
#   - modify asset_key
#   - create findings
#   - create tickets
#   - infer remediation
#   - query raw enterprise sources
#
# Post-agnostic:
#   - no example_post_a IPs
#   - no example_post_a hostnames
#   - no example_post_a counts
#   - Nmap target CIDRs come from runtime evidence
#   - same analytical source runs unchanged for future Posts
#
# Safety:
#   - READ ONLY
#   - durable RCAIP products + runtime collection metadata only
#   - Delta writes: NONE
# ============================================================================

import ipaddress
import json

from pyspark.sql import functions as F
from pyspark.sql import types as T


# ---------------------------------------------------------------------------
# 1. Runtime validation
# ---------------------------------------------------------------------------

REQUIRED_RUNTIME_OBJECTS = [
    "RCAIP_CONFIG_000_READY",
    "RCAIP_POST_NAME",
    "RCAIP_POST_SLUG",
    "RCAIP_RUN_ID",
    "get_rcaip_table",
]


missing_runtime_objects = [
    name
    for name in REQUIRED_RUNTIME_OBJECTS
    if name not in globals()
]


if missing_runtime_objects:
    raise RuntimeError(
        "Cell 21 requires Config 001 runtime. Missing: "
        + " | ".join(missing_runtime_objects)
    )


if not RCAIP_CONFIG_000_READY:
    raise RuntimeError(
        "Config 000 did not publish a ready runtime."
    )


runtime_nmap_scans = globals().get(
    "RCAIP_NMAP_SCANS",
    []
)


# ---------------------------------------------------------------------------
# 2. Resolve durable products
# ---------------------------------------------------------------------------

CONTROL_FEATURE_TABLE = get_rcaip_table(
    "IP006_CONTROL_ASSURANCE_FEATURE"
)


TENABLE_NORM_TABLE = get_rcaip_table(
    "TENABLE_NORM"
)


SCORED_ASSET_TABLE = get_rcaip_table(
    "ASSET_RECONCILIATION_SCORED"
)


for table_name in [
    CONTROL_FEATURE_TABLE,
    TENABLE_NORM_TABLE,
    SCORED_ASSET_TABLE,
]:

    if not spark.catalog.tableExists(
        table_name
    ):

        raise RuntimeError(
            "Required durable RCAIP product unavailable: "
            + table_name
        )


feature_source_df = spark.table(
    CONTROL_FEATURE_TABLE
)


tenable_source_df = spark.table(
    TENABLE_NORM_TABLE
)


scored_source_df = spark.table(
    SCORED_ASSET_TABLE
)


# ---------------------------------------------------------------------------
# 3. Required contracts
# ---------------------------------------------------------------------------

REQUIRED_FEATURE_COLUMNS = {
    "asset_key",
    "post_slug",
    "rcaip_run_id",

    "canonical_name",
    "canonical_serial",
    "canonical_ip",

    "device_family",
    "device_scope",

    "network_scope",

    "operational_boundary",
    "operational_boundary_confidence",

    "management_model",
    "management_owner",

    "identity_basis",
    "identity_strength",

    "source_mask_raw",
    "source_mask_active",
    "source_mask_stale",

    "current_observation_status",
    "visibility_evidence_count",
    "post_visibility_state",

    "attribution_confidence",
    "attribution_conflict_flag",

    "active_unresolved_ip_candidate",

    "acr_band",
}


REQUIRED_TENABLE_COLUMNS = {
    "asset_key",
    "post_slug",
    "rcaip_run_id",

    "ip_address",
    "tenable_host_uuid",

    "tenable_acr_score",
    "tenable_key_drivers",
    "tenable_organization_name",

    "tenable_event_time",

    "last_observed_timestamp",
    "days_since_observed",
    "observation_age_bucket",
    "is_stale_90",
}


REQUIRED_SCORED_COLUMNS = {
    "asset_key",
    "post_slug",
    "rcaip_run_id",

    "cmdb_present",
    "cmdb_ip",

    "nmap_present",
    "nmap_ip",
    "nmap_active",
    "nmap_stale",

    "qualys_present",
    "qualys_ip",
    "qualys_active",
    "qualys_stale",
}


missing_feature_columns = sorted(
    REQUIRED_FEATURE_COLUMNS
    -
    set(
        feature_source_df.columns
    )
)


missing_tenable_columns = sorted(
    REQUIRED_TENABLE_COLUMNS
    -
    set(
        tenable_source_df.columns
    )
)


missing_scored_columns = sorted(
    REQUIRED_SCORED_COLUMNS
    -
    set(
        scored_source_df.columns
    )
)


if missing_feature_columns:

    raise RuntimeError(
        "Control Assurance Feature missing columns: "
        + " | ".join(
            missing_feature_columns
        )
    )


if missing_tenable_columns:

    raise RuntimeError(
        "TENABLE_NORM missing columns: "
        + " | ".join(
            missing_tenable_columns
        )
    )


if missing_scored_columns:

    raise RuntimeError(
        "ASSET_RECONCILIATION_SCORED missing columns: "
        + " | ".join(
            missing_scored_columns
        )
    )


# ---------------------------------------------------------------------------
# 4. Runtime scoping
# ---------------------------------------------------------------------------

def runtime_slice(
    df
):

    return (
        df

        .filter(
            (
                F.lower(
                    F.trim(
                        F.col(
                            "post_slug"
                        )
                    )
                )
                ==
                F.lit(
                    str(
                        RCAIP_POST_SLUG
                    ).strip().lower()
                )
            )
            &
            (
                F.col(
                    "rcaip_run_id"
                )
                ==
                F.lit(
                    RCAIP_RUN_ID
                )
            )
        )
    )


feature_df = (
    runtime_slice(
        feature_source_df
    )
    .cache()
)


tenable_df = (
    runtime_slice(
        tenable_source_df
    )
    .cache()
)


scored_df = (
    runtime_slice(
        scored_source_df
    )
    .cache()
)


# ---------------------------------------------------------------------------
# 5. Grain certification
# ---------------------------------------------------------------------------

feature_rows = (
    feature_df.count()
)


feature_assets = (
    feature_df

    .select(
        "asset_key"
    )

    .distinct()

    .count()
)


tenable_rows = (
    tenable_df.count()
)


tenable_assets = (
    tenable_df

    .select(
        "asset_key"
    )

    .distinct()

    .count()
)


scored_rows = (
    scored_df.count()
)


scored_assets = (
    scored_df

    .select(
        "asset_key"
    )

    .distinct()

    .count()
)


if feature_rows != feature_assets:

    raise RuntimeError(
        "Control Assurance Feature is not one row per asset."
    )


if tenable_rows != tenable_assets:

    raise RuntimeError(
        "TENABLE_NORM is not one row per asset."
    )


if scored_rows != scored_assets:

    raise RuntimeError(
        "ASSET_RECONCILIATION_SCORED is not one row per asset."
    )


# ---------------------------------------------------------------------------
# 6. Helpers
# ---------------------------------------------------------------------------

def nonblank(
    col_expr
):

    return (
        col_expr.isNotNull()
        &
        (
            F.length(
                F.trim(
                    col_expr.cast(
                        "string"
                    )
                )
            )
            >
            F.lit(0)
        )
    )


def normalized(
    col_expr
):

    return (
        F.lower(
            F.trim(
                col_expr.cast(
                    "string"
                )
            )
        )
    )


def stale_flag_true(
    col_expr
):

    return (
        F.upper(
            F.trim(
                F.coalesce(
                    col_expr.cast(
                        "string"
                    ),
                    F.lit("")
                )
            )
        )
        .isin(
            "Y",
            "YES",
            "TRUE",
            "1",
        )
    )


# ---------------------------------------------------------------------------
# 7. Reconstruct current unresolved-IP population
# ---------------------------------------------------------------------------

unresolved_feature_df = (
    feature_df

    .filter(
        F.coalesce(
            F.col(
                "active_unresolved_ip_candidate"
            ),
            F.lit(False)
        )
        ==
        F.lit(True)
    )

    .select(
        "asset_key",

        "canonical_name",
        "canonical_serial",
        "canonical_ip",

        "device_family",
        "device_scope",

        "network_scope",

        "operational_boundary",
        "operational_boundary_confidence",

        "management_model",
        "management_owner",

        "identity_basis",
        "identity_strength",

        "source_mask_raw",
        "source_mask_active",
        "source_mask_stale",

        "current_observation_status",
        "visibility_evidence_count",
        "post_visibility_state",

        "attribution_confidence",
        "attribution_conflict_flag",

        "acr_band",
    )

    .cache()
)


starting_unresolved_ip_rows = (
    unresolved_feature_df.count()
)


# ---------------------------------------------------------------------------
# 8. Attach normalized Tenable evidence
#
# Inner join deliberately defines this analytical sub-branch:
# unresolved-IP assets that actually have normalized Tenable evidence.
# ---------------------------------------------------------------------------

tenable_context_df = (
    tenable_df

    .select(
        "asset_key",

        F.col(
            "ip_address"
        ).alias(
            "candidate_tenable_ip"
        ),

        F.col(
            "tenable_host_uuid"
        ).alias(
            "candidate_tenable_uuid"
        ),

        F.col(
            "tenable_acr_score"
        ).alias(
            "candidate_tenable_acr_score"
        ),

        F.col(
            "tenable_key_drivers"
        ).alias(
            "candidate_tenable_key_drivers"
        ),

        F.col(
            "tenable_organization_name"
        ).alias(
            "candidate_tenable_organization_name"
        ),

        F.col(
            "tenable_event_time"
        ).alias(
            "candidate_tenable_event_time"
        ),

        F.col(
            "last_observed_timestamp"
        ).alias(
            "candidate_tenable_last_observed"
        ),

        F.col(
            "days_since_observed"
        ).alias(
            "candidate_tenable_age_days"
        ),

        F.col(
            "observation_age_bucket"
        ).alias(
            "candidate_tenable_age_bucket"
        ),

        F.col(
            "is_stale_90"
        ).alias(
            "candidate_tenable_stale_90"
        ),
    )
)


candidate_member_df = (
    unresolved_feature_df

    .join(
        tenable_context_df,
        on="asset_key",
        how="inner",
    )

    .withColumn(
        "candidate_uuid_norm",

        F.when(
            nonblank(
                F.col(
                    "candidate_tenable_uuid"
                )
            ),

            normalized(
                F.col(
                    "candidate_tenable_uuid"
                )
            )
        )
    )

    .withColumn(
        "candidate_ip",

        F.coalesce(
            F.col(
                "canonical_ip"
            ),
            F.col(
                "candidate_tenable_ip"
            )
        )
    )

    .withColumn(
        "candidate_ip_norm",

        normalized(
            F.col(
                "candidate_ip"
            )
        )
    )

    .withColumn(
        "tenable_identity_group_key",

        F.when(
            F.col(
                "candidate_uuid_norm"
            ).isNotNull(),

            F.concat(
                F.lit(
                    "TENABLE_UUID::"
                ),

                F.col(
                    "candidate_uuid_norm"
                )
            )
        )

        .otherwise(
            F.concat(
                F.lit(
                    "NO_UUID::"
                ),

                F.col(
                    "asset_key"
                )
            )
        )
    )

    .cache()
)


tenable_unresolved_rows = (
    candidate_member_df.count()
)


non_tenable_unresolved_rows = (
    starting_unresolved_ip_rows
    -
    tenable_unresolved_rows
)


# ---------------------------------------------------------------------------
# 9. Stronger Asset Plane identity context
# ---------------------------------------------------------------------------

asset_identity_df = (
    feature_df

    .select(
        "asset_key",

        F.col(
            "identity_basis"
        ).alias(
            "target_identity_basis"
        ),

        F.col(
            "identity_strength"
        ).alias(
            "target_identity_strength"
        ),
    )

    .withColumn(
        "target_stronger_non_ip_identity",

        (
            F.coalesce(
                F.col(
                    "target_identity_basis"
                ),
                F.lit(
                    "UNKNOWN"
                )
            )
            !=
            F.lit(
                "IP"
            )
        )
        &
        F.coalesce(
            F.col(
                "target_identity_strength"
            ),
            F.lit(
                "UNKNOWN"
            )
        ).isin(
            "STRONG",
            "MODERATE",
        )
    )
)


# ---------------------------------------------------------------------------
# 10. Source-local Tenable UUID profile
#
# Determine whether an unresolved candidate UUID is already represented by a
# stronger non-IP Asset Plane identity.
# ---------------------------------------------------------------------------

all_tenable_uuid_member_df = (
    tenable_df

    .filter(
        nonblank(
            F.col(
                "tenable_host_uuid"
            )
        )
    )

    .select(
        "asset_key",

        normalized(
            F.col(
                "tenable_host_uuid"
            )
        ).alias(
            "uuid_norm"
        ),
    )

    .join(
        asset_identity_df,
        on="asset_key",
        how="left",
    )
)


uuid_profile_df = (
    all_tenable_uuid_member_df

    .groupBy(
        "uuid_norm"
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "all_uuid_asset_count"
        ),

        F.countDistinct(
            F.when(
                F.col(
                    "target_stronger_non_ip_identity"
                ),

                F.col(
                    "asset_key"
                )
            )
        ).alias(
            "stronger_uuid_asset_count"
        ),
    )
)


candidate_group_df = (
    candidate_member_df

    .groupBy(
        "tenable_identity_group_key",
        "candidate_uuid_norm",
    )

    .agg(
        F.first(
            "candidate_tenable_uuid",
            ignorenulls=True,
        ).alias(
            "candidate_tenable_uuid"
        ),

        F.countDistinct(
            "asset_key"
        ).alias(
            "candidate_asset_count"
        ),

        F.sort_array(
            F.collect_set(
                "asset_key"
            )
        ).alias(
            "candidate_asset_keys"
        ),

        F.sort_array(
            F.collect_set(
                "candidate_ip"
            )
        ).alias(
            "candidate_ips"
        ),
    )

    .join(
        uuid_profile_df,

        F.col(
            "candidate_uuid_norm"
        )
        ==
        F.col(
            "uuid_norm"
        ),

        how="left",
    )

    .drop(
        "uuid_norm"
    )

    .fillna({
        "all_uuid_asset_count": 0,
        "stronger_uuid_asset_count": 0,
    })

    .withColumn(
        "source_local_uuid_class",

        F.when(
            F.col(
                "stronger_uuid_asset_count"
            )
            >
            F.lit(0),

            F.lit(
                "UUID_LINKS_EXISTING_DURABLE_ASSET"
            )
        )

        .when(
            F.col(
                "candidate_asset_count"
            )
            >
            F.lit(1),

            F.lit(
                "UUID_COLLAPSES_MULTIPLE_IP_ASSET_KEYS"
            )
        )

        .otherwise(
            F.lit(
                "UNIQUE_TENABLE_UUID_NO_EXISTING_ASSET_LINK"
            )
        )
    )

    .cache()
)


candidate_group_count = (
    candidate_group_df.count()
)


source_local_link_group_count = (
    candidate_group_df

    .filter(
        F.col(
            "source_local_uuid_class"
        )
        ==
        F.lit(
            "UUID_LINKS_EXISTING_DURABLE_ASSET"
        )
    )

    .count()
)


remaining_group_df = (
    candidate_group_df

    .filter(
        F.col(
            "source_local_uuid_class"
        )
        !=
        F.lit(
            "UUID_LINKS_EXISTING_DURABLE_ASSET"
        )
    )

    .cache()
)


remaining_candidate_member_df = (
    candidate_member_df

    .join(
        F.broadcast(
            remaining_group_df

            .select(
                "tenable_identity_group_key"
            )
        ),

        on="tenable_identity_group_key",
        how="inner",
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 11. Build stronger exact-IP evidence from certified Asset Plane
#
# Only:
#   CMDB
#   Nmap
#   Qualys
#
# MDE public IP is deliberately excluded.
# ---------------------------------------------------------------------------

cmdb_ip_df = (
    scored_df

    .filter(
        F.col(
            "cmdb_present"
        )
        ==
        F.lit(
            "Y"
        )
    )

    .filter(
        nonblank(
            F.col(
                "cmdb_ip"
            )
        )
    )

    .select(
        F.col(
            "asset_key"
        ).alias(
            "target_asset_key"
        ),

        normalized(
            F.col(
                "cmdb_ip"
            )
        ).alias(
            "evidence_ip_norm"
        ),

        F.lit(
            "CMDB"
        ).alias(
            "evidence_source"
        ),
    )
)


nmap_ip_df = (
    scored_df

    .filter(
        F.col(
            "nmap_present"
        )
        ==
        F.lit(
            "Y"
        )
    )

    .filter(
        nonblank(
            F.col(
                "nmap_ip"
            )
        )
    )

    .select(
        F.col(
            "asset_key"
        ).alias(
            "target_asset_key"
        ),

        normalized(
            F.col(
                "nmap_ip"
            )
        ).alias(
            "evidence_ip_norm"
        ),

        F.lit(
            "NMAP"
        ).alias(
            "evidence_source"
        ),
    )
)


qualys_ip_df = (
    scored_df

    .filter(
        F.col(
            "qualys_present"
        )
        ==
        F.lit(
            "Y"
        )
    )

    .filter(
        nonblank(
            F.col(
                "qualys_ip"
            )
        )
    )

    .select(
        F.col(
            "asset_key"
        ).alias(
            "target_asset_key"
        ),

        normalized(
            F.col(
                "qualys_ip"
            )
        ).alias(
            "evidence_ip_norm"
        ),

        F.lit(
            "QUALYS"
        ).alias(
            "evidence_source"
        ),
    )
)


strong_exact_ip_evidence_df = (
    cmdb_ip_df

    .unionByName(
        nmap_ip_df
    )

    .unionByName(
        qualys_ip_df
    )

    .join(
        asset_identity_df

        .select(
            F.col(
                "asset_key"
            ).alias(
                "target_asset_key"
            ),

            "target_stronger_non_ip_identity",
        ),

        on="target_asset_key",
        how="left",
    )

    .filter(
        F.col(
            "target_stronger_non_ip_identity"
        )
        ==
        F.lit(True)
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 12. Identify remaining groups with ANY stronger exact-IP relationship
# ---------------------------------------------------------------------------

exact_ip_linked_group_df = (
    remaining_candidate_member_df.alias(
        "candidate"
    )

    .join(
        strong_exact_ip_evidence_df.alias(
            "target"
        ),

        (
            F.col(
                "candidate.candidate_ip_norm"
            )
            ==
            F.col(
                "target.evidence_ip_norm"
            )
        )
        &
        (
            F.col(
                "candidate.asset_key"
            )
            !=
            F.col(
                "target.target_asset_key"
            )
        ),

        how="inner",
    )

    .select(
        F.col(
            "candidate.tenable_identity_group_key"
        ).alias(
            "tenable_identity_group_key"
        )
    )

    .distinct()
)


exact_ip_linked_group_count = (
    exact_ip_linked_group_df.count()
)


# ---------------------------------------------------------------------------
# 13. True no-link Tenable identity population
# ---------------------------------------------------------------------------

no_link_group_df = (
    remaining_group_df

    .join(
        exact_ip_linked_group_df,
        on="tenable_identity_group_key",
        how="left_anti",
    )

    .cache()
)


no_link_group_count = (
    no_link_group_df.count()
)


no_link_member_df = (
    candidate_member_df

    .join(
        F.broadcast(
            no_link_group_df

            .select(
                "tenable_identity_group_key",
                "candidate_asset_count",
                "source_local_uuid_class",
            )
        ),

        on="tenable_identity_group_key",
        how="inner",
    )

    .cache()
)


no_link_member_count = (
    no_link_member_df.count()
)


# ---------------------------------------------------------------------------
# 14. Add actual Nmap Asset Plane observation state
# ---------------------------------------------------------------------------

candidate_nmap_context_df = (
    scored_df

    .select(
        "asset_key",

        F.col(
            "nmap_present"
        ).alias(
            "candidate_nmap_present"
        ),

        F.col(
            "nmap_active"
        ).alias(
            "candidate_nmap_active"
        ),

        F.col(
            "nmap_stale"
        ).alias(
            "candidate_nmap_stale"
        ),
    )
)


no_link_member_df = (
    no_link_member_df

    .join(
        candidate_nmap_context_df,
        on="asset_key",
        how="left",
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 15. Parse certified Nmap target collections from runtime
#
# D0024:
#   - full multi-CIDR target collection is authoritative
#   - target_cidr is compatibility fallback
#
# No raw XML is read here.
# ---------------------------------------------------------------------------

def _record_to_dict(
    record
):

    if record is None:
        return {}

    if hasattr(
        record,
        "asDict"
    ):

        return record.asDict(
            recursive=True
        )

    if isinstance(
        record,
        dict
    ):

        return dict(
            record
        )

    raise TypeError(
        "RCAIP_NMAP_SCANS contains an unsupported record type: "
        + str(
            type(
                record
            )
        )
    )


def _value_list(
    value
):

    if value is None:
        return []

    if isinstance(
        value,
        (
            list,
            tuple,
            set,
        )
    ):

        return list(
            value
        )

    text = str(
        value
    ).strip()

    if not text:
        return []

    if text.startswith(
        "["
    ):

        try:

            decoded = json.loads(
                text
            )

            if isinstance(
                decoded,
                list
            ):

                return decoded

        except Exception:
            pass

    return [
        text
    ]


scan_records = (
    list(
        runtime_nmap_scans
    )
    if isinstance(
        runtime_nmap_scans,
        (
            list,
            tuple,
        )
    )
    else [
        runtime_nmap_scans
    ]
    if runtime_nmap_scans
    else []
)


scan_target_records = []

scan_target_errors = []


for raw_scan_record in scan_records:

    scan_record = _record_to_dict(
        raw_scan_record
    )


    scan_file = str(
        scan_record.get(
            "file"
        )
        or
        scan_record.get(
            "scan_file"
        )
        or
        scan_record.get(
            "source_file_path"
        )
        or
        ""
    ).strip()


    target_values = _value_list(
        scan_record.get(
            "target_cidrs_json"
        )
    )


    if not target_values:

        target_values = _value_list(
            scan_record.get(
                "target_cidrs"
            )
        )


    if not target_values:

        target_values = _value_list(
            scan_record.get(
                "target_cidr"
            )
        )


    normalized_targets = []


    for target_value in target_values:

        target_text = str(
            target_value
            or
            ""
        ).strip()


        if not target_text:
            continue


        if target_text.upper() in {
            "MULTI_TARGET",
            "MULTI_SUBNET",
            "UNKNOWN",
            "REVIEW_REQUIRED",
        }:

            scan_target_errors.append(
                (
                    scan_file,
                    target_text,
                    "Compatibility sentinel encountered without usable CIDR collection."
                )
            )

            continue


        try:

            network = ipaddress.ip_network(
                target_text,
                strict=False,
            )


            normalized_target = str(
                network
            )


            if normalized_target not in [
                row[
                    "target_cidr"
                ]
                for row in normalized_targets
            ]:

                normalized_targets.append({
                    "target_cidr":
                        normalized_target,

                    "network":
                        network,
                })


        except Exception as exc:

            scan_target_errors.append(
                (
                    scan_file,
                    target_text,
                    str(
                        exc
                    ),
                )
            )


    for target_record in normalized_targets:

        scan_target_records.append({
            "scan_file":
                scan_file,

            "scan_scope":
                str(
                    scan_record.get(
                        "scan_scope"
                    )
                    or
                    ""
                ).strip(),

            "scan_perspective":
                str(
                    scan_record.get(
                        "scan_perspective"
                    )
                    or
                    ""
                ).strip(),

            "network_role":
                str(
                    scan_record.get(
                        "network_role"
                    )
                    or
                    ""
                ).strip(),

            "target_cidr":
                target_record[
                    "target_cidr"
                ],

            "network":
                target_record[
                    "network"
                ],
        })


if scan_target_errors:

    print(
        "Nmap target parsing errors:"
    )

    for error_row in scan_target_errors:

        print(
            " -",
            error_row
        )


    raise RuntimeError(
        "Cell 21 could not safely interpret the certified Nmap target collection."
    )


certified_nmap_target_count = (
    len(
        scan_target_records
    )
)


nmap_target_context_available = (
    certified_nmap_target_count
    >
    0
)


# ---------------------------------------------------------------------------
# 16. Resolve candidate-IP membership in certified Nmap target sets
#
# Driver collection is intentionally limited to the already-compressed
# no-link identity population. No enterprise source is collected.
# ---------------------------------------------------------------------------

candidate_ip_rows = (
    no_link_member_df

    .select(
        "tenable_identity_group_key",
        "candidate_ip",
        "candidate_ip_norm",
    )

    .dropDuplicates()

    .collect()
)


coverage_rows = []


for candidate_ip_row in candidate_ip_rows:

    identity_group_key = (
        candidate_ip_row[
            "tenable_identity_group_key"
        ]
    )


    candidate_ip = (
        candidate_ip_row[
            "candidate_ip"
        ]
    )


    candidate_ip_norm = (
        candidate_ip_row[
            "candidate_ip_norm"
        ]
    )


    matched_targets = []


    if not candidate_ip:

        coverage_state = (
            "CANDIDATE_IP_UNAVAILABLE"
        )


    elif not nmap_target_context_available:

        coverage_state = (
            "NMAP_TARGET_CONTEXT_UNAVAILABLE"
        )


    else:

        try:

            candidate_ip_object = (
                ipaddress.ip_address(
                    str(
                        candidate_ip
                    ).strip()
                )
            )


            for scan_target_record in scan_target_records:

                target_network = (
                    scan_target_record[
                        "network"
                    ]
                )


                if (
                    candidate_ip_object.version
                    ==
                    target_network.version
                    and
                    candidate_ip_object
                    in
                    target_network
                ):

                    matched_targets.append(
                        scan_target_record
                    )


            coverage_state = (
                "WITHIN_CERTIFIED_NMAP_TARGET_SET"
                if matched_targets
                else
                "OUTSIDE_CERTIFIED_NMAP_TARGET_SET"
            )


        except Exception:

            coverage_state = (
                "INVALID_CANDIDATE_IP"
            )


    coverage_rows.append(
        (
            identity_group_key,
            candidate_ip_norm,
            candidate_ip,

            coverage_state,

            len(
                matched_targets
            ),

            sorted(
                set(
                    target[
                        "target_cidr"
                    ]
                    for target in matched_targets
                )
            ),

            sorted(
                set(
                    target[
                        "scan_file"
                    ]
                    for target in matched_targets
                    if target[
                        "scan_file"
                    ]
                )
            ),

            sorted(
                set(
                    target[
                        "scan_scope"
                    ]
                    for target in matched_targets
                    if target[
                        "scan_scope"
                    ]
                )
            ),

            sorted(
                set(
                    target[
                        "scan_perspective"
                    ]
                    for target in matched_targets
                    if target[
                        "scan_perspective"
                    ]
                )
            ),
        )
    )


coverage_schema = T.StructType([
    T.StructField(
        "tenable_identity_group_key",
        T.StringType(),
        False,
    ),

    T.StructField(
        "candidate_ip_norm",
        T.StringType(),
        True,
    ),

    T.StructField(
        "coverage_candidate_ip",
        T.StringType(),
        True,
    ),

    T.StructField(
        "nmap_target_membership_state",
        T.StringType(),
        False,
    ),

    T.StructField(
        "matched_nmap_target_count",
        T.IntegerType(),
        False,
    ),

    T.StructField(
        "matched_nmap_target_cidrs",
        T.ArrayType(
            T.StringType()
        ),
        False,
    ),

    T.StructField(
        "matched_nmap_scan_files",
        T.ArrayType(
            T.StringType()
        ),
        False,
    ),

    T.StructField(
        "matched_nmap_scan_scopes",
        T.ArrayType(
            T.StringType()
        ),
        False,
    ),

    T.StructField(
        "matched_nmap_scan_perspectives",
        T.ArrayType(
            T.StringType()
        ),
        False,
    ),
])


nmap_target_membership_df = (
    spark.createDataFrame(
        coverage_rows,
        schema=coverage_schema,
    )
)


# ---------------------------------------------------------------------------
# 17. Parse Tenable key-driver evidence
#
# Map-based parse is intentionally tolerant of absent keys.
# ---------------------------------------------------------------------------

key_driver_schema = T.MapType(
    T.StringType(),
    T.StringType(),
)


qualified_member_df = (
    no_link_member_df

    .join(
        nmap_target_membership_df,

        on=[
            "tenable_identity_group_key",
            "candidate_ip_norm",
        ],

        how="left",
    )

    .withColumn(
        "_tenable_key_driver_map",

        F.from_json(
            F.col(
                "candidate_tenable_key_drivers"
            ),
            key_driver_schema,
        )
    )

    .withColumn(
        "tenable_device_type_hint",

        F.lower(
            F.trim(
                F.coalesce(
                    F.element_at(
                        F.col(
                            "_tenable_key_driver_map"
                        ),
                        F.lit(
                            "device type"
                        ),
                    ),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "tenable_device_capability_hint",

        F.lower(
            F.trim(
                F.coalesce(
                    F.element_at(
                        F.col(
                            "_tenable_key_driver_map"
                        ),
                        F.lit(
                            "device capability"
                        ),
                    ),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "tenable_internet_exposure_hint",

        F.lower(
            F.trim(
                F.coalesce(
                    F.element_at(
                        F.col(
                            "_tenable_key_driver_map"
                        ),
                        F.lit(
                            "internet exposure"
                        ),
                    ),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "tenable_device_hint_class",

        F.when(
            F.length(
                F.col(
                    "tenable_device_type_hint"
                )
            )
            ==
            F.lit(0),

            F.lit(
                "NO_DEVICE_TYPE_HINT"
            )
        )

        .when(
            F.col(
                "tenable_device_type_hint"
            ).rlike(
                r"printer|print|mfd|multifunction"
            ),

            F.lit(
                "NON_ENDPOINT_PRINT_DEVICE_HINT"
            )
        )

        .when(
            F.col(
                "tenable_device_type_hint"
            ).rlike(
                r"switch|router|firewall|network|appliance|"
                r"access[_ -]?point|phone|voip|camera|iot|"
                r"storage|ups|load[_ -]?balancer"
            ),

            F.lit(
                "INFRASTRUCTURE_OR_SPECIALTY_DEVICE_HINT"
            )
        )

        .when(
            F.col(
                "tenable_device_type_hint"
            ).rlike(
                r"general[_ -]?purpose|workstation|desktop|"
                r"laptop|computer|server"
            ),

            F.lit(
                "GENERAL_PURPOSE_COMPUTE_HINT"
            )
        )

        .otherwise(
            F.lit(
                "OTHER_EXPLICIT_DEVICE_TYPE_HINT"
            )
        )
    )

    .withColumn(
        "tenable_stale_flag",

        stale_flag_true(
            F.col(
                "candidate_tenable_stale_90"
            )
        )
    )

    .withColumn(
        "tenable_recency_class",

        F.when(
            F.col(
                "tenable_stale_flag"
            ),

            F.lit(
                "STALE_GT_90_DAYS"
            )
        )

        .when(
            F.col(
                "candidate_tenable_age_days"
            ).isNull(),

            F.lit(
                "AGE_UNKNOWN"
            )
        )

        .when(
            F.col(
                "candidate_tenable_age_days"
            )
            <=
            F.lit(30),

            F.lit(
                "CURRENT_0_30_DAYS"
            )
        )

        .when(
            F.col(
                "candidate_tenable_age_days"
            )
            <=
            F.lit(90),

            F.lit(
                "CURRENT_31_90_DAYS"
            )
        )

        .otherwise(
            F.lit(
                "STALE_GT_90_DAYS"
            )
        )
    )

    .withColumn(
        "nmap_observation_state",

        F.when(
            F.coalesce(
                F.col(
                    "candidate_nmap_active"
                ),
                F.lit(0)
            )
            ==
            F.lit(1),

            F.lit(
                "CURRENT_NMAP_OBSERVATION"
            )
        )

        .when(
            F.coalesce(
                F.col(
                    "candidate_nmap_stale"
                ),
                F.lit(0)
            )
            ==
            F.lit(1),

            F.lit(
                "STALE_NMAP_OBSERVATION"
            )
        )

        .otherwise(
            F.lit(
                "NO_NMAP_ASSET_OBSERVATION"
            )
        )
    )

    .withColumn(
        "nmap_collection_relationship",

        F.when(
            F.col(
                "nmap_observation_state"
            )
            ==
            F.lit(
                "CURRENT_NMAP_OBSERVATION"
            ),

            F.lit(
                "CURRENT_NMAP_OBSERVATION_PRESENT"
            )
        )

        .when(
            F.col(
                "nmap_observation_state"
            )
            ==
            F.lit(
                "STALE_NMAP_OBSERVATION"
            ),

            F.lit(
                "STALE_NMAP_OBSERVATION_PRESENT"
            )
        )

        .when(
            F.col(
                "nmap_target_membership_state"
            )
            ==
            F.lit(
                "WITHIN_CERTIFIED_NMAP_TARGET_SET"
            ),

            F.lit(
                "WITHIN_NMAP_TARGET_SET_NO_OBSERVATION"
            )
        )

        .when(
            F.col(
                "nmap_target_membership_state"
            )
            ==
            F.lit(
                "OUTSIDE_CERTIFIED_NMAP_TARGET_SET"
            ),

            F.lit(
                "OUTSIDE_CERTIFIED_NMAP_TARGET_SET"
            )
        )

        .otherwise(
            F.lit(
                "NMAP_COLLECTION_CONTEXT_UNAVAILABLE_OR_INVALID"
            )
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 18. Deterministic member-level qualification
#
# These are analytical treatments only.
# No final customer assignment occurs here.
# ---------------------------------------------------------------------------

qualified_member_df = (
    qualified_member_df

    .withColumn(
        "member_qualification_class",

        F.when(
            F.col(
                "candidate_asset_count"
            )
            >
            F.lit(1),

            F.lit(
                "MULTI_IP_SOURCE_LOCAL_IDENTITY_NO_CORROBORATION"
            )
        )

        .when(
            F.col(
                "tenable_recency_class"
            )
            ==
            F.lit(
                "STALE_GT_90_DAYS"
            ),

            F.lit(
                "STALE_SINGLE_SOURCE_IDENTITY_LIFECYCLE_REVIEW"
            )
        )

        .when(
            F.col(
                "tenable_device_hint_class"
            )
            ==
            F.lit(
                "NON_ENDPOINT_PRINT_DEVICE_HINT"
            ),

            F.lit(
                "TENABLE_PRINT_DEVICE_CONTEXT_CANDIDATE"
            )
        )

        .when(
            F.col(
                "tenable_device_hint_class"
            )
            ==
            F.lit(
                "INFRASTRUCTURE_OR_SPECIALTY_DEVICE_HINT"
            ),

            F.lit(
                "TENABLE_INFRASTRUCTURE_DEVICE_CONTEXT_CANDIDATE"
            )
        )

        .when(
            (
                F.col(
                    "tenable_device_hint_class"
                )
                ==
                F.lit(
                    "GENERAL_PURPOSE_COMPUTE_HINT"
                )
            )
            &
            (
                F.col(
                    "tenable_recency_class"
                )
                ==
                F.lit(
                    "CURRENT_0_30_DAYS"
                )
            ),

            F.lit(
                "FRESH_GENERAL_PURPOSE_COMPUTE_UNCORROBORATED"
            )
        )

        .when(
            (
                F.col(
                    "tenable_device_hint_class"
                )
                ==
                F.lit(
                    "GENERAL_PURPOSE_COMPUTE_HINT"
                )
            )
            &
            (
                F.col(
                    "tenable_recency_class"
                )
                ==
                F.lit(
                    "CURRENT_31_90_DAYS"
                )
            ),

            F.lit(
                "AGING_GENERAL_PURPOSE_COMPUTE_UNCORROBORATED"
            )
        )

        .when(
            (
                F.col(
                    "tenable_device_hint_class"
                )
                ==
                F.lit(
                    "NO_DEVICE_TYPE_HINT"
                )
            )
            &
            (
                F.col(
                    "tenable_recency_class"
                )
                ==
                F.lit(
                    "CURRENT_0_30_DAYS"
                )
            ),

            F.lit(
                "FRESH_UNKNOWN_DEVICE_SINGLE_SOURCE"
            )
        )

        .when(
            (
                F.col(
                    "tenable_device_hint_class"
                )
                ==
                F.lit(
                    "NO_DEVICE_TYPE_HINT"
                )
            )
            &
            (
                F.col(
                    "tenable_recency_class"
                )
                ==
                F.lit(
                    "CURRENT_31_90_DAYS"
                )
            ),

            F.lit(
                "AGING_UNKNOWN_DEVICE_SINGLE_SOURCE"
            )
        )

        .otherwise(
            F.lit(
                "OTHER_DEVICE_CONTEXT_REVIEW"
            )
        )
    )

    .withColumn(
        "member_next_gate",

        F.when(
            F.col(
                "member_qualification_class"
            )
            ==
            F.lit(
                "MULTI_IP_SOURCE_LOCAL_IDENTITY_NO_CORROBORATION"
            ),

            F.lit(
                "SOURCE_LOCAL_LIFECYCLE_RECONCILIATION_BEFORE_ENUMERATION"
            )
        )

        .when(
            F.col(
                "member_qualification_class"
            )
            ==
            F.lit(
                "STALE_SINGLE_SOURCE_IDENTITY_LIFECYCLE_REVIEW"
            ),

            F.lit(
                "LIFECYCLE_RECONCILIATION_BEFORE_ENUMERATION"
            )
        )

        .when(
            F.col(
                "member_qualification_class"
            ).isin(
                "TENABLE_PRINT_DEVICE_CONTEXT_CANDIDATE",
                "TENABLE_INFRASTRUCTURE_DEVICE_CONTEXT_CANDIDATE",
            ),

            F.lit(
                "DEVICE_CLASS_AND_INVENTORY_VALIDATION"
            )
        )

        .when(
            F.col(
                "member_qualification_class"
            )
            ==
            F.lit(
                "FRESH_GENERAL_PURPOSE_COMPUTE_UNCORROBORATED"
            ),

            F.lit(
                "TARGETED_IDENTITY_ENUMERATION"
            )
        )

        .when(
            F.col(
                "member_qualification_class"
            )
            ==
            F.lit(
                "AGING_GENERAL_PURPOSE_COMPUTE_UNCORROBORATED"
            ),

            F.lit(
                "RECENCY_VALIDATION_THEN_TARGETED_ENUMERATION"
            )
        )

        .when(
            F.col(
                "member_qualification_class"
            )
            ==
            F.lit(
                "FRESH_UNKNOWN_DEVICE_SINGLE_SOURCE"
            ),

            F.lit(
                "TARGETED_DEVICE_CONTEXT_ENUMERATION"
            )
        )

        .when(
            F.col(
                "member_qualification_class"
            )
            ==
            F.lit(
                "AGING_UNKNOWN_DEVICE_SINGLE_SOURCE"
            ),

            F.lit(
                "RECENCY_VALIDATION_OR_MONITORING_BEFORE_ENUMERATION"
            )
        )

        .otherwise(
            F.lit(
                "MODEL_OR_DEVICE_CONTEXT_REVIEW"
            )
        )
    )

    .withColumn(
        "workload_promotion_state",

        F.when(
            F.col(
                "member_next_gate"
            )
            ==
            F.lit(
                "TARGETED_IDENTITY_ENUMERATION"
            ),

            F.lit(
                "RESIDUAL_IDENTITY_REVIEW_CANDIDATE"
            )
        )

        .when(
            F.col(
                "member_next_gate"
            )
            ==
            F.lit(
                "TARGETED_DEVICE_CONTEXT_ENUMERATION"
            ),

            F.lit(
                "RESIDUAL_DEVICE_CONTEXT_REVIEW_CANDIDATE"
            )
        )

        .otherwise(
            F.lit(
                "NOT_READY_FOR_WORKLOAD_PROMOTION"
            )
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 19. Device / recency profile
# ---------------------------------------------------------------------------

device_recency_profile_df = (
    qualified_member_df

    .groupBy(
        "tenable_device_hint_class",
        "tenable_device_type_hint",
        "tenable_recency_class",
        "acr_band",
    )

    .agg(
        F.countDistinct(
            "tenable_identity_group_key"
        ).alias(
            "tenable_identity_groups"
        ),

        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_rows"
        ),

        F.min(
            "candidate_tenable_age_days"
        ).alias(
            "minimum_age_days"
        ),

        F.max(
            "candidate_tenable_age_days"
        ).alias(
            "maximum_age_days"
        ),
    )

    .orderBy(
        F.desc(
            "tenable_identity_groups"
        ),
        "tenable_device_hint_class",
    )
)


print("=" * 120)
print("NO-LINK TENABLE IDENTITIES - DEVICE / RECENCY PROFILE")
print("TENABLE DEVICE TYPE IS SOURCE-DERIVED CONTEXT, NOT AUTHORITATIVE RCAIP DEVICE CLASS")
print("=" * 120)

display(
    device_recency_profile_df
)


# ---------------------------------------------------------------------------
# 20. Nmap collection-context profile
# ---------------------------------------------------------------------------

nmap_context_profile_df = (
    qualified_member_df

    .groupBy(
        "nmap_target_membership_state",
        "nmap_observation_state",
        "nmap_collection_relationship",
    )

    .agg(
        F.countDistinct(
            "tenable_identity_group_key"
        ).alias(
            "tenable_identity_groups"
        ),

        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_rows"
        ),

        F.max(
            "matched_nmap_target_count"
        ).alias(
            "maximum_matching_collection_targets"
        ),

        F.array_sort(
            F.array_distinct(
                F.flatten(
                    F.collect_list(
                        "matched_nmap_target_cidrs"
                    )
                )
            )
        ).alias(
            "matched_target_cidrs"
        ),

        F.array_sort(
            F.array_distinct(
                F.flatten(
                    F.collect_list(
                        "matched_nmap_scan_scopes"
                    )
                )
            )
        ).alias(
            "matched_scan_scopes"
        ),

        F.array_sort(
            F.array_distinct(
                F.flatten(
                    F.collect_list(
                        "matched_nmap_scan_perspectives"
                    )
                )
            )
        ).alias(
            "matched_scan_perspectives"
        ),
    )

    .orderBy(
        F.desc(
            "tenable_identity_groups"
        )
    )
)


print()
print("=" * 120)
print("NO-LINK TENABLE IDENTITIES - NMAP COLLECTION CONTEXT")
print("TARGET MEMBERSHIP DOES NOT MEAN NMAP OBSERVED THE HOST")
print("=" * 120)

display(
    nmap_context_profile_df
)


# ---------------------------------------------------------------------------
# 21. Compress to one row per Tenable identity
# ---------------------------------------------------------------------------

group_qualification_df = (
    qualified_member_df

    .groupBy(
        "tenable_identity_group_key"
    )

    .agg(
        F.first(
            "candidate_tenable_uuid",
            ignorenulls=True,
        ).alias(
            "candidate_tenable_uuid"
        ),

        F.countDistinct(
            "asset_key"
        ).alias(
            "candidate_asset_count"
        ),

        F.sort_array(
            F.collect_set(
                "asset_key"
            )
        ).alias(
            "candidate_asset_keys"
        ),

        F.sort_array(
            F.collect_set(
                "candidate_ip"
            )
        ).alias(
            "candidate_ips"
        ),

        F.countDistinct(
            "member_qualification_class"
        ).alias(
            "member_qualification_class_count"
        ),

        F.first(
            "member_qualification_class"
        ).alias(
            "_first_qualification_class"
        ),

        F.first(
            "member_next_gate"
        ).alias(
            "_first_next_gate"
        ),

        F.first(
            "workload_promotion_state"
        ).alias(
            "_first_promotion_state"
        ),

        F.sort_array(
            F.collect_set(
                "tenable_device_hint_class"
            )
        ).alias(
            "tenable_device_hint_classes"
        ),

        F.sort_array(
            F.collect_set(
                "tenable_device_type_hint"
            )
        ).alias(
            "tenable_device_type_hints"
        ),

        F.sort_array(
            F.collect_set(
                "tenable_recency_class"
            )
        ).alias(
            "tenable_recency_classes"
        ),

        F.sort_array(
            F.collect_set(
                "acr_band"
            )
        ).alias(
            "acr_bands"
        ),

        F.sort_array(
            F.collect_set(
                "nmap_collection_relationship"
            )
        ).alias(
            "nmap_collection_relationships"
        ),

        F.sort_array(
            F.collect_set(
                "tenable_internet_exposure_hint"
            )
        ).alias(
            "tenable_internet_exposure_hints"
        ),

        F.min(
            "candidate_tenable_age_days"
        ).alias(
            "minimum_tenable_age_days"
        ),

        F.max(
            "candidate_tenable_age_days"
        ).alias(
            "maximum_tenable_age_days"
        ),
    )

    .withColumn(
        "qualification_class",

        F.when(
            F.col(
                "member_qualification_class_count"
            )
            >
            F.lit(1),

            F.lit(
                "MIXED_MEMBER_CONTEXT_REVIEW"
            )
        )

        .otherwise(
            F.col(
                "_first_qualification_class"
            )
        )
    )

    .withColumn(
        "next_gate",

        F.when(
            F.col(
                "member_qualification_class_count"
            )
            >
            F.lit(1),

            F.lit(
                "MODEL_REVIEW_REQUIRED"
            )
        )

        .otherwise(
            F.col(
                "_first_next_gate"
            )
        )
    )

    .withColumn(
        "workload_promotion_state",

        F.when(
            F.col(
                "member_qualification_class_count"
            )
            >
            F.lit(1),

            F.lit(
                "NOT_READY_FOR_WORKLOAD_PROMOTION"
            )
        )

        .otherwise(
            F.col(
                "_first_promotion_state"
            )
        )
    )

    .drop(
        "_first_qualification_class",
        "_first_next_gate",
        "_first_promotion_state",
    )

    .withColumn(
        "qualification_signature",

        F.concat_ws(
            " | ",

            F.col(
                "qualification_class"
            ),

            F.col(
                "next_gate"
            ),

            F.col(
                "workload_promotion_state"
            ),
        )
    )

    .withColumn(
        "qualification_cohort_id",

        F.concat(
            F.lit(
                "VISQ-"
            ),

            F.substring(
                F.sha2(
                    F.col(
                        "qualification_signature"
                    ),
                    256,
                ),
                1,
                12,
            )
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 22. Deterministic qualification cohorts
# ---------------------------------------------------------------------------

qualification_cohort_summary_df = (
    group_qualification_df

    .groupBy(
        "qualification_cohort_id",
        "qualification_class",
        "next_gate",
        "workload_promotion_state",
    )

    .agg(
        F.count(
            F.lit(1)
        ).alias(
            "tenable_identity_groups"
        ),

        F.sum(
            "candidate_asset_count"
        ).alias(
            "candidate_asset_rows"
        ),

        F.min(
            "minimum_tenable_age_days"
        ).alias(
            "minimum_age_days"
        ),

        F.max(
            "maximum_tenable_age_days"
        ).alias(
            "maximum_age_days"
        ),

        F.array_sort(
            F.array_distinct(
                F.flatten(
                    F.collect_list(
                        "tenable_device_hint_classes"
                    )
                )
            )
        ).alias(
            "device_hint_classes"
        ),

        F.array_sort(
            F.array_distinct(
                F.flatten(
                    F.collect_list(
                        "tenable_device_type_hints"
                    )
                )
            )
        ).alias(
            "device_type_hints"
        ),

        F.array_sort(
            F.array_distinct(
                F.flatten(
                    F.collect_list(
                        "acr_bands"
                    )
                )
            )
        ).alias(
            "acr_bands"
        ),

        F.array_sort(
            F.array_distinct(
                F.flatten(
                    F.collect_list(
                        "nmap_collection_relationships"
                    )
                )
            )
        ).alias(
            "nmap_context_states"
        ),

        F.sort_array(
            F.collect_set(
                "tenable_identity_group_key"
            )
        ).alias(
            "member_identity_groups"
        ),
    )

    .orderBy(
        "workload_promotion_state",
        F.desc(
            "tenable_identity_groups"
        ),
        "qualification_class",
    )
)


print()
print("=" * 120)
print("NO-LINK TENABLE IDENTITIES - QUALIFICATION COHORTS")
print("ANALYTICAL QUALIFICATION ONLY - NOT ASSURANCE CASES / NOT FINAL ROUTING")
print("=" * 120)

display(
    qualification_cohort_summary_df
)


