# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 22 - Residual Tenable / Nmap Temporal Collection Qualification
# Version: 1.1
#
# Purpose:
#   Apply temporal qualification ONLY to the focused identity-enumeration
#   population certified by Cell 21.
#
# Version 1.1 correction:
#   - DO NOT parse RCAIP_NMAP_SCANS.scan_start_raw.
#   - Use certified durable NMAP_SCAN_PROVENANCE timestamps.
#   - Use current-run NMAP_NORM scan_id/file relationships as the preferred
#     scope bridge to provenance.
#   - Use unique provenance-file matching only as a safe fallback.
#
# Core question:
#
#     For each residual Tenable identity, did a certified Nmap collection
#     covering the candidate IP occur:
#
#       A. after Tenable last observed it,
#       B. before Tenable observed it,
#       C. overlapping the Tenable timestamp, or
#       D. without sufficient temporal evidence?
#
# Interpretation:
#
#   Later Nmap non-observation DOES NOT prove absence.
#   It means currentness should be validated before identity enumeration.
#
#   Tenable observation AFTER all relevant Nmap collections means there was
#   no later Nmap collection available to qualify the current Tenable evidence.
#   That identity remains the stronger residual enumeration candidate.
#
# IMPORTANT:
#   - Cell 21 PASS is prerequisite.
#   - No raw XML parsing.
#   - No scan_start_raw parsing.
#   - No identity merge.
#   - No asset_key changes.
#   - No assurance cases.
#   - No final customer routing.
#   - No findings / tickets / remediation.
#   - No Delta writes.
#
# Post-agnostic:
#   - no example_post_a IPs
#   - no example_post_a timestamps
#   - no example_post_a row counts
#   - target CIDRs come from runtime certified evidence
#   - temporal evidence comes from durable NMAP_SCAN_PROVENANCE
#
# Safety:
#   READ ONLY
# ============================================================================

import ipaddress
import json
import re

from datetime import datetime, timezone

from pyspark.sql import functions as F
from pyspark.sql import types as T


# ---------------------------------------------------------------------------
# 1. Required runtime / prior diagnostic state
# ---------------------------------------------------------------------------

REQUIRED_RUNTIME_OBJECTS = [
    "RCAIP_CONFIG_000_READY",
    "RCAIP_POST_NAME",
    "RCAIP_POST_SLUG",
    "RCAIP_RUN_ID",
    "get_rcaip_table",
    "RCAIP_NMAP_SCANS",
]


REQUIRED_CELL21_OBJECTS = [
    "qualified_member_df",
    "group_qualification_df",
]


missing_runtime_objects = [
    name
    for name in REQUIRED_RUNTIME_OBJECTS
    if name not in globals()
]


missing_cell21_objects = [
    name
    for name in REQUIRED_CELL21_OBJECTS
    if name not in globals()
]


if missing_runtime_objects:
    raise RuntimeError(
        "Cell 22 v1.1 requires Config 001 runtime. Missing: "
        + " | ".join(missing_runtime_objects)
    )


if missing_cell21_objects:
    raise RuntimeError(
        "Cell 22 v1.1 requires the current Cell 21 PASS state. Missing: "
        + " | ".join(missing_cell21_objects)
    )


if not RCAIP_CONFIG_000_READY:
    raise RuntimeError(
        "Config 000 did not publish a ready runtime."
    )


# ---------------------------------------------------------------------------
# 2. Resolve durable Nmap products
# ---------------------------------------------------------------------------

NMAP_NORM_TABLE = get_rcaip_table(
    "NMAP_NORM"
)


NMAP_PROVENANCE_TABLE = get_rcaip_table(
    "NMAP_SCAN_PROVENANCE"
)


for table_name in [
    NMAP_NORM_TABLE,
    NMAP_PROVENANCE_TABLE,
]:

    if not spark.catalog.tableExists(table_name):

        raise RuntimeError(
            "Required durable RCAIP product unavailable: "
            + table_name
        )


nmap_norm_source_df = spark.table(
    NMAP_NORM_TABLE
)


nmap_provenance_source_df = spark.table(
    NMAP_PROVENANCE_TABLE
)


# ---------------------------------------------------------------------------
# 3. Contract validation
# ---------------------------------------------------------------------------

NMAP_NORM_REQUIRED_COLUMNS = {
    "scan_id",
    "scan_source_file",
}


missing_nmap_columns = sorted(
    NMAP_NORM_REQUIRED_COLUMNS
    -
    set(
        nmap_norm_source_df.columns
    )
)


if missing_nmap_columns:

    raise RuntimeError(
        "NMAP_NORM missing required columns: "
        + " | ".join(
            missing_nmap_columns
        )
    )


if "scan_id" not in nmap_provenance_source_df.columns:

    raise RuntimeError(
        "NMAP_SCAN_PROVENANCE is missing scan_id."
    )


provenance_has_start = (
    "scan_start_timestamp"
    in
    nmap_provenance_source_df.columns
)


provenance_has_end = (
    "scan_end_timestamp"
    in
    nmap_provenance_source_df.columns
)


if not (
    provenance_has_start
    or
    provenance_has_end
):

    raise RuntimeError(
        "NMAP_SCAN_PROVENANCE requires scan_start_timestamp "
        "or scan_end_timestamp."
    )


PROVENANCE_FILE_COLUMN = None


for candidate_column in [
    "source_file_name",
    "source_file_path",
]:

    if candidate_column in nmap_provenance_source_df.columns:

        PROVENANCE_FILE_COLUMN = (
            candidate_column
        )

        break


if PROVENANCE_FILE_COLUMN is None:

    raise RuntimeError(
        "NMAP_SCAN_PROVENANCE exposes no source-file identity column."
    )


# ---------------------------------------------------------------------------
# 4. Helpers
# ---------------------------------------------------------------------------

def runtime_slice(
    df
):

    scoped_df = df


    if "post_slug" in scoped_df.columns:

        scoped_df = (
            scoped_df

            .filter(
                F.lower(
                    F.trim(
                        F.col(
                            "post_slug"
                        )
                    )
                )
                ==
                F.lit(
                    str(
                        RCAIP_POST_SLUG
                    )
                    .strip()
                    .lower()
                )
            )
        )


    if "rcaip_run_id" in scoped_df.columns:

        scoped_df = (
            scoped_df

            .filter(
                F.col(
                    "rcaip_run_id"
                )
                ==
                F.lit(
                    RCAIP_RUN_ID
                )
            )
        )


    return scoped_df


def _record_to_dict(
    record
):

    if record is None:
        return {}


    if hasattr(
        record,
        "asDict"
    ):

        return record.asDict(
            recursive=True
        )


    if isinstance(
        record,
        dict
    ):

        return dict(
            record
        )


    raise TypeError(
        "Unsupported RCAIP_NMAP_SCANS record type: "
        + str(
            type(
                record
            )
        )
    )


def _value_list(
    value
):

    if value is None:
        return []


    if isinstance(
        value,
        (
            list,
            tuple,
            set,
        )
    ):

        return list(
            value
        )


    text = str(
        value
    ).strip()


    if not text:
        return []


    if text.startswith(
        "["
    ):

        try:

            decoded = json.loads(
                text
            )


            if isinstance(
                decoded,
                list
            ):

                return decoded

        except Exception:
            pass


    return [
        text
    ]


def _basename(
    value
):

    text = str(
        value
        or
        ""
    ).strip()


    if not text:
        return ""


    return (
        re.split(
            r"[\\/]",
            text,
        )[-1]
        .strip()
        .lower()
    )


def spark_file_key(
    column_expression
):

    normalized_path = (
        F.lower(
            F.trim(
                column_expression.cast(
                    "string"
                )
            )
        )
    )


    normalized_path = (
        F.regexp_replace(
            normalized_path,
            r"\\",
            "/",
        )
    )


    return (
        F.regexp_extract(
            normalized_path,
            r"([^/]+)$",
            1,
        )
    )


def epoch_to_iso(
    epoch_value
):

    if epoch_value is None:
        return None


    return (
        datetime.fromtimestamp(
            int(
                epoch_value
            ),
            tz=timezone.utc,
        )
        .isoformat()
        .replace(
            "+00:00",
            "Z",
        )
    )


# ---------------------------------------------------------------------------
# 5. Select ONLY Cell 21 focused identity-enumeration groups
# ---------------------------------------------------------------------------

targeted_group_keys_df = (
    group_qualification_df

    .filter(
        F.col(
            "next_gate"
        )
        ==
        F.lit(
            "TARGETED_IDENTITY_ENUMERATION"
        )
    )

    .filter(
        F.col(
            "workload_promotion_state"
        )
        ==
        F.lit(
            "RESIDUAL_IDENTITY_REVIEW_CANDIDATE"
        )
    )

    .select(
        "tenable_identity_group_key"
    )

    .distinct()

    .cache()
)


targeted_candidate_count = (
    targeted_group_keys_df.count()
)


if targeted_candidate_count == 0:

    raise RuntimeError(
        "Cell 21 produced no focused identity-enumeration population."
    )


targeted_member_df = (
    qualified_member_df

    .join(
        F.broadcast(
            targeted_group_keys_df
        ),

        on="tenable_identity_group_key",
        how="inner",
    )

    .withColumn(
        "candidate_tenable_epoch",

        F.col(
            "candidate_tenable_last_observed"
        ).cast(
            "long"
        )
    )

    .cache()
)


targeted_asset_rows = (
    targeted_member_df.count()
)


targeted_distinct_groups = (
    targeted_member_df

    .select(
        "tenable_identity_group_key"
    )

    .distinct()

    .count()
)


targeted_duplicate_groups = (
    targeted_member_df

    .groupBy(
        "tenable_identity_group_key"
    )

    .count()

    .filter(
        F.col(
            "count"
        )
        >
        F.lit(1)
    )

    .count()
)


# ---------------------------------------------------------------------------
# 6. Current-run NMAP_NORM
#
# Exact current-run scan IDs are the preferred bridge into the provenance
# table. This avoids treating the provenance table itself as Post/run scoped
# when its schema does not publish those columns.
# ---------------------------------------------------------------------------

nmap_norm_df = (
    runtime_slice(
        nmap_norm_source_df
    )

    .cache()
)


current_nmap_rows = (
    nmap_norm_df.count()
)


current_scan_ids = (
    nmap_norm_df

    .select(
        "scan_id"
    )

    .filter(
        F.col(
            "scan_id"
        ).isNotNull()
    )

    .distinct()

    .count()
)


current_scan_file_map_df = (
    nmap_norm_df

    .filter(
        F.col(
            "scan_id"
        ).isNotNull()
    )

    .filter(
        F.col(
            "scan_source_file"
        ).isNotNull()
    )

    .select(
        "scan_id",

        spark_file_key(
            F.col(
                "scan_source_file"
            )
        ).alias(
            "scan_file_key"
        ),
    )

    .filter(
        F.length(
            F.col(
                "scan_file_key"
            )
        )
        >
        F.lit(0)
    )

    .dropDuplicates()

    .cache()
)


current_scan_file_ambiguity = (
    current_scan_file_map_df

    .groupBy(
        "scan_file_key"
    )

    .agg(
        F.countDistinct(
            "scan_id"
        ).alias(
            "scan_id_count"
        )
    )

    .filter(
        F.col(
            "scan_id_count"
        )
        >
        F.lit(1)
    )

    .count()
)


# ---------------------------------------------------------------------------
# 7. Durable NMAP_SCAN_PROVENANCE projection
# ---------------------------------------------------------------------------

provenance_df = (
    runtime_slice(
        nmap_provenance_source_df
    )

    .cache()
)


if provenance_has_start:

    provenance_start_expr = (
        F.col(
            "scan_start_timestamp"
        )
        .cast(
            "timestamp"
        )
    )


else:

    provenance_start_expr = (
        F.col(
            "scan_end_timestamp"
        )
        .cast(
            "timestamp"
        )
    )


if provenance_has_end:

    provenance_end_expr = (
        F.col(
            "scan_end_timestamp"
        )
        .cast(
            "timestamp"
        )
    )


else:

    provenance_end_expr = (
        F.col(
            "scan_start_timestamp"
        )
        .cast(
            "timestamp"
        )
    )


provenance_time_df = (
    provenance_df

    .select(
        "scan_id",

        spark_file_key(
            F.col(
                PROVENANCE_FILE_COLUMN
            )
        ).alias(
            "provenance_file_key"
        ),

        provenance_start_expr.alias(
            "scan_start_timestamp"
        ),

        provenance_end_expr.alias(
            "scan_end_timestamp"
        ),
    )

    .withColumn(
        "scan_start_epoch",

        F.col(
            "scan_start_timestamp"
        ).cast(
            "long"
        )
    )

    .withColumn(
        "scan_end_epoch",

        F.col(
            "scan_end_timestamp"
        ).cast(
            "long"
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 8. Preferred current-run scan-id -> provenance mapping
# ---------------------------------------------------------------------------

primary_scan_time_df = (
    current_scan_file_map_df.alias(
        "scan_map"
    )

    .join(
        provenance_time_df.alias(
            "provenance"
        ),

        F.col(
            "scan_map.scan_id"
        )
        ==
        F.col(
            "provenance.scan_id"
        ),

        how="left",
    )

    .select(
        F.col(
            "scan_map.scan_file_key"
        ).alias(
            "scan_file_key"
        ),

        F.col(
            "scan_map.scan_id"
        ).alias(
            "primary_scan_id"
        ),

        F.col(
            "provenance.scan_start_timestamp"
        ).alias(
            "primary_scan_start_timestamp"
        ),

        F.col(
            "provenance.scan_end_timestamp"
        ).alias(
            "primary_scan_end_timestamp"
        ),

        F.col(
            "provenance.scan_start_epoch"
        ).alias(
            "primary_scan_start_epoch"
        ),

        F.col(
            "provenance.scan_end_epoch"
        ).alias(
            "primary_scan_end_epoch"
        ),
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 9. Safe provenance-file fallback
#
# Only files represented by exactly ONE provenance scan_id are eligible.
# This supports a certified scan file that produced no NMAP_NORM asset row
# while refusing ambiguous historical filename reuse.
# ---------------------------------------------------------------------------

provenance_file_profile_df = (
    provenance_time_df

    .filter(
        F.length(
            F.col(
                "provenance_file_key"
            )
        )
        >
        F.lit(0)
    )

    .groupBy(
        "provenance_file_key"
    )

    .agg(
        F.countDistinct(
            "scan_id"
        ).alias(
            "provenance_scan_id_count"
        )
    )
)


unique_provenance_file_df = (
    provenance_time_df.alias(
        "provenance"
    )

    .join(
        provenance_file_profile_df

        .filter(
            F.col(
                "provenance_scan_id_count"
            )
            ==
            F.lit(1)
        )

        .alias(
            "profile"
        ),

        F.col(
            "provenance.provenance_file_key"
        )
        ==
        F.col(
            "profile.provenance_file_key"
        ),

        how="inner",
    )

    .select(
        F.col(
            "provenance.provenance_file_key"
        ).alias(
            "scan_file_key"
        ),

        F.col(
            "provenance.scan_id"
        ).alias(
            "fallback_scan_id"
        ),

        F.col(
            "provenance.scan_start_timestamp"
        ).alias(
            "fallback_scan_start_timestamp"
        ),

        F.col(
            "provenance.scan_end_timestamp"
        ).alias(
            "fallback_scan_end_timestamp"
        ),

        F.col(
            "provenance.scan_start_epoch"
        ).alias(
            "fallback_scan_start_epoch"
        ),

        F.col(
            "provenance.scan_end_epoch"
        ).alias(
            "fallback_scan_end_epoch"
        ),
    )

    .dropDuplicates(
        [
            "scan_file_key"
        ]
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 10. Parse D0024-safe certified runtime target sets
#
# No timestamps are parsed here.
# Runtime is used ONLY for:
#   - which scan file
#   - which target CIDR(s)
#   - scan scope/perspective/capability
#
# Durable provenance is temporal authority.
# ---------------------------------------------------------------------------

runtime_scan_records = (
    list(
        RCAIP_NMAP_SCANS
    )
    if isinstance(
        RCAIP_NMAP_SCANS,
        (
            list,
            tuple,
        )
    )
    else [
        RCAIP_NMAP_SCANS
    ]
)


runtime_target_rows = []

runtime_target_parse_errors = []


for raw_scan_record in runtime_scan_records:

    scan_record = _record_to_dict(
        raw_scan_record
    )


    scan_file_raw = (
        scan_record.get(
            "file"
        )
        or
        scan_record.get(
            "scan_file"
        )
        or
        scan_record.get(
            "scan_source_file"
        )
        or
        scan_record.get(
            "source_file_path"
        )
        or
        ""
    )


    scan_file_display = _basename(
        scan_file_raw
    )


    if not scan_file_display:

        runtime_target_parse_errors.append(
            (
                "<MISSING_FILE>",
                "",
                "Runtime Nmap record has no usable file identity.",
            )
        )

        continue


    target_values = _value_list(
        scan_record.get(
            "target_cidrs_json"
        )
    )


    if not target_values:

        target_values = _value_list(
            scan_record.get(
                "target_cidrs"
            )
        )


    if not target_values:

        target_values = _value_list(
            scan_record.get(
                "target_cidr"
            )
        )


    normalized_targets = []


    for target_value in target_values:

        target_text = str(
            target_value
            or
            ""
        ).strip()


        if not target_text:
            continue


        if target_text.upper() in {
            "MULTI_TARGET",
            "MULTI_SUBNET",
            "UNKNOWN",
            "REVIEW_REQUIRED",
        }:

            runtime_target_parse_errors.append(
                (
                    scan_file_display,
                    target_text,
                    "Compatibility sentinel encountered without usable CIDR collection.",
                )
            )

            continue


        try:

            normalized_cidr = str(
                ipaddress.ip_network(
                    target_text,
                    strict=False,
                )
            )


            if normalized_cidr not in normalized_targets:

                normalized_targets.append(
                    normalized_cidr
                )


        except Exception as exc:

            runtime_target_parse_errors.append(
                (
                    scan_file_display,
                    target_text,
                    str(
                        exc
                    ),
                )
            )


    for normalized_cidr in normalized_targets:

        runtime_target_rows.append(
            (
                scan_file_display,
                scan_file_display,

                str(
                    scan_record.get(
                        "scan_scope"
                    )
                    or
                    ""
                ).strip(),

                str(
                    scan_record.get(
                        "scan_perspective"
                    )
                    or
                    ""
                ).strip(),

                str(
                    scan_record.get(
                        "collection_capability"
                    )
                    or
                    ""
                ).strip(),

                normalized_cidr,
            )
        )


if runtime_target_parse_errors:

    print(
        "Runtime Nmap target parsing errors:"
    )


    for error_row in runtime_target_parse_errors:

        print(
            " -",
            error_row
        )


    raise RuntimeError(
        "Cell 22 v1.1 could not safely interpret certified Nmap target scope."
    )


runtime_target_schema = T.StructType([
    T.StructField(
        "scan_file_key",
        T.StringType(),
        False,
    ),

    T.StructField(
        "scan_file",
        T.StringType(),
        False,
    ),

    T.StructField(
        "scan_scope",
        T.StringType(),
        True,
    ),

    T.StructField(
        "scan_perspective",
        T.StringType(),
        True,
    ),

    T.StructField(
        "collection_capability",
        T.StringType(),
        True,
    ),

    T.StructField(
        "target_cidr",
        T.StringType(),
        False,
    ),
])


runtime_target_df = (
    spark.createDataFrame(
        runtime_target_rows,
        schema=runtime_target_schema,
    )

    .cache()
)


runtime_target_relationship_count = (
    runtime_target_df.count()
)


runtime_scan_file_count = (
    runtime_target_df

    .select(
        "scan_file_key"
    )

    .distinct()

    .count()
)


# ---------------------------------------------------------------------------
# 11. Attach durable provenance timestamps to runtime target rows
# ---------------------------------------------------------------------------

runtime_target_time_df = (
    runtime_target_df.alias(
        "runtime"
    )

    .join(
        primary_scan_time_df.alias(
            "primary"
        ),

        F.col(
            "runtime.scan_file_key"
        )
        ==
        F.col(
            "primary.scan_file_key"
        ),

        how="left",
    )

    .join(
        unique_provenance_file_df.alias(
            "fallback"
        ),

        F.col(
            "runtime.scan_file_key"
        )
        ==
        F.col(
            "fallback.scan_file_key"
        ),

        how="left",
    )

    .select(
        F.col(
            "runtime.scan_file_key"
        ).alias(
            "scan_file_key"
        ),

        F.col(
            "runtime.scan_file"
        ).alias(
            "scan_file"
        ),

        F.col(
            "runtime.scan_scope"
        ).alias(
            "scan_scope"
        ),

        F.col(
            "runtime.scan_perspective"
        ).alias(
            "scan_perspective"
        ),

        F.col(
            "runtime.collection_capability"
        ).alias(
            "collection_capability"
        ),

        F.col(
            "runtime.target_cidr"
        ).alias(
            "target_cidr"
        ),

        F.coalesce(
            F.col(
                "primary.primary_scan_id"
            ),
            F.col(
                "fallback.fallback_scan_id"
            )
        ).alias(
            "resolved_scan_id"
        ),

        F.coalesce(
            F.col(
                "primary.primary_scan_start_timestamp"
            ),
            F.col(
                "fallback.fallback_scan_start_timestamp"
            )
        ).alias(
            "scan_start_timestamp"
        ),

        F.coalesce(
            F.col(
                "primary.primary_scan_end_timestamp"
            ),
            F.col(
                "fallback.fallback_scan_end_timestamp"
            )
        ).alias(
            "scan_end_timestamp"
        ),

        F.coalesce(
            F.col(
                "primary.primary_scan_start_epoch"
            ),
            F.col(
                "fallback.fallback_scan_start_epoch"
            )
        ).alias(
            "scan_start_epoch"
        ),

        F.coalesce(
            F.col(
                "primary.primary_scan_end_epoch"
            ),
            F.col(
                "fallback.fallback_scan_end_epoch"
            )
        ).alias(
            "scan_end_epoch"
        ),

        F.when(
            F.col(
                "primary.primary_scan_id"
            ).isNotNull(),

            F.lit(
                "CURRENT_RUN_NMAP_NORM_SCAN_ID"
            )
        )

        .when(
            F.col(
                "fallback.fallback_scan_id"
            ).isNotNull(),

            F.lit(
                "UNIQUE_PROVENANCE_FILE_FALLBACK"
            )
        )

        .otherwise(
            F.lit(
                "PROVENANCE_UNRESOLVED"
            )
        ).alias(
            "provenance_resolution_basis"
        ),

        F.col(
            "primary.primary_scan_id"
        ).alias(
            "primary_scan_id"
        ),

        F.col(
            "fallback.fallback_scan_id"
        ).alias(
            "fallback_scan_id"
        ),
    )

    .cache()
)


primary_fallback_scan_id_conflicts = (
    runtime_target_time_df

    .filter(
        F.col(
            "primary_scan_id"
        ).isNotNull()
        &
        F.col(
            "fallback_scan_id"
        ).isNotNull()
        &
        (
            F.col(
                "primary_scan_id"
            )
            !=
            F.col(
                "fallback_scan_id"
            )
        )
    )

    .count()
)


runtime_target_rows_with_provenance = (
    runtime_target_time_df

    .filter(
        F.col(
            "resolved_scan_id"
        ).isNotNull()
    )

    .count()
)


runtime_target_rows_with_timestamp = (
    runtime_target_time_df

    .filter(
        F.col(
            "scan_start_epoch"
        ).isNotNull()
        |
        F.col(
            "scan_end_epoch"
        ).isNotNull()
    )

    .count()
)


# ---------------------------------------------------------------------------
# 12. Show scan/provenance bridge
# ---------------------------------------------------------------------------

runtime_provenance_summary_df = (
    runtime_target_time_df

    .groupBy(
        "scan_file",
        "resolved_scan_id",
        "provenance_resolution_basis",
        "scan_start_timestamp",
        "scan_end_timestamp",
        "scan_scope",
        "scan_perspective",
        "collection_capability",
    )

    .agg(
        F.countDistinct(
            "target_cidr"
        ).alias(
            "certified_target_cidrs"
        ),

        F.sort_array(
            F.collect_set(
                "target_cidr"
            )
        ).alias(
            "target_cidrs"
        ),
    )

    .orderBy(
        "scan_file"
    )
)


print("=" * 120)
print("NMAP RUNTIME TARGETS / DURABLE PROVENANCE MATCH")
print("NMAP_SCAN_PROVENANCE IS TEMPORAL AUTHORITY")
print("=" * 120)

display(
    runtime_provenance_summary_df
)


# ---------------------------------------------------------------------------
# 13. Small driver-side temporal analysis
#
# Collection is restricted to:
#   - Cell 21 residual enumeration identities
#   - current-run certified Nmap target relationships
#
# No enterprise-scale dataset is collected.
# ---------------------------------------------------------------------------

targeted_driver_rows = (
    targeted_member_df

    .select(
        "tenable_identity_group_key",
        "asset_key",

        "candidate_tenable_uuid",
        "candidate_ip",

        "candidate_tenable_last_observed",
        "candidate_tenable_epoch",
        "candidate_tenable_age_days",

        "candidate_tenable_acr_score",
        "tenable_device_type_hint",

        "nmap_observation_state",
    )

    .collect()
)


scan_target_time_rows = [
    row.asDict(
        recursive=True
    )
    for row in (
        runtime_target_time_df

        .select(
            "scan_file",
            "scan_scope",
            "scan_perspective",
            "collection_capability",
            "target_cidr",

            "resolved_scan_id",

            "scan_start_epoch",
            "scan_end_epoch",

            "provenance_resolution_basis",
        )

        .collect()
    )
]


temporal_rows = []


for candidate_row in targeted_driver_rows:

    candidate_ip = str(
        candidate_row[
            "candidate_ip"
        ]
        or
        ""
    ).strip()


    candidate_epoch = (
        candidate_row[
            "candidate_tenable_epoch"
        ]
    )


    matched_scan_rows = []


    if candidate_ip:

        try:

            candidate_ip_object = (
                ipaddress.ip_address(
                    candidate_ip
                )
            )


            for scan_row in scan_target_time_rows:

                target_network = (
                    ipaddress.ip_network(
                        scan_row[
                            "target_cidr"
                        ],
                        strict=False,
                    )
                )


                if (
                    candidate_ip_object.version
                    ==
                    target_network.version
                    and
                    candidate_ip_object
                    in
                    target_network
                ):

                    matched_scan_rows.append(
                        scan_row
                    )


        except Exception:
            pass


    # -----------------------------------------------------------------------
    # Deduplicate target-CIDR rows to scan-instance grain.
    # -----------------------------------------------------------------------

    scan_instance_map = {}


    for scan_row in matched_scan_rows:

        scan_identity = (
            scan_row[
                "resolved_scan_id"
            ]
            or
            scan_row[
                "scan_file"
            ]
        )


        if scan_identity not in scan_instance_map:

            scan_instance_map[
                scan_identity
            ] = scan_row


    matched_scan_instances = list(
        scan_instance_map.values()
    )


    timestamped_scan_instances = []


    for scan_row in matched_scan_instances:

        raw_start = (
            scan_row[
                "scan_start_epoch"
            ]
        )


        raw_end = (
            scan_row[
                "scan_end_epoch"
            ]
        )


        if (
            raw_start is None
            and
            raw_end is None
        ):

            continue


        interval_start = (
            raw_start
            if raw_start is not None
            else raw_end
        )


        interval_end = (
            raw_end
            if raw_end is not None
            else raw_start
        )


        if interval_end < interval_start:

            interval_start, interval_end = (
                interval_end,
                interval_start,
            )


        enriched_scan_row = dict(
            scan_row
        )


        enriched_scan_row[
            "interval_start_epoch"
        ] = int(
            interval_start
        )


        enriched_scan_row[
            "interval_end_epoch"
        ] = int(
            interval_end
        )


        timestamped_scan_instances.append(
            enriched_scan_row
        )


    later_scans = []

    prior_scans = []

    overlapping_scans = []


    if candidate_epoch is not None:

        candidate_epoch = int(
            candidate_epoch
        )


        for scan_row in timestamped_scan_instances:

            if (
                scan_row[
                    "interval_start_epoch"
                ]
                >
                candidate_epoch
            ):

                later_scans.append(
                    scan_row
                )


            elif (
                scan_row[
                    "interval_end_epoch"
                ]
                <
                candidate_epoch
            ):

                prior_scans.append(
                    scan_row
                )


            else:

                overlapping_scans.append(
                    scan_row
                )


    earliest_later_scan = (
        min(
            later_scans,
            key=lambda row:
                row[
                    "interval_start_epoch"
                ],
        )
        if later_scans
        else None
    )


    latest_prior_scan = (
        max(
            prior_scans,
            key=lambda row:
                row[
                    "interval_end_epoch"
                ],
        )
        if prior_scans
        else None
    )


    latest_relevant_scan = (
        max(
            timestamped_scan_instances,
            key=lambda row:
                row[
                    "interval_end_epoch"
                ],
        )
        if timestamped_scan_instances
        else None
    )


    latest_relevant_scan_end_epoch = (
        latest_relevant_scan[
            "interval_end_epoch"
        ]
        if latest_relevant_scan
        else None
    )


    tenable_vs_latest_scan_hours = (
        (
            candidate_epoch
            -
            latest_relevant_scan_end_epoch
        )
        /
        3600.0
        if (
            candidate_epoch is not None
            and
            latest_relevant_scan_end_epoch
            is not None
        )
        else None
    )


    temporal_rows.append(
        (
            candidate_row[
                "tenable_identity_group_key"
            ],

            candidate_row[
                "asset_key"
            ],

            candidate_row[
                "candidate_tenable_uuid"
            ],

            candidate_ip,

            candidate_row[
                "candidate_tenable_last_observed"
            ],

            candidate_epoch,

            candidate_row[
                "candidate_tenable_age_days"
            ],

            candidate_row[
                "candidate_tenable_acr_score"
            ],

            candidate_row[
                "tenable_device_type_hint"
            ],

            len(
                matched_scan_instances
            ),

            len(
                timestamped_scan_instances
            ),

            len(
                later_scans
            ),

            len(
                prior_scans
            ),

            len(
                overlapping_scans
            ),

            (
                earliest_later_scan[
                    "interval_start_epoch"
                ]
                if earliest_later_scan
                else None
            ),

            (
                epoch_to_iso(
                    earliest_later_scan[
                        "interval_start_epoch"
                    ]
                )
                if earliest_later_scan
                else None
            ),

            (
                latest_prior_scan[
                    "interval_end_epoch"
                ]
                if latest_prior_scan
                else None
            ),

            (
                epoch_to_iso(
                    latest_prior_scan[
                        "interval_end_epoch"
                    ]
                )
                if latest_prior_scan
                else None
            ),

            latest_relevant_scan_end_epoch,

            (
                epoch_to_iso(
                    latest_relevant_scan_end_epoch
                )
                if latest_relevant_scan_end_epoch
                is not None
                else None
            ),

            tenable_vs_latest_scan_hours,

            sorted(
                {
                    row[
                        "target_cidr"
                    ]
                    for row in matched_scan_rows
                }
            ),

            sorted(
                {
                    row[
                        "scan_file"
                    ]
                    for row in matched_scan_instances
                }
            ),

            sorted(
                {
                    row[
                        "scan_scope"
                    ]
                    for row in matched_scan_instances
                    if row[
                        "scan_scope"
                    ]
                }
            ),

            sorted(
                {
                    row[
                        "scan_perspective"
                    ]
                    for row in matched_scan_instances
                    if row[
                        "scan_perspective"
                    ]
                }
            ),

            sorted(
                {
                    row[
                        "collection_capability"
                    ]
                    for row in matched_scan_instances
                    if row[
                        "collection_capability"
                    ]
                }
            ),

            sorted(
                {
                    row[
                        "provenance_resolution_basis"
                    ]
                    for row in matched_scan_instances
                }
            ),

            (
                candidate_row[
                    "nmap_observation_state"
                ]
                ==
                "CURRENT_NMAP_OBSERVATION"
            ),
        )
    )


# ---------------------------------------------------------------------------
# 14. Temporal result schema
# ---------------------------------------------------------------------------

