# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 23 - Residual Current Identity Customer Qualification
# Version: 1.0
#
# Purpose:
#   Apply D0029 customer qualification ONLY to the residual current Tenable
#   identities that survived Cell 22 temporal qualification.
#
# Analytical sequence:
#
#       unresolved IP
#           ->
#       source-local Tenable identity
#           ->
#       stronger identity reconciliation
#           ->
#       device/network qualification
#           ->
#       temporal qualification
#           ->
#       THIS CELL: customer / treatment qualification
#
# This cell DOES NOT create an assurance case.
#
# Customer logic:
#
#   1. Clearly enterprise-managed identity uncertainty
#        -> ENTERPRISE_SERVICE_OWNER
#
#   2. Clearly Post-managed identity uncertainty
#        -> POST_DT
#
#   3. Still-unresolved current identity / attribution uncertainty
#        -> RCSO
#
#   4. Broken analytical contract
#        -> RCAIP_ENGINEERING
#
# Important:
#   - No example_post_a-specific logic.
#   - No IP address is hard-coded.
#   - No expected row count is hard-coded.
#   - No raw source scan.
#   - No new identity matching.
#   - No asset merge.
#   - No case creation.
#   - No finding.
#   - No ticket.
#   - No remediation.
#   - No Delta write.
#
# "Would this exact cell run for Paris?"
#   YES.
#
# Safety:
#   READ ONLY
# ============================================================================

from pyspark.sql import functions as F
from pyspark.sql import types as T


# ---------------------------------------------------------------------------
# 1. Required prior diagnostic state
# ---------------------------------------------------------------------------

REQUIRED_CELL23_OBJECTS = [
    "residual_current_enumeration_df",
    "qualified_member_df",
]


missing_cell23_objects = [
    object_name
    for object_name in REQUIRED_CELL23_OBJECTS
    if object_name not in globals()
]


if missing_cell23_objects:

    raise RuntimeError(
        "Cell 23 requires the Cell 21 / Cell 22 PASS state. Missing: "
        + " | ".join(
            missing_cell23_objects
        )
    )


# ---------------------------------------------------------------------------
# 2. Bind exact Cell 22 residual population
#
# This is the ONLY population eligible for customer qualification here.
# Cell 22 currentness-validation identities remain outside active workload.
# ---------------------------------------------------------------------------

cell23_residual_input_df = (
    residual_current_enumeration_df

    .select(
        "tenable_identity_group_key",
        "asset_key",

        "candidate_tenable_uuid",
        "candidate_ip",

        "candidate_tenable_acr_score",
        "tenable_device_type_hint",

        "candidate_tenable_last_observed",
        "candidate_tenable_age_days",

        "latest_relevant_nmap_scan_end_time_utc",
        "tenable_vs_latest_nmap_hours",

        "matched_nmap_target_cidrs",
        "matched_nmap_scan_files",

        "temporal_collection_class",
        "temporal_next_gate",
        "temporal_interpretation",
    )

    .cache()
)


residual_input_rows = (
    cell23_residual_input_df.count()
)


residual_input_distinct_groups = (
    cell23_residual_input_df

    .select(
        "tenable_identity_group_key"
    )

    .distinct()

    .count()
)


residual_input_distinct_assets = (
    cell23_residual_input_df

    .select(
        "asset_key"
    )

    .distinct()

    .count()
)


residual_duplicate_groups = (
    cell23_residual_input_df

    .groupBy(
        "tenable_identity_group_key"
    )

    .count()

    .filter(
        F.col("count")
        >
        F.lit(1)
    )

    .count()
)


# ---------------------------------------------------------------------------
# 3. Validate exact temporal boundary inherited from Cell 22
# ---------------------------------------------------------------------------

invalid_temporal_gate_rows = (
    cell23_residual_input_df

    .filter(
        ~(
            F.col(
                "temporal_collection_class"
            )
            ==
            F.lit(
                "TENABLE_OBSERVED_AFTER_ALL_RELEVANT_NMAP_COLLECTIONS"
            )
        )
        |
        ~(
            F.col(
                "temporal_next_gate"
            )
            ==
            F.lit(
                "FOCUSED_IDENTITY_DEVICE_ENUMERATION"
            )
        )
    )

    .count()
)


# ---------------------------------------------------------------------------
# 4. Reattach ONLY already-derived Cell runtime Asset Plane context
#
# No source is rescanned.
# No identity matching is performed.
# ---------------------------------------------------------------------------

QUALIFIED_MEMBER_REQUIRED_KEYS = {
    "tenable_identity_group_key",
    "asset_key",
}


missing_qualified_member_keys = sorted(
    QUALIFIED_MEMBER_REQUIRED_KEYS
    -
    set(
        qualified_member_df.columns
    )
)


if missing_qualified_member_keys:

    raise RuntimeError(
        "Cell 21 qualified-member context is missing required keys: "
        + " | ".join(
            missing_qualified_member_keys
        )
    )


qualified_context_duplicate_rows = (
    qualified_member_df

    .groupBy(
        "tenable_identity_group_key",
        "asset_key",
    )

    .count()

    .filter(
        F.col("count")
        >
        F.lit(1)
    )

    .count()
)


if qualified_context_duplicate_rows:

    raise RuntimeError(
        "Cell 21 qualified-member context is not one row per "
        "Tenable identity group / asset key."
    )


def optional_context_column(
    dataframe,
    column_name,
    data_type="string",
    default_value=None,
):

    if column_name in dataframe.columns:

        return (
            F.col(
                column_name
            )
            .cast(
                data_type
            )
            .alias(
                column_name
            )
        )


    return (
        F.lit(
            default_value
        )
        .cast(
            data_type
        )
        .alias(
            column_name
        )
    )


qualified_context_df = (
    qualified_member_df

    .select(
        "tenable_identity_group_key",
        "asset_key",

        optional_context_column(
            qualified_member_df,
            "canonical_name",
        ),

        optional_context_column(
            qualified_member_df,
            "canonical_serial",
        ),

        optional_context_column(
            qualified_member_df,
            "canonical_ip",
        ),

        optional_context_column(
            qualified_member_df,
            "device_family",
        ),

        optional_context_column(
            qualified_member_df,
            "device_scope",
        ),

        optional_context_column(
            qualified_member_df,
            "device_family_confidence",
        ),

        optional_context_column(
            qualified_member_df,
            "network_scope",
        ),

        optional_context_column(
            qualified_member_df,
            "operational_boundary",
        ),

        optional_context_column(
            qualified_member_df,
            "operational_boundary_confidence",
        ),

        optional_context_column(
            qualified_member_df,
            "management_model",
        ),

        optional_context_column(
            qualified_member_df,
            "management_owner",
        ),

        optional_context_column(
            qualified_member_df,
            "identity_basis",
        ),

        optional_context_column(
            qualified_member_df,
            "identity_strength",
        ),

        optional_context_column(
            qualified_member_df,
            "source_mask_active",
        ),

        optional_context_column(
            qualified_member_df,
            "current_observation_status",
        ),

        optional_context_column(
            qualified_member_df,
            "visibility_class",
        ),

        optional_context_column(
            qualified_member_df,
            "post_visibility_state",
        ),

        optional_context_column(
            qualified_member_df,
            "attribution_confidence",
        ),

        optional_context_column(
            qualified_member_df,
            "attribution_conflict_flag",
            data_type="boolean",
            default_value=False,
        ),

        optional_context_column(
            qualified_member_df,
            "acr_band",
        ),

        F.lit(
            True
        ).alias(
            "_qualified_context_present"
        ),
    )
)


# ---------------------------------------------------------------------------
# 5. Join exact residual to existing context
# ---------------------------------------------------------------------------

residual_context_df = (
    cell23_residual_input_df.alias(
        "residual"
    )

    .join(
        qualified_context_df.alias(
            "context"
        ),

        on=[
            "tenable_identity_group_key",
            "asset_key",
        ],

        how="left",
    )

    .cache()
)


residual_context_rows = (
    residual_context_df.count()
)


missing_context_rows = (
    residual_context_df

    .filter(
        F.col(
            "_qualified_context_present"
        ).isNull()
    )

    .count()
)


# ---------------------------------------------------------------------------
# 6. Normalize existing evidence for deterministic routing
# ---------------------------------------------------------------------------

customer_base_df = (
    residual_context_df

    .withColumn(
        "_management_owner",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col(
                        "management_owner"
                    ),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "_management_model",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col(
                        "management_model"
                    ),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "_operational_boundary",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col(
                        "operational_boundary"
                    ),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "_identity_basis",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col(
                        "identity_basis"
                    ),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "_identity_strength",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col(
                        "identity_strength"
                    ),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "_source_mask_active",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col(
                        "source_mask_active"
                    ),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "_attribution_confidence",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col(
                        "attribution_confidence"
                    ),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "_network_scope",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col(
                        "network_scope"
                    ),
                    F.lit("")
                )
            )
        )
    )
)


# ---------------------------------------------------------------------------
# 7. Existing ownership signals
#
# Important:
#   ENTERPRISE_MANAGED_POST_OPERATED is treated as enterprise management,
#   not as Post management merely because the word POST is present.
# ---------------------------------------------------------------------------

customer_signal_df = (
    customer_base_df

    .withColumn(
        "enterprise_management_signal",

        (
            F.col(
                "_management_owner"
            ).isin(
                "ENTERPRISE",
                "ENTERPRISE_SERVICE_OWNER",
                "ENTERPRISE_DATA_OWNER",
            )
        )

        |

        (
            F.col(
                "_management_model"
            ).rlike(
                r"^ENTERPRISE"
            )
        )

        |

        (
            F.col(
                "_operational_boundary"
            ).rlike(
                r"^ENTERPRISE_MANAGED"
            )
        )
    )

    .withColumn(
        "post_management_signal",

        (
            F.col(
                "_management_owner"
            ).isin(
                "POST",
                "POST_DT",
            )
        )

        |

        (
            F.col(
                "_management_model"
            ).rlike(
                r"^POST"
            )
        )

        |

        (
            F.col(
                "_operational_boundary"
            ).rlike(
                r"^POST_MANAGED"
            )
        )
    )

    .withColumn(
        "identity_still_unresolved",

        (
            F.col(
                "_identity_basis"
            ).isin(
                "",
                "IP",
                "IP_ONLY",
                "UNRESOLVED_IP",
            )
        )

        |

        (
            F.col(
                "_identity_strength"
            ).isin(
                "",
                "WEAK",
                "IP_ONLY",
                "UNRESOLVED",
            )
        )
    )

    .withColumn(
        "attribution_requires_review",

        F.coalesce(
            F.col(
                "attribution_conflict_flag"
            ),
            F.lit(False)
        )

        |

        F.col(
            "_attribution_confidence"
        ).isin(
            "",
            "UNKNOWN",
            "LOW",
            "WEAK",
            "UNRESOLVED",
            "REVIEW_REQUIRED",
        )
    )
)


# ---------------------------------------------------------------------------
# 8. Contract anomaly checks
# ---------------------------------------------------------------------------

customer_signal_df = (
    customer_signal_df

    .withColumn(
        "analytical_contract_anomaly",

        F.col(
            "_qualified_context_present"
        ).isNull()

        |

        F.col(
            "candidate_ip"
        ).isNull()

        |

        F.col(
            "candidate_tenable_uuid"
        ).isNull()

        |

        ~(
            F.col(
                "temporal_collection_class"
            )
            ==
            F.lit(
                "TENABLE_OBSERVED_AFTER_ALL_RELEVANT_NMAP_COLLECTIONS"
            )
        )

        |

        ~(
            F.col(
                "temporal_next_gate"
            )
            ==
            F.lit(
                "FOCUSED_IDENTITY_DEVICE_ENUMERATION"
            )
        )
    )
)


# ---------------------------------------------------------------------------
# 9. D0029 customer qualification
#
# Precedence:
#
#   CONTRACT ANOMALY
#       -> RCAIP_ENGINEERING
#
#   CLEAR ENTERPRISE MANAGEMENT
#       -> ENTERPRISE_SERVICE_OWNER
#
#   CLEAR POST MANAGEMENT
#       -> POST_DT
#
#   CURRENT IDENTITY / ATTRIBUTION STILL UNRESOLVED
#       -> RCSO
#
# We do NOT infer ownership from the mere fact that an IP is inside a Post
# target range.
# ---------------------------------------------------------------------------

customer_qualified_df = (
    customer_signal_df

    .withColumn(
        "residual_treatment_class",

        F.when(
            F.col(
                "analytical_contract_anomaly"
            ),

            F.lit(
                "RCAIP_EVIDENCE_MODEL_REVIEW"
            )
        )

        .when(
            F.col(
                "enterprise_management_signal"
            ),

            F.lit(
                "ENTERPRISE_IDENTITY_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "post_management_signal"
            ),

            F.lit(
                "FOCUSED_POST_IDENTITY_VALIDATION"
            )
        )

        .otherwise(
            F.lit(
                "RCSO_IDENTITY_ATTRIBUTION_REVIEW"
            )
        )
    )

    .withColumn(
        "primary_customer",

        F.when(
            F.col(
                "residual_treatment_class"
            )
            ==
            F.lit(
                "RCAIP_EVIDENCE_MODEL_REVIEW"
            ),

            F.lit(
                "RCAIP_ENGINEERING"
            )
        )

        .when(
            F.col(
                "residual_treatment_class"
            )
            ==
            F.lit(
                "ENTERPRISE_IDENTITY_RECONCILIATION"
            ),

            F.lit(
                "ENTERPRISE_SERVICE_OWNER"
            )
        )

        .when(
            F.col(
                "residual_treatment_class"
            )
            ==
            F.lit(
                "FOCUSED_POST_IDENTITY_VALIDATION"
            ),

            F.lit(
                "POST_DT"
            )
        )

        .otherwise(
            F.lit(
                "RCSO"
            )
        )
    )

    .withColumn(
        "case_class_candidate",

        F.when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "ENTERPRISE_SERVICE_OWNER"
            ),

            F.lit(
                "ENTERPRISE_RECONCILIATION_REFERRAL"
            )
        )

        .when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "POST_DT"
            ),

            F.lit(
                "FOCUSED_POST_VALIDATION"
            )
        )

        .when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "RCSO"
            ),

            F.lit(
                "RCSO_IDENTITY_ATTRIBUTION_REVIEW"
            )
        )

        .otherwise(
            F.lit(
                "EVIDENCE_LIMITATION"
            )
        )
    )

    .withColumn(
        "customer_routing_basis",

        F.when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "ENTERPRISE_SERVICE_OWNER"
            ),

            F.lit(
                "Current Tenable identity remains unresolved after deterministic "
                "cross-source and temporal qualification, while existing Asset "
                "Plane context indicates enterprise management. Enterprise "
                "service ownership is therefore the primary resolution path."
            )
        )

        .when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "POST_DT"
            ),

            F.lit(
                "Current Tenable identity remains unresolved after deterministic "
                "cross-source and temporal qualification, while existing Asset "
                "Plane context indicates Post management. The remaining question "
                "is bounded operational identity validation."
            )
        )

        .when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "RCSO"
            ),

            F.lit(
                "The identity remains current and unresolved after source-local, "
                "cross-source, device/network, and temporal qualification, and "
                "existing evidence does not establish a customer with clear "
                "management authority. RCSO attribution judgment is required "
                "before assignment."
            )
        )

        .otherwise(
            F.lit(
                "The residual population violates the expected analytical "
                "contract and requires RCAIP engineering review before workload "
                "or customer assignment."
            )
        )
    )

    .withColumn(
        "recommended_next_action",

        F.when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "ENTERPRISE_SERVICE_OWNER"
            ),

            F.lit(
                "Reconcile the current Tenable host UUID and IP to the governed "
                "enterprise device identity and lifecycle record. Return the "
                "durable identifier and responsible owner, or document the "
                "source-record explanation."
            )
        )

        .when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "POST_DT"
            ),

            F.lit(
                "Validate the bounded current IP identity using authoritative "
                "Post operational records. Confirm device identity, function, "
                "and owner, or confirm that the address is no longer assigned. "
                "Do not treat unresolved identity itself as a vulnerability."
            )
        )

        .when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "RCSO"
            ),

            F.lit(
                "Perform a bounded identity and attribution review using existing "
                "governed enterprise evidence and, where necessary, focused Post "
                "coordination. Determine whether the identity represents a "
                "current Post asset, an enterprise-managed asset, expected "
                "infrastructure/service activity, or an unresolved source "
                "identity before case formation."
            )
        )

        .otherwise(
            F.lit(
                "Review the RCAIP evidence-model contract before any identity "
                "enumeration, routing, or case formation."
            )
        )
    )

    .withColumn(
        "case_formation_state",

        F.when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "RCAIP_ENGINEERING"
            ),

            F.lit(
                "BLOCKED_ENGINEERING_REVIEW"
            )
        )

        .otherwise(
            F.lit(
                "READY_FOR_DETERMINISTIC_CASE_FORMATION"
            )
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 10. Customer qualification summary
# ---------------------------------------------------------------------------

customer_qualification_summary_df = (
    customer_qualified_df

    .groupBy(
        "primary_customer",
        "residual_treatment_class",
        "case_class_candidate",
        "case_formation_state",
    )

    .agg(
        F.countDistinct(
            "tenable_identity_group_key"
        ).alias(
            "identity_groups"
        ),

        F.countDistinct(
            "asset_key"
        ).alias(
            "analytical_asset_keys"
        ),

        F.collect_set(
            "network_scope"
        ).alias(
            "network_scopes"
        ),

        F.collect_set(
            "operational_boundary"
        ).alias(
            "operational_boundaries"
        ),

        F.collect_set(
            "management_model"
        ).alias(
            "management_models"
        ),

        F.collect_set(
            "management_owner"
        ).alias(
            "management_owners"
        ),

        F.collect_set(
            "identity_basis"
        ).alias(
            "identity_bases"
        ),

        F.collect_set(
            "identity_strength"
        ).alias(
            "identity_strengths"
        ),

        F.collect_set(
            "attribution_confidence"
        ).alias(
            "attribution_confidence_states"
        ),
    )

    .orderBy(
        "primary_customer",
        "residual_treatment_class",
    )
)


print("=" * 120)
print("RESIDUAL CURRENT TENABLE IDENTITY - CUSTOMER QUALIFICATION SUMMARY")
print("D0029 CUSTOMER QUALIFICATION PRECEDES CASE FORMATION")
print("=" * 120)

display(
    customer_qualification_summary_df
)


