# ---------------------------------------------------------------------------
# 17. Canonical case semantics
#
# Specialized Cell 23 route/subtype is preserved.
#
# Canonical case-class mapping:
#
#   RCSO identity / attribution uncertainty
#       -> EVIDENCE_LIMITATION
#
#   Post validation
#       -> FOCUSED_POST_VALIDATION
#
#   Enterprise identity/service reconciliation
#       -> ENTERPRISE_RECONCILIATION_REFERRAL
#
#   RCAIP model limitation
#       -> EVIDENCE_LIMITATION
#
# No condition in this branch is promoted to a cybersecurity-control finding
# solely because an identity remains unresolved.
# ---------------------------------------------------------------------------

cell24_case_member_base_df = (
    cell23_customer_df

    .withColumn(
        "case_family",

        F.when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "RCSO"
            ),

            F.lit(
                "ASSET_IDENTITY_ATTRIBUTION_ASSURANCE"
            )
        )

        .when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "POST_DT"
            ),

            F.lit(
                "ASSET_IDENTITY_VALIDATION"
            )
        )

        .when(
            F.col(
                "primary_customer"
            ).isin(
                "ENTERPRISE_SERVICE_OWNER",
                "ENTERPRISE_DATA_OWNER",
            ),

            F.lit(
                "ASSET_IDENTITY_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "RCAIP_ENGINEERING"
            ),

            F.lit(
                "ASSET_VISIBILITY_EVIDENCE_MODEL_REVIEW"
            )
        )

        .otherwise(
            F.lit(
                "ASSET_IDENTITY_ASSURANCE"
            )
        )
    )

    .withColumn(
        "case_class",

        F.when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "POST_DT"
            ),

            F.lit(
                "FOCUSED_POST_VALIDATION"
            )
        )

        .when(
            F.col(
                "primary_customer"
            ).isin(
                "ENTERPRISE_SERVICE_OWNER",
                "ENTERPRISE_DATA_OWNER",
            ),

            F.lit(
                "ENTERPRISE_RECONCILIATION_REFERRAL"
            )
        )

        .when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "MONITORING"
            ),

            F.lit(
                "MONITORING_OR_TREND"
            )
        )

        .otherwise(
            F.lit(
                "EVIDENCE_LIMITATION"
            )
        )
    )

    .withColumn(
        "case_subtype",

        F.col(
            "case_class_candidate"
        )
    )

    .withColumn(
        "relationship_outcome",

        F.lit(
            "CURRENT_IDENTITY_UNRESOLVED_AFTER_RECONCILIATION"
        )
    )

    .withColumn(
        "priority_band",

        F.when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "RCAIP_ENGINEERING"
            ),

            F.lit(
                "MODEL_REVIEW"
            )
        )

        .otherwise(
            F.lit(
                "REVIEW"
            )
        )
    )

    .withColumn(
        "confidence_band",

        F.when(
            upper_normalized(
                F.col(
                    "identity_strength"
                )
            ).isin(
                "",
                "WEAK",
                "IP_ONLY",
                "UNRESOLVED",
            ),

            F.lit(
                "MODERATE"
            )
        )

        .otherwise(
            F.lit(
                "HIGH"
            )
        )
    )

    .withColumn(
        "priority_basis",

        F.lit(
            "Current in-scope identity evidence survived source-local, "
            "cross-source, device-context, lifecycle/recency, temporal, and "
            "customer qualification. Priority represents bounded review need, "
            "not vulnerability severity."
        )
    )

    .withColumn(
        "confidence_basis",

        F.lit(
            "The current source observation and collection chronology are "
            "supported by certified RCAIP evidence, but the durable asset "
            "identity remains unresolved."
        )
    )

    .withColumn(
        "condition_title",

        F.when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "RCSO"
            ),

            F.lit(
                "Current unresolved asset identity requires RCSO attribution review"
            )
        )

        .when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "POST_DT"
            ),

            F.lit(
                "Current unresolved asset identity requires focused Post validation"
            )
        )

        .when(
            F.col(
                "primary_customer"
            ).isin(
                "ENTERPRISE_SERVICE_OWNER",
                "ENTERPRISE_DATA_OWNER",
            ),

            F.lit(
                "Current unresolved asset identity requires enterprise reconciliation"
            )
        )

        .otherwise(
            F.lit(
                "Asset identity evidence requires analytical-model review"
            )
        )
    )

    .withColumn(
        "residual_concern",

        F.when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "RCSO"
            ),

            F.lit(
                "A current in-scope source identity remains unreconciled to a "
                "stronger durable asset identity and the existing evidence does "
                "not establish an operational owner. Cybersecurity attribution "
                "judgment is required before assignment."
            )
        )

        .when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "POST_DT"
            ),

            F.lit(
                "A current in-scope source identity remains unresolved after "
                "deterministic reconciliation, but existing evidence supports "
                "Post management and a bounded local validation question."
            )
        )

        .when(
            F.col(
                "primary_customer"
            ).isin(
                "ENTERPRISE_SERVICE_OWNER",
                "ENTERPRISE_DATA_OWNER",
            ),

            F.lit(
                "A current in-scope source identity remains unresolved after "
                "deterministic reconciliation while existing evidence supports "
                "enterprise management or enterprise data ownership."
            )
        )

        .otherwise(
            F.lit(
                "The remaining identity condition cannot be promoted until an "
                "RCAIP evidence-model limitation is resolved."
            )
        )
    )

    .withColumn(
        "secondary_customer_scope",

        F.when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "RCSO"
            ),

            F.lit(
                "POST_DT;ENTERPRISE_SERVICE_OWNER_AS_NEEDED"
            )
        )

        .when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "POST_DT"
            ),

            F.lit(
                "RCSO_AWARENESS"
            )
        )

        .when(
            F.col(
                "primary_customer"
            ).isin(
                "ENTERPRISE_SERVICE_OWNER",
                "ENTERPRISE_DATA_OWNER",
            ),

            F.lit(
                "RCSO_AWARENESS"
            )
        )

        .otherwise(
            F.lit(
                "RCSO_AWARENESS"
            )
        )
    )

    .withColumn(
        "_network_scope_norm",

        upper_normalized(
            F.col(
                "network_scope"
            )
        )
    )

    .withColumn(
        "_device_scope_norm",

        upper_normalized(
            F.col(
                "device_scope"
            )
        )
    )

    .withColumn(
        "_management_model_norm",

        upper_normalized(
            F.col(
                "management_model"
            )
        )
    )

    .withColumn(
        "_identity_basis_norm",

        upper_normalized(
            F.col(
                "identity_basis"
            )
        )
    )

    .withColumn(
        "_identity_strength_norm",

        upper_normalized(
            F.col(
                "identity_strength"
            )
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 18. Deterministic case signature
#
# Member-specific identifiers such as:
#   - IP
#   - UUID
#   - hostname
#   - serial
#
# are intentionally NOT part of the case signature.
#
# They remain case-member evidence.
# ---------------------------------------------------------------------------

cell24_case_member_base_df = (
    cell24_case_member_base_df

    .withColumn(
        "case_signature",

        F.concat_ws(
            " | ",

            F.col(
                "case_family"
            ),

            F.col(
                "case_class"
            ),

            F.col(
                "case_subtype"
            ),

            F.col(
                "primary_customer"
            ),

            F.col(
                "relationship_outcome"
            ),

            F.col(
                "_device_scope_norm"
            ),

            F.col(
                "_network_scope_norm"
            ),

            F.col(
                "_management_model_norm"
            ),

            F.col(
                "_identity_basis_norm"
            ),

            F.col(
                "_identity_strength_norm"
            ),

            F.col(
                "priority_band"
            ),

            F.col(
                "recommended_next_action"
            ),
        )
    )

    .withColumn(
        "case_instance_id",

        F.concat(
            F.lit(
                "CASE-"
            ),

            F.substring(
                F.sha2(
                    F.concat_ws(
                        "||",

                        F.lit(
                            str(
                                RCAIP_POST_SLUG
                            ).strip().lower()
                        ),

                        F.lit(
                            RCAIP_RUN_ID
                        ),

                        F.col(
                            "case_signature"
                        ),
                    ),
                    256,
                ),
                1,
                16,
            )
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 19. Case-member relationship product
# ---------------------------------------------------------------------------

RCAIP_DIAG001_UNRESOLVED_IP_CASE_MEMBER_DF = (
    cell24_case_member_base_df

    .select(
        "case_instance_id",

        F.lit(
            "PROBABLE_ASSET_IDENTITY"
        ).alias(
            "member_type"
        ),

        F.col(
            "tenable_identity_group_key"
        ).alias(
            "member_id"
        ),

        F.col(
            "asset_key"
        ).alias(
            "asset_id"
        ),

        F.lit(
            "Member survived source-local identity reconciliation, stronger "
            "exact-IP reconciliation, device/recency qualification, temporal "
            "qualification, and customer routing."
        ).alias(
            "membership_reason"
        ),

        "relationship_outcome",

        F.col(
            "identity_strength"
        ).alias(
            "identity_confidence"
        ),

        F.col(
            "confidence_band"
        ).alias(
            "evidence_confidence"
        ),

        F.lit(
            "NONE"
        ).alias(
            "member_priority_modifier"
        ),

        F.lit(
            "IP006_CONTROL_ASSURANCE_FEATURE|TENABLE_NORM|"
            "NMAP_SCAN_PROVENANCE|DIAG001_CELLS_16_23"
        ).alias(
            "source_provenance"
        ),

        F.lit(
            str(
                RCAIP_POST_SLUG
            ).strip().lower()
        ).alias(
            "post_profile_key"
        ),

        F.lit(
            RCAIP_RUN_ID
        ).alias(
            "assessment_run_id"
        ),

        "candidate_ip",
        "candidate_tenable_uuid",

        "candidate_tenable_last_observed",
        "candidate_tenable_age_days",

        "latest_relevant_nmap_scan_end_time_utc",
        "tenable_vs_latest_nmap_hours",

        "candidate_tenable_acr_score",
        "tenable_device_type_hint",

        "network_scope",
        "operational_boundary",

        "management_model",
        "management_owner",

        "identity_basis",
        "identity_strength",

        "source_mask_active",
        "current_observation_status",
        "post_visibility_state",

        "attribution_confidence",
        "attribution_conflict_flag",

        "primary_customer",
        "residual_treatment_class",
        "case_subtype",

        "customer_routing_basis",
        "recommended_next_action",
    )

    .cache()
)


case_member_count = (
    RCAIP_DIAG001_UNRESOLVED_IP_CASE_MEMBER_DF.count()
)


# ---------------------------------------------------------------------------
# 20. Assurance-case product
#
# One coherent condition + one common treatment = one assurance case.
# ---------------------------------------------------------------------------

cell24_case_aggregate_df = (
    cell24_case_member_base_df

    .groupBy(
        "case_instance_id",
        "case_family",
        "case_signature",
        "case_class",
        "case_subtype",

        "primary_customer",
        "secondary_customer_scope",

        "priority_band",
        "confidence_band",

        "priority_basis",
        "confidence_basis",

        "condition_title",
        "residual_concern",

        "recommended_next_action",
    )

    .agg(
        F.count(
            F.lit(1)
        ).alias(
            "affected_member_count"
        ),

        F.countDistinct(
            "asset_key"
        ).alias(
            "affected_asset_count"
        ),

        F.sort_array(
            F.collect_set(
                "asset_key"
            )
        ).alias(
            "affected_asset_keys"
        ),

        F.sort_array(
            F.collect_set(
                "candidate_ip"
            )
        ).alias(
            "candidate_ips"
        ),

        F.sort_array(
            F.collect_set(
                "candidate_tenable_uuid"
            )
        ).alias(
            "candidate_tenable_uuids"
        ),

        F.sort_array(
            F.collect_set(
                "network_scope"
            )
        ).alias(
            "network_scopes"
        ),

        F.sort_array(
            F.collect_set(
                "source_mask_active"
            )
        ).alias(
            "active_source_patterns"
        ),

        F.sort_array(
            F.collect_set(
                "identity_basis"
            )
        ).alias(
            "identity_bases"
        ),

        F.sort_array(
            F.collect_set(
                "identity_strength"
            )
        ).alias(
            "identity_strengths"
        ),

        F.min(
            "candidate_tenable_last_observed"
        ).alias(
            "earliest_member_tenable_observation"
        ),

        F.max(
            "candidate_tenable_last_observed"
        ).alias(
            "latest_member_tenable_observation"
        ),

        F.max(
            "latest_relevant_nmap_scan_end_time_utc"
        ).alias(
            "latest_relevant_nmap_scan_end_time_utc"
        ),
    )
)


RCAIP_DIAG001_UNRESOLVED_IP_CASE_DF = (
    cell24_case_aggregate_df

    .withColumn(
        "executive_summary",

        F.when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "RCSO"
            ),

            F.concat(
                F.lit(
                    "RCAIP identified "
                ),

                F.col(
                    "affected_member_count"
                ).cast(
                    "string"
                ),

                F.lit(
                    " current in-scope source identity relationship(s) that "
                    "remain unresolved after deterministic identity, device, "
                    "lifecycle, temporal, and ownership qualification. RCSO "
                    "judgment is required before the condition is assigned "
                    "elsewhere or interpreted as a security concern."
                )
            )
        )

        .when(
            F.col(
                "primary_customer"
            )
            ==
            F.lit(
                "POST_DT"
            ),

            F.concat(
                F.lit(
                    "RCAIP identified "
                ),

                F.col(
                    "affected_member_count"
                ).cast(
                    "string"
                ),

                F.lit(
                    " current identity relationship(s) requiring a bounded "
                    "Post operational validation."
                )
            )
        )

        .when(
            F.col(
                "primary_customer"
            ).isin(
                "ENTERPRISE_SERVICE_OWNER",
                "ENTERPRISE_DATA_OWNER",
            ),

            F.concat(
                F.lit(
                    "RCAIP identified "
                ),

                F.col(
                    "affected_member_count"
                ).cast(
                    "string"
                ),

                F.lit(
                    " current identity relationship(s) requiring enterprise "
                    "identity or ownership reconciliation."
                )
            )
        )

        .otherwise(
            F.lit(
                "RCAIP identified a residual evidence-model condition requiring "
                "engineering review before operational assignment."
            )
        )
    )

    .withColumn(
        "why_it_matters",

        F.lit(
            "Current source evidence within assessment scope should be understood "
            "before the RCSO concludes that the observation is an expected asset, "
            "an enterprise-managed asset, a transient or reassigned identity, "
            "or a cybersecurity condition. RCAIP therefore preserves the "
            "uncertainty as a bounded assurance case rather than manufacturing "
            "a finding from a missing identity relationship."
        )
    )

    .withColumn(
        "evidence_summary",

        F.concat(
            F.lit(
                "Affected identity members="
            ),

            F.col(
                "affected_member_count"
            ).cast(
                "string"
            ),

            F.lit(
                "; active source patterns="
            ),

            F.concat_ws(
                ",",
                F.col(
                    "active_source_patterns"
                )
            ),

            F.lit(
                "; identity basis="
            ),

            F.concat_ws(
                ",",
                F.col(
                    "identity_bases"
                )
            ),

            F.lit(
                "; identity strength="
            ),

            F.concat_ws(
                ",",
                F.col(
                    "identity_strengths"
                )
            ),

            F.lit(
                "; network scope="
            ),

            F.concat_ws(
                ",",
                F.col(
                    "network_scopes"
                )
            ),

            F.lit(
                "."
            )
        )
    )

    .withColumn(
        "benign_explanations_considered",

        F.lit(
            "Preceding RCAIP gates considered source-local UUID linkage, stronger "
            "existing exact-IP relationships, multiple-IP source-local identity, "
            "device-type context, observation aging, stale/lifecycle behavior, "
            "certified Nmap collection timing, and existing Post/enterprise "
            "management evidence."
        )
    )

    .withColumn(
        "recommended_action",

        F.col(
            "recommended_next_action"
        )
    )

    .withColumn(
        "action_owner",

        F.col(
            "primary_customer"
        )
    )

    # Raw source-record grain is not represented by this diagnostic case input.
    # Preserve NULL rather than mislabeling normalized/member rows as raw records.
    .withColumn(
        "source_record_count",

        F.lit(
            None
        ).cast(
            "long"
        )
    )

    .withColumn(
        "relationship_count",

        F.col(
            "affected_member_count"
        ).cast(
            "long"
        )
    )

    .withColumn(
        "related_assessment_question_ids",

        F.expr(
            "CAST(array() AS ARRAY<STRING>)"
        )
    )

    .withColumn(
        "trend_state",

        F.lit(
            "NOT_EVALUATED"
        )
    )

    .withColumn(
        "disposition_status",

        F.lit(
            "OPEN_REVIEW"
        )
    )

    .withColumn(
        "post_profile_key",

        F.lit(
            str(
                RCAIP_POST_SLUG
            ).strip().lower()
        )
    )

    .withColumn(
        "assessment_run_id",

        F.lit(
            RCAIP_RUN_ID
        )
    )

    .withColumn(
        "case_provenance",

        F.lit(
            "IP006_CONTROL_ASSURANCE_FEATURE|TENABLE_NORM|"
            "ASSET_RECONCILIATION_SCORED|NMAP_SCAN_PROVENANCE|"
            "RCAIP_DIAG001_CELLS_16_24"
        )
    )

    .select(
        "case_instance_id",
        "case_family",
        "case_signature",

        "case_class",
        "case_subtype",

        "primary_customer",
        "secondary_customer_scope",

        "priority_band",
        "confidence_band",

        "condition_title",
        "executive_summary",
        "why_it_matters",
        "evidence_summary",

        "benign_explanations_considered",
        "residual_concern",

        "recommended_action",
        "action_owner",

        "priority_basis",
        "confidence_basis",

        "affected_member_count",
        "affected_asset_count",

        "source_record_count",
        "relationship_count",

        "related_assessment_question_ids",

        "trend_state",
        "disposition_status",

        "post_profile_key",
        "assessment_run_id",

        "case_provenance",

        "affected_asset_keys",
        "candidate_ips",
        "candidate_tenable_uuids",

        "network_scopes",
        "active_source_patterns",
        "identity_bases",
        "identity_strengths",

        "earliest_member_tenable_observation",
        "latest_member_tenable_observation",
        "latest_relevant_nmap_scan_end_time_utc",
    )

    .cache()
)


