# ---------------------------------------------------------------------------
# 17. Deterministic qualification class
#
# These are POPULATION QUALIFICATIONS.
#
# They are not:
#   - cases
#   - findings
#   - final customer assignments
#
# Existing Discovery 002 and IP-005 semantics are preserved.
# ---------------------------------------------------------------------------

qualified_df = (
    attribution_reuse_df

    .withColumn(
        "_d002_status",

        normalized_upper(
            F.col(
                "d002_attribution_evidence_status"
            )
        )
    )

    .withColumn(
        "_ip005_case_type",

        normalized_upper(
            F.col(
                "ip005_primary_case_type"
            )
        )
    )

    .withColumn(
        "qualification_class",

        F.when(
            F.col(
                "boundary_semantic_class"
            )
            ==
            F.lit(
                "BOUNDARY_STATE_REQUIRES_SEMANTIC_REVIEW"
            ),

            F.lit(
                "IP006_BOUNDARY_SEMANTIC_REVIEW"
            )
        )

        .when(
            F.col(
                "discovery002_coverage_state"
            )
            ==
            F.lit(
                "DISCOVERY002_EXPECTED_BUT_MISSING"
            ),

            F.lit(
                "DISCOVERY002_COVERAGE_GAP"
            )
        )

        .when(
            F.col(
                "_d002_status"
            )
            ==
            F.lit(
                "CONSISTENT_MULTI_SOURCE_ATTRIBUTION_SEED"
            ),

            F.lit(
                "DISC002_CONSISTENT_MULTI_SOURCE_ATTRIBUTION_SEED"
            )
        )

        .when(
            F.col(
                "_d002_status"
            )
            ==
            F.lit(
                "MULTI_SOURCE_PRIMARY_WITH_SECONDARY_VARIANCE"
            ),

            F.lit(
                "DISC002_MULTI_SOURCE_PRIMARY_WITH_SECONDARY_VARIANCE"
            )
        )

        .when(
            F.col(
                "_d002_status"
            )
            ==
            F.lit(
                "CROSS_SOURCE_ATTRIBUTION_CONFLICT"
            ),

            F.lit(
                "DISC002_CROSS_SOURCE_ATTRIBUTION_CONFLICT"
            )
        )

        .when(
            F.col(
                "_d002_status"
            )
            ==
            F.lit(
                "STRONG_SINGLE_SOURCE_ATTRIBUTION_SEED"
            ),

            F.lit(
                "DISC002_STRONG_SINGLE_SOURCE_ATTRIBUTION_SEED"
            )
        )

        .when(
            F.col(
                "_d002_status"
            )
            ==
            F.lit(
                "MODERATE_SINGLE_SOURCE_ATTRIBUTION_EVIDENCE"
            ),

            F.lit(
                "DISC002_MODERATE_SINGLE_SOURCE_ATTRIBUTION_EVIDENCE"
            )
        )

        .when(
            F.col(
                "_d002_status"
            )
            ==
            F.lit(
                "NO_USABLE_ATTRIBUTION_SIGNAL"
            ),

            F.lit(
                "DISC002_NO_USABLE_ATTRIBUTION_SIGNAL"
            )
        )

        .when(
            F.col(
                "_d002_present"
            )
            ==
            F.lit(True),

            F.lit(
                "DISC002_OTHER_ATTRIBUTION_STATUS"
            )
        )

        .when(
            F.col(
                "_ip005_case_type"
            )
            ==
            F.lit(
                "POST_CMDB_REGISTRATION_VALIDATION"
            ),

            F.lit(
                "IP005_POST_CMDB_REGISTRATION_VALIDATION"
            )
        )

        .when(
            F.col(
                "_ip005_case_type"
            )
            ==
            F.lit(
                "CONFIRMED_OPERATIONAL_BASELINE"
            ),

            F.lit(
                "IP005_CONFIRMED_BASELINE_LOW_BOUNDARY_REVIEW"
            )
        )

        .when(
            F.col(
                "_ip005_case_type"
            )
            ==
            F.lit(
                "ENTERPRISE_ATTRIBUTION_CANDIDATE"
            ),

            F.lit(
                "DISCOVERY002_COVERAGE_GAP"
            )
        )

        .otherwise(
            F.lit(
                "IP005_OTHER_OPERATIONAL_TAXONOMY_REVIEW"
            )
        )
    )

    .withColumn(
        "qualification_next_gate",

        F.when(
            F.col(
                "qualification_class"
            )
            ==
            F.lit(
                "DISC002_CONSISTENT_MULTI_SOURCE_ATTRIBUTION_SEED"
            ),

            F.lit(
                "GOVERNED_CROSSWALK_VALIDATION"
            )
        )

        .when(
            F.col(
                "qualification_class"
            )
            ==
            F.lit(
                "DISC002_MULTI_SOURCE_PRIMARY_WITH_SECONDARY_VARIANCE"
            ),

            F.lit(
                "PRIMARY_VALUE_VARIANCE_REVIEW"
            )
        )

        .when(
            F.col(
                "qualification_class"
            )
            ==
            F.lit(
                "DISC002_CROSS_SOURCE_ATTRIBUTION_CONFLICT"
            ),

            F.lit(
                "IDENTITY_RECENCY_SOURCE_OWNER_CONFLICT_REVIEW"
            )
        )

        .when(
            F.col(
                "qualification_class"
            )
            ==
            F.lit(
                "DISC002_STRONG_SINGLE_SOURCE_ATTRIBUTION_SEED"
            ),

            F.lit(
                "SOURCE_CROSSWALK_THEN_CORROBORATE"
            )
        )

        .when(
            F.col(
                "qualification_class"
            )
            ==
            F.lit(
                "DISC002_MODERATE_SINGLE_SOURCE_ATTRIBUTION_EVIDENCE"
            ),

            F.lit(
                "SECOND_SOURCE_CORROBORATION"
            )
        )

        .when(
            F.col(
                "qualification_class"
            )
            ==
            F.lit(
                "DISC002_NO_USABLE_ATTRIBUTION_SIGNAL"
            ),

            F.lit(
                "ENTERPRISE_ATTRIBUTION_LOOKUP_OR_BOUNDED_POST_CORROBORATION"
            )
        )

        .when(
            F.col(
                "qualification_class"
            )
            ==
            F.lit(
                "IP005_POST_CMDB_REGISTRATION_VALIDATION"
            ),

            F.lit(
                "POST_INDICATIVE_IDENTITY_AND_CMDB_VALIDATION"
            )
        )

        .when(
            F.col(
                "qualification_class"
            )
            ==
            F.lit(
                "IP005_CONFIRMED_BASELINE_LOW_BOUNDARY_REVIEW"
            ),

            F.lit(
                "BOUNDARY_MODEL_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "qualification_class"
            )
            ==
            F.lit(
                "DISCOVERY002_COVERAGE_GAP"
            ),

            F.lit(
                "DISCOVERY002_COVERAGE_RECONCILIATION"
            )
        )

        .when(
            F.col(
                "qualification_class"
            )
            ==
            F.lit(
                "IP006_BOUNDARY_SEMANTIC_REVIEW"
            ),

            F.lit(
                "BOUNDARY_MODEL_RECONCILIATION"
            )
        )

        .otherwise(
            F.lit(
                "OPERATIONAL_TAXONOMY_REVIEW"
            )
        )
    )

    .withColumn(
        "qualification_evidence_basis",

        F.when(
            F.col(
                "_d002_present"
            )
            ==
            F.lit(True),

            F.lit(
                "DISCOVERY002_DURABLE_ATTRIBUTION_DISPOSITION"
            )
        )

        .otherwise(
            F.lit(
                "IP005_DURABLE_OPERATIONAL_TAXONOMY"
            )
        )
    )

    .withColumn(
        "existing_validation_responsibility",

        F.coalesce(
            F.col(
                "d002_validation_responsibility"
            ),

            F.col(
                "ip005_recommended_owner_scope"
            ),

            F.lit(
                "NOT_YET_ESTABLISHED"
            )
        )
    )

    .withColumn(
        "workload_promotion_state",

        F.lit(
            "NOT_READY_FOR_CASE_FORMATION"
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 18. Deterministic qualification cohorts
#
# Deliberately do NOT include IP / hostname / individual asset identifiers.
#
# We are grouping by established analytical meaning and next treatment only.
# Detailed source/device variation is profiled AFTER cohort selection.
# ---------------------------------------------------------------------------

qualification_cohort_summary_df = (
    qualified_df

    .groupBy(
        "qualification_class",
        "qualification_next_gate",
        "qualification_evidence_basis",
        "existing_validation_responsibility",
        "workload_promotion_state",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.countDistinct(
            "source_mask_active"
        ).alias(
            "active_source_patterns"
        ),

        F.countDistinct(
            "device_scope"
        ).alias(
            "device_scope_patterns"
        ),

        F.countDistinct(
            "network_scope"
        ).alias(
            "network_scope_patterns"
        ),

        F.sum(
            F.when(
                F.col(
                    "mde_missing_branch_status"
                )
                !=
                F.lit(
                    "NOT_IN_MDE_MISSING_BRANCH"
                ),

                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "prior_mde_branch_overlay_assets"
        ),
    )

    .withColumn(
        "qualification_signature",

        F.concat_ws(
            " | ",

            F.col(
                "qualification_class"
            ),

            F.col(
                "qualification_next_gate"
            ),

            F.col(
                "qualification_evidence_basis"
            ),

            F.col(
                "existing_validation_responsibility"
            ),
        )
    )

    .withColumn(
        "qualification_cohort_id",

        F.concat(
            F.lit(
                "ATTRQ-"
            ),

            F.substring(
                F.sha2(
                    F.col(
                        "qualification_signature"
                    ),
                    256,
                ),
                1,
                12,
            )
        )
    )

    .orderBy(
        F.desc(
            "asset_count"
        ),
        "qualification_class",
        "existing_validation_responsibility",
    )

    .cache()
)


qualification_cohort_count = (
    qualification_cohort_summary_df.count()
)


qualification_asset_reconciliation = int(
    qualification_cohort_summary_df

    .agg(
        F.sum(
            "asset_count"
        ).alias(
            "asset_count"
        )
    )

    .first()[
        "asset_count"
    ]
    or
    0
)


print()
print("=" * 120)
print("ATTRIBUTION BRANCH - DETERMINISTIC QUALIFICATION COHORTS")
print("QUALIFICATION POPULATIONS ONLY - NOT CASES / NOT FINAL CUSTOMER ROUTING")
print("=" * 120)

display(
    qualification_cohort_summary_df
)


# ---------------------------------------------------------------------------
# 19. Select largest qualification cohort
#
# IMPORTANT:
#   Largest by asset count is used ONLY to sequence further analysis.
#   It is NOT a priority or severity determination.
# ---------------------------------------------------------------------------

largest_cohort_record = (
    qualification_cohort_summary_df

    .orderBy(
        F.desc(
            "asset_count"
        ),
        "qualification_class",
        "existing_validation_responsibility",
    )

    .limit(1)

    .first()
)


if largest_cohort_record is None:

    largest_cohort_id = (
        "NONE"
    )

    largest_cohort_class = (
        "NONE"
    )

    largest_cohort_next_gate = (
        "NONE"
    )

    largest_cohort_asset_count = 0


else:

    largest_cohort_id = str(
        largest_cohort_record[
            "qualification_cohort_id"
        ]
    )


    largest_cohort_class = str(
        largest_cohort_record[
            "qualification_class"
        ]
    )


    largest_cohort_next_gate = str(
        largest_cohort_record[
            "qualification_next_gate"
        ]
    )


    largest_cohort_asset_count = int(
        largest_cohort_record[
            "asset_count"
        ]
        or
        0
    )


largest_cohort_df = (
    qualified_df

    .join(
        qualification_cohort_summary_df

        .filter(
            F.col(
                "qualification_cohort_id"
            )
            ==
            F.lit(
                largest_cohort_id
            )
        )

        .select(
            "qualification_class",
            "qualification_next_gate",
            "qualification_evidence_basis",
            "existing_validation_responsibility",
        ),

        on=[
            "qualification_class",
            "qualification_next_gate",
            "qualification_evidence_basis",
            "existing_validation_responsibility",
        ],

        how="inner",
    )

    .cache()
)


largest_cohort_actual_count = (
    largest_cohort_df.count()
)


# ---------------------------------------------------------------------------
# 20. Largest-cohort visibility / device context
# ---------------------------------------------------------------------------

largest_cohort_context_profile_df = (
    largest_cohort_df

    .groupBy(
        "source_mask_active",
        "current_observation_status",

        "visibility_class",
        "post_visibility_state",

        "device_family",
        "device_scope",

        "network_scope",

        "ip005_primary_case_type",

        "d002_attribution_evidence_status",
        "d002_attribution_confidence",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "applicability_review_count"
                ),
                F.lit(0)
            )
        ).alias(
            "applicability_review_relationships"
        ),

        F.sum(
            F.coalesce(
                F.col(
                    "adverse_relationship_count"
                ),
                F.lit(0)
            )
        ).alias(
            "adverse_control_relationships"
        ),
    )

    .orderBy(
        F.desc(
            "asset_count"
        ),
        "source_mask_active",
        "device_scope",
    )
)


print()
print("=" * 120)
print("LARGEST ATTRIBUTION QUALIFICATION COHORT - VISIBILITY / DEVICE CONTEXT")
print("SELECTED BY POPULATION SIZE FOR ANALYTICAL SEQUENCING - NOT BY PRIORITY")
print("=" * 120)

