# ---------------------------------------------------------------------------
# 24. Certification
# ---------------------------------------------------------------------------

certification_failures = []


if branch_duplicate_assets != 0:

    certification_failures.append(
        "Cell 25 attribution branch contains duplicate asset keys."
    )


if branch_rows != branch_distinct_assets:

    certification_failures.append(
        "Cell 25 attribution branch is not one row per asset_key."
    )


if ip005_duplicate_assets != 0:

    certification_failures.append(
        "IP-005 investigation universe contains duplicate asset keys."
    )


if branch_missing_ip005_count != 0:

    certification_failures.append(
        "One or more Cell 25 attribution-branch assets are missing IP-005 "
        "operational taxonomy."
    )


if reuse_rows != branch_rows:

    certification_failures.append(
        "IP-005 / Discovery 002 reuse join changed the attribution branch row count."
    )


if reuse_distinct_assets != branch_distinct_assets:

    certification_failures.append(
        "IP-005 / Discovery 002 reuse join changed the distinct asset population."
    )


if d002_duplicate_assets != 0:

    certification_failures.append(
        "Discovery 002 disposition contains duplicate asset keys."
    )


if d002_closure_status != "PASS":

    certification_failures.append(
        "Discovery 002 closure certificate status is not PASS."
    )


if not d002_closure_ready:

    certification_failures.append(
        "Discovery 002 closure certificate is not ready."
    )


if d002_rows != d002_closure_candidate_count:

    certification_failures.append(
        "Discovery 002 disposition row count does not match certified candidate count."
    )


if d002_rows != d002_closure_disposition_count:

    certification_failures.append(
        "Discovery 002 disposition row count does not match certified disposition count."
    )


if d002_status_reconciliation_failures != 0:

    certification_failures.append(
        "Discovery 002 evidence-status counts do not reconcile to its closure certificate."
    )


if d002_automatic_action_violations != 0:

    certification_failures.append(
        "Discovery 002 contains an unexpected automatic assignment/finding/"
        "ticket/remediation permission."
    )


if d002_expected_but_missing_count != 0:

    certification_failures.append(
        "IP-005 enterprise-attribution candidates are missing from current-run "
        "Discovery 002 disposition."
    )


if d002_overlap_ip005_semantic_mismatch != 0:

    certification_failures.append(
        "Discovery 002 branch overlap contains assets not classified by IP-005 "
        "as ENTERPRISE_ATTRIBUTION_CANDIDATE."
    )


if qualification_asset_reconciliation != branch_rows:

    certification_failures.append(
        "Deterministic qualification cohorts do not reconcile to the attribution branch."
    )


if unmapped_qualification_count != 0:

    certification_failures.append(
        "One or more attribution-branch assets received no qualification."
    )


if largest_cohort_missing_reconciliation:

    certification_failures.append(
        "Largest qualification cohort detail count does not reconcile to its summary."
    )


status = (
    "PASS"
    if not certification_failures
    else
    "FAIL"
)


analytical_exception_count = (
    boundary_semantic_review_count
    +
    d002_unknown_status_count
)


if status != "PASS":

    qualification_readiness = (
        "NOT_READY"
    )


elif analytical_exception_count > 0:

    qualification_readiness = (
        "PARTIAL_MODEL_REVIEW_REQUIRED"
    )


else:

    qualification_readiness = (
        "READY_FOR_COHORT_QUALIFICATION"
    )


