# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 27 - Largest Attribution Cohort Source / Intune Platform Qualification
# Version: 1.0
#
# Purpose:
#   Inspect the runtime asset DISC002_NO_USABLE_ATTRIBUTION_SIGNAL cohort before
#   performing any additional attribution or MDE-history analysis.
#
# Questions:
#   1. What active-source families make up the cohort?
#   2. What operating-system/platform families make up the Intune-only slice?
#   3. Does existing Asset Plane evidence already preserve stale/historical MDE
#      context for any Intune-only assets?
#   4. Which Intune-only platform populations merit an MDE history lookback,
#      and which require device/control applicability qualification first?
#
# Important:
#   - Microsoft platform support != RCAIP control applicability.
#   - iOS/iPadOS/Android Intune enrollment does not automatically imply that
#     MDE must be present.
#   - No new MDE matching is performed here.
#   - No raw MDE or Intune source is scanned.
#   - No identity or Asset Plane mutation.
#   - No Delta writes.
#
# Post-agnostic acceptance:
#   Would this exact analytical cell run for Paris? YES.
# ============================================================================

from pyspark.sql import functions as F


# ---------------------------------------------------------------------------
# 1. Prior-state / runtime validation
# ---------------------------------------------------------------------------

REQUIRED_OBJECTS = [
    "RCAIP_CONFIG_000_READY",
    "RCAIP_POST_NAME",
    "RCAIP_POST_SLUG",
    "RCAIP_RUN_ID",
    "get_rcaip_table",
    "RCAIP_DIAG001_CELL26_READY",
    "RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_DF",
    "RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_CLASS",
]


missing_objects = [
    name
    for name in REQUIRED_OBJECTS
    if name not in globals()
]


if missing_objects:
    raise RuntimeError(
        "Cell 27 missing required runtime / Cell 26 objects: "
        + " | ".join(missing_objects)
    )


if not RCAIP_CONFIG_000_READY:
    raise RuntimeError(
        "Config 000 did not publish a ready runtime."
    )


if not RCAIP_DIAG001_CELL26_READY:
    raise RuntimeError(
        "Cell 26 did not publish a ready state."
    )


# ---------------------------------------------------------------------------
# 2. Bind exact Cell 26 selected cohort
# ---------------------------------------------------------------------------

cohort_df = (
    RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_DF
    .cache()
)


cohort_rows = cohort_df.count()


cohort_distinct_assets = (
    cohort_df
    .select("asset_key")
    .distinct()
    .count()
)


if cohort_rows != cohort_distinct_assets:
    raise RuntimeError(
        "Cell 26 selected cohort is not one row per asset_key."
    )


# ---------------------------------------------------------------------------
# 3. Normalize active-source family
# ---------------------------------------------------------------------------

source_family_df = (
    cohort_df

    .withColumn(
        "_active_source_mask",
        F.upper(
            F.trim(
                F.coalesce(
                    F.col("source_mask_active"),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "source_family",

        F.when(
            F.col("_active_source_mask") == F.lit("INTUNE"),
            F.lit("INTUNE_ONLY")
        )

        .when(
            F.col("_active_source_mask") == F.lit("TENABLE"),
            F.lit("TENABLE_ONLY")
        )

        .when(
            F.col("_active_source_mask") == F.lit("NMAP"),
            F.lit("NMAP_ONLY")
        )

        .when(
            F.col("_active_source_mask").rlike(
                r"(^|\|)NMAP(\||$)"
            ),
            F.lit("NMAP_MULTI_SOURCE")
        )

        .otherwise(
            F.concat(
                F.lit("OTHER::"),
                F.col("_active_source_mask")
            )
        )
    )

    .cache()
)


source_family_summary_df = (
    source_family_df

    .groupBy(
        "source_family",
        "source_mask_active",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        )
    )

    .orderBy(
        F.desc("asset_count"),
        "source_family",
    )
)


print("=" * 120)
print("LARGEST ATTRIBUTION COHORT - ACTIVE SOURCE FAMILY")
print("=" * 120)

display(
    source_family_summary_df
)


# ---------------------------------------------------------------------------
# 4. Select Intune-only slice
# ---------------------------------------------------------------------------

intune_only_base_df = (
    source_family_df

    .filter(
        F.col("source_family")
        ==
        F.lit("INTUNE_ONLY")
    )

    .cache()
)


intune_only_count = (
    intune_only_base_df.count()
)


# ---------------------------------------------------------------------------
# 5. Resolve current certified INTUNE_NORM
# ---------------------------------------------------------------------------

INTUNE_NORM_TABLE = get_rcaip_table(
    "INTUNE_NORM"
)


if not spark.catalog.tableExists(
    INTUNE_NORM_TABLE
):
    raise RuntimeError(
        "INTUNE_NORM is unavailable: "
        + INTUNE_NORM_TABLE
    )


intune_source_df = spark.table(
    INTUNE_NORM_TABLE
)


REQUIRED_INTUNE_COLUMNS = {
    "asset_key",
    "post_slug",
    "rcaip_run_id",
    "intune_device_name",
    "intune_user_name",
    "intune_last_contact",
    "intune_os_version",
    "intune_serial_number",
    "intune_operating_system",
    "days_since_observed",
    "observation_age_bucket",
    "is_stale_90",
}


missing_intune_columns = sorted(
    REQUIRED_INTUNE_COLUMNS
    -
    set(intune_source_df.columns)
)


if missing_intune_columns:
    raise RuntimeError(
        "INTUNE_NORM missing required columns: "
        + " | ".join(missing_intune_columns)
    )


intune_norm_df = (
    intune_source_df

    .filter(
        F.lower(
            F.trim(
                F.col("post_slug")
            )
        )
        ==
        F.lit(
            str(RCAIP_POST_SLUG)
            .strip()
            .lower()
        )
    )

    .filter(
        F.col("rcaip_run_id")
        ==
        F.lit(RCAIP_RUN_ID)
    )

    .select(
        "asset_key",
        "intune_device_name",
        "intune_user_name",
        "intune_last_contact",
        "intune_os_version",
        "intune_serial_number",
        "intune_operating_system",

        F.col(
            "days_since_observed"
        ).alias(
            "intune_age_days"
        ),

        F.col(
            "observation_age_bucket"
        ).alias(
            "intune_age_bucket"
        ),

        F.col(
            "is_stale_90"
        ).alias(
            "intune_stale_90"
        ),

        F.lit(True).alias(
            "_intune_norm_present"
        ),
    )

    .cache()
)


intune_norm_rows = (
    intune_norm_df.count()
)


intune_norm_distinct_assets = (
    intune_norm_df
    .select("asset_key")
    .distinct()
    .count()
)


if (
    intune_norm_rows
    !=
    intune_norm_distinct_assets
):
    raise RuntimeError(
        "INTUNE_NORM is not one row per asset_key."
    )


# ---------------------------------------------------------------------------
# 6. Attach normalized Intune detail
# ---------------------------------------------------------------------------

intune_only_df = (
    intune_only_base_df

    .join(
        intune_norm_df,
        on="asset_key",
        how="left",
    )

    .withColumn(
        "_os",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col("intune_operating_system"),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "intune_platform_family",

        # iOS / iPadOS before broader Apple/macOS test.
        F.when(
            F.col("_os").rlike(
                r"(^|[^A-Z])(IOS|IPADOS)([^A-Z]|$)"
            )
            |
            F.col("_os").rlike(
                r"IPHONE|IPAD"
            ),

            F.lit("IOS_IPADOS")
        )

        .when(
            F.col("_os").rlike(
                r"MACOS|MAC OS|OS X|DARWIN"
            ),

            F.lit("MACOS")
        )

        .when(
            F.col("_os").contains(
                "WINDOWS"
            ),

            F.lit("WINDOWS")
        )

        .when(
            F.col("_os").contains(
                "ANDROID"
            ),

            F.lit("ANDROID")
        )

        .when(
            F.col("_os").contains(
                "LINUX"
            ),

            F.lit("LINUX")
        )

        .when(
            F.length(
                F.col("_os")
            )
            ==
            F.lit(0),

            F.lit("UNKNOWN")
        )

        .otherwise(
            F.concat(
                F.lit("OTHER::"),
                F.col("_os")
            )
        )
    )

    .withColumn(
        "platform_context_class",

        F.when(
            F.col("intune_platform_family")
            .isin(
                "IOS_IPADOS",
                "ANDROID",
            ),

            F.lit(
                "MOBILE_PLATFORM"
            )
        )

        .when(
            F.col("intune_platform_family")
            .isin(
                "WINDOWS",
                "MACOS",
                "LINUX",
            ),

            F.lit(
                "COMPUTE_PLATFORM"
            )
        )

        .otherwise(
            F.lit(
                "PLATFORM_REQUIRES_REVIEW"
            )
        )
    )

    .withColumn(
        "intune_name_present",

        F.col("intune_device_name").isNotNull()
        &
        (
            F.length(
                F.trim(
                    F.col("intune_device_name")
                )
            )
            >
            F.lit(0)
        )
    )

    .withColumn(
        "intune_serial_present",

        F.col("intune_serial_number").isNotNull()
        &
        (
            F.length(
                F.trim(
                    F.col("intune_serial_number")
                )
            )
            >
            F.lit(0)
        )
    )

    .withColumn(
        "intune_user_present",

        F.col("intune_user_name").isNotNull()
        &
        (
            F.length(
                F.trim(
                    F.col("intune_user_name")
                )
            )
            >
            F.lit(0)
        )
    )

    .cache()
)


missing_intune_norm_context = (
    intune_only_df

    .filter(
        F.col("_intune_norm_present").isNull()
    )

    .count()
)


# ---------------------------------------------------------------------------
# 7. Determine whether MDE context ALREADY exists in the Asset Plane
#
# source_mask_active == INTUNE for this population by definition.
#
# But source_mask_raw / source_mask_stale may reveal that MDE evidence exists
# historically or is stale at the already-reconciled asset_key.
# ---------------------------------------------------------------------------

intune_only_df = (
    intune_only_df

    .withColumn(
        "_source_mask_raw_upper",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col("source_mask_raw"),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "_source_mask_stale_upper",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col("source_mask_stale"),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "mde_in_raw_source_history",

        F.col(
            "_source_mask_raw_upper"
        ).rlike(
            r"(^|\|)MDE(\||$)"
        )
    )

    .withColumn(
        "mde_in_stale_source_history",

        F.col(
            "_source_mask_stale_upper"
        ).rlike(
            r"(^|\|)MDE(\||$)"
        )
    )

    .withColumn(
        "prior_mde_rediscovery_overlay",

        F.coalesce(
            F.col("mde_missing_branch_status"),
            F.lit(
                "NOT_IN_MDE_MISSING_BRANCH"
            )
        )
        !=
        F.lit(
            "NOT_IN_MDE_MISSING_BRANCH"
        )
    )

    .withColumn(
        "existing_mde_context_class",

        F.when(
            F.col(
                "prior_mde_rediscovery_overlay"
            ),

            F.lit(
                "PRIOR_MDE_REDISCOVERY_ANALYSIS_AVAILABLE"
            )
        )

        .when(
            F.col(
                "mde_in_stale_source_history"
            ),

            F.lit(
                "STALE_MDE_CONTEXT_ALREADY_IN_ASSET_PLANE"
            )
        )

        .when(
            F.col(
                "mde_in_raw_source_history"
            ),

            F.lit(
                "MDE_RAW_CONTEXT_ALREADY_IN_ASSET_PLANE"
            )
        )

        .otherwise(
            F.lit(
                "NO_EXISTING_MDE_CONTEXT"
            )
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 8. Platform-aware MDE-history sequencing
#
# This is deliberately NOT an MDE applicability decision.
#
# Microsoft supports MDE across several platforms, including mobile.
# RCAIP still needs organizational control/applicability semantics before
# treating absence as meaningful.
# ---------------------------------------------------------------------------

intune_only_df = (
    intune_only_df

    .withColumn(
        "mde_history_next_gate",

        F.when(
            F.col(
                "existing_mde_context_class"
            )
            !=
            F.lit(
                "NO_EXISTING_MDE_CONTEXT"
            ),

            F.lit(
                "USE_EXISTING_MDE_CONTEXT_FIRST"
            )
        )

        .when(
            F.col(
                "intune_platform_family"
            ).isin(
                "IOS_IPADOS",
                "ANDROID",
            ),

            F.lit(
                "MOBILE_MDE_APPLICABILITY_POLICY_REVIEW_FIRST"
            )
        )

        .when(
            F.col(
                "intune_platform_family"
            ).isin(
                "WINDOWS",
                "MACOS",
                "LINUX",
            ),

            F.lit(
                "GOVERNED_MDE_HISTORY_LOOKBACK_CANDIDATE"
            )
        )

        .otherwise(
            F.lit(
                "PLATFORM_AND_CONTROL_APPLICABILITY_REVIEW_FIRST"
            )
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 9. Intune-only operating-system / platform profile
# ---------------------------------------------------------------------------

intune_platform_profile_df = (
    intune_only_df

    .groupBy(
        "intune_platform_family",
        "platform_context_class",
        "intune_operating_system",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "intune_name_present"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_device_name"
        ),

        F.sum(
            F.when(
                F.col(
                    "intune_serial_present"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_serial"
        ),

        F.sum(
            F.when(
                F.col(
                    "intune_user_present"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_user"
        ),

        F.min(
            "intune_age_days"
        ).alias(
            "minimum_age_days"
        ),

        F.max(
            "intune_age_days"
        ).alias(
            "maximum_age_days"
        ),
    )

    .orderBy(
        F.desc("asset_count"),
        "intune_platform_family",
    )
)


print()
print("=" * 120)
print("INTUNE-ONLY ATTRIBUTION POPULATION - PLATFORM PROFILE")
print("PLATFORM SUPPORT DOES NOT BY ITSELF ESTABLISH MDE APPLICABILITY")
print("=" * 120)

display(
    intune_platform_profile_df
)


# ---------------------------------------------------------------------------
# 10. Existing MDE context by platform
# ---------------------------------------------------------------------------

intune_mde_context_profile_df = (
    intune_only_df

    .groupBy(
        "intune_platform_family",
        "existing_mde_context_class",
        "mde_history_next_gate",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "mde_in_raw_source_history"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_mde_raw_history"
        ),

        F.sum(
            F.when(
                F.col(
                    "mde_in_stale_source_history"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_stale_mde_history"
        ),

        F.sum(
            F.when(
                F.col(
                    "prior_mde_rediscovery_overlay"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_prior_mde_rediscovery"
        ),
    )

    .orderBy(
        F.desc("asset_count"),
        "intune_platform_family",
    )
)


print()
print("=" * 120)
print("INTUNE-ONLY ATTRIBUTION POPULATION - EXISTING MDE CONTEXT")
print("NO NEW MDE LOOKBACK PERFORMED")
print("=" * 120)

display(
    intune_mde_context_profile_df
)


# ---------------------------------------------------------------------------
# 11. MDE lookback-readiness summary
# ---------------------------------------------------------------------------

mde_lookback_readiness_df = (
    intune_only_df

    .groupBy(
        "mde_history_next_gate"
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.sort_array(
            F.collect_set(
                "intune_platform_family"
            )
        ).alias(
            "platform_families"
        ),

        F.sum(
            F.when(
                F.col(
                    "intune_serial_present"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_serial"
        ),

        F.sum(
            F.when(
                F.col(
                    "intune_name_present"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_device_name"
        ),
    )

    .orderBy(
        F.desc("asset_count")
    )
)


print()
print("=" * 120)
print("INTUNE-ONLY ATTRIBUTION POPULATION - MDE HISTORY LOOKBACK READINESS")
print("=" * 120)

display(
    mde_lookback_readiness_df
)


# ---------------------------------------------------------------------------
# 12. Identity-quality profile for any future governed MDE lookback
#
# Important:
#   This does NOT perform the lookup.
#   It tells us whether supported identifiers exist before designing it.
# ---------------------------------------------------------------------------

mde_lookup_candidate_identity_profile_df = (
    intune_only_df

    .filter(
        F.col(
            "mde_history_next_gate"
        )
        ==
        F.lit(
            "GOVERNED_MDE_HISTORY_LOOKBACK_CANDIDATE"
        )
    )

    .groupBy(
        "intune_platform_family",
        "intune_serial_present",
        "intune_name_present",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        )
    )

    .orderBy(
        F.desc("asset_count"),
        "intune_platform_family",
    )
)


if (
    mde_lookup_candidate_identity_profile_df.count()
    >
    0
):

    print()
    print("=" * 120)
    print("POTENTIAL FUTURE MDE LOOKBACK - AVAILABLE INTUNE IDENTITY EVIDENCE")
    print("IDENTIFIER PROFILE ONLY - NO MATCHING PERFORMED")
    print("=" * 120)

    display(
        mde_lookup_candidate_identity_profile_df
    )


# ---------------------------------------------------------------------------
# 13. Certification metrics
# ---------------------------------------------------------------------------

source_family_reconciliation = int(
    source_family_summary_df

    .agg(
        F.sum(
            "asset_count"
        ).alias(
            "asset_count"
        )
    )

    .first()[
        "asset_count"
    ]
    or
    0
)


intune_platform_reconciliation = int(
    intune_platform_profile_df

    .agg(
        F.sum(
            "asset_count"
        ).alias(
            "asset_count"
        )
    )

    .first()[
        "asset_count"
    ]
    or
    0
)


mobile_intune_only_count = (
    intune_only_df

    .filter(
        F.col(
            "intune_platform_family"
        ).isin(
            "IOS_IPADOS",
            "ANDROID",
        )
    )

    .count()
)


windows_intune_only_count = (
    intune_only_df

    .filter(
        F.col(
            "intune_platform_family"
        )
        ==
        F.lit(
            "WINDOWS"
        )
    )

    .count()
)


macos_intune_only_count = (
    intune_only_df

    .filter(
        F.col(
            "intune_platform_family"
        )
        ==
        F.lit(
            "MACOS"
        )
    )

    .count()
)


linux_intune_only_count = (
    intune_only_df

    .filter(
        F.col(
            "intune_platform_family"
        )
        ==
        F.lit(
            "LINUX"
        )
    )

    .count()
)


unknown_other_intune_count = (
    intune_only_df

    .filter(
        (
            F.col(
                "intune_platform_family"
            )
            ==
            F.lit(
                "UNKNOWN"
            )
        )
        |
        F.col(
            "intune_platform_family"
        ).startswith(
            "OTHER::"
        )
    )

    .count()
)


existing_mde_context_count = (
    intune_only_df

    .filter(
        F.col(
            "existing_mde_context_class"
        )
        !=
        F.lit(
            "NO_EXISTING_MDE_CONTEXT"
        )
    )

    .count()
)


prior_mde_rediscovery_count = (
    intune_only_df

    .filter(
        F.col(
            "prior_mde_rediscovery_overlay"
        )
    )

    .count()
)


governed_mde_lookback_candidate_count = (
    intune_only_df

    .filter(
        F.col(
            "mde_history_next_gate"
        )
        ==
        F.lit(
            "GOVERNED_MDE_HISTORY_LOOKBACK_CANDIDATE"
        )
    )

    .count()
)


mobile_applicability_first_count = (
    intune_only_df

    .filter(
        F.col(
            "mde_history_next_gate"
        )
        ==
        F.lit(
            "MOBILE_MDE_APPLICABILITY_POLICY_REVIEW_FIRST"
        )
    )

    .count()
)


# ---------------------------------------------------------------------------
# 14. Certification
# ---------------------------------------------------------------------------

certification_failures = []


if cohort_rows != cohort_distinct_assets:

    certification_failures.append(
        "Largest Cell 26 cohort is not one row per asset_key."
    )


if source_family_reconciliation != cohort_rows:

    certification_failures.append(
        "Source-family profile does not reconcile to the selected cohort."
    )


if missing_intune_norm_context != 0:

    certification_failures.append(
        "One or more Intune-only assets are missing current INTUNE_NORM context."
    )


if intune_platform_reconciliation != intune_only_count:

    certification_failures.append(
        "Intune platform profile does not reconcile to Intune-only population."
    )


status = (
    "PASS"
    if not certification_failures
    else
    "FAIL"
)


readiness = (
    "READY_TO_SELECT_PLATFORM_APPROPRIATE_NEXT_GATE"
    if status == "PASS"
    else
    "NOT_READY"
)


print()
print("=" * 120)
print("RCAIP DIAG 001 - CELL 27 CERTIFICATION")
print("=" * 120)

print(
    "Status:",
    status
)

print(
    "Post:",
    RCAIP_POST_NAME
)

print(
    "Run ID:",
    RCAIP_RUN_ID
)

print(
    "Selected Cell 26 qualification class:",
    RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_CLASS
)

print(
    "Selected cohort assets:",
    cohort_rows
)

print(
    "Source-family reconciliation:",
    source_family_reconciliation,
    "/",
    cohort_rows
)

print(
    "Intune-only assets:",
    intune_only_count
)

print(
    "Intune-only assets missing INTUNE_NORM context:",
    missing_intune_norm_context
)

print(
    "Intune platform reconciliation:",
    intune_platform_reconciliation,
    "/",
    intune_only_count
)

print(
    "Intune-only mobile-platform assets:",
    mobile_intune_only_count
)

print(
    "Intune-only Windows assets:",
    windows_intune_only_count
)

print(
    "Intune-only macOS assets:",
    macos_intune_only_count
)

print(
    "Intune-only Linux assets:",
    linux_intune_only_count
)

print(
    "Intune-only unknown/other-platform assets:",
    unknown_other_intune_count
)

print(
    "Intune-only assets with existing Asset Plane MDE context:",
    existing_mde_context_count
)

print(
    "Intune-only assets already covered by prior MDE rediscovery:",
    prior_mde_rediscovery_count
)

print(
    "Compute-platform assets eligible for governed MDE-history design:",
    governed_mde_lookback_candidate_count
)

print(
    "Mobile-platform assets requiring applicability/policy qualification first:",
    mobile_applicability_first_count
)

print(
    "New MDE history search performed:",
    "NO"
)

print(
    "Raw Intune source scanned:",
    "NO"
)

print(
    "Raw MDE source scanned:",
    "NO"
)

print(
    "Asset Plane or identity mutated:",
    "NO"
)

print(
    "Delta writes:",
    0
)

print(
    "Readiness:",
    readiness
)


if certification_failures:

    print()
    print("Certification failures:")

    for failure in certification_failures:
        print(
            " -",
            failure
        )

else:

    print()

    print(
        "Next gate: use the observed Intune platform distribution to decide "
        "whether MDE history reconciliation is analytically appropriate. "
        "Do not infer MDE applicability from Intune enrollment alone."
    )


print("=" * 120)


if certification_failures:

    raise RuntimeError(
        "Cell 27 certification failed: "
        + " || ".join(
            certification_failures
        )
    )


# ---------------------------------------------------------------------------
# 15. Publish state for next gate
# ---------------------------------------------------------------------------

RCAIP_DIAG001_CELL27_READY = True

RCAIP_DIAG001_LARGEST_ATTRIBUTION_SOURCE_FAMILY_DF = (
    source_family_df
)

RCAIP_DIAG001_INTUNE_ONLY_DF = (
    intune_only_df
)

RCAIP_DIAG001_INTUNE_PLATFORM_PROFILE_DF = (
    intune_platform_profile_df
)

RCAIP_DIAG001_INTUNE_MDE_CONTEXT_PROFILE_DF = (
    intune_mde_context_profile_df
)

RCAIP_DIAG001_INTUNE_MDE_LOOKBACK_READINESS_DF = (
    mde_lookback_readiness_df
)


# ---------------------------------------------------------------------------
# 16. Release temporary cache
# ---------------------------------------------------------------------------

cohort_df.unpersist(
    blocking=False
)

intune_norm_df.unpersist(
    blocking=False
)

intune_only_base_df.unpersist(
    blocking=False
)

# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 27 - Largest Attribution Cohort Source / Intune Platform Qualification
# Version: 1.0
#
# Purpose:
#   Inspect the runtime asset DISC002_NO_USABLE_ATTRIBUTION_SIGNAL cohort before
#   performing any additional attribution or MDE-history analysis.
#
# Questions:
#   1. What active-source families make up the cohort?
#   2. What operating-system/platform families make up the Intune-only slice?
#   3. Does existing Asset Plane evidence already preserve stale/historical MDE
#      context for any Intune-only assets?
#   4. Which Intune-only platform populations merit an MDE history lookback,
#      and which require device/control applicability qualification first?
#
# Important:
#   - Microsoft platform support != RCAIP control applicability.
#   - iOS/iPadOS/Android Intune enrollment does not automatically imply that
#     MDE must be present.
#   - No new MDE matching is performed here.
#   - No raw MDE or Intune source is scanned.
#   - No identity or Asset Plane mutation.
#   - No Delta writes.
#
# Post-agnostic acceptance:
#   Would this exact analytical cell run for Paris? YES.
# ============================================================================

from pyspark.sql import functions as F


# ---------------------------------------------------------------------------
# 1. Prior-state / runtime validation
# ---------------------------------------------------------------------------

REQUIRED_OBJECTS = [
    "RCAIP_CONFIG_000_READY",
    "RCAIP_POST_NAME",
    "RCAIP_POST_SLUG",
    "RCAIP_RUN_ID",
    "get_rcaip_table",
    "RCAIP_DIAG001_CELL26_READY",
    "RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_DF",
    "RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_CLASS",
]


missing_objects = [
    name
    for name in REQUIRED_OBJECTS
    if name not in globals()
]


if missing_objects:
    raise RuntimeError(
        "Cell 27 missing required runtime / Cell 26 objects: "
        + " | ".join(missing_objects)
    )


if not RCAIP_CONFIG_000_READY:
    raise RuntimeError(
        "Config 000 did not publish a ready runtime."
    )


if not RCAIP_DIAG001_CELL26_READY:
    raise RuntimeError(
        "Cell 26 did not publish a ready state."
    )


# ---------------------------------------------------------------------------
# 2. Bind exact Cell 26 selected cohort
# ---------------------------------------------------------------------------

cohort_df = (
    RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_DF
    .cache()
)


cohort_rows = cohort_df.count()


cohort_distinct_assets = (
    cohort_df
    .select("asset_key")
    .distinct()
    .count()
)


if cohort_rows != cohort_distinct_assets:
    raise RuntimeError(
        "Cell 26 selected cohort is not one row per asset_key."
    )


# ---------------------------------------------------------------------------
# 3. Normalize active-source family
# ---------------------------------------------------------------------------

source_family_df = (
    cohort_df

    .withColumn(
        "_active_source_mask",
        F.upper(
            F.trim(
                F.coalesce(
                    F.col("source_mask_active"),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "source_family",

        F.when(
            F.col("_active_source_mask") == F.lit("INTUNE"),
            F.lit("INTUNE_ONLY")
        )

        .when(
            F.col("_active_source_mask") == F.lit("TENABLE"),
            F.lit("TENABLE_ONLY")
        )

        .when(
            F.col("_active_source_mask") == F.lit("NMAP"),
            F.lit("NMAP_ONLY")
        )

        .when(
            F.col("_active_source_mask").rlike(
                r"(^|\|)NMAP(\||$)"
            ),
            F.lit("NMAP_MULTI_SOURCE")
        )

        .otherwise(
            F.concat(
                F.lit("OTHER::"),
                F.col("_active_source_mask")
            )
        )
    )

    .cache()
)


source_family_summary_df = (
    source_family_df

    .groupBy(
        "source_family",
        "source_mask_active",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        )
    )

    .orderBy(
        F.desc("asset_count"),
        "source_family",
    )
)


print("=" * 120)
print("LARGEST ATTRIBUTION COHORT - ACTIVE SOURCE FAMILY")
print("=" * 120)

display(
    source_family_summary_df
)


# ---------------------------------------------------------------------------
# 4. Select Intune-only slice
# ---------------------------------------------------------------------------

intune_only_base_df = (
    source_family_df

    .filter(
        F.col("source_family")
        ==
        F.lit("INTUNE_ONLY")
    )

    .cache()
)


intune_only_count = (
    intune_only_base_df.count()
)


# ---------------------------------------------------------------------------
# 5. Resolve current certified INTUNE_NORM
# ---------------------------------------------------------------------------

INTUNE_NORM_TABLE = get_rcaip_table(
    "INTUNE_NORM"
)


if not spark.catalog.tableExists(
    INTUNE_NORM_TABLE
):
    raise RuntimeError(
        "INTUNE_NORM is unavailable: "
        + INTUNE_NORM_TABLE
    )


intune_source_df = spark.table(
    INTUNE_NORM_TABLE
)


REQUIRED_INTUNE_COLUMNS = {
    "asset_key",
    "post_slug",
    "rcaip_run_id",
    "intune_device_name",
    "intune_user_name",
    "intune_last_contact",
    "intune_os_version",
    "intune_serial_number",
    "intune_operating_system",
    "days_since_observed",
    "observation_age_bucket",
    "is_stale_90",
}


missing_intune_columns = sorted(
    REQUIRED_INTUNE_COLUMNS
    -
    set(intune_source_df.columns)
)


if missing_intune_columns:
    raise RuntimeError(
        "INTUNE_NORM missing required columns: "
        + " | ".join(missing_intune_columns)
    )


intune_norm_df = (
    intune_source_df

    .filter(
        F.lower(
            F.trim(
                F.col("post_slug")
            )
        )
        ==
        F.lit(
            str(RCAIP_POST_SLUG)
            .strip()
            .lower()
        )
    )

    .filter(
        F.col("rcaip_run_id")
        ==
        F.lit(RCAIP_RUN_ID)
    )

    .select(
        "asset_key",
        "intune_device_name",
        "intune_user_name",
        "intune_last_contact",
        "intune_os_version",
        "intune_serial_number",
        "intune_operating_system",

        F.col(
            "days_since_observed"
        ).alias(
            "intune_age_days"
        ),

        F.col(
            "observation_age_bucket"
        ).alias(
            "intune_age_bucket"
        ),

        F.col(
            "is_stale_90"
        ).alias(
            "intune_stale_90"
        ),

        F.lit(True).alias(
            "_intune_norm_present"
        ),
    )

    .cache()
)


intune_norm_rows = (
    intune_norm_df.count()
)


intune_norm_distinct_assets = (
    intune_norm_df
    .select("asset_key")
    .distinct()
    .count()
)


if (
    intune_norm_rows
    !=
    intune_norm_distinct_assets
):
    raise RuntimeError(
        "INTUNE_NORM is not one row per asset_key."
    )


# ---------------------------------------------------------------------------
# 6. Attach normalized Intune detail
# ---------------------------------------------------------------------------

intune_only_df = (
    intune_only_base_df

    .join(
        intune_norm_df,
        on="asset_key",
        how="left",
    )

    .withColumn(
        "_os",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col("intune_operating_system"),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "intune_platform_family",

        # iOS / iPadOS before broader Apple/macOS test.
        F.when(
            F.col("_os").rlike(
                r"(^|[^A-Z])(IOS|IPADOS)([^A-Z]|$)"
            )
            |
            F.col("_os").rlike(
                r"IPHONE|IPAD"
            ),

            F.lit("IOS_IPADOS")
        )

        .when(
            F.col("_os").rlike(
                r"MACOS|MAC OS|OS X|DARWIN"
            ),

            F.lit("MACOS")
        )

        .when(
            F.col("_os").contains(
                "WINDOWS"
            ),

            F.lit("WINDOWS")
        )

        .when(
            F.col("_os").contains(
                "ANDROID"
            ),

            F.lit("ANDROID")
        )

        .when(
            F.col("_os").contains(
                "LINUX"
            ),

            F.lit("LINUX")
        )

        .when(
            F.length(
                F.col("_os")
            )
            ==
            F.lit(0),

            F.lit("UNKNOWN")
        )

        .otherwise(
            F.concat(
                F.lit("OTHER::"),
                F.col("_os")
            )
        )
    )

    .withColumn(
        "platform_context_class",

        F.when(
            F.col("intune_platform_family")
            .isin(
                "IOS_IPADOS",
                "ANDROID",
            ),

            F.lit(
                "MOBILE_PLATFORM"
            )
        )

        .when(
            F.col("intune_platform_family")
            .isin(
                "WINDOWS",
                "MACOS",
                "LINUX",
            ),

            F.lit(
                "COMPUTE_PLATFORM"
            )
        )

        .otherwise(
            F.lit(
                "PLATFORM_REQUIRES_REVIEW"
            )
        )
    )

    .withColumn(
        "intune_name_present",

        F.col("intune_device_name").isNotNull()
        &
        (
            F.length(
                F.trim(
                    F.col("intune_device_name")
                )
            )
            >
            F.lit(0)
        )
    )

    .withColumn(
        "intune_serial_present",

        F.col("intune_serial_number").isNotNull()
        &
        (
            F.length(
                F.trim(
                    F.col("intune_serial_number")
                )
            )
            >
            F.lit(0)
        )
    )

    .withColumn(
        "intune_user_present",

        F.col("intune_user_name").isNotNull()
        &
        (
            F.length(
                F.trim(
                    F.col("intune_user_name")
                )
            )
            >
            F.lit(0)
        )
    )

    .cache()
)


missing_intune_norm_context = (
    intune_only_df

    .filter(
        F.col("_intune_norm_present").isNull()
    )

    .count()
)


# ---------------------------------------------------------------------------
# 7. Determine whether MDE context ALREADY exists in the Asset Plane
#
# source_mask_active == INTUNE for this population by definition.
#
# But source_mask_raw / source_mask_stale may reveal that MDE evidence exists
# historically or is stale at the already-reconciled asset_key.
# ---------------------------------------------------------------------------

intune_only_df = (
    intune_only_df

    .withColumn(
        "_source_mask_raw_upper",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col("source_mask_raw"),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "_source_mask_stale_upper",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col("source_mask_stale"),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "mde_in_raw_source_history",

        F.col(
            "_source_mask_raw_upper"
        ).rlike(
            r"(^|\|)MDE(\||$)"
        )
    )

    .withColumn(
        "mde_in_stale_source_history",

        F.col(
            "_source_mask_stale_upper"
        ).rlike(
            r"(^|\|)MDE(\||$)"
        )
    )

    .withColumn(
        "prior_mde_rediscovery_overlay",

        F.coalesce(
            F.col("mde_missing_branch_status"),
            F.lit(
                "NOT_IN_MDE_MISSING_BRANCH"
            )
        )
        !=
        F.lit(
            "NOT_IN_MDE_MISSING_BRANCH"
        )
    )

    .withColumn(
        "existing_mde_context_class",

        F.when(
            F.col(
                "prior_mde_rediscovery_overlay"
            ),

            F.lit(
                "PRIOR_MDE_REDISCOVERY_ANALYSIS_AVAILABLE"
            )
        )

        .when(
            F.col(
                "mde_in_stale_source_history"
            ),

            F.lit(
                "STALE_MDE_CONTEXT_ALREADY_IN_ASSET_PLANE"
            )
        )

        .when(
            F.col(
                "mde_in_raw_source_history"
            ),

            F.lit(
                "MDE_RAW_CONTEXT_ALREADY_IN_ASSET_PLANE"
            )
        )

        .otherwise(
            F.lit(
                "NO_EXISTING_MDE_CONTEXT"
            )
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 8. Platform-aware MDE-history sequencing
#
# This is deliberately NOT an MDE applicability decision.
#
# Microsoft supports MDE across several platforms, including mobile.
# RCAIP still needs organizational control/applicability semantics before
# treating absence as meaningful.
# ---------------------------------------------------------------------------

intune_only_df = (
    intune_only_df

    .withColumn(
        "mde_history_next_gate",

        F.when(
            F.col(
                "existing_mde_context_class"
            )
            !=
            F.lit(
                "NO_EXISTING_MDE_CONTEXT"
            ),

            F.lit(
                "USE_EXISTING_MDE_CONTEXT_FIRST"
            )
        )

        .when(
            F.col(
                "intune_platform_family"
            ).isin(
                "IOS_IPADOS",
                "ANDROID",
            ),

            F.lit(
                "MOBILE_MDE_APPLICABILITY_POLICY_REVIEW_FIRST"
            )
        )

        .when(
            F.col(
                "intune_platform_family"
            ).isin(
                "WINDOWS",
                "MACOS",
                "LINUX",
            ),

            F.lit(
                "GOVERNED_MDE_HISTORY_LOOKBACK_CANDIDATE"
            )
        )

        .otherwise(
            F.lit(
                "PLATFORM_AND_CONTROL_APPLICABILITY_REVIEW_FIRST"
            )
        )
    )

    .cache()
)


# ---------------------------------------------------------------------------
# 9. Intune-only operating-system / platform profile
# ---------------------------------------------------------------------------

intune_platform_profile_df = (
    intune_only_df

    .groupBy(
        "intune_platform_family",
        "platform_context_class",
        "intune_operating_system",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "intune_name_present"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_device_name"
        ),

        F.sum(
            F.when(
                F.col(
                    "intune_serial_present"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_serial"
        ),

        F.sum(
            F.when(
                F.col(
                    "intune_user_present"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_user"
        ),

        F.min(
            "intune_age_days"
        ).alias(
            "minimum_age_days"
        ),

        F.max(
            "intune_age_days"
        ).alias(
            "maximum_age_days"
        ),
    )

    .orderBy(
        F.desc("asset_count"),
        "intune_platform_family",
    )
)


print()
print("=" * 120)
print("INTUNE-ONLY ATTRIBUTION POPULATION - PLATFORM PROFILE")
print("PLATFORM SUPPORT DOES NOT BY ITSELF ESTABLISH MDE APPLICABILITY")
print("=" * 120)

display(
    intune_platform_profile_df
)


# ---------------------------------------------------------------------------
# 10. Existing MDE context by platform
# ---------------------------------------------------------------------------

intune_mde_context_profile_df = (
    intune_only_df

    .groupBy(
        "intune_platform_family",
        "existing_mde_context_class",
        "mde_history_next_gate",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.sum(
            F.when(
                F.col(
                    "mde_in_raw_source_history"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_mde_raw_history"
        ),

        F.sum(
            F.when(
                F.col(
                    "mde_in_stale_source_history"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_stale_mde_history"
        ),

        F.sum(
            F.when(
                F.col(
                    "prior_mde_rediscovery_overlay"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_prior_mde_rediscovery"
        ),
    )

    .orderBy(
        F.desc("asset_count"),
        "intune_platform_family",
    )
)


print()
print("=" * 120)
print("INTUNE-ONLY ATTRIBUTION POPULATION - EXISTING MDE CONTEXT")
print("NO NEW MDE LOOKBACK PERFORMED")
print("=" * 120)

display(
    intune_mde_context_profile_df
)


# ---------------------------------------------------------------------------
# 11. MDE lookback-readiness summary
# ---------------------------------------------------------------------------

mde_lookback_readiness_df = (
    intune_only_df

    .groupBy(
        "mde_history_next_gate"
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.sort_array(
            F.collect_set(
                "intune_platform_family"
            )
        ).alias(
            "platform_families"
        ),

        F.sum(
            F.when(
                F.col(
                    "intune_serial_present"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_serial"
        ),

        F.sum(
            F.when(
                F.col(
                    "intune_name_present"
                ),
                F.lit(1)
            )
            .otherwise(
                F.lit(0)
            )
        ).alias(
            "assets_with_device_name"
        ),
    )

    .orderBy(
        F.desc("asset_count")
    )
)


print()
print("=" * 120)
print("INTUNE-ONLY ATTRIBUTION POPULATION - MDE HISTORY LOOKBACK READINESS")
print("=" * 120)

display(
    mde_lookback_readiness_df
)


# ---------------------------------------------------------------------------
# 12. Identity-quality profile for any future governed MDE lookback
#
# Important:
#   This does NOT perform the lookup.
#   It tells us whether supported identifiers exist before designing it.
# ---------------------------------------------------------------------------

mde_lookup_candidate_identity_profile_df = (
    intune_only_df

    .filter(
        F.col(
            "mde_history_next_gate"
        )
        ==
        F.lit(
            "GOVERNED_MDE_HISTORY_LOOKBACK_CANDIDATE"
        )
    )

    .groupBy(
        "intune_platform_family",
        "intune_serial_present",
        "intune_name_present",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        )
    )

    .orderBy(
        F.desc("asset_count"),
        "intune_platform_family",
    )
)


if (
    mde_lookup_candidate_identity_profile_df.count()
    >
    0
):

    print()
    print("=" * 120)
    print("POTENTIAL FUTURE MDE LOOKBACK - AVAILABLE INTUNE IDENTITY EVIDENCE")
    print("IDENTIFIER PROFILE ONLY - NO MATCHING PERFORMED")
    print("=" * 120)

    display(
        mde_lookup_candidate_identity_profile_df
    )


# ---------------------------------------------------------------------------
# 13. Certification metrics
# ---------------------------------------------------------------------------

source_family_reconciliation = int(
    source_family_summary_df

    .agg(
        F.sum(
            "asset_count"
        ).alias(
            "asset_count"
        )
    )

    .first()[
        "asset_count"
    ]
    or
    0
)


intune_platform_reconciliation = int(
    intune_platform_profile_df

    .agg(
        F.sum(
            "asset_count"
        ).alias(
            "asset_count"
        )
    )

    .first()[
        "asset_count"
    ]
    or
    0
)


mobile_intune_only_count = (
    intune_only_df

    .filter(
        F.col(
            "intune_platform_family"
        ).isin(
            "IOS_IPADOS",
            "ANDROID",
        )
    )

    .count()
)


windows_intune_only_count = (
    intune_only_df

    .filter(
        F.col(
            "intune_platform_family"
        )
        ==
        F.lit(
            "WINDOWS"
        )
    )

    .count()
)


macos_intune_only_count = (
    intune_only_df

    .filter(
        F.col(
            "intune_platform_family"
        )
        ==
        F.lit(
            "MACOS"
        )
    )

    .count()
)


linux_intune_only_count = (
    intune_only_df

    .filter(
        F.col(
            "intune_platform_family"
        )
        ==
        F.lit(
            "LINUX"
        )
    )

    .count()
)


unknown_other_intune_count = (
    intune_only_df

    .filter(
        (
            F.col(
                "intune_platform_family"
            )
            ==
            F.lit(
                "UNKNOWN"
            )
        )
        |
        F.col(
            "intune_platform_family"
        ).startswith(
            "OTHER::"
        )
    )

    .count()
)


existing_mde_context_count = (
    intune_only_df

    .filter(
        F.col(
            "existing_mde_context_class"
        )
        !=
        F.lit(
            "NO_EXISTING_MDE_CONTEXT"
        )
    )

    .count()
)


prior_mde_rediscovery_count = (
    intune_only_df

    .filter(
        F.col(
            "prior_mde_rediscovery_overlay"
        )
    )

    .count()
)


governed_mde_lookback_candidate_count = (
    intune_only_df

    .filter(
        F.col(
            "mde_history_next_gate"
        )
        ==
        F.lit(
            "GOVERNED_MDE_HISTORY_LOOKBACK_CANDIDATE"
        )
    )

    .count()
)


mobile_applicability_first_count = (
    intune_only_df

    .filter(
        F.col(
            "mde_history_next_gate"
        )
        ==
        F.lit(
            "MOBILE_MDE_APPLICABILITY_POLICY_REVIEW_FIRST"
        )
    )

    .count()
)


# ---------------------------------------------------------------------------
# 14. Certification
# ---------------------------------------------------------------------------

certification_failures = []


if cohort_rows != cohort_distinct_assets:

    certification_failures.append(
        "Largest Cell 26 cohort is not one row per asset_key."
    )


if source_family_reconciliation != cohort_rows:

    certification_failures.append(
        "Source-family profile does not reconcile to the selected cohort."
    )


if missing_intune_norm_context != 0:

    certification_failures.append(
        "One or more Intune-only assets are missing current INTUNE_NORM context."
    )


if intune_platform_reconciliation != intune_only_count:

    certification_failures.append(
        "Intune platform profile does not reconcile to Intune-only population."
    )


status = (
    "PASS"
    if not certification_failures
    else
    "FAIL"
)


readiness = (
    "READY_TO_SELECT_PLATFORM_APPROPRIATE_NEXT_GATE"
    if status == "PASS"
    else
    "NOT_READY"
)


print()
print("=" * 120)
print("RCAIP DIAG 001 - CELL 27 CERTIFICATION")
print("=" * 120)

print(
    "Status:",
    status
)

print(
    "Post:",
    RCAIP_POST_NAME
)

print(
    "Run ID:",
    RCAIP_RUN_ID
)

print(
    "Selected Cell 26 qualification class:",
    RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_CLASS
)

print(
    "Selected cohort assets:",
    cohort_rows
)

print(
    "Source-family reconciliation:",
    source_family_reconciliation,
    "/",
    cohort_rows
)

print(
    "Intune-only assets:",
    intune_only_count
)

print(
    "Intune-only assets missing INTUNE_NORM context:",
    missing_intune_norm_context
)

print(
    "Intune platform reconciliation:",
    intune_platform_reconciliation,
    "/",
    intune_only_count
)

print(
    "Intune-only mobile-platform assets:",
    mobile_intune_only_count
)

print(
    "Intune-only Windows assets:",
    windows_intune_only_count
)

print(
    "Intune-only macOS assets:",
    macos_intune_only_count
)

print(
    "Intune-only Linux assets:",
    linux_intune_only_count
)

print(
    "Intune-only unknown/other-platform assets:",
    unknown_other_intune_count
)

print(
    "Intune-only assets with existing Asset Plane MDE context:",
    existing_mde_context_count
)

print(
    "Intune-only assets already covered by prior MDE rediscovery:",
    prior_mde_rediscovery_count
)

print(
    "Compute-platform assets eligible for governed MDE-history design:",
    governed_mde_lookback_candidate_count
)

print(
    "Mobile-platform assets requiring applicability/policy qualification first:",
    mobile_applicability_first_count
)

print(
    "New MDE history search performed:",
    "NO"
)

print(
    "Raw Intune source scanned:",
    "NO"
)

print(
    "Raw MDE source scanned:",
    "NO"
)

print(
    "Asset Plane or identity mutated:",
    "NO"
)

print(
    "Delta writes:",
    0
)

print(
    "Readiness:",
    readiness
)


if certification_failures:

    print()
    print("Certification failures:")

    for failure in certification_failures:
        print(
            " -",
            failure
        )

else:

    print()

    print(
        "Next gate: use the observed Intune platform distribution to decide "
        "whether MDE history reconciliation is analytically appropriate. "
        "Do not infer MDE applicability from Intune enrollment alone."
    )


print("=" * 120)


if certification_failures:

    raise RuntimeError(
        "Cell 27 certification failed: "
        + " || ".join(
            certification_failures
        )
    )


# ---------------------------------------------------------------------------
# 15. Publish state for next gate
# ---------------------------------------------------------------------------

RCAIP_DIAG001_CELL27_READY = True

RCAIP_DIAG001_LARGEST_ATTRIBUTION_SOURCE_FAMILY_DF = (
    source_family_df
)

RCAIP_DIAG001_INTUNE_ONLY_DF = (
    intune_only_df
)

RCAIP_DIAG001_INTUNE_PLATFORM_PROFILE_DF = (
    intune_platform_profile_df
)

RCAIP_DIAG001_INTUNE_MDE_CONTEXT_PROFILE_DF = (
    intune_mde_context_profile_df
)

RCAIP_DIAG001_INTUNE_MDE_LOOKBACK_READINESS_DF = (
    mde_lookback_readiness_df
)


# ---------------------------------------------------------------------------
# 16. Release temporary cache
# ---------------------------------------------------------------------------

cohort_df.unpersist(
    blocking=False
)

intune_norm_df.unpersist(
    blocking=False
)

intune_only_base_df.unpersist(
    blocking=False
)

# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 28 - Intune Source Platform / Identity Recovery
# Version: 1.1 - DATETIME SAFE
#
# Purpose:
#   Recover source-native platform and identity context for the Intune-only
#   attribution population after Cell 27 demonstrated that
#   INTUNE_NORM.intune_operating_system is null for the population.
#
# Known source-contract issue under test:
#
#   Raw Intune:
#       properties_OS
#
#   Existing normalizer:
#       maps properties_DeviceOperatingSystem
#       but does not explicitly map properties_OS
#
# Method:
#   - exact Cell 27 Intune-only population
#   - exact source-native serial matching
#   - one bounded Intune source access
#   - one latest source record per serial
#   - tolerant timestamp conversion using try_cast()
#
# READ ONLY.
# No MDE source access.
# No Asset Plane / identity mutation.
# No Delta writes.
#
# Would this exact analytical logic run for Paris?
#   YES.
# ============================================================================

from pyspark.sql import functions as F
from pyspark.sql.window import Window
import re


# ---------------------------------------------------------------------------
# 1. Runtime / Cell 27 contract
# ---------------------------------------------------------------------------

required_objects = [
    "RCAIP_CONFIG_000_READY",
    "RCAIP_POST_NAME",
    "RCAIP_POST_SLUG",
    "RCAIP_RUN_ID",
    "get_rcaip_table",
    "RCAIP_DIAG001_CELL27_READY",
    "RCAIP_DIAG001_INTUNE_ONLY_DF",
]

missing_objects = [
    name
    for name in required_objects
    if name not in globals()
]

if missing_objects:
    raise RuntimeError(
        "Cell 28 missing required objects: "
        + " | ".join(missing_objects)
    )

if not RCAIP_CONFIG_000_READY:
    raise RuntimeError(
        "Config 000 runtime is not ready."
    )

if not RCAIP_DIAG001_CELL27_READY:
    raise RuntimeError(
        "Cell 27 did not publish a ready state."
    )


# ---------------------------------------------------------------------------
# 2. Bind exact Intune-only population
# ---------------------------------------------------------------------------

candidate_df = (
    RCAIP_DIAG001_INTUNE_ONLY_DF

    .select(
        "asset_key",
        "intune_device_name",
        "intune_serial_number",
        "intune_user_name",
        "intune_last_contact",
        "intune_operating_system",
        "intune_os_version",
        "intune_age_days",
        "existing_mde_context_class",
    )

    .cache()
)

candidate_count = candidate_df.count()

candidate_distinct_assets = (
    candidate_df
    .select("asset_key")
    .distinct()
    .count()
)

if candidate_count != candidate_distinct_assets:
    raise RuntimeError(
        "Cell 27 Intune-only population is not one row per asset_key."
    )

candidate_without_serial = (
    candidate_df

    .filter(
        F.col("intune_serial_number").isNull()
        |
        (
            F.length(
                F.trim(
                    F.col("intune_serial_number")
                )
            )
            == 0
        )
    )

    .count()
)

if candidate_without_serial != 0:
    raise RuntimeError(
        "Cell 28 requires retained Intune serial evidence for every candidate. "
        "Missing serial assets: "
        + str(candidate_without_serial)
    )


candidate_serial_df = (
    candidate_df

    .select(
        "asset_key",

        F.trim(
            F.col("intune_serial_number")
        ).alias(
            "candidate_serial"
        ),
    )

    .withColumn(
        "candidate_serial_norm",

        F.upper(
            F.col("candidate_serial")
        )
    )

    .cache()
)


distinct_candidate_serial_count = (
    candidate_serial_df
    .select("candidate_serial_norm")
    .distinct()
    .count()
)


shared_candidate_serial_groups = (
    candidate_serial_df

    .groupBy("candidate_serial_norm")

    .agg(
        F.countDistinct("asset_key").alias(
            "asset_count"
        )
    )

    .filter(
        F.col("asset_count") > 1
    )

    .count()
)


# ---------------------------------------------------------------------------
# 3. Resolve governed Intune source lineage
# ---------------------------------------------------------------------------

INTUNE_NORM_TABLE = get_rcaip_table(
    "INTUNE_NORM"
)

if not spark.catalog.tableExists(
    INTUNE_NORM_TABLE
):
    raise RuntimeError(
        "INTUNE_NORM unavailable: "
        + INTUNE_NORM_TABLE
    )


intune_norm_source_df = (
    spark.table(INTUNE_NORM_TABLE)

    .filter(
        F.lower(
            F.trim(
                F.col("post_slug")
            )
        )
        ==
        F.lit(
            str(RCAIP_POST_SLUG)
            .strip()
            .lower()
        )
    )

    .filter(
        F.col("rcaip_run_id")
        ==
        F.lit(RCAIP_RUN_ID)
    )
)


if "raw_source_table" not in intune_norm_source_df.columns:
    raise RuntimeError(
        "INTUNE_NORM does not preserve raw_source_table provenance."
    )


raw_source_names = [
    row["raw_source_table"]

    for row in (
        intune_norm_source_df

        .filter(
            F.col("raw_source_table").isNotNull()
        )

        .select("raw_source_table")
        .distinct()
        .collect()
    )
]


if len(raw_source_names) != 1:
    raise RuntimeError(
        "Expected exactly one governed Intune raw source for the current run. "
        "Observed: "
        + str(raw_source_names)
    )


INTUNE_RAW_TABLE = raw_source_names[0]


if not spark.catalog.tableExists(
    INTUNE_RAW_TABLE
):
    raise RuntimeError(
        "Governed Intune raw source unavailable: "
        + INTUNE_RAW_TABLE
    )


raw_df = spark.table(
    INTUNE_RAW_TABLE
)


# ---------------------------------------------------------------------------
# 4. Resolve source fields from schema
# ---------------------------------------------------------------------------

def normalized_column_token(name):

    return re.sub(
        r"[^a-z0-9]+",
        "_",
        str(name).strip().lower()
    ).strip("_")


raw_column_lookup = {
    normalized_column_token(column_name):
        column_name

    for column_name in raw_df.columns
}


def resolve_raw_column(
    *candidate_names
):

    for candidate_name in candidate_names:

        matched = raw_column_lookup.get(
            normalized_column_token(
                candidate_name
            )
        )

        if matched is not None:
            return matched

    return None


RAW_SERIAL = resolve_raw_column(
    "properties_SerialNumber",
    "records_properties_SerialNumber",
    "serial_number",
    "serialnumber",
)

RAW_DEVICE_NAME = resolve_raw_column(
    "properties_DeviceName",
    "properties_ManagedDeviceName",
    "records_properties_DeviceName",
    "records_properties_ManagedDeviceName",
)

RAW_DEVICE_ID = resolve_raw_column(
    "properties_DeviceId",
    "records_properties_DeviceId",
)

RAW_AAD_DEVICE_ID = resolve_raw_column(
    "properties_AADDeviceId",
    "records_properties_AADDeviceId",
)

RAW_INTUNE_DEVICE_ID = resolve_raw_column(
    "properties_IntuneDeviceId",
    "records_properties_IntuneDeviceId",
)

RAW_OS = resolve_raw_column(
    "properties_OS",
    "records_properties_OS",
)

RAW_DEVICE_OPERATING_SYSTEM = resolve_raw_column(
    "properties_DeviceOperatingSystem",
    "records_properties_DeviceOperatingSystem",
)

RAW_OS_VERSION = resolve_raw_column(
    "properties_OSVersion",
    "records_properties_OSVersion",
)

RAW_DEVICE_TYPE = resolve_raw_column(
    "properties_DeviceType",
    "records_properties_DeviceType",
)

RAW_MANUFACTURER = resolve_raw_column(
    "properties_Manufacturer",
    "records_properties_Manufacturer",
)

RAW_MODEL = resolve_raw_column(
    "properties_Model",
    "records_properties_Model",
)

RAW_LAST_CONTACT = resolve_raw_column(
    "properties_LastContact",
    "records_properties_LastContact",
)

RAW_CATEGORY = resolve_raw_column(
    "category"
)

RAW_OPERATION_NAME = resolve_raw_column(
    "operationName",
    "operation_name",
)

RAW_EVENT_TIME = resolve_raw_column(
    "_event_time",
    "event_time",
)

RAW_INGEST_TIME = resolve_raw_column(
    "_ingest_time",
    "ingest_time",
)


if RAW_SERIAL is None:
    raise RuntimeError(
        "Could not resolve a source-native Intune serial-number field."
    )

if RAW_OS is None:
    raise RuntimeError(
        "Governed Intune source does not expose properties_OS or an approved "
        "equivalent. Platform recovery cannot proceed."
    )


# ---------------------------------------------------------------------------
# 5. Source contract display
# ---------------------------------------------------------------------------

source_field_rows = [
    ("SERIAL_NUMBER", RAW_SERIAL),
    ("DEVICE_NAME", RAW_DEVICE_NAME),
    ("DEVICE_ID", RAW_DEVICE_ID),
    ("AAD_DEVICE_ID", RAW_AAD_DEVICE_ID),
    ("INTUNE_DEVICE_ID", RAW_INTUNE_DEVICE_ID),
    ("OS", RAW_OS),
    ("DEVICE_OPERATING_SYSTEM", RAW_DEVICE_OPERATING_SYSTEM),
    ("OS_VERSION", RAW_OS_VERSION),
    ("DEVICE_TYPE", RAW_DEVICE_TYPE),
    ("MANUFACTURER", RAW_MANUFACTURER),
    ("MODEL", RAW_MODEL),
    ("LAST_CONTACT", RAW_LAST_CONTACT),
    ("EVENT_TIME", RAW_EVENT_TIME),
    ("INGEST_TIME", RAW_INGEST_TIME),
]

source_field_df = spark.createDataFrame(
    source_field_rows,
    [
        "semantic_role",
        "raw_column",
    ]
)

print("=" * 120)
print("INTUNE SOURCE PLATFORM / IDENTITY FIELD CONTRACT")
print("=" * 120)

display(
    source_field_df
)


# ---------------------------------------------------------------------------
# 6. Candidate serial set
# ---------------------------------------------------------------------------

candidate_serial_values = [
    row["candidate_serial"]

    for row in (
        candidate_serial_df

        .select("candidate_serial")
        .distinct()
        .collect()
    )
]

if not candidate_serial_values:
    raise RuntimeError(
        "Cell 28 resolved zero candidate serial values."
    )


# ---------------------------------------------------------------------------
# 7. Safe source expressions
#
# IMPORTANT:
#   try_cast protects this diagnostic from source datetime values that Spark
#   cannot parse under ANSI mode.
# ---------------------------------------------------------------------------

def escaped_column_name(
    column_name
):

    return str(
        column_name
    ).replace(
        "`",
        "``"
    )


def raw_col(
    column_name
):

    return F.col(
        f"`{escaped_column_name(column_name)}`"
    )


def raw_text(
    column_name
):

    if column_name is None:
        return F.lit(None).cast("string")

    value = raw_col(
        column_name
    ).cast("string")

    return (
        F.when(
            F.length(
                F.trim(value)
            )
            > 0,

            F.trim(value)
        )

        .otherwise(
            F.lit(None).cast("string")
        )
    )


def raw_timestamp_safe(
    column_name
):

    if column_name is None:
        return F.lit(None).cast("timestamp")

    escaped_name = escaped_column_name(
        column_name
    )

    return F.expr(
        f"try_cast(`{escaped_name}` AS TIMESTAMP)"
    )


# ---------------------------------------------------------------------------
# 8. One bounded Intune source access
# ---------------------------------------------------------------------------

bounded_raw_df = (
    raw_df

    .filter(
        raw_col(
            RAW_SERIAL
        )
        .cast("string")
        .isin(
            candidate_serial_values
        )
    )
)


# Preserve known Devices collection semantics where those fields exist.

if RAW_CATEGORY is not None:

    bounded_raw_df = (
        bounded_raw_df

        .filter(
            F.upper(
                F.trim(
                    raw_col(
                        RAW_CATEGORY
                    ).cast("string")
                )
            )
            ==
            F.lit("DEVICES")
        )
    )


if RAW_OPERATION_NAME is not None:

    bounded_raw_df = (
        bounded_raw_df

        .filter(
            F.upper(
                F.trim(
                    raw_col(
                        RAW_OPERATION_NAME
                    ).cast("string")
                )
            )
            ==
            F.lit("DEVICES")
        )
    )


bounded_projection_df = (
    bounded_raw_df

    .select(
        raw_text(
            RAW_SERIAL
        ).alias(
            "raw_serial"
        ),

        raw_text(
            RAW_DEVICE_NAME
        ).alias(
            "raw_device_name"
        ),

        raw_text(
            RAW_DEVICE_ID
        ).alias(
            "raw_device_id"
        ),

        raw_text(
            RAW_AAD_DEVICE_ID
        ).alias(
            "raw_aad_device_id"
        ),

        raw_text(
            RAW_INTUNE_DEVICE_ID
        ).alias(
            "raw_intune_device_id"
        ),

        raw_text(
            RAW_OS
        ).alias(
            "raw_os"
        ),

        raw_text(
            RAW_DEVICE_OPERATING_SYSTEM
        ).alias(
            "raw_device_operating_system"
        ),

        raw_text(
            RAW_OS_VERSION
        ).alias(
            "raw_os_version"
        ),

        raw_text(
            RAW_DEVICE_TYPE
        ).alias(
            "raw_device_type"
        ),

        raw_text(
            RAW_MANUFACTURER
        ).alias(
            "raw_manufacturer"
        ),

        raw_text(
            RAW_MODEL
        ).alias(
            "raw_model"
        ),

        raw_timestamp_safe(
            RAW_LAST_CONTACT
        ).alias(
            "raw_last_contact"
        ),

        raw_timestamp_safe(
            RAW_EVENT_TIME
        ).alias(
            "raw_event_time"
        ),

        raw_timestamp_safe(
            RAW_INGEST_TIME
        ).alias(
            "raw_ingest_time"
        ),
    )

    .withColumn(
        "raw_serial_norm",

        F.upper(
            F.trim(
                F.col("raw_serial")
            )
        )
    )

    .cache()
)


bounded_source_row_count = (
    bounded_projection_df.count()
)


# ---------------------------------------------------------------------------
# 9. Latest source record per serial
# ---------------------------------------------------------------------------

latest_window = (
    Window

    .partitionBy(
        "raw_serial_norm"
    )

    .orderBy(
        F.col(
            "raw_last_contact"
        ).desc_nulls_last(),

        F.col(
            "raw_event_time"
        ).desc_nulls_last(),

        F.col(
            "raw_ingest_time"
        ).desc_nulls_last(),
    )
)


latest_raw_df = (
    bounded_projection_df

    .filter(
        F.col(
            "raw_serial_norm"
        ).isNotNull()
    )

    .withColumn(
        "_latest_rank",

        F.row_number().over(
            latest_window
        )
    )

    .filter(
        F.col("_latest_rank") == 1
    )

    .drop(
        "_latest_rank"
    )

    .withColumn(
        "_raw_intune_match",
        F.lit(True)
    )

    .cache()
)


latest_raw_serial_count = (
    latest_raw_df.count()
)


# ---------------------------------------------------------------------------
# 10. Attach recovered source context to candidate assets
# ---------------------------------------------------------------------------

recovered_df = (
    candidate_df

    .withColumn(
        "candidate_serial_norm",

        F.upper(
            F.trim(
                F.col(
                    "intune_serial_number"
                )
            )
        )
    )

    .join(
        latest_raw_df,

        F.col(
            "candidate_serial_norm"
        )
        ==
        F.col(
            "raw_serial_norm"
        ),

        how="left",
    )

    .withColumn(
        "_raw_intune_match",

        F.coalesce(
            F.col(
                "_raw_intune_match"
            ),
            F.lit(False)
        )
    )

    .withColumn(
        "_raw_os_upper",

        F.upper(
            F.trim(
                F.coalesce(
                    F.col("raw_os"),
                    F.lit("")
                )
            )
        )
    )

    .withColumn(
        "recovered_platform_family",

        F.when(
            F.col("_raw_os_upper").contains(
                "WINDOWS"
            ),
            F.lit("WINDOWS")
        )

        .when(
            F.col("_raw_os_upper").rlike(
                r"(^|[^A-Z])(IOS|IPADOS)([^A-Z]|$)"
            )
            |
            F.col("_raw_os_upper").rlike(
                r"IPHONE|IPAD"
            ),
            F.lit("IOS_IPADOS")
        )

        .when(
            F.col("_raw_os_upper").rlike(
                r"MACOS|MAC OS|OS X|DARWIN"
            ),
            F.lit("MACOS")
        )

        .when(
            F.col("_raw_os_upper").contains(
                "ANDROID"
            ),
            F.lit("ANDROID")
        )

        .when(
            F.col("_raw_os_upper").contains(
                "LINUX"
            ),
            F.lit("LINUX")
        )

        .when(
            F.length(
                F.col("_raw_os_upper")
            )
            == 0,
            F.lit("UNKNOWN")
        )

        .otherwise(
            F.concat(
                F.lit("OTHER::"),
                F.col("_raw_os_upper")
            )
        )
    )

    .withColumn(
        "source_native_identity_strength",

        F.when(
            (
                F.col("raw_aad_device_id").isNotNull()
                |
                F.col("raw_intune_device_id").isNotNull()
                |
                F.col("raw_device_id").isNotNull()
            )
            &
            F.col("intune_serial_number").isNotNull(),

            F.lit(
                "DURABLE_ID_PLUS_SERIAL"
            )
        )

        .when(
            F.col("intune_serial_number").isNotNull(),

            F.lit(
                "SERIAL_ONLY_DURABLE"
            )
        )

        .otherwise(
            F.lit(
                "WEAK_IDENTITY"
            )
        )
    )

    .cache()
)


recovered_asset_count = (
    recovered_df.count()
)


raw_match_asset_count = (
    recovered_df

    .filter(
        F.col("_raw_intune_match")
    )

    .count()
)


# ---------------------------------------------------------------------------
# 11. Recovered platform profile
# ---------------------------------------------------------------------------

platform_profile_df = (
    recovered_df

    .groupBy(
        "recovered_platform_family",
        "raw_os",
        "raw_device_type",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.countDistinct(
            "raw_manufacturer"
        ).alias(
            "manufacturer_count"
        ),

        F.countDistinct(
            "raw_model"
        ).alias(
            "model_count"
        ),

        F.min(
            "intune_age_days"
        ).alias(
            "minimum_intune_age_days"
        ),

        F.max(
            "intune_age_days"
        ).alias(
            "maximum_intune_age_days"
        ),
    )

    .orderBy(
        F.desc("asset_count"),
        "recovered_platform_family",
        "raw_os",
    )
)


print()
