# ---------------------------------------------------------------------------
# 13. Source-native identity profile
# ---------------------------------------------------------------------------

identity_profile_df = (
    recovered_df

    .groupBy(
        "recovered_platform_family",
        "source_native_identity_strength",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.sum(
            F.when(
                F.col("raw_device_id").isNotNull(),
                1
            ).otherwise(0)
        ).alias(
            "device_id_assets"
        ),

        F.sum(
            F.when(
                F.col("raw_aad_device_id").isNotNull(),
                1
            ).otherwise(0)
        ).alias(
            "aad_device_id_assets"
        ),

        F.sum(
            F.when(
                F.col("raw_intune_device_id").isNotNull(),
                1
            ).otherwise(0)
        ).alias(
            "intune_device_id_assets"
        ),

        F.sum(
            F.when(
                F.col("intune_serial_number").isNotNull(),
                1
            ).otherwise(0)
        ).alias(
            "serial_assets"
        ),

        F.sum(
            F.when(
                F.col("intune_device_name").isNotNull(),
                1
            ).otherwise(0)
        ).alias(
            "name_assets"
        ),
    )

    .orderBy(
        F.desc("asset_count")
    )
)


print()
print("=" * 120)
print("INTUNE-ONLY POPULATION - SOURCE-NATIVE IDENTITY EVIDENCE")
print("NO MDE MATCHING PERFORMED")
