# COMMAND ----------

# ============================================================================
# RCAIP DIAG 001 - ASSET VISIBILITY FUNNEL
# Cell 30 - Cross-Platform MDE History Execution Preflight
# Version: 1.0
#
# Purpose:
#   Determine whether the Intune-only identities qualified in Cell 29 can be
#   safely reconciled against enterprise-global MDE history.
#
# Enterprise control expectation supplied for this diagnostic:
#   Managed Windows and iOS/iPadOS devices are expected to have MDE.
#
# IMPORTANT:
#   This expectation is enterprise policy/applicability context.
#   It is NOT Post-specific logic.
#
# Candidate population:
#   - Windows historical-MDE candidates from Cell 29
#   - iOS/iPadOS managed identities from Cell 29
#
# Excluded:
#   - identities already carrying prior RCAIP MDE rediscovery evidence
#   - shared-serial/source-identity conditions requiring identity review first
#
# This cell:
#   1. certifies the exact candidate population;
#   2. inventories usable Intune identity evidence;
#   3. resolves the governed enterprise MDE source from MDE_NORM lineage;
#   4. inspects MDE source schema only;
#   5. inventories candidate durable identity/name/time fields;
#   6. inspects table metadata/layout without scanning source rows;
#   7. searches the RCAIP registry for existing compact MDE identity/index
#      products;
#   8. decides whether a safe historical-search path exists.
#
# It does NOT:
#   - search raw MDE rows
#   - perform historical matching
#   - equate Intune DeviceId with MDE DeviceId
#   - merge identities
#   - change Asset Plane keys
#   - write Delta tables
#
# Would this exact analytical logic run for Paris?
#   YES.
# ============================================================================

from pyspark.sql import functions as F
from pyspark.sql import types as T
import re


# ---------------------------------------------------------------------------
# 1. Runtime / Cell 29 validation
# ---------------------------------------------------------------------------

required_objects = [
    "RCAIP_CONFIG_000_READY",
    "RCAIP_POST_NAME",
    "RCAIP_POST_SLUG",
    "RCAIP_RUN_ID",
    "RCAIP_TABLES",
    "get_rcaip_table",
    "RCAIP_DIAG001_CELL29_READY",
    "RCAIP_DIAG001_INTUNE_PLATFORM_QUALIFIED_DF",
]


missing_objects = [
    name
    for name in required_objects
    if name not in globals()
]


if missing_objects:
    raise RuntimeError(
        "Cell 30 missing required runtime / Cell 29 objects: "
        + " | ".join(missing_objects)
    )


if not RCAIP_CONFIG_000_READY:
    raise RuntimeError(
        "Config 000 runtime is not ready."
    )


if not RCAIP_DIAG001_CELL29_READY:
    raise RuntimeError(
        "Cell 29 did not publish a ready state."
    )


# ---------------------------------------------------------------------------
# 2. Enterprise MDE applicability expectation
#
# Diagnostic policy input:
#   Managed Windows and iOS/iPadOS devices are expected to have MDE.
#
# This must eventually live in a governed applicability / knowledge-base
# contract rather than being embedded in downstream analytical logic.
# ---------------------------------------------------------------------------

MDE_EXPECTED_PLATFORM_FAMILIES = [
    "WINDOWS",
    "IOS_IPADOS",
]


# ---------------------------------------------------------------------------
# 3. Bind exact Cell 29 qualified population
# ---------------------------------------------------------------------------

cell29_df = (
    RCAIP_DIAG001_INTUNE_PLATFORM_QUALIFIED_DF
    .cache()
)


cell29_rows = cell29_df.count()


cell29_distinct_assets = (
    cell29_df
    .select("asset_key")
    .distinct()
    .count()
)


if cell29_rows != cell29_distinct_assets:
    raise RuntimeError(
        "Cell 29 population is not one row per asset_key."
    )


# ---------------------------------------------------------------------------
# 4. Build MDE-history candidate population
#
# Include:
#   - Windows historical candidates
#   - iOS/iPadOS managed devices
#
# Exclude:
#   - prior MDE rediscovery context
#   - shared serial identity review
# ---------------------------------------------------------------------------

mde_history_candidate_df = (
    cell29_df

    .filter(
        F.col(
            "recovered_platform_family"
        ).isin(
            MDE_EXPECTED_PLATFORM_FAMILIES
        )
    )

    .filter(
        ~F.col(
            "has_existing_mde_context"
        )
    )

    .filter(
        F.col(
            "serial_identity_state"
        )
        ==
        F.lit(
            "UNIQUE_SERIAL"
        )
    )

    .select(
        "asset_key",

        "recovered_platform_family",

        "raw_device_id",
        "raw_device_name",
        "raw_serial",

        "raw_os",
        "raw_os_version",

        "raw_manufacturer",
        "raw_model",

        "intune_user_name",
        "intune_last_contact",
        "intune_age_days",

        "source_native_identity_strength",

        "existing_mde_context_class",
    )

    .cache()
)


candidate_rows = (
    mde_history_candidate_df.count()
)


candidate_distinct_assets = (
    mde_history_candidate_df
    .select("asset_key")
    .distinct()
    .count()
)


# ---------------------------------------------------------------------------
# 5. Candidate platform accounting
# ---------------------------------------------------------------------------

candidate_platform_summary_df = (
    mde_history_candidate_df

    .groupBy(
        "recovered_platform_family",
        "raw_manufacturer",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.countDistinct(
            "raw_device_id"
        ).alias(
            "source_device_ids"
        ),

        F.countDistinct(
            "raw_serial"
        ).alias(
            "serials"
        ),

        F.countDistinct(
            "raw_device_name"
        ).alias(
            "device_names"
        ),

        F.min(
            "intune_age_days"
        ).alias(
            "minimum_intune_age_days"
        ),

        F.max(
            "intune_age_days"
        ).alias(
            "maximum_intune_age_days"
        ),
    )

    .orderBy(
        F.desc("asset_count"),
        "recovered_platform_family",
        "raw_manufacturer",
    )
)


print("=" * 120)
print("INTUNE -> MDE HISTORY CANDIDATE POPULATION")
print("WINDOWS + IOS/IPADOS UNDER CURRENT ENTERPRISE CONTROL EXPECTATION")
print("=" * 120)

display(
    candidate_platform_summary_df
)


# ---------------------------------------------------------------------------
# 6. Candidate identity quality
#
# Source-native Intune DeviceId is preserved as strong SOURCE-LOCAL evidence.
# It is NOT assumed to share a namespace with MDE DeviceId.
# ---------------------------------------------------------------------------

mde_history_candidate_df = (
    mde_history_candidate_df

    .withColumn(
        "intune_device_id_present",
        F.col(
            "raw_device_id"
        ).isNotNull()
    )

    .withColumn(
        "serial_present",
        F.col(
            "raw_serial"
        ).isNotNull()
    )

    .withColumn(
        "device_name_present",
        F.col(
            "raw_device_name"
        ).isNotNull()
    )

    .withColumn(
        "identity_bundle_class",

        F.when(
            F.col("intune_device_id_present")
            &
            F.col("serial_present")
            &
            F.col("device_name_present"),

            F.lit(
                "INTUNE_DEVICE_ID_PLUS_SERIAL_PLUS_NAME"
            )
        )

        .when(
            F.col("serial_present")
            &
            F.col("device_name_present"),

            F.lit(
                "SERIAL_PLUS_NAME"
            )
        )

        .when(
            F.col("device_name_present"),

            F.lit(
                "NAME_ONLY"
            )
        )

        .otherwise(
            F.lit(
                "INSUFFICIENT_IDENTITY"
            )
        )
    )

    .cache()
)


candidate_identity_summary_df = (
    mde_history_candidate_df

    .groupBy(
        "recovered_platform_family",
        "identity_bundle_class",
    )

    .agg(
        F.countDistinct(
            "asset_key"
        ).alias(
            "asset_count"
        ),

        F.countDistinct(
            "raw_device_id"
        ).alias(
            "source_device_ids"
        ),

        F.countDistinct(
            "raw_serial"
        ).alias(
            "serials"
        ),

        F.countDistinct(
            "raw_device_name"
        ).alias(
            "device_names"
        ),
    )

    .orderBy(
        F.desc("asset_count"),
        "recovered_platform_family",
    )
)


print()
print("=" * 120)
print("MDE HISTORY CANDIDATES - INTUNE IDENTITY BUNDLE")
print("INTUNE DEVICEID IS SOURCE-LOCAL; NO MDE DEVICEID EQUIVALENCE IS ASSUMED")
print("=" * 120)

display(
    candidate_identity_summary_df
)


# ---------------------------------------------------------------------------
# 7. Resolve current MDE_NORM and governed raw-source lineage
# ---------------------------------------------------------------------------

MDE_NORM_TABLE = get_rcaip_table(
    "MDE_NORM"
)


if not spark.catalog.tableExists(
    MDE_NORM_TABLE
):
    raise RuntimeError(
        "MDE_NORM unavailable: "
        + MDE_NORM_TABLE
    )


mde_norm_df = (
    spark.table(
        MDE_NORM_TABLE
    )

    .filter(
        F.lower(
            F.trim(
                F.col(
                    "post_slug"
                )
            )
        )
        ==
        F.lit(
            str(
                RCAIP_POST_SLUG
            )
            .strip()
            .lower()
        )
    )

    .filter(
        F.col(
            "rcaip_run_id"
        )
        ==
        F.lit(
            RCAIP_RUN_ID
        )
    )

    .cache()
)


if "raw_source_table" not in mde_norm_df.columns:
    raise RuntimeError(
        "MDE_NORM does not expose raw_source_table lineage."
    )


mde_norm_rows = (
    mde_norm_df.count()
)


mde_raw_source_values = [
    row["raw_source_table"]

    for row in (
        mde_norm_df

        .filter(
            F.col(
                "raw_source_table"
            ).isNotNull()
        )

        .select(
            F.trim(
                F.col(
                    "raw_source_table"
                )
            ).alias(
                "raw_source_table"
            )
        )

        .distinct()

        .collect()
    )
]


if len(
    mde_raw_source_values
) != 1:
    raise RuntimeError(
        "Expected exactly one governed raw MDE lineage source for the "
        "current run. Observed: "
        + str(
            mde_raw_source_values
        )
    )


MDE_RAW_TABLE = (
    mde_raw_source_values[0]
)


if not spark.catalog.tableExists(
    MDE_RAW_TABLE
):
    raise RuntimeError(
        "Governed MDE source table unavailable: "
        + MDE_RAW_TABLE
    )


# ---------------------------------------------------------------------------
# 8. MDE raw-source schema inspection ONLY
#
# spark.table(...).schema does not execute a source row scan.
# ---------------------------------------------------------------------------

mde_raw_df = spark.table(
    MDE_RAW_TABLE
)


raw_mde_columns = (
    mde_raw_df.columns
)


def normalize_schema_name(
    column_name
):

    return re.sub(
        r"[^a-z0-9]+",
        "_",
        str(
            column_name
        )
        .strip()
        .lower()
    ).strip(
        "_"
    )


# ---------------------------------------------------------------------------
# 9. Classify MDE source identity / context fields
#
# Structural classification only.
# Field-name similarity does NOT establish cross-source identifier equivalence.
# ---------------------------------------------------------------------------

def classify_mde_column(
    column_name
):

    key = normalize_schema_name(
        column_name
    )


    # Strong / durable identifier candidates.
    if any(
        token in key

        for token in [
            "deviceid",
            "device_id",
            "machineid",
            "machine_id",
            "aaddeviceid",
            "aad_device_id",
            "azureaddeviceid",
            "azure_ad_device_id",
            "hostid",
            "host_id",
            "hardwareuuid",
            "hardware_uuid",
            "uuid",
            "guid",
            "serialnumber",
            "serial_number",
        ]
    ):
        return (
            "TIER_1_DURABLE_IDENTIFIER_CANDIDATE"
        )


    # Device / host name candidates.
    if any(
        token in key

        for token in [
            "devicename",
            "device_name",
            "hostname",
            "host_name",
            "computer_dns_name",
            "computerdnsname",
            "machinefqdn",
            "machine_fqdn",
            "fqdn",
        ]
    ):
        return (
            "TIER_2_MACHINE_NAME_CANDIDATE"
        )


    # Time context.
    if any(
        token in key

        for token in [
            "timestamp",
            "lastseen",
            "last_seen",
            "firstseen",
            "first_seen",
            "eventtime",
            "event_time",
            "ingest",
        ]
    ):
        return (
            "TEMPORAL_CONTEXT"
        )


    # Platform context.
    if any(
        token in key

        for token in [
            "operatingsystem",
            "operating_system",
            "osplatform",
            "os_platform",
            "osversion",
            "os_version",
            "devicecategory",
            "device_category",
            "devicetype",
            "device_type",
        ]
    ):
        return (
            "PLATFORM_CONTEXT"
        )


    # Attribution / management context.
    if any(
        token in key

        for token in [
            "machinegroup",
            "machine_group",
            "site",
            "location",
            "dynamic_tag",
            "dynamictag",
            "manual_tag",
            "manualtag",
            "onboarding",
            "sensorhealth",
            "sensor_health",
        ]
    ):
        return (
            "ATTRIBUTION_OR_CONTROL_CONTEXT"
        )


    return None


mde_field_rows = []


for field in mde_raw_df.schema.fields:

    classification = classify_mde_column(
        field.name
    )


    if classification is not None:

        mde_field_rows.append(
            (
                field.name,
                normalize_schema_name(
                    field.name
                ),
                field.dataType.simpleString(),
                classification,
            )
        )


mde_field_schema = T.StructType([
    T.StructField(
        "source_column",
        T.StringType(),
        False,
    ),

    T.StructField(
        "normalized_column",
        T.StringType(),
        False,
    ),

    T.StructField(
        "data_type",
        T.StringType(),
        False,
    ),

    T.StructField(
        "field_class",
        T.StringType(),
        False,
    ),
])


mde_source_field_profile_df = (
    spark.createDataFrame(
        mde_field_rows,
        schema=mde_field_schema,
    )

    .orderBy(
        "field_class",
        "source_column",
    )
)


print()
