# COMMAND ----------
# ============================================================================
# RCAIP DIAG 001
# Cell 31 - Attribution Cohort Resume After Intune Subbranch Qualification
#
# Purpose:
#   Preserve the certified parent cohort and Intune qualification.
#   Carry the certified Cell 30 history candidates as an unresolved overlay.
#   Resume the parent and select the largest remaining source-family cohort.
#
# Prior READY flags and published DataFrames are the governed handoff.
# This cell checks conservation; it does not repeat prior transformations.
#
# Live Databricks restoration remains a production-execution prerequisite.
# It is not an additional analytical gate implemented by this cell.
#
# No explicit source acquisition, MDE search, Delta writes, identity merging,
# Asset Plane mutation, customer routing, case formation, findings, tickets,
# or remediation.
#
# Would this exact analytical logic run for Paris?
# YES. Cohort metadata, populations, and selection come from runtime evidence.
# No recorded Post-specific result is an algorithmic acceptance constant.
#
# This advances the existing attribution/accounting delivery work.
# It creates no additional delivery gate.
# ============================================================================

from pyspark.sql import DataFrame
from pyspark.sql import functions as F


# Invalidate only Cell 31 publications before attempting a new handoff.
# A failed rerun must not expose stale successful Cell 31 outputs.
for _c31_name in tuple(globals()):
    if _c31_name.startswith("RCAIP_DIAG001_CELL31_"):
        del globals()[_c31_name]
del _c31_name

RCAIP_DIAG001_CELL31_READY = False


def _build_cell31():
    def require(condition, message):
        if not condition:
            raise RuntimeError("Cell 31 certification failed: " + message)

    frame_names = {
        "parent": "RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_DF",
        "summary": "RCAIP_DIAG001_ATTRIBUTION_COHORT_SUMMARY_DF",
        "families": "RCAIP_DIAG001_LARGEST_ATTRIBUTION_SOURCE_FAMILY_DF",
        "intune": "RCAIP_DIAG001_INTUNE_ONLY_DF",
        "qualified": "RCAIP_DIAG001_INTUNE_PLATFORM_QUALIFIED_DF",
        "windows": "RCAIP_DIAG001_WINDOWS_MDE_HISTORY_CANDIDATE_DF",
        "shared": "RCAIP_DIAG001_INTUNE_SHARED_SERIAL_REVIEW_DF",
        "mobile": "RCAIP_DIAG001_IOS_MOBILE_CONTEXT_DF",
        "history": "RCAIP_DIAG001_MDE_HISTORY_CANDIDATE_DF",
    }
    ready_names = [
        "RCAIP_CONFIG_000_READY",
        "RCAIP_DIAG001_CELL26_READY",
        "RCAIP_DIAG001_CELL27_READY",
        "RCAIP_DIAG001_CELL28_READY",
        "RCAIP_DIAG001_CELL29_READY",
        "RCAIP_DIAG001_CELL30_READY",
    ]
    scalar_names = [
        "RCAIP_POST_SLUG",
        "RCAIP_RUN_ID",
        "RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_ID",
        "RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_CLASS",
        "RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_GATE",
        "RCAIP_DIAG001_MDE_HISTORY_EXECUTION_READINESS",
    ]

    required = ready_names + scalar_names + list(frame_names.values())
    missing = sorted(name for name in required if name not in globals())
    require(not missing, "Missing objects: " + " | ".join(missing))

    for name in ready_names:
        require(globals()[name] is True, name + " is not True.")

    for name in scalar_names:
        value = globals()[name]
        require(
            isinstance(value, str) and bool(value.strip()),
            name + " must be a nonblank string.",
        )

    frames = {key: globals()[name] for key, name in frame_names.items()}
    for key, df in frames.items():
        require(isinstance(df, DataFrame), frame_names[key] + " is not a DataFrame.")
        require(
            len(df.columns) == len(set(df.columns)),
            frame_names[key] + " has duplicate column names.",
        )
        require(
            not any(column.startswith("c31_") for column in df.columns),
            frame_names[key] + " already contains Cell 31 annotations.",
        )

    parent = frames["parent"]
    summary = frames["summary"]
    families = frames["families"]
    intune = frames["intune"]
    qualified = frames["qualified"]
    windows = frames["windows"]
    shared = frames["shared"]
    mobile = frames["mobile"]
    history = frames["history"]

    post_slug = RCAIP_POST_SLUG.strip().lower()
    run_id = RCAIP_RUN_ID
    cohort_id = RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_ID
    cohort_class = RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_CLASS
    cohort_gate = RCAIP_DIAG001_ATTRIBUTION_NEXT_COHORT_GATE
    history_readiness = RCAIP_DIAG001_MDE_HISTORY_EXECUTION_READINESS

    def need(df, columns, label):
        absent = sorted(set(columns) - set(df.columns))
        require(not absent, label + " missing columns: " + " | ".join(absent))

    def reject_rows(df, condition, message):
        require(
            df.filter(F.coalesce(condition, F.lit(True))).limit(1).count() == 0,
            message,
        )

    def asset_count(df, label):
        need(df, ["asset_key"], label)
        metrics = df.agg(
            F.count(F.lit(1)).alias("rows"),
            F.countDistinct("asset_key").alias("assets"),
            F.sum(
                F.when(
                    F.col("asset_key").isNull()
                    | (F.length(F.trim(F.col("asset_key").cast("string"))) == 0),
                    1,
                ).otherwise(0)
            ).alias("invalid_keys"),
        ).first()
        require(
            int(metrics["invalid_keys"] or 0) == 0,
            label + " has null or blank asset keys.",
        )
        require(
            metrics["rows"] == metrics["assets"],
            label + " is not one row per asset_key.",
        )
        return int(metrics["rows"])

    def subset(child, denominator, label):
        require(
            child.select("asset_key").join(
                denominator.select("asset_key"), "asset_key", "left_anti"
            ).limit(1).count() == 0,
            label + " contains assets outside its denominator.",
        )

    def same_members(left, right, label):
        subset(left, right, label)
        subset(right, left, label)

    counts = {
        name: asset_count(df, frame_names[name])
        for name, df in frames.items()
        if name not in {"summary", "shared"}
    }

    # -----------------------------------------------------------------------
    # 1. Preserve Cell 26 runtime cohort authority.
    # -----------------------------------------------------------------------

    need(
        summary,
        [
            "qualification_cohort_id", "qualification_class",
            "qualification_next_gate", "asset_count",
        ],
        "Cell 26 summary",
    )
    need(
        parent,
        [
            "post_slug", "rcaip_run_id",
            "qualification_class", "qualification_next_gate",
        ],
        "Cell 26 parent",
    )

    selected_summary = summary.filter(
        F.col("qualification_cohort_id") == F.lit(cohort_id)
    )
    require(
        selected_summary.count() == 1,
        "Cell 26 cohort ID does not identify exactly one summary record.",
    )
    record = selected_summary.first()
    require(
        record["qualification_class"] == cohort_class
        and record["qualification_next_gate"] == cohort_gate,
        "Cell 26 ID/class/gate scalars disagree with the summary record.",
    )
    require(
        record["asset_count"] == counts["parent"],
        "Parent membership count disagrees with Cell 26 summary authority.",
    )
    reject_rows(
        parent,
        ~F.col("qualification_class").eqNullSafe(F.lit(cohort_class))
        | ~F.col("qualification_next_gate").eqNullSafe(F.lit(cohort_gate)),
        "Parent rows disagree with the selected cohort metadata.",
    )
    reject_rows(
        parent,
        ~F.lower(F.trim(F.col("post_slug"))).eqNullSafe(F.lit(post_slug))
        | ~F.col("rcaip_run_id").eqNullSafe(F.lit(run_id)),
        "Parent accounting scope disagrees with the configured Post/run.",
    )

    # -----------------------------------------------------------------------
    # 2. Consume existing source-family membership without reconstructing it.
    # -----------------------------------------------------------------------

    need(families, ["source_family", "source_mask_active"], "Cell 27 families")
    reject_rows(
        families,
        F.col("source_family").isNull()
        | (F.length(F.trim(F.col("source_family"))) == 0),
        "A parent asset lacks an existing source-family classification.",
    )
    same_members(families, parent, "Cell 27 / Cell 26 membership")
    require(
        counts["families"] == counts["parent"],
        "Source-family membership does not preserve the parent count.",
    )

    intune_family = families.filter(F.col("source_family") == "INTUNE_ONLY")
    same_members(intune, intune_family, "Cell 27 Intune-only membership")
    same_members(qualified, intune, "Cell 29 Intune qualification membership")
    require(
        counts["qualified"] == counts["intune"],
        "Qualified Intune count differs from the existing Intune denominator.",
    )

    # -----------------------------------------------------------------------
    # 3. Account for published Cell 29 qualifications.
    #
    # Class labels are consumed as certified dispositions. No platform,
    # serial-profile, or qualification-generation logic is repeated.
    # -----------------------------------------------------------------------

    need(
        qualified,
        ["qualification_class", "has_existing_mde_context"],
        "Cell 29 qualified population",
    )
    reject_rows(
        qualified,
        F.col("qualification_class").isNull()
        | (F.length(F.trim(F.col("qualification_class"))) == 0),
        "An Intune asset has no published exclusive qualification.",
    )

    mobile_class = "INTUNE_IOS_IPADOS_MANAGED_MOBILE_CONTEXT"
    windows_class = "WINDOWS_HISTORICAL_MDE_RECONCILIATION_CANDIDATE"
    existing_class = "WINDOWS_EXISTING_MDE_CONTEXT"
    shared_class = "INTUNE_SHARED_SERIAL_IDENTITY_REVIEW"

    same_members(
        mobile,
        qualified.filter(F.col("qualification_class") == mobile_class),
        "Published managed-mobile disposition membership",
    )
    same_members(
        windows,
        qualified.filter(F.col("qualification_class") == windows_class),
        "Published Windows-history disposition membership",
    )

    # The shared-serial handoff remains group-grain. Expand only its published
    # membership array for asset conservation; do not rebuild serial semantics.
    need(shared, ["asset_keys", "asset_count"], "Cell 29 shared-serial groups")
    reject_rows(
        shared,
        F.col("asset_keys").isNull()
        | F.col("asset_count").isNull()
        | (F.size("asset_keys") == 0)
        | (F.size("asset_keys") != F.col("asset_count")),
        "A shared-serial group has incomplete published member accounting.",
    )
    shared_members = shared.select(F.explode("asset_keys").alias("asset_key"))
    shared_member_count = asset_count(shared_members, "Shared-serial members")
    shared_group_count = shared.count()
    same_members(
        shared_members,
        qualified.filter(F.col("qualification_class") == shared_class),
        "Published shared-serial disposition membership",
    )

    qualification_rows = qualified.groupBy("qualification_class").agg(
        F.count(F.lit(1)).alias("asset_count")
    ).orderBy("qualification_class").collect()
    require(
        sum(int(row["asset_count"]) for row in qualification_rows)
        == counts["intune"],
        "Exclusive qualifications do not account for the complete Intune set.",
    )

    # -----------------------------------------------------------------------
    # 4. Preserve Cell 30 candidates as an independent unresolved overlay.
    # -----------------------------------------------------------------------

    subset(history, qualified, "Cell 30 history-candidate membership")

    # Exclusions are checked against published dispositions/flags, not rebuilt
    # from platform or raw-source identity fields.
    protected_members = qualified.filter(
        F.col("has_existing_mde_context")
        | F.col("qualification_class").isin(existing_class, shared_class)
    ).select("asset_key")

    require(
        history.join(protected_members, "asset_key", "inner").limit(1).count() == 0,
        "Existing-MDE or shared-serial dispositions entered the history overlay.",
    )
    require(
        history.join(shared_members, "asset_key", "inner").limit(1).count() == 0,
        "A published shared-serial member entered the history overlay.",
    )
    reject_rows(
        history.select("asset_key").join(
            qualified.select("asset_key", "has_existing_mde_context"),
            "asset_key", "inner",
        ),
        F.col("has_existing_mde_context").isNull(),
        "A history candidate has indeterminate published existing-MDE context.",
    )

    # -----------------------------------------------------------------------
    # 5. Publish additive accounting state. Original columns remain unchanged.
    # -----------------------------------------------------------------------

    history_membership = history.select("asset_key").withColumn(
        "c31_history_candidate", F.lit(True)
    )

    intune_disposition = (
        qualified
        .join(history_membership, "asset_key", "left")
        .withColumn(
            "c31_history_candidate",
            F.coalesce(F.col("c31_history_candidate"), F.lit(False)),
        )
        .withColumn(
            "c31_subbranch_status",
            F.lit("QUALIFICATION_PRESERVED_PARENT_RESUMED"),
        )
        .withColumn(
            "c31_history_dependency",
            F.when(
                F.col("c31_history_candidate"),
                F.lit("UNRESOLVED_ENGINEERING_EVIDENCE_BOUNDARY"),
            ).otherwise(F.lit("OUTSIDE_CELL30_HISTORY_OVERLAY")),
        )
    )

    history_dependency = (
        history
        .withColumn(
            "c31_dependency_state",
            F.lit("UNRESOLVED_ENGINEERING_EVIDENCE_BOUNDARY"),
        )
        .withColumn("c31_original_execution_readiness", F.lit(history_readiness))
        .withColumn("c31_blocks_asset_delivery", F.lit(False))
        .withColumn("c31_blocks_paris", F.lit(False))
        .withColumn("c31_history_search_authorized", F.lit(False))
        .withColumn(
            "c31_interpretation",
            F.lit(
                "Unresolved history evidence is not a Post failure, "
                "RCSO finding, or control-missing determination."
            ),
        )
    )

    # Keep the exact parent fields and attach only Cell 27's family assignment.
    # Any existing parent source_family field must agree with that assignment.
    if "source_family" in parent.columns:
        require(
            parent.select("asset_key", "source_family").exceptAll(
                families.select("asset_key", "source_family")
            ).limit(1).count() == 0,
            "Parent and Cell 27 source-family membership disagree.",
        )
        parent_base = parent
    else:
        parent_base = parent.join(
            families.select("asset_key", "source_family"),
            "asset_key", "inner",
        )

    parent_resume = (
        parent_base
        .join(
            intune_disposition.select(
                "asset_key",
                F.col("qualification_class").alias("c31_intune_qualification_class"),
                "c31_history_candidate",
                "c31_history_dependency",
            ),
            "asset_key", "left",
        )
        .withColumn(
            "c31_history_candidate",
            F.coalesce(F.col("c31_history_candidate"), F.lit(False)),
        )
        .withColumn(
            "c31_resume_state",
            F.when(
                F.col("source_family") == "INTUNE_ONLY",
                F.lit("QUALIFICATION_PRESERVED_PARENT_RESUMED"),
            ).otherwise(F.lit("AWAITING_SOURCE_FAMILY_QUALIFICATION")),
        )
        .withColumn("c31_parent_cohort_id", F.lit(cohort_id))
        .withColumn("c31_parent_cohort_class", F.lit(cohort_class))
        .withColumn("c31_parent_cohort_gate", F.lit(cohort_gate))
    )

    # -----------------------------------------------------------------------
    # 6. Select the largest remaining existing family; lexical tie-breaker.
    # Population size sequences analysis only, not priority or case formation.
    # -----------------------------------------------------------------------

    family_status = families.groupBy("source_family").agg(
        F.count(F.lit(1)).alias("asset_count"),
        F.sort_array(F.collect_set("source_mask_active")).alias("source_masks"),
    )
    family_rows = family_status.orderBy("source_family").collect()
    require(
        sum(int(row["asset_count"]) for row in family_rows) == counts["parent"],
        "Source-family counts do not reconcile to the complete parent.",
    )

    eligible_rows = sorted(
        (row for row in family_rows if row["source_family"] != "INTUNE_ONLY"),
        key=lambda row: (-int(row["asset_count"]), row["source_family"]),
    )
    next_family = eligible_rows[0]["source_family"] if eligible_rows else None
    next_count = int(eligible_rows[0]["asset_count"]) if eligible_rows else 0
    next_gate = (
        "SOURCE_FAMILY_ATTRIBUTION_QUALIFICATION"
        if next_family is not None else None
    )

    selected_condition = (
        F.col("source_family") == F.lit(next_family)
        if next_family is not None else F.lit(False)
    )
    next_df = parent_resume.filter(selected_condition)

    family_status = (
        family_status
        .withColumn(
            "analytical_state",
            F.when(
                F.col("source_family") == "INTUNE_ONLY",
                F.lit("QUALIFICATION_PRESERVED_PARENT_RESUMED"),
            ).otherwise(F.lit("AWAITING_SOURCE_FAMILY_QUALIFICATION")),
        )
        .withColumn(
            "eligible_for_next_selection",
            F.col("source_family") != "INTUNE_ONLY",
        )
        .withColumn("selected_next", selected_condition)
        .orderBy(F.desc("asset_count"), "source_family")
    )

    # -----------------------------------------------------------------------
    # 7. Certify only the conservation introduced by this resume operation.
    # -----------------------------------------------------------------------

    output_counts = {
        "parent": asset_count(parent_resume, "Cell 31 parent"),
        "intune": asset_count(intune_disposition, "Cell 31 Intune dispositions"),
        "history": asset_count(history_dependency, "Cell 31 history dependency"),
        "next": asset_count(next_df, "Cell 31 next source family"),
    }
    require(output_counts["parent"] == counts["parent"], "Parent assets were lost.")
    require(output_counts["intune"] == counts["intune"], "Intune assets were lost.")
    require(output_counts["history"] == counts["history"], "History candidates were lost.")
    require(output_counts["next"] == next_count, "Selected family count changed.")

    same_members(parent_resume, parent, "Resumed parent conservation")
    same_members(intune_disposition, qualified, "Intune disposition conservation")
    same_members(history_dependency, history, "History overlay conservation")
    same_members(
        parent_resume.filter(F.col("source_family") == "INTUNE_ONLY"),
        intune_disposition,
        "Parent / Intune disposition coverage",
    )
    same_members(
        parent_resume.filter(F.col("c31_history_candidate")),
        history_dependency,
        "Parent / history overlay coverage",
    )
    same_members(
        next_df,
        families.filter(selected_condition),
        "Selected next family / existing Cell 27 membership",
    )

    reject_rows(
        parent_resume.filter(F.col("source_family") == "INTUNE_ONLY"),
        F.col("c31_intune_qualification_class").isNull()
        | F.col("c31_history_dependency").isNull(),
        "An Intune member lacks its preserved disposition or overlay state.",
    )
    reject_rows(
        parent_resume.filter(F.col("source_family") != "INTUNE_ONLY"),
        F.col("c31_intune_qualification_class").isNotNull()
        | F.col("c31_history_candidate"),
        "Intune annotations were attached outside the Intune family.",
    )

    # -----------------------------------------------------------------------
    # 8. Runtime-derived certification report.
    # -----------------------------------------------------------------------

    print("RCAIP DIAG 001 - CELL 31 CERTIFICATION")
    print("Status: PASS")
    print("Parent class:", cohort_class)
    print("Parent gate:", cohort_gate)
    print("Starting parent assets:", counts["parent"])
    print("Preserved parent assets:", output_counts["parent"])
    print("Source-family assets:")
    for row in family_rows:
        print("  " + row["source_family"] + ": " + str(row["asset_count"]))
    print("Intune assets preserved:", output_counts["intune"])
    print("Exclusive Intune qualifications:")
    for row in qualification_rows:
        print("  " + row["qualification_class"] + ": " + str(row["asset_count"]))
    print("Shared-serial groups:", shared_group_count)
    print("Shared-serial member assets:", shared_member_count)
    print("Unresolved MDE-history overlay assets:", output_counts["history"])
    print("Original Cell 30 readiness:", history_readiness)
    print("Next source family:", next_family)
    print("Next source-family assets:", next_count)
    print("Next gate:", next_gate)
    print("Parent / source-family / Intune / overlay conservation: PASS")
    print("Duplicate, missing, or orphan asset membership: NONE")
    print("MDE-history dependency blocks Asset delivery or Paris: NO")
    print("MDE search / writes / routing / cases / findings / tickets / remediation: NONE")
    print("Would this exact analytical logic run for Paris? YES")

    return {
        "RCAIP_DIAG001_CELL31_POST_SLUG": post_slug,
        "RCAIP_DIAG001_CELL31_RUN_ID": run_id,
        "RCAIP_DIAG001_CELL31_PARENT_COHORT_ID": cohort_id,
        "RCAIP_DIAG001_CELL31_PARENT_RESUME_DF": parent_resume,
        "RCAIP_DIAG001_CELL31_INTUNE_DISPOSITION_DF": intune_disposition,
        "RCAIP_DIAG001_CELL31_MDE_HISTORY_DEPENDENCY_DF": history_dependency,
        "RCAIP_DIAG001_CELL31_SOURCE_FAMILY_STATUS_DF": family_status,
        "RCAIP_DIAG001_CELL31_NEXT_SOURCE_FAMILY": next_family,
        "RCAIP_DIAG001_CELL31_NEXT_ASSET_COUNT": next_count,
        "RCAIP_DIAG001_CELL31_NEXT_SOURCE_FAMILY_DF": next_df,
        "RCAIP_DIAG001_CELL31_NEXT_GATE": next_gate,
    }


_c31_publications = _build_cell31()
globals().update(_c31_publications)

# READY is published last, only after successful conservation checks.
RCAIP_DIAG001_CELL31_READY = True

del _c31_publications
del _build_cell31
# COMMAND ----------
# ============================================================================
# RCAIP DIAG 001
# Cell 32 - NMAP-Only Attribution / Observation Qualification
#
# Candidate authority: exact Cell 31 selected-family DataFrame.
#
# Reuse existing durable Network Assurance attribution, host observations,
# and scan provenance. Do not reconstruct matching or scan semantics.
#
# Grains:
#   Input candidates: one row per asset_key.
#   Host attribution / observations: Post/run x scan_id x ip_address.
#   Scan provenance: Post/run x scan_id.
#   Detail output: asset_key x scan_id x ip_address.
#   Qualified output: one row per original candidate asset_key.
#
# Evidence-boundary availability and candidate relationship evidence are
# separate states. An unavailable boundary is not negative asset evidence.
#
# Association uses only existing structural/independent attribution keys.
# IP is used only with scan_id to relate certified observation products.
#
# No raw acquisition, XML parsing, scans, Delta writes, identity mutation,
# customer routing, workload promotion, cases, findings, tickets, remediation,
# or Databricks recovery work.
#
# Would this exact analytical logic run for Paris?
# YES, if Paris reaches the same NMAP_ONLY branch.
# ============================================================================

from pyspark.sql import DataFrame
from pyspark.sql import functions as F
from pyspark.sql import types as T


for _c32_name in tuple(globals()):
    if _c32_name.startswith("RCAIP_DIAG001_CELL32_"):
        del globals()[_c32_name]
del _c32_name

RCAIP_DIAG001_CELL32_READY = False


def _build_cell32():
    def require(condition, message):
        if not condition:
            raise RuntimeError("Cell 32 STOP: " + message)

    required = [
        "spark",
        "get_rcaip_table",
        "RCAIP_CONFIG_000_READY",
        "RCAIP_POST_SLUG",
        "RCAIP_RUN_ID",
        "RCAIP_DIAG001_CELL31_READY",
        "RCAIP_DIAG001_CELL31_POST_SLUG",
        "RCAIP_DIAG001_CELL31_RUN_ID",
        "RCAIP_DIAG001_CELL31_PARENT_COHORT_ID",
        "RCAIP_DIAG001_CELL31_PARENT_RESUME_DF",
        "RCAIP_DIAG001_CELL31_SOURCE_FAMILY_STATUS_DF",
        "RCAIP_DIAG001_CELL31_NEXT_SOURCE_FAMILY",
        "RCAIP_DIAG001_CELL31_NEXT_ASSET_COUNT",
        "RCAIP_DIAG001_CELL31_NEXT_GATE",
        "RCAIP_DIAG001_CELL31_NEXT_SOURCE_FAMILY_DF",
    ]
    missing = sorted(name for name in required if name not in globals())
    require(not missing, "Missing runtime objects: " + " | ".join(missing))
    require(RCAIP_CONFIG_000_READY is True, "Config runtime is not ready.")
    require(RCAIP_DIAG001_CELL31_READY is True, "Cell 31 is not ready.")

    # Stop before reading evidence if another branch was selected.
    require(
        RCAIP_DIAG001_CELL31_NEXT_SOURCE_FAMILY == "NMAP_ONLY",
        "This cell applies only to a Cell-31-selected NMAP_ONLY cohort; "
        "the selected family requires its own analytical continuation.",
    )
    require(
        RCAIP_DIAG001_CELL31_NEXT_GATE
        == "SOURCE_FAMILY_ATTRIBUTION_QUALIFICATION",
        "Unexpected Cell 31 continuation state.",
    )

    post_slug = str(RCAIP_POST_SLUG).strip().lower()
    run_id = RCAIP_RUN_ID
    parent_id = RCAIP_DIAG001_CELL31_PARENT_COHORT_ID
    require(
        bool(post_slug) and bool(run_id) and bool(parent_id),
        "Blank runtime scope.",
    )
    require(
        RCAIP_DIAG001_CELL31_POST_SLUG == post_slug
        and RCAIP_DIAG001_CELL31_RUN_ID == run_id,
        "Cell 31 scope differs from the configured Post/run.",
    )

    candidates = RCAIP_DIAG001_CELL31_NEXT_SOURCE_FAMILY_DF
    parent = RCAIP_DIAG001_CELL31_PARENT_RESUME_DF
    family_status = RCAIP_DIAG001_CELL31_SOURCE_FAMILY_STATUS_DF

    def need(df, columns, label):
        require(isinstance(df, DataFrame), label + " is not a DataFrame.")
        require(
            len(df.columns) == len(set(df.columns)),
            label + " has duplicate column names.",
        )
        absent = sorted(set(columns) - set(df.columns))
        require(
            not absent,
            label + " missing columns: " + " | ".join(absent),
        )

    def reject(df, condition, message):
        require(
            df.filter(F.coalesce(condition, F.lit(True))).limit(1).count() == 0,
            message,
        )

    def asset_count(df, label):
        need(df, ["asset_key"], label)
        reject(
            df,
            F.col("asset_key").isNull()
            | (F.length(F.trim(F.col("asset_key"))) == 0),
            label + " has an invalid asset_key.",
        )
        count = df.count()
        require(
            count == df.select("asset_key").distinct().count(),
            label + " is not one row per asset.",
        )
        return count

    def same_assets(left, right, label):
        a = left.select("asset_key")
        b = right.select("asset_key")
        require(
            a.join(b, "asset_key", "left_anti").limit(1).count() == 0
            and b.join(a, "asset_key", "left_anti").limit(1).count() == 0,
            label + " membership differs.",
        )

    need(
        candidates,
        [
            "asset_key",
            "source_family",
            "post_slug",
            "rcaip_run_id",
            "c31_parent_cohort_id",
        ],
        "Cell 31 selected cohort",
    )
    need(parent, ["asset_key", "source_family"], "Cell 31 parent")
    need(
        family_status,
        ["source_family", "asset_count", "selected_next"],
        "Cell 31 family status",
    )
    require(
        not any(name.startswith("c32_") for name in candidates.columns),
        "Candidate input already contains Cell 32 annotations.",
    )

    starting = asset_count(candidates, "Cell 31 selected cohort")
    parent_count = asset_count(parent, "Cell 31 parent")
    require(
        starting == RCAIP_DIAG001_CELL31_NEXT_ASSET_COUNT,
        "Candidate count differs from Cell 31 selected count.",
    )
    reject(
        candidates,
        ~F.col("source_family").eqNullSafe(F.lit("NMAP_ONLY"))
        | ~F.col("c31_parent_cohort_id").eqNullSafe(F.lit(parent_id))
        | ~F.lower(F.trim(F.col("post_slug"))).eqNullSafe(F.lit(post_slug))
        | ~F.col("rcaip_run_id").eqNullSafe(F.lit(run_id)),
        "Candidate branch, parent, or scope is inconsistent.",
    )
    same_assets(
        candidates,
        parent.filter(F.col("source_family") == "NMAP_ONLY"),
        "Selected family / parent",
    )

    selected_status = family_status.filter(F.col("selected_next"))
    require(
        selected_status.count() == 1,
        "Cell 31 selection is not unique.",
    )
    selected_record = selected_status.first()
    require(
        selected_record["source_family"] == "NMAP_ONLY"
        and selected_record["asset_count"] == starting,
        "Cell 31 family summary disagrees with the selected denominator.",
    )

    # -----------------------------------------------------------------------
    # 1. Read existing registered products at the exact Post/run.
    #
    # Report missing contracts explicitly. Never silently treat a replacement
    # empty DataFrame as proof that a candidate has no network relationship.
    #
    # Unexpected access/read errors propagate rather than becoming absence.
    # -----------------------------------------------------------------------

    source_notes = []

    def read_product(logical_name, field_types):
        schema = T.StructType([
            T.StructField(name, dtype, True)
            for name, dtype in field_types.items()
        ])

        def unavailable(reason):
            source_notes.append(logical_name + ": " + reason)
            return spark.createDataFrame([], schema), {
                "status": reason,
                "missing_fields": sorted(field_types),
                "contract_complete": False,
            }

        try:
            table_name = get_rcaip_table(logical_name)
        except KeyError:
            return unavailable("REGISTRY_BINDING_MISSING")

        if not spark.catalog.tableExists(table_name):
            return unavailable("DURABLE_PRODUCT_UNAVAILABLE")

        source = spark.table(table_name)
        require(
            len(source.columns) == len(set(source.columns)),
            logical_name + " has duplicate column names.",
        )
        if not {"post_slug", "rcaip_run_id"}.issubset(source.columns):
            return unavailable("POST_RUN_SCOPE_FIELDS_MISSING")

        scoped = source.filter(
            (F.lower(F.trim(F.col("post_slug"))) == F.lit(post_slug))
            & (F.col("rcaip_run_id") == F.lit(run_id))
        )
        absent = sorted(set(field_types) - set(scoped.columns))
        if absent:
            source_notes.append(
                logical_name + ": MISSING_FIELDS=" + ",".join(absent)
            )

        projected = scoped.select(*[
            (
                F.col(name).cast(dtype)
                if name in scoped.columns
                else F.lit(None).cast(dtype)
            ).alias(name)
            for name, dtype in field_types.items()
        ])

        return projected, {
            "status": "SCOPED_PRODUCT_READ",
            "missing_fields": absent,
            "contract_complete": not absent,
        }

    S = T.StringType()
    B = T.BooleanType()
    TS = T.TimestampType()

    host_types = {
        "scan_id": S,
        "ip_address": S,
        "structural_linked_asset_key": S,
        "independently_attributed_asset_key": S,
        "structural_link_status": S,
        "independent_attribution_status": S,
        "identity_conflict_requires_review": B,
        "network_attribution_state": S,
        "scan_perspective": S,
        "network_role": S,
        "service_owner": S,
        "target_cidrs_json": S,
        "network_semantic_source": S,
        "target_scope_authority": S,
        "scan_start_timestamp": TS,
        "scan_end_timestamp": TS,
        "scan_source_file": S,
        "source_file_sha256": S,
    }

    hosts, host_read = read_product(
        "IP001_NETWORK_HOST_ATTRIBUTION",
        host_types,
    )
    observations, observation_read = read_product(
        "NMAP_NORM_WITH_PROVENANCE",
        {"scan_id": S, "ip_address": S},
    )
    scans, scan_read = read_product(
        "NMAP_SCAN_PROVENANCE",
        {
            "scan_id": S,
            "source_file_sha256": S,
            "scan_start_timestamp": TS,
            "scan_end_timestamp": TS,
            "mapping_status": S,
        },
    )

    supported_perspectives = [
        "INTERNAL_OPENNET",
        "INTERNAL_ENTERPRISE_WIFI",
        "PUBLIC_FACING",
    ]
    known_network_states = [
        "IDENTITY_CONFLICT_REQUIRES_REVIEW",
        "INDEPENDENT_ATTRIBUTION_CORROBORATES_STRUCTURAL_LINK",
        "INDEPENDENT_ATTRIBUTION_WITHOUT_STRUCTURAL_LINK",
        "NAME_IDENTITY_REQUIRES_REVIEW",
        "STRUCTURAL_LINK_WITH_IP_CONTEXT_REVIEW",
        "STRUCTURAL_LINK_ONLY",
        "UNRESOLVED_WITH_IP_CONTEXT_REVIEW",
        "UNRESOLVED_NETWORK_OBSERVATION",
    ]
    review_states = [
        "IDENTITY_CONFLICT_REQUIRES_REVIEW",
        "NAME_IDENTITY_REQUIRES_REVIEW",
        "STRUCTURAL_LINK_WITH_IP_CONTEXT_REVIEW",
        "UNRESOLVED_WITH_IP_CONTEXT_REVIEW",
    ]
    independent_states = [
        "ATTRIBUTED_EXACT_FULL_NAME_MULTISOURCE",
        "ATTRIBUTED_SHORT_NAME_FALLBACK_MULTISOURCE",
    ]

    # -----------------------------------------------------------------------
    # 2. Establish whether the host-attribution boundary can be evaluated.
    #
    # Core relationship fields differ from supporting context fields.
    # Missing perspective/provenance context must not erase a relationship.
    #
    # A valid observation may have BOTH attribution keys null. That is a
    # legitimate unassigned observation, not an unavailable materialization.
    # Availability is evaluated before filtering to selected candidates.
    # -----------------------------------------------------------------------

    core_host_fields = {
        "scan_id",
        "ip_address",
        "structural_linked_asset_key",
        "independently_attributed_asset_key",
        "structural_link_status",
        "independent_attribution_status",
        "identity_conflict_requires_review",
        "network_attribution_state",
    }
    missing_core = sorted(
        core_host_fields.intersection(host_read["missing_fields"])
    )

    def nonblank(column):
        return (
            F.col(column).isNotNull()
            & (F.length(F.trim(F.col(column).cast("string"))) > 0)
        )

    usable_host_row = (
        nonblank("scan_id")
        & nonblank("ip_address")
        & nonblank("structural_link_status")
        & nonblank("independent_attribution_status")
        & F.col("identity_conflict_requires_review").isNotNull()
        & F.col("network_attribution_state").isin(known_network_states)
    )

    host_current_run_rows = hosts.count()
    host_usable_rows = hosts.filter(
        F.coalesce(usable_host_row, F.lit(False))
    ).count()

    if host_read["status"] != "SCOPED_PRODUCT_READ":
        boundary_available = False
        boundary_reason = host_read["status"]
    elif missing_core:
        boundary_available = False
        boundary_reason = "CORE_ATTRIBUTION_FIELDS_MISSING: " + ",".join(missing_core)
    elif host_current_run_rows == 0:
        boundary_available = False
        boundary_reason = "NO_CURRENT_RUN_MATERIALIZATION"
    elif host_usable_rows == 0:
        boundary_available = False
        boundary_reason = "NO_USABLE_CURRENT_RUN_ATTRIBUTION_ROWS"
    else:
        boundary_available = True
        boundary_reason = "CURRENT_RUN_CORE_ATTRIBUTION_EVIDENCE_AVAILABLE"

    boundary_state = (
        "AVAILABLE_FOR_CURRENT_RUN"
        if boundary_available
        else "NETWORK_ATTRIBUTION_EVIDENCE_UNAVAILABLE"
    )

    if not boundary_available:
        source_notes.append(
            "IP001_NETWORK_HOST_ATTRIBUTION: " + boundary_reason
        )
    elif host_usable_rows != host_current_run_rows:
        source_notes.append(
            "IP001_NETWORK_HOST_ATTRIBUTION: "
            "SOME_CURRENT_RUN_ROWS_HAVE_INCOMPLETE_CORE_VALUES"
        )

    # When the boundary is unavailable, this empty relation means
    # "not evaluable", never "no asset relationship".
    #
    # When available, retain all rows for association. A candidate linked to
    # an incomplete row must retain that relationship as incomplete context.
    association_source = hosts if boundary_available else hosts.limit(0)

    # -----------------------------------------------------------------------
    # 3. Associate using only existing certified attribution-product keys.
    # Structural and independent relationships remain distinct.
    # -----------------------------------------------------------------------

    keys = candidates.select("asset_key")
    linked = (
        association_source.alias("h")
        .join(
            F.broadcast(keys).alias("c"),
            (F.col("h.structural_linked_asset_key") == F.col("c.asset_key"))
            | (
                F.col("h.independently_attributed_asset_key")
                == F.col("c.asset_key")
            ),
            "inner",
        )
        .select(F.col("c.asset_key"), "h.*")
    )

    observation_key = ["scan_id", "ip_address"]
    detail_key = ["asset_key"] + observation_key

    require(
        linked.groupBy(*detail_key).count()
        .filter(F.col("count") > 1).limit(1).count() == 0,
        "The attribution product duplicates a candidate/observation association. "
        "No arbitrary deduplication is permitted.",
    )

    represented_keys = linked.select(*observation_key).distinct()
    observation_coverage = (
        observations.join(represented_keys, observation_key, "left_semi")
        .groupBy(*observation_key)
        .agg(
            F.count(F.lit(1)).alias("c32_observation_record_count")
        )
    )

    represented_scans = linked.select("scan_id").distinct()
    scan_coverage = (
        scans.join(represented_scans, "scan_id", "left_semi")
        .groupBy("scan_id")
        .agg(
            F.count(F.lit(1)).alias("c32_scan_record_count"),
            F.collect_list(
                F.struct(
                    "source_file_sha256",
                    "scan_start_timestamp",
                    "scan_end_timestamp",
                    "mapping_status",
                )
            ).alias("c32_scan_provenance_records"),
        )
    )

    association_multiplicity = linked.groupBy(*observation_key).agg(
        F.countDistinct("asset_key").alias("c32_selected_asset_associations")
    )

    detail = (
        linked
        .join(observation_coverage, observation_key, "left")
        .join(scan_coverage, "scan_id", "left")
        .join(association_multiplicity, observation_key, "left")
        .fillna(
            0,
            subset=[
                "c32_observation_record_count",
                "c32_scan_record_count",
            ],
        )
    )

    # Existing review evidence is retained without rerunning matching.
    review = (
        F.coalesce(
            F.col("identity_conflict_requires_review"),
            F.lit(False),
        )
        | F.col("network_attribution_state").isin(review_states)
        | (F.col("c32_selected_asset_associations") > 1)
        | (
            F.col("structural_linked_asset_key").isNotNull()
            & F.col("independently_attributed_asset_key").isNotNull()
            & (
                F.col("structural_linked_asset_key")
                != F.col("independently_attributed_asset_key")
            )
        )
    )

    independently_supported = (
        F.col("independently_attributed_asset_key").eqNullSafe(
            F.col("asset_key")
        )
        & F.col("independent_attribution_status").isin(independent_states)
        & ~F.coalesce(review, F.lit(False))
    )

    targets = F.from_json(
        F.col("target_cidrs_json"),
        T.ArrayType(T.StringType()),
    )

    context_complete = (
        F.lit(
            host_read["contract_complete"]
            and observation_read["contract_complete"]
            and scan_read["contract_complete"]
        )
        & usable_host_row
        & (F.col("c32_observation_record_count") == 1)
        & (F.col("c32_scan_record_count") == 1)
        & F.col("scan_perspective").isin(supported_perspectives)
        & (
            F.col("network_semantic_source")
            == "CERTIFIED_RCAIP_V3_NMAP_EVIDENCE"
        )
        & (F.col("target_scope_authority") == "TARGET_CIDRS_JSON")
        & (F.size(targets) > 0)
        & F.col("scan_source_file").isNotNull()
        & F.col("source_file_sha256").isNotNull()
        & F.col("scan_start_timestamp").isNotNull()
    )

    detail = (
        detail
        .withColumn(
            "c32_existing_review_context",
            F.coalesce(review, F.lit(False)),
        )
        .withColumn(
            "c32_independent_support_for_candidate",
            F.coalesce(independently_supported, F.lit(False)),
        )
        .withColumn(
            "c32_observation_context_complete",
            F.coalesce(context_complete, F.lit(False)),
        )
        .withColumn(
            "c32_host_attribution_boundary_state",
            F.lit(boundary_state),
        )
        .withColumn("c32_accounting_post_slug", F.lit(post_slug))
        .withColumn("c32_accounting_run_id", F.lit(run_id))
    )

    # -----------------------------------------------------------------------
    # 4. Aggregate candidate/observation associations to the original assets.
    #
    # Repeated observations retain their native detail rows.
    # Counts describe recorded observations, not continuous asset presence.
    # Service-owner labels remain context, not customer routing.
    # -----------------------------------------------------------------------

    rollup = detail.groupBy("asset_key").agg(
        F.count(F.lit(1)).alias("c32_observation_association_count"),
        F.countDistinct("scan_id").alias("c32_distinct_scan_count"),
        F.sum(
            F.when(
                F.col("c32_observation_record_count") == 1, 1
            ).otherwise(0)
        ).alias("c32_observation_covered_count"),
        F.sum(
            F.when(
                F.col("c32_scan_record_count") == 1, 1
            ).otherwise(0)
        ).alias("c32_provenance_covered_count"),
        F.sum(
            F.when(
                F.col("c32_observation_context_complete"), 1
            ).otherwise(0)
        ).alias("c32_complete_context_count"),
        F.sum(
            F.when(
                F.col("c32_existing_review_context"), 1
            ).otherwise(0)
        ).alias("c32_review_context_count"),
        F.sum(
            F.when(
                F.col("c32_independent_support_for_candidate"), 1
            ).otherwise(0)
        ).alias("c32_independent_support_count"),
        F.sort_array(
            F.collect_set("scan_perspective")
        ).alias("c32_scan_perspectives"),
        F.sort_array(
            F.collect_set("network_role")
        ).alias("c32_network_roles"),
        F.sort_array(
            F.collect_set("service_owner")
        ).alias("c32_service_owner_context"),
        F.sort_array(
            F.collect_set("network_attribution_state")
        ).alias("c32_existing_network_states"),
        F.min("scan_start_timestamp").alias("c32_first_recorded_scan"),
        F.max("scan_end_timestamp").alias("c32_last_recorded_scan"),
    )

    count_columns = [
        "c32_observation_association_count",
        "c32_distinct_scan_count",
        "c32_observation_covered_count",
        "c32_provenance_covered_count",
        "c32_complete_context_count",
        "c32_review_context_count",
        "c32_independent_support_count",
    ]

    qualified = candidates.join(
        rollup, "asset_key", "left"
    ).fillna(0, subset=count_columns)

    for column in [
        "c32_scan_perspectives",
        "c32_network_roles",
        "c32_service_owner_context",
        "c32_existing_network_states",
    ]:
        qualified = qualified.withColumn(
            column,
            F.coalesce(
                F.col(column),
                F.array().cast("array<string>"),
            ),
        )

    total = F.col("c32_observation_association_count")

    qualified = (
        qualified
        .withColumn(
            "c32_host_attribution_boundary_state",
            F.lit(boundary_state),
        )
        .withColumn(
            "c32_host_attribution_boundary_reason",
            F.lit(boundary_reason),
        )
        .withColumn(
            "c32_relationship_evaluation_performed",
            F.lit(boundary_available),
        )
        .withColumn(
            "c32_qualification_state",
            F.when(
                F.lit(not boundary_available),
                F.lit("NETWORK_ATTRIBUTION_EVIDENCE_UNAVAILABLE"),
            )
            .when(
                total == 0,
                F.lit("NO_CERTIFIED_OBSERVATION_LINK"),
            )
            .when(
                F.col("c32_complete_context_count") != total,
                F.lit("OBSERVATION_CONTEXT_INCOMPLETE"),
            )
            .when(
                F.col("c32_review_context_count") > 0,
                F.lit("CERTIFIED_NETWORK_REVIEW_CONTEXT"),
            )
            .when(
                F.col("c32_independent_support_count") == total,
                F.lit("INDEPENDENT_NETWORK_ATTRIBUTION_CONTEXT"),
            )
            .when(
                F.col("c32_independent_support_count") > 0,
                F.lit("PARTIAL_INDEPENDENT_NETWORK_ATTRIBUTION_CONTEXT"),
            )
            .otherwise(
                F.lit("STRUCTURAL_OBSERVATION_CONTEXT_ONLY")
            ),
        )
        .withColumn(
            "c32_post_attribution_state",
            F.lit("NOT_ESTABLISHED_BY_THIS_CELL"),
        )
        .withColumn(
            "c32_evidence_limitations",
            F.lit(
                " | ".join(source_notes)
                if source_notes
                else "NONE_AT_SCHEMA_LEVEL"
            ),
        )
        .withColumn(
            "c32_customer_routing_performed",
            F.lit(False),
        )
        .withColumn(
            "c32_workload_promotion_authorized",
            F.lit(False),
        )
    )

    # Zero association counts under an unavailable boundary mean that no
    # associations were evaluated. The explicit boundary/evaluation fields
    # prevent those zeros from being interpreted as negative asset evidence.

    summary = qualified.groupBy(
        "c32_host_attribution_boundary_state",
        "c32_host_attribution_boundary_reason",
        "c32_qualification_state",
    ).agg(
        F.count(F.lit(1)).alias("asset_count"),
        F.sum(
            "c32_observation_association_count"
        ).alias("observation_associations"),
        F.sum(
            "c32_observation_covered_count"
        ).alias("covered_observation_associations"),
        F.sum(
            "c32_provenance_covered_count"
        ).alias("covered_provenance_associations"),
        F.sum(
            "c32_complete_context_count"
        ).alias("complete_context_associations"),
    ).orderBy("c32_qualification_state")

    # -----------------------------------------------------------------------
    # 5. Conservation, availability distinction, and coverage certification.
    # -----------------------------------------------------------------------

    ending = asset_count(qualified, "Cell 32 qualified output")
    require(
        ending == starting,
        "Starting assets were not fully preserved.",
    )
    same_assets(
        qualified, candidates,
        "Cell 32 / Cell 31 candidates",
    )

    require(
        detail.select("asset_key").join(
            keys, "asset_key", "left_anti"
        ).limit(1).count() == 0,
        "Observation evidence introduced a candidate.",
    )
    require(
        detail.groupBy(*detail_key).count()
        .filter(F.col("count") > 1).limit(1).count() == 0,
        "Detail joins multiplied candidate/observation associations.",
    )

    association_count = detail.count()
    summary_rows = summary.collect()

    require(
        sum(int(row["asset_count"]) for row in summary_rows) == starting,
        "Qualification states do not reconcile to the selected denominator.",
    )
    require(
        sum(
            int(row["observation_associations"] or 0)
            for row in summary_rows
        ) == association_count,
        "Asset rollups do not reconcile to observation detail.",
    )

    unavailable_assets = qualified.filter(
        F.col("c32_qualification_state")
        == "NETWORK_ATTRIBUTION_EVIDENCE_UNAVAILABLE"
    ).count()

    no_link_assets = qualified.filter(
        F.col("c32_qualification_state")
        == "NO_CERTIFIED_OBSERVATION_LINK"
    ).count()

    assets_with_links = detail.select("asset_key").distinct().count()

    incomplete_context_assets = qualified.filter(
        F.col("c32_qualification_state")
        == "OBSERVATION_CONTEXT_INCOMPLETE"
    ).count()

    if boundary_available:
        require(
            unavailable_assets == 0,
            "An available boundary was classified as unavailable.",
        )
        require(
            assets_with_links + no_link_assets == starting,
            "Evaluated linked/unlinked asset coverage does not reconcile.",
        )
    else:
        require(
            unavailable_assets == starting,
            "Unavailable evidence did not preserve every candidate explicitly.",
        )
        require(
            no_link_assets == 0 and association_count == 0,
            "Unavailable evidence was interpreted as evaluated asset evidence.",
        )

    require(
        unavailable_assets + no_link_assets + assets_with_links == starting,
        "Boundary-unavailable / evaluated-unlinked / linked populations "
        "do not reconcile.",
    )

    covered_observations = detail.filter(
        F.col("c32_observation_record_count") == 1
    ).count()
    covered_provenance = detail.filter(
        F.col("c32_scan_record_count") == 1
    ).count()
    incomplete_observations = detail.filter(
        F.col("c32_observation_record_count") != 1
    ).count()
    incomplete_provenance = detail.filter(
        F.col("c32_scan_record_count") != 1
    ).count()

    require(
        covered_observations + incomplete_observations == association_count
        and covered_provenance + incomplete_provenance == association_count,
        "Observation/provenance coverage does not reconcile.",
    )

    # Helper-product incompleteness cannot erase an established association
    # or place its candidate in the evaluated-no-link population.
    reject(
        qualified,
        (F.col("c32_observation_association_count") > 0)
        & (
            (F.col("c32_observation_covered_count") != total)
            | (F.col("c32_provenance_covered_count") != total)
        )
        & (
            F.col("c32_qualification_state")
            != "OBSERVATION_CONTEXT_INCOMPLETE"
        ),
        "Helper-product coverage gaps were not retained as incomplete context.",
    )

    # Existing Cell 31 objects remain unchanged. This is a separate result
    # for the exact selected cohort, not a mutation of the parent funnel.
    print("RCAIP DIAG 001 - CELL 32 CERTIFICATION")
    print("Status: PASS - qualification/accounting only")
    print("Source family: NMAP_ONLY")
    print("Starting assets:", starting)
    print("Accounted assets:", ending)
    print(
        "Other parent assets retained in Cell 31:",
        parent_count - starting,
    )
    print("Host-attribution boundary state:", boundary_state)
    print("Host-attribution boundary reason:", boundary_reason)
    print("Host-attribution current-run rows:", host_current_run_rows)
    print("Host-attribution usable current-run rows:", host_usable_rows)
    print("Assets with unavailable attribution evidence:", unavailable_assets)
    print("Evaluated assets with no certified observation link:", no_link_assets)
    print("Assets with certified observation associations:", assets_with_links)
    print("Assets with incomplete observation context:", incomplete_context_assets)
    print("Candidate/observation associations:", association_count)
    print(
        "Distinct associated scan/IP observations:",
        detail.select(*observation_key).distinct().count(),
    )
    print(
        "Observation coverage, covered / incomplete:",
        covered_observations, "/", incomplete_observations,
    )
    print(
        "Provenance coverage, covered / incomplete:",
        covered_provenance, "/", incomplete_provenance,
    )
    print(
        "Relationship and coverage counts are NOT EVALUATED when "
        "the host-attribution boundary is unavailable."
    )
    for row in summary_rows:
        print(
            "Qualification:",
            row["c32_qualification_state"],
            row["asset_count"],
        )
    for note in source_notes:
        print("Evidence limitation:", note)
    print("New candidates / duplicate asset outputs: 0 / 0")
    print("Post ownership established by this cell: NO")
    print("Routing / workload promotion / cases / findings / tickets: NONE")
    print("Source acquisition / Delta writes / identity mutation / remediation: NONE")
    print("Would this exact analytical logic run for Paris? YES, on NMAP_ONLY.")

    return {
        "RCAIP_DIAG001_CELL32_POST_SLUG": post_slug,
        "RCAIP_DIAG001_CELL32_RUN_ID": run_id,
        "RCAIP_DIAG001_CELL32_SOURCE_FAMILY": "NMAP_ONLY",
        "RCAIP_DIAG001_CELL32_STARTING_ASSET_COUNT": starting,
        "RCAIP_DIAG001_CELL32_HOST_ATTRIBUTION_BOUNDARY_STATE": boundary_state,
        "RCAIP_DIAG001_CELL32_HOST_ATTRIBUTION_BOUNDARY_REASON": boundary_reason,
        "RCAIP_DIAG001_CELL32_QUALIFIED_DF": qualified,
        "RCAIP_DIAG001_CELL32_QUALIFICATION_SUMMARY_DF": summary,
        "RCAIP_DIAG001_CELL32_OBSERVATION_CONTEXT_DF": detail,
        "RCAIP_DIAG001_CELL32_NEXT_GATE": "ATTRIBUTION_COHORT_RESUME",
    }


_c32_publications = _build_cell32()
globals().update(_c32_publications)
RCAIP_DIAG001_CELL32_READY = True

del _c32_publications
del _build_cell32
# COMMAND ----------
# ============================================================================
# RCAIP DIAG 001
# Cell 33 - Attribution Cohort Resume After NMAP-Only Qualification
#
# Runtime handoffs only. Asset/source-family accounting only.
# Cell 31 supplies the authoritative parent and selected-family membership.
# Cell 32 supplies qualification results; this cell does not reinterpret them.
#
# Qualification preserved / parent resumed does not mean attribution resolved.
# Structural linkage != independent attribution.
# Independent attribution != Post ownership.
#
# Preserve the separate Cell 31 MDE-history dependency without searching,
# resolving, reprioritizing, or copying it into a new output.
#
# No source acquisition, evidence reads, Network Assurance re-analysis,
# Delta writes, Asset Plane mutation, identity merging, customer routing,
# workload promotion, cases, findings, tickets, remediation, or recovery.
#
# Would this exact analytical logic run for Paris?
# YES. Counts and next-family selection come from runtime handoffs.
# No recorded example_post_a count is an acceptance or branching constant.
# ============================================================================

from pyspark.sql import DataFrame
from pyspark.sql import functions as F


for _c33_name in tuple(globals()):
    if _c33_name.startswith("RCAIP_DIAG001_CELL33_"):
        del globals()[_c33_name]
del _c33_name

RCAIP_DIAG001_CELL33_READY = False


def _build_cell33():
    def require(condition, message):
        if not condition:
            raise RuntimeError("Cell 33 STOP: " + message)

    required = [
        "RCAIP_DIAG001_CELL31_READY",
        "RCAIP_DIAG001_CELL31_POST_SLUG",
        "RCAIP_DIAG001_CELL31_RUN_ID",
        "RCAIP_DIAG001_CELL31_PARENT_COHORT_ID",
        "RCAIP_DIAG001_CELL31_PARENT_RESUME_DF",
        "RCAIP_DIAG001_CELL31_INTUNE_DISPOSITION_DF",
        "RCAIP_DIAG001_CELL31_MDE_HISTORY_DEPENDENCY_DF",
        "RCAIP_DIAG001_CELL31_SOURCE_FAMILY_STATUS_DF",
        "RCAIP_DIAG001_CELL31_NEXT_SOURCE_FAMILY",
        "RCAIP_DIAG001_CELL31_NEXT_ASSET_COUNT",
        "RCAIP_DIAG001_CELL31_NEXT_SOURCE_FAMILY_DF",
        "RCAIP_DIAG001_CELL32_READY",
        "RCAIP_DIAG001_CELL32_POST_SLUG",
        "RCAIP_DIAG001_CELL32_RUN_ID",
        "RCAIP_DIAG001_CELL32_SOURCE_FAMILY",
        "RCAIP_DIAG001_CELL32_STARTING_ASSET_COUNT",
        "RCAIP_DIAG001_CELL32_HOST_ATTRIBUTION_BOUNDARY_STATE",
        "RCAIP_DIAG001_CELL32_HOST_ATTRIBUTION_BOUNDARY_REASON",
        "RCAIP_DIAG001_CELL32_QUALIFIED_DF",
        "RCAIP_DIAG001_CELL32_QUALIFICATION_SUMMARY_DF",
        "RCAIP_DIAG001_CELL32_NEXT_GATE",
    ]
    missing = sorted(name for name in required if name not in globals())
    require(not missing, "Missing runtime objects: " + " | ".join(missing))
    require(RCAIP_DIAG001_CELL31_READY is True, "Cell 31 is not ready.")
    require(RCAIP_DIAG001_CELL32_READY is True, "Cell 32 is not ready.")

    post_slug = RCAIP_DIAG001_CELL31_POST_SLUG
    run_id = RCAIP_DIAG001_CELL31_RUN_ID
    parent_id = RCAIP_DIAG001_CELL31_PARENT_COHORT_ID
    processed_family = RCAIP_DIAG001_CELL32_SOURCE_FAMILY
    boundary_state = RCAIP_DIAG001_CELL32_HOST_ATTRIBUTION_BOUNDARY_STATE
    boundary_reason = RCAIP_DIAG001_CELL32_HOST_ATTRIBUTION_BOUNDARY_REASON

    require(
        bool(post_slug) and bool(run_id) and bool(parent_id),
        "Blank Cell 31 scope.",
    )
    require(
        RCAIP_DIAG001_CELL32_POST_SLUG == post_slug
        and RCAIP_DIAG001_CELL32_RUN_ID == run_id,
        "Cell 31 and Cell 32 Post/run scopes disagree.",
    )
    require(
        processed_family == RCAIP_DIAG001_CELL31_NEXT_SOURCE_FAMILY
        and processed_family == "NMAP_ONLY",
        "Cell 32 does not represent the Cell-31-selected NMAP_ONLY cohort.",
    )
    require(
        RCAIP_DIAG001_CELL32_NEXT_GATE == "ATTRIBUTION_COHORT_RESUME",
        "Unexpected Cell 32 continuation gate.",
    )

    parent = RCAIP_DIAG001_CELL31_PARENT_RESUME_DF
    selected = RCAIP_DIAG001_CELL31_NEXT_SOURCE_FAMILY_DF
    prior_status = RCAIP_DIAG001_CELL31_SOURCE_FAMILY_STATUS_DF
    intune = RCAIP_DIAG001_CELL31_INTUNE_DISPOSITION_DF
    history = RCAIP_DIAG001_CELL31_MDE_HISTORY_DEPENDENCY_DF
    qualified = RCAIP_DIAG001_CELL32_QUALIFIED_DF
    qualification_summary = RCAIP_DIAG001_CELL32_QUALIFICATION_SUMMARY_DF

    completed_state = "QUALIFICATION_PRESERVED_PARENT_RESUMED"
    awaiting_state = "AWAITING_SOURCE_FAMILY_QUALIFICATION"

    def need(df, columns, label):
        require(isinstance(df, DataFrame), label + " is not a DataFrame.")
        require(
            len(df.columns) == len(set(df.columns)),
            label + " has duplicate column names.",
        )
        absent = sorted(set(columns) - set(df.columns))
        require(
            not absent,
            label + " missing columns: " + " | ".join(absent),
        )

    def reject(df, condition, message):
        require(df.filter(condition).limit(1).count() == 0, message)

    def blank(name):
        return F.col(name).isNull() | (F.trim(F.col(name)) == "")

    def asset_count(df, label):
        need(df, ["asset_key"], label)
        reject(df, blank("asset_key"), label + " has blank asset keys.")
        reject(
            df.groupBy("asset_key").count(),
            F.col("count") != 1,
            label + " is not one row per asset.",
        )
        return df.count()

    def same_assets(left, right, label):
        left_keys = left.select("asset_key")
        right_keys = right.select("asset_key")
        require(
            left_keys.join(right_keys, "asset_key", "left_anti")
            .limit(1).count() == 0
            and right_keys.join(left_keys, "asset_key", "left_anti")
            .limit(1).count() == 0,
            label + " has missing or orphan assets.",
        )

    def same_rows(left, right, columns, label):
        # Current handoffs contain set-comparable scalar/array fields.
        # Comparison certifies preservation; it does not derive new evidence.
        left_projection = left.select(*columns)
        right_projection = right.select(*columns)
        require(
            left_projection.exceptAll(right_projection).limit(1).count() == 0
            and right_projection.exceptAll(left_projection).limit(1).count() == 0,
            label + " changed.",
        )

    def check_scope(df, label):
        need(df, ["post_slug", "rcaip_run_id"], label)
        reject(
            df,
            ~F.col("post_slug").eqNullSafe(F.lit(post_slug))
            | ~F.col("rcaip_run_id").eqNullSafe(F.lit(run_id)),
            label + " contains another or null Post/run scope.",
        )

    # -----------------------------------------------------------------------
    # 1. Validate the existing asset-grain handoff boundaries.
    # -----------------------------------------------------------------------

    need(
        parent,
        [
            "asset_key", "source_family", "source_mask_active",
            "c31_resume_state", "c31_parent_cohort_id",
            "c31_intune_qualification_class", "c31_history_candidate",
        ],
        "Cell 31 parent",
    )
    require(
        not any(name.startswith(("c32_", "c33_")) for name in parent.columns),
        "Cell 31 parent unexpectedly already contains later-cell annotations.",
    )
    need(selected, parent.columns, "Cell 31 selected cohort")
    need(qualified, parent.columns, "Cell 32 qualified assets")
    need(
        prior_status,
        [
            "source_family", "asset_count", "source_masks",
            "analytical_state", "eligible_for_next_selection", "selected_next",
        ],
        "Cell 31 source-family status",
    )

    parent_count = asset_count(parent, "Cell 31 parent")
    selected_count = asset_count(selected, "Cell 31 selected cohort")
    qualified_count = asset_count(qualified, "Cell 32 qualified assets")
    intune_count = asset_count(intune, "Cell 31 Intune dispositions")
    history_count = asset_count(history, "Cell 31 history dependency")

    for df, label in [
        (parent, "Cell 31 parent"),
        (selected, "Cell 31 selected cohort"),
        (qualified, "Cell 32 qualified assets"),
    ]:
        check_scope(df, label)

    reject(parent, blank("source_family"), "Parent has a blank source family.")
    reject(
        parent,
        ~F.col("c31_parent_cohort_id").eqNullSafe(F.lit(parent_id)),
        "Parent cohort identity differs from the Cell 31 scalar.",
    )
    require(
        selected_count > 0
        and selected_count == RCAIP_DIAG001_CELL31_NEXT_ASSET_COUNT
        and selected_count == RCAIP_DIAG001_CELL32_STARTING_ASSET_COUNT
        and selected_count == qualified_count,
        "Selected and qualified starting denominators disagree.",
    )

    expected_selected = parent.filter(
        F.col("source_family") == processed_family
    )
    same_assets(selected, expected_selected, "Cell 31 selected membership")
    same_assets(qualified, selected, "Cell 32 selected membership")
    same_rows(
        selected, expected_selected, parent.columns,
        "Cell 31 selected parent fields",
    )
    same_rows(
        qualified, selected, parent.columns,
        "Cell 32 inherited parent fields",
    )

    same_assets(
        parent.filter(F.col("source_family") == "INTUNE_ONLY"),
        intune,
        "Intune parent membership",
    )
    same_assets(
        parent.filter(F.col("c31_history_candidate")),
        history,
        "Separate history overlay membership",
    )

    # -----------------------------------------------------------------------
    # 2. Validate accounting, preserving all Cell 32 meanings verbatim.
    # -----------------------------------------------------------------------

    annotation_columns = [
        name for name in qualified.columns if name not in parent.columns
    ]
    require(
        bool(annotation_columns)
        and all(name.startswith("c32_") for name in annotation_columns),
        "Unexpected Cell 32 additive-field contract.",
    )

    summary_keys = [
        "c32_host_attribution_boundary_state",
        "c32_host_attribution_boundary_reason",
        "c32_qualification_state",
    ]
    need(qualified, summary_keys, "Cell 32 qualified assets")
    need(
        qualification_summary,
        summary_keys + ["asset_count"],
        "Cell 32 qualification summary",
    )
    reject(
        qualified,
        blank("c32_qualification_state"),
        "A Cell 32 asset lacks a qualification state.",
    )
    reject(
        qualified,
        ~F.col("c32_host_attribution_boundary_state")
        .eqNullSafe(F.lit(boundary_state))
        | ~F.col("c32_host_attribution_boundary_reason")
        .eqNullSafe(F.lit(boundary_reason)),
        "Cell 32 boundary scalars and asset annotations disagree.",
    )

    qualification_counts = qualified.groupBy(*summary_keys).agg(
        F.count(F.lit(1)).alias("asset_count")
    )
    same_rows(
        qualification_counts,
        qualification_summary,
        summary_keys + ["asset_count"],
        "Cell 32 qualification denominator accounting",
    )
    qualification_rows = qualification_counts.orderBy(
        "c32_qualification_state"
    ).collect()
    require(
        sum(int(row["asset_count"]) for row in qualification_rows)
        == selected_count,
        "Qualification states do not account for the selected denominator.",
    )

    # There is deliberately no test requiring AVAILABLE evidence, a resolved
    # qualification, an observation link, or independent attribution.
    # Cell 32 meanings and boundary availability/reason remain unchanged.

    # -----------------------------------------------------------------------
    # 3. Reconcile source families using existing Cell 31 membership.
    # -----------------------------------------------------------------------

    reject(
        prior_status,
        blank("source_family"),
        "Cell 31 status has a blank source family.",
    )
    reject(
        prior_status.groupBy("source_family").count(),
        F.col("count") != 1,
        "Cell 31 status is not one row per source family.",
    )

    membership = parent.groupBy("source_family").agg(
        F.count(F.lit(1)).alias("asset_count"),
        F.sort_array(F.collect_set("source_mask_active")).alias("source_masks"),
    )
    same_rows(
        membership, prior_status,
        ["source_family", "asset_count", "source_masks"],
        "Cell 31 source-family accounting",
    )

    prior_rows = prior_status.collect()
    require(
        all(
            row["analytical_state"]
            == (
                completed_state
                if row["source_family"] == "INTUNE_ONLY"
                else awaiting_state
            )
            and row["eligible_for_next_selection"]
            == (row["analytical_state"] == awaiting_state)
            and row["selected_next"]
            == (row["source_family"] == processed_family)
            for row in prior_rows
        ),
        "Cell 31 source-family completion/selection state is inconsistent.",
    )

    prior_parent_state = parent.join(
        prior_status.select(
            "source_family",
            F.col("analytical_state").alias("_c33_prior_state"),
        ),
        "source_family",
        "left",
    )
    reject(
        prior_parent_state,
        ~F.col("c31_resume_state").eqNullSafe(F.col("_c33_prior_state")),
        "Cell 31 parent and source-family resume states disagree.",
    )

    family_status = (
        prior_status
        .withColumn(
            "analytical_state",
            F.when(
                F.col("source_family") == processed_family,
                F.lit(completed_state),
            ).otherwise(F.col("analytical_state")),
        )
        .withColumn(
            "eligible_for_next_selection",
            F.col("analytical_state") == awaiting_state,
        )
    )

    remaining_rows = (
        family_status
        .filter(F.col("eligible_for_next_selection"))
        .orderBy(F.desc("asset_count"), F.asc("source_family"))
        .collect()
    )
    next_family = remaining_rows[0]["source_family"] if remaining_rows else None
    next_count = int(remaining_rows[0]["asset_count"]) if remaining_rows else 0
    next_gate = (
        "SOURCE_FAMILY_ATTRIBUTION_QUALIFICATION"
        if next_family is not None else None
    )
    next_condition = (
        F.col("source_family") == F.lit(next_family)
        if next_family is not None else F.lit(False)
    )
    family_status = (
        family_status
        .withColumn("selected_next", next_condition)
        .orderBy(F.desc("asset_count"), F.asc("source_family"))
    )

    # Size sequences analytical work only. Neither Cell 32 outcomes nor the
    # parked MDE-history overlay participates in next-family selection.
    # No remaining family means no automatic continuation selection; it does
    # not authorize closure of the parent or the wider attribution branch.

    # -----------------------------------------------------------------------
    # 4. Attach original qualification annotations and current resume state.
    # -----------------------------------------------------------------------

    parent_resume = (
        parent
        .join(
            qualified.select("asset_key", *annotation_columns),
            "asset_key",
            "left",
        )
        .join(
            family_status.select(
                "source_family",
                F.col("analytical_state").alias("c33_resume_state"),
            ),
            "source_family",
            "left",
        )
        .select(*parent.columns, *annotation_columns, "c33_resume_state")
    )
    next_df = parent_resume.filter(next_condition)

    # Original Cell 31 and Cell 32 globals remain untouched. The original
    # c31_resume_state remains historical evidence. c33_resume_state records
    # the current source-family qualification/resume boundary.

    # -----------------------------------------------------------------------
    # 5. Certify only conservation and accounting introduced by this cell.
    # -----------------------------------------------------------------------

    ending_count = asset_count(parent_resume, "Cell 33 resumed parent")
    next_actual_count = asset_count(next_df, "Cell 33 next family")
    require(ending_count == parent_count, "Parent denominator changed.")
    same_assets(parent_resume, parent, "Parent conservation")
    same_rows(parent_resume, parent, parent.columns, "Original parent fields")

    resumed_processed = parent_resume.filter(
        F.col("source_family") == processed_family
    )
    same_assets(resumed_processed, qualified, "Processed family conservation")
    same_rows(
        resumed_processed, qualified, qualified.columns,
        "Every Cell 32 asset-grain field",
    )

    other_assets = parent_resume.filter(
        F.col("source_family") != processed_family
    )
    annotations_present = F.lit(False)
    for name in annotation_columns:
        annotations_present = annotations_present | F.col(name).isNotNull()
    reject(
        other_assets,
        annotations_present,
        "Cell 32 annotations escaped their selected source family.",
    )

    same_assets(
        parent_resume.filter(F.col("source_family") == "INTUNE_ONLY"),
        intune,
        "Preserved Intune membership",
    )
    same_assets(
        parent_resume.filter(F.col("c31_history_candidate")),
        history,
        "Preserved separate history overlay membership",
    )
    reject(
        parent_resume,
        F.col("c33_resume_state").isNull(),
        "A parent asset has no current source-family resume state.",
    )
    reject(
        parent_resume.filter(
            F.col("source_family").isin("INTUNE_ONLY", processed_family)
        ),
        F.col("c33_resume_state") != completed_state,
        "A completed qualification subbranch was not preserved/resumed.",
    )

    family_rows = family_status.collect()
    completed_count = sum(
        int(row["asset_count"]) for row in family_rows
        if row["analytical_state"] == completed_state
    )
    remaining_count = sum(
        int(row["asset_count"]) for row in family_rows
        if row["analytical_state"] == awaiting_state
    )
    require(
        completed_count + remaining_count == parent_count,
        "Completed and remaining families do not reconcile to the parent.",
    )
    require(
        next_actual_count == next_count,
        "Next-family count differs from existing source-family accounting.",
    )
    same_assets(
        next_df,
        parent.filter(next_condition),
        "Next selection / existing parent source-family membership",
    )

    # -----------------------------------------------------------------------
    # 6. Runtime-derived report and minimal continuation interface.
    # -----------------------------------------------------------------------

    print("RCAIP DIAG 001 - CELL 33 CERTIFICATION")
    print("Status: PASS - resume/accounting only")
    print("Starting parent assets:", parent_count)
    print("Preserved parent assets:", ending_count)
    print("Cell 32 selected / qualified assets:", selected_count, qualified_count)
    print("Intune assets preserved:", intune_count)
    print("Unresolved MDE-history overlay retained separately:", history_count)
    print("Host-attribution boundary state preserved:", boundary_state)
    print("Host-attribution boundary reason preserved:", boundary_reason)

    for row in qualification_rows:
        print(
            "Preserved Cell 32 qualification:",
            row["c32_qualification_state"],
            row["asset_count"],
        )
    for row in family_rows:
        print(
            "Source family:",
            row["source_family"],
            row["asset_count"],
            row["analytical_state"],
        )

    print("Qualification-preserved / parent-resumed assets:", completed_count)
    print("Assets awaiting source-family qualification:", remaining_count)
    print("Next source family:", next_family)
    print("Next source-family assets:", next_count)
    print("Next gate:", next_gate)
    print("Original parent fields and every Cell 32 asset field preserved: YES")
    print("Duplicate / lost / orphan assets: NONE")
    print("Cell 32 annotations outside its selected family: NONE")
    print("Unavailable or unresolved qualification blocks continuation: NO")
    print("History overlay influences selection: NO")
    print("Parent cohort / wider attribution branch closed: NO / NO")
    print("Post ownership established / customer routing performed: NO / NO")
    print("Workload / cases / findings / tickets / remediation: NONE")
    print("Source reads / Delta writes / identity mutation / recovery: NONE")
    print("Would this exact analytical logic run for Paris? YES")

    return {
        "RCAIP_DIAG001_CELL33_POST_SLUG": post_slug,
        "RCAIP_DIAG001_CELL33_RUN_ID": run_id,
        "RCAIP_DIAG001_CELL33_PARENT_COHORT_ID": parent_id,
        "RCAIP_DIAG001_CELL33_PARENT_RESUME_DF": parent_resume,
        "RCAIP_DIAG001_CELL33_SOURCE_FAMILY_STATUS_DF": family_status,
        "RCAIP_DIAG001_CELL33_NEXT_SOURCE_FAMILY": next_family,
        "RCAIP_DIAG001_CELL33_NEXT_ASSET_COUNT": next_count,
        "RCAIP_DIAG001_CELL33_NEXT_SOURCE_FAMILY_DF": next_df,
        "RCAIP_DIAG001_CELL33_NEXT_GATE": next_gate,
    }


_c33_publications = _build_cell33()
globals().update(_c33_publications)

# Publish readiness only after every accounting/preservation guard succeeds.
RCAIP_DIAG001_CELL33_READY = True

del _c33_publications
del _build_cell33
# COMMAND ----------
# ============================================================================
# RCAIP DIAG 001
# Cell 34 - Multi-Source Attribution / Corroboration Qualification
#
# Sole candidate authority:
#   Cell 33 selected-family DataFrame, one row per asset_key.
#
# Evidence:
#   Existing certified runtime handoff fields only.
#   No durable/source reads or matching reconstruction.
#
# Discovery 002 coverage:
#   Consume discovery002_coverage_state exactly as published by Cell 26.
#   Do not reconstruct coverage from IP-005 or _d002_present.
#   Missing required columns are structural contract failures.
#   Outside-contract coverage is valid and is not unavailable evidence.
#
# Grain:
#   Input/output: one row per selected asset_key.
#   Parent comparison: existing asset_key membership and original fields.
#   No evidence joins or source-grain aggregation.
#   Summary: each asset contributes once to its mask/qualification/context group.
#   No arbitrary first-row selection or manufactured one-to-one lineage.
#
# Observation != identity.
# Structural Nmap linkage != independent enterprise identity.
# Independent network attribution != Post ownership.
# CMDB registration != current physical observation.
# Historical evidence != current operational control.
# Existing Discovery 002 assessments remain existing assessments only.
#
# No source reads, Tenable/Nmap re-analysis, new scores, identity merging,
# Asset Plane mutation, Delta writes, routing, workload, cases, findings,
# tickets, remediation, MDE work, or Databricks recovery.
#
# Would this exact analytical logic run for Paris if Paris reaches this family?
# YES. Membership, masks, counts, and assessments are runtime evidence.
# ============================================================================

from pyspark.sql import DataFrame
from pyspark.sql import functions as F


for _c34_name in tuple(globals()):
    if _c34_name.startswith("RCAIP_DIAG001_CELL34_"):
        del globals()[_c34_name]
del _c34_name

RCAIP_DIAG001_CELL34_READY = False


def _build_cell34():
    def require(condition, message):
        if not condition:
            raise RuntimeError("Cell 34 STOP: " + message)

    required = [
        "RCAIP_DIAG001_CELL33_READY",
        "RCAIP_DIAG001_CELL33_POST_SLUG",
        "RCAIP_DIAG001_CELL33_RUN_ID",
        "RCAIP_DIAG001_CELL33_PARENT_COHORT_ID",
        "RCAIP_DIAG001_CELL33_PARENT_RESUME_DF",
        "RCAIP_DIAG001_CELL33_SOURCE_FAMILY_STATUS_DF",
        "RCAIP_DIAG001_CELL33_NEXT_SOURCE_FAMILY",
        "RCAIP_DIAG001_CELL33_NEXT_ASSET_COUNT",
        "RCAIP_DIAG001_CELL33_NEXT_SOURCE_FAMILY_DF",
        "RCAIP_DIAG001_CELL33_NEXT_GATE",
    ]
    missing = sorted(name for name in required if name not in globals())
    require(not missing, "Missing runtime objects: " + " | ".join(missing))
    require(RCAIP_DIAG001_CELL33_READY is True, "Cell 33 is not ready.")

    family = RCAIP_DIAG001_CELL33_NEXT_SOURCE_FAMILY

    # Branch applicability only. Cell 33 performed dynamic family selection.
    require(
        family == "NMAP_MULTI_SOURCE",
        "Selected family requires a different analytical continuation.",
    )
    require(
        RCAIP_DIAG001_CELL33_NEXT_GATE
        == "SOURCE_FAMILY_ATTRIBUTION_QUALIFICATION",
        "Unexpected Cell 33 continuation gate.",
    )

    post_slug = RCAIP_DIAG001_CELL33_POST_SLUG
    run_id = RCAIP_DIAG001_CELL33_RUN_ID
    parent_id = RCAIP_DIAG001_CELL33_PARENT_COHORT_ID
    require(
        bool(post_slug) and bool(run_id) and bool(parent_id),
        "Blank Cell 33 scope.",
    )

    candidates = RCAIP_DIAG001_CELL33_NEXT_SOURCE_FAMILY_DF
    parent = RCAIP_DIAG001_CELL33_PARENT_RESUME_DF
    family_status = RCAIP_DIAG001_CELL33_SOURCE_FAMILY_STATUS_DF

    def need(df, columns, label):
        require(isinstance(df, DataFrame), label + " is not a DataFrame.")
        require(
            len(df.columns) == len(set(df.columns)),
            label + " has duplicate column names.",
        )
        absent = sorted(set(columns) - set(df.columns))
        require(
            not absent,
            label + " missing required columns: " + " | ".join(absent),
        )

    def reject(df, condition, message):
        require(df.filter(condition).limit(1).count() == 0, message)

    def asset_count(df, label):
        need(df, ["asset_key"], label)
        reject(
            df,
            F.col("asset_key").isNull()
            | (F.trim(F.col("asset_key")) == ""),
            label + " has a blank asset_key.",
        )
        reject(
            df.groupBy("asset_key").count(),
            F.col("count") != 1,
            label + " is not one row per asset_key.",
        )
        return df.count()

    def same_assets(left, right, label):
        left_keys = left.select("asset_key")
        right_keys = right.select("asset_key")
        require(
            left_keys.join(right_keys, "asset_key", "left_anti")
            .limit(1).count() == 0
            and right_keys.join(left_keys, "asset_key", "left_anti")
            .limit(1).count() == 0,
            label + " has missing or additional assets.",
        )

    def same_rows(left, right, columns, label):
        left_projection = left.select(*columns)
        right_projection = right.select(*columns)
        require(
            left_projection.exceptAll(right_projection).limit(1).count() == 0
            and right_projection.exceptAll(left_projection).limit(1).count() == 0,
            label + " changed.",
        )

    def optional_text(name):
        return (
            F.col(name).cast("string")
            if name in candidates.columns
            else F.lit(None).cast("string")
        )

    def optional_field(name, data_type):
        return (
            F.col(name).cast(data_type)
            if name in candidates.columns
            else F.lit(None).cast(data_type)
        )

    def has_text(expression):
        return expression.isNotNull() & (F.length(F.trim(expression)) > 0)

    # -----------------------------------------------------------------------
    # 1. Certified structural handoff and exact candidate authority.
    # -----------------------------------------------------------------------

    structural_columns = [
        "asset_key",
        "post_slug",
        "rcaip_run_id",
        "source_family",
        "source_mask_active",
        "c31_parent_cohort_id",
        "c33_resume_state",
        "discovery002_coverage_state",
        "_d002_present",
        "d002_attribution_evidence_status",
        "ip005_primary_case_type",
    ]
    need(parent, structural_columns, "Cell 33 parent")
    need(candidates, structural_columns, "Cell 33 selected candidates")
    require(
        candidates.columns == parent.columns,
        "Selected candidates do not retain the exact parent column contract.",
    )
    require(
        not any(name.startswith("c34_") for name in candidates.columns),
        "Candidates already contain Cell 34 annotations.",
    )
    need(
        family_status,
        [
            "source_family",
            "asset_count",
            "source_masks",
            "analytical_state",
            "eligible_for_next_selection",
            "selected_next",
        ],
        "Cell 33 source-family status",
    )

    candidate_types = {
        item.name: item.dataType.simpleString()
        for item in candidates.schema.fields
    }
    for name in [
        "discovery002_coverage_state",
        "d002_attribution_evidence_status",
        "ip005_primary_case_type",
    ]:
        require(
            candidate_types[name] == "string",
            name + " must retain its certified string contract.",
        )
    require(
        candidate_types["_d002_present"] == "boolean",
        "_d002_present must retain its certified boolean contract.",
    )

    parent_count = asset_count(parent, "Cell 33 parent")
    starting = asset_count(candidates, "Cell 33 selected candidates")
    require(
        starting > 0
        and starting == RCAIP_DIAG001_CELL33_NEXT_ASSET_COUNT,
        "Selected denominator differs from the Cell 33 scalar.",
    )

    for df, label in [(parent, "Parent"), (candidates, "Candidates")]:
        reject(
            df,
            ~F.col("post_slug").eqNullSafe(F.lit(post_slug))
            | ~F.col("rcaip_run_id").eqNullSafe(F.lit(run_id))
            | ~F.col("c31_parent_cohort_id").eqNullSafe(F.lit(parent_id)),
            label + " contains another or null Post/run/parent scope.",
        )

    expected_candidates = parent.filter(F.col("source_family") == family)
    same_assets(candidates, expected_candidates, "Selected family membership")
    same_rows(
        candidates,
        expected_candidates,
        parent.columns,
        "Selected original parent fields",
    )
    reject(
        candidates,
        ~F.col("c33_resume_state").eqNullSafe(
            F.lit("AWAITING_SOURCE_FAMILY_QUALIFICATION")
        ),
        "Selected assets are not awaiting source-family qualification.",
    )

    selected_status_rows = family_status.filter(
        F.col("selected_next") == True
    ).collect()
    require(
        len(selected_status_rows) == 1,
        "Cell 33 does not identify exactly one selected source family.",
    )
    selected_status = selected_status_rows[0]
    require(
        selected_status["source_family"] == family
        and selected_status["asset_count"] == starting
        and selected_status["eligible_for_next_selection"] is True
        and selected_status["analytical_state"]
        == "AWAITING_SOURCE_FAMILY_QUALIFICATION",
        "Selected-family status disagrees with its candidates.",
    )

    # Validate existing family membership without selecting a family or
    # treating source count as confidence.
    mask = F.upper(F.trim(F.col("source_mask_active")))
    tokens = F.split(mask, r"\|")
    non_nmap_tokens = F.array_except(tokens, F.array(F.lit("NMAP")))

    reject(
        candidates,
        mask.isNull()
        | (mask == "")
        | (mask == "NMAP")
        | ~F.array_contains(tokens, "NMAP")
        | F.array_contains(tokens, "")
        | (F.size(tokens) != F.size(F.array_distinct(tokens)))
        | (F.size(non_nmap_tokens) == 0),
        "A selected mask violates the existing multi-source contract.",
    )

    actual_masks = [
        row["source_mask_active"]
        for row in candidates.select("source_mask_active").distinct().collect()
    ]
    require(
        sorted(actual_masks) == sorted(selected_status["source_masks"] or []),
        "Selected masks differ from Cell 33 source-family accounting.",
    )

    # -----------------------------------------------------------------------
    # 2. Consume Cell 26 coverage exactly; do not rebuild its taxonomy.
    # -----------------------------------------------------------------------

    coverage_present = "DISCOVERY002_DISPOSITION_PRESENT"
    coverage_gap = "DISCOVERY002_EXPECTED_BUT_MISSING"
    coverage_outside = "OUTSIDE_DISCOVERY002_CANDIDATE_CONTRACT"
    coverage_review = "DISCOVERY002_COVERAGE_STATE_REQUIRES_REVIEW"

    recognized_coverage = [
        coverage_present,
        coverage_gap,
        coverage_outside,
    ]
    known_statuses = [
        "CONSISTENT_MULTI_SOURCE_ATTRIBUTION_SEED",
        "MULTI_SOURCE_PRIMARY_WITH_SECONDARY_VARIANCE",
        "CROSS_SOURCE_ATTRIBUTION_CONFLICT",
        "STRONG_SINGLE_SOURCE_ATTRIBUTION_SEED",
        "MODERATE_SINGLE_SOURCE_ATTRIBUTION_EVIDENCE",
        "NO_USABLE_ATTRIBUTION_SIGNAL",
    ]

    coverage = F.col("discovery002_coverage_state")
    recorded_status = F.col("d002_attribution_evidence_status")
    present_flag = F.col("_d002_present")

    # _d002_present participates only in consistency certification.
    # Null is valid for a non-present row from the upstream left join.
    reject(
        candidates,
        (coverage == coverage_present)
        & ~present_flag.eqNullSafe(F.lit(True)),
        "Disposition-present coverage disagrees with _d002_present.",
    )
    reject(
        candidates,
        coverage.isin(coverage_gap, coverage_outside)
        & present_flag.eqNullSafe(F.lit(True)),
        "Non-present coverage incorrectly claims a present disposition.",
    )

    boundary_state = (
        F.when(
            coverage == coverage_present,
            F.lit("DISCOVERY002_ASSESSMENT_PRESENT"),
        )
        .when(
            coverage == coverage_gap,
            F.lit("DISCOVERY002_EXPECTED_COVERAGE_GAP"),
        )
        .when(coverage == coverage_outside, F.lit(coverage_outside))
        .otherwise(F.lit(coverage_review))
    )

    boundary_reason = (
        F.when(
            (coverage == coverage_present)
            & recorded_status.isin(*known_statuses),
            F.lit("EXISTING_CERTIFIED_DISCOVERY002_ASSESSMENT_PRESERVED"),
        )
        .when(
            coverage == coverage_present,
            F.lit("DISPOSITION_PRESENT_WITH_BLANK_OR_UNRECOGNIZED_STATUS"),
        )
        .when(
            coverage == coverage_gap,
            F.lit("CELL26_EXPECTED_COVERAGE_WITHOUT_CERTIFIED_DISPOSITION"),
        )
        .when(
            coverage == coverage_outside,
            F.lit(
                "DISPOSITION_NOT_REQUIRED_BY_DISCOVERY002_CANDIDATE_CONTRACT"
            ),
        )
        .otherwise(F.lit("NULL_OR_UNRECOGNIZED_CELL26_COVERAGE_STATE"))
    )

    qualification_state = (
        F.when(
            (coverage == coverage_present)
            & recorded_status.isin(*known_statuses),
            recorded_status,
        )
        .when(
            coverage == coverage_present,
            F.lit("ATTRIBUTION_STATUS_REQUIRES_REVIEW"),
        )
        .when(
            coverage == coverage_gap,
            F.lit("DISCOVERY002_COVERAGE_GAP"),
        )
        .when(coverage == coverage_outside, F.lit(coverage_outside))
        .otherwise(F.lit(coverage_review))
    )

    # -----------------------------------------------------------------------
    # 3. Preserve independent observation, registration, and context dimensions.
    # -----------------------------------------------------------------------

    context_fields = [
        "identity_basis",
        "identity_strength",
        "management_model",
        "management_owner",
        "current_observation_status",
        "source_mask_stale",
        "attribution_confidence",
        "attribution_conflict_flag",
        "conflict_count",
        "ip005_primary_case_type",
        "ip005_cmdb_present_flag",
        "ip005_current_evidence_flag",
        "ip005_stale_evidence_flag",
    ]
    context_notes = []
    for name in context_fields:
        if name not in candidates.columns:
            context_notes.append(F.lit("FIELD_NOT_CARRIED:" + name))
        else:
            context_notes.append(
                F.when(
                    ~has_text(optional_text(name)),
                    F.lit("VALUE_NOT_POPULATED:" + name),
                )
            )

    context_limitations = F.filter(
        F.array(*context_notes), lambda value: value.isNotNull()
    )

    # CMDB denotes registration in the active mask, not a second current
    # tool observation. No source-token count becomes attribution confidence.
    other_observation_tokens = F.array_except(
        tokens, F.array(F.lit("NMAP"), F.lit("CMDB"))
    )
    observation_context = (
        F.when(
            F.size(other_observation_tokens) > 0,
            F.lit("MULTI_SOURCE_ACTIVE_OBSERVATION_CONTEXT"),
        )
        .otherwise(
            F.lit("NMAP_OBSERVATION_WITH_CMDB_REGISTRATION_CONTEXT")
        )
    )

    attribution_conflict = optional_field(
        "attribution_conflict_flag", "boolean"
    )
    inherited_conflict_count = optional_field("conflict_count", "long")
    review_context = (
        F.when(
            attribution_conflict == True,
            F.lit("ATTRIBUTION_CONFLICT_RECORDED"),
        )
        .when(
            inherited_conflict_count > 0,
            F.lit("OTHER_CONFLICT_CONTEXT_RECORDED"),
        )
        .when(
            attribution_conflict.isNull() | inherited_conflict_count.isNull(),
            F.lit("CONFLICT_CONTEXT_INCOMPLETE"),
        )
        .otherwise(F.lit("NO_CONFLICT_RECORDED_IN_CONSUMED_FIELDS"))
    )

    qualified = (
        candidates
        .withColumn(
            "c34_discovery002_coverage_state",
            F.col("discovery002_coverage_state"),
        )
        .withColumn("c34_observation_context", observation_context)
        .withColumn(
            "c34_cmdb_registration_context",
            F.array_contains(tokens, "CMDB"),
        )
        .withColumn(
            "c34_attribution_evidence_boundary_state",
            boundary_state,
        )
        .withColumn(
            "c34_attribution_evidence_boundary_reason",
            boundary_reason,
        )
        .withColumn("c34_qualification_state", qualification_state)
        .withColumn("c34_existing_review_context", review_context)
        .withColumn("c34_context_limitations", context_limitations)
        .withColumn(
            "c34_independent_identity_corroboration_state",
            F.lit("NOT_ASSESSED_FROM_SOURCE_PRESENCE"),
        )
        .withColumn(
            "c34_interpretation_limit",
            F.lit(
                "Existing identity context and attribution assessments are "
                "preserved. This handoff qualification does not certify an "
                "independent network-to-enterprise identity relationship or "
                "Post ownership. Outside the Discovery 002 candidate contract "
                "is a valid nonfailure state."
            ),
        )
        .withColumn(
            "c34_post_attribution_state",
            F.lit("NOT_ESTABLISHED_BY_THIS_CELL"),
        )
        .withColumn("c34_customer_routing_performed", F.lit(False))
        .withColumn("c34_workload_promotion_authorized", F.lit(False))
    )

    # Each asset contributes to exactly one summary group. Raw coverage,
    # source-mask patterns, and orthogonal evidence dimensions remain explicit.
    summary_columns = [
        "source_family",
        "source_mask_active",
        "c34_discovery002_coverage_state",
        "c34_observation_context",
        "c34_cmdb_registration_context",
        "c34_attribution_evidence_boundary_state",
        "c34_attribution_evidence_boundary_reason",
        "c34_qualification_state",
        "c34_existing_review_context",
    ] + [
        name for name in [
            "identity_basis",
            "identity_strength",
            "management_model",
            "management_owner",
            "current_observation_status",
            "source_mask_stale",
            "ip005_primary_case_type",
            "ip005_cmdb_present_flag",
            "ip005_current_evidence_flag",
            "ip005_stale_evidence_flag",
        ]
        if name in candidates.columns
    ]

    summary = (
        qualified.groupBy(*summary_columns)
        .agg(F.count(F.lit(1)).alias("asset_count"))
        .orderBy(
            "source_mask_active",
            "c34_discovery002_coverage_state",
            "c34_qualification_state",
        )
    )

    # -----------------------------------------------------------------------
    # 4. Conservation and coverage-semantic certification.
    # -----------------------------------------------------------------------

    ending = asset_count(qualified, "Cell 34 qualified output")
    require(ending == starting, "The selected denominator changed.")
    same_assets(qualified, candidates, "Cell 34 candidate conservation")
    same_rows(
        qualified, candidates, candidates.columns,
        "Every inherited candidate field",
    )

    reject(
        qualified,
        ~F.col("c34_discovery002_coverage_state")
        .eqNullSafe(F.col("discovery002_coverage_state")),
        "Raw Discovery 002 coverage state was changed.",
    )

    output_state = F.col("c34_qualification_state")
    output_boundary = F.col("c34_attribution_evidence_boundary_state")
    known_coverage_row = F.coalesce(
        coverage.isin(*recognized_coverage), F.lit(False)
    )

    allowed_states = known_statuses + [
        "ATTRIBUTION_STATUS_REQUIRES_REVIEW",
        "DISCOVERY002_COVERAGE_GAP",
        coverage_outside,
        coverage_review,
    ]
    reject(
        qualified,
        output_state.isNull() | ~output_state.isin(*allowed_states),
        "An asset lacks an explicit qualification.",
    )
    reject(
        qualified,
        ~known_coverage_row
        & (
            ~output_state.eqNullSafe(F.lit(coverage_review))
            | ~output_boundary.eqNullSafe(F.lit(coverage_review))
        ),
        "Null/unrecognized coverage was not explicitly retained as review.",
    )
    reject(
        qualified,
        (coverage == coverage_gap)
        & (
            ~output_state.eqNullSafe(F.lit("DISCOVERY002_COVERAGE_GAP"))
            | ~output_boundary.eqNullSafe(
                F.lit("DISCOVERY002_EXPECTED_COVERAGE_GAP")
            )
        ),
        "Expected-but-missing coverage lost its coverage-gap meaning.",
    )
    reject(
        qualified,
        (coverage == coverage_outside)
        & (
            ~output_state.eqNullSafe(F.lit(coverage_outside))
            | ~output_boundary.eqNullSafe(F.lit(coverage_outside))
        ),
        "Outside-contract coverage was changed into a gap or failure.",
    )
    reject(
        qualified,
        output_state.isin(*known_statuses)
        & (
            ~coverage.eqNullSafe(F.lit(coverage_present))
            | ~output_state.eqNullSafe(recorded_status)
        ),
        "A known attribution status was invented or used outside present coverage.",
    )
    reject(
        qualified,
        (coverage == coverage_present)
        & (
            ~present_flag.eqNullSafe(F.lit(True))
            | ~output_boundary.eqNullSafe(
                F.lit("DISCOVERY002_ASSESSMENT_PRESENT")
            )
        ),
        "Present-disposition consistency was not preserved.",
    )
    reject(
        qualified,
        (coverage == coverage_present)
        & F.coalesce(recorded_status.isin(*known_statuses), F.lit(False))
        & ~output_state.eqNullSafe(recorded_status),
        "A known present-disposition status was not preserved exactly.",
    )
    reject(
        qualified,
        (coverage == coverage_present)
        & ~F.coalesce(recorded_status.isin(*known_statuses), F.lit(False))
        & ~output_state.eqNullSafe(
            F.lit("ATTRIBUTION_STATUS_REQUIRES_REVIEW")
        ),
        "Blank/unrecognized present-disposition status was not retained as review.",
    )

    summary_total = summary.agg(
        F.sum("asset_count").alias("asset_count")
    ).collect()[0]["asset_count"]
    require(summary_total == starting, "Summary denominator does not reconcile.")

    state_counts = (
        qualified.groupBy(
            "source_mask_active",
            "c34_discovery002_coverage_state",
            "c34_attribution_evidence_boundary_state",
            "c34_qualification_state",
        )
        .agg(F.count(F.lit(1)).alias("asset_count"))
        .orderBy(
            "source_mask_active",
            "c34_discovery002_coverage_state",
            "c34_qualification_state",
        )
        .collect()
    )
    require(
        sum(int(row["asset_count"]) for row in state_counts) == starting,
        "Qualification populations do not reconcile to all selected assets.",
    )

    # No upstream objects are overwritten. Parent-resume accounting belongs
    # to Cell 35, which will consume these preserved asset-grain annotations.
    print("RCAIP DIAG 001 - CELL 34 CERTIFICATION")
    print("Status: PASS - inherited-evidence qualification only")
    print("Source family:", family)
    print("Starting selected assets:", starting)
    print("Accounted selected assets:", ending)
    print("Other assets retained in Cell 33 parent:", parent_count - starting)
    print("Runtime source-mask patterns:", sorted(actual_masks))

    for row in state_counts:
        print(
            "Qualification:",
            row["source_mask_active"],
            row["c34_discovery002_coverage_state"],
            row["c34_attribution_evidence_boundary_state"],
            row["c34_qualification_state"],
            row["asset_count"],
        )

    print("Original candidate fields / scope / family / masks preserved: YES")
    print("Raw Cell 26 Discovery 002 coverage preserved exactly: YES")
    print("Present coverage / disposition flag consistency: PASS")
    print("Expected coverage gap distinguished from outside-contract: YES")
    print("Null/unrecognized coverage retained as explicit review: YES")
    print("Known attribution statuses used only for present dispositions: YES")
    print("Outside-contract treated as unavailable evidence or failure: NO")
    print("Duplicate / lost / additional candidate assets: NONE")
    print("Independent identity corroboration newly certified: NO")
    print("Source presence used as attribution confidence: NO")
    print("Parent and other source-family objects modified: NO")
    print("Source reads / matching / MDE work / Delta writes: NONE")
    print("Routing / workload / cases / findings / tickets / remediation: NONE")
    print("Next gate: ATTRIBUTION_COHORT_RESUME")
    print("Would this exact analytical logic run for Paris? YES, on this branch.")

    return {
        "RCAIP_DIAG001_CELL34_POST_SLUG": post_slug,
        "RCAIP_DIAG001_CELL34_RUN_ID": run_id,
        "RCAIP_DIAG001_CELL34_SOURCE_FAMILY": family,
        "RCAIP_DIAG001_CELL34_STARTING_ASSET_COUNT": starting,
        "RCAIP_DIAG001_CELL34_QUALIFIED_DF": qualified,
        "RCAIP_DIAG001_CELL34_QUALIFICATION_SUMMARY_DF": summary,
        "RCAIP_DIAG001_CELL34_NEXT_GATE": "ATTRIBUTION_COHORT_RESUME",
    }


_c34_publications = _build_cell34()
globals().update(_c34_publications)
RCAIP_DIAG001_CELL34_READY = True

del _c34_publications
del _build_cell34
# COMMAND ----------
# ============================================================================
# RCAIP DIAG 001
# Cell 35 - Attribution Cohort Resume After Multi-Source Qualification
#
# Runtime handoffs only. Resume/accounting/next-selection only.
#
# Authoritative denominator:
#   Exact Cell 33 parent, one row per asset_key.
#
# Completion authority:
#   Successful Cell 34 handoff for exactly the Cell 33 selected family.
#   Qualification completion does not imply attribution resolution.
#
# Preserve:
#   Every original parent field, including earlier qualification annotations.
#   Every additive Cell 34 field, without reinterpretation.
#   Cell 34 summary in its original runtime object.
#   Separate parked MDE-history membership and original handoffs.
#
# No source reads, source analysis, matching, Discovery 002/IP-005 recomputation,
# MDE work, Delta writes, Asset Plane mutation, identity merging, routing,
# workload promotion, cases, findings, tickets, remediation, or recovery.
#
# Would this exact Cell 35 logic run for Paris?
# YES. Processed and next families and all counts come from runtime handoffs.
# Population size sequences analytical work only.
# ============================================================================

from pyspark.sql import DataFrame
from pyspark.sql import functions as F


for _c35_name in tuple(globals()):
    if _c35_name.startswith("RCAIP_DIAG001_CELL35_"):
        del globals()[_c35_name]
del _c35_name

RCAIP_DIAG001_CELL35_READY = False


def _build_cell35():
    def require(condition, message):
        if not condition:
            raise RuntimeError("Cell 35 STOP: " + message)

    required = [
        "RCAIP_DIAG001_CELL33_READY",
        "RCAIP_DIAG001_CELL33_POST_SLUG",
        "RCAIP_DIAG001_CELL33_RUN_ID",
        "RCAIP_DIAG001_CELL33_PARENT_COHORT_ID",
        "RCAIP_DIAG001_CELL33_PARENT_RESUME_DF",
        "RCAIP_DIAG001_CELL33_SOURCE_FAMILY_STATUS_DF",
        "RCAIP_DIAG001_CELL33_NEXT_SOURCE_FAMILY",
        "RCAIP_DIAG001_CELL33_NEXT_ASSET_COUNT",
        "RCAIP_DIAG001_CELL33_NEXT_SOURCE_FAMILY_DF",
        "RCAIP_DIAG001_CELL34_READY",
        "RCAIP_DIAG001_CELL34_POST_SLUG",
        "RCAIP_DIAG001_CELL34_RUN_ID",
        "RCAIP_DIAG001_CELL34_SOURCE_FAMILY",
        "RCAIP_DIAG001_CELL34_STARTING_ASSET_COUNT",
        "RCAIP_DIAG001_CELL34_QUALIFIED_DF",
        "RCAIP_DIAG001_CELL34_QUALIFICATION_SUMMARY_DF",
        "RCAIP_DIAG001_CELL34_NEXT_GATE",
    ]
    missing = sorted(name for name in required if name not in globals())
    require(not missing, "Missing runtime objects: " + " | ".join(missing))
    require(RCAIP_DIAG001_CELL33_READY is True, "Cell 33 is not ready.")
    require(RCAIP_DIAG001_CELL34_READY is True, "Cell 34 is not ready.")

    post_slug = RCAIP_DIAG001_CELL33_POST_SLUG
    run_id = RCAIP_DIAG001_CELL33_RUN_ID
    parent_id = RCAIP_DIAG001_CELL33_PARENT_COHORT_ID
    processed_family = RCAIP_DIAG001_CELL34_SOURCE_FAMILY

    require(
        bool(post_slug) and bool(run_id) and bool(parent_id)
        and bool(processed_family),
        "Blank runtime scope or processed family.",
    )
    require(
        RCAIP_DIAG001_CELL34_POST_SLUG == post_slug
        and RCAIP_DIAG001_CELL34_RUN_ID == run_id,
        "Cell 33 and Cell 34 Post/run scopes disagree.",
    )
    require(
        processed_family == RCAIP_DIAG001_CELL33_NEXT_SOURCE_FAMILY,
        "Cell 34 family differs from the Cell 33 selected family.",
    )
    require(
        RCAIP_DIAG001_CELL34_NEXT_GATE == "ATTRIBUTION_COHORT_RESUME",
        "Unexpected Cell 34 continuation gate.",
    )

    parent = RCAIP_DIAG001_CELL33_PARENT_RESUME_DF
    selected = RCAIP_DIAG001_CELL33_NEXT_SOURCE_FAMILY_DF
    prior_status = RCAIP_DIAG001_CELL33_SOURCE_FAMILY_STATUS_DF
    qualified = RCAIP_DIAG001_CELL34_QUALIFIED_DF
    qualification_summary = RCAIP_DIAG001_CELL34_QUALIFICATION_SUMMARY_DF

    completed = "QUALIFICATION_PRESERVED_PARENT_RESUMED"
    awaiting = "AWAITING_SOURCE_FAMILY_QUALIFICATION"

    def need(df, columns, label):
        require(isinstance(df, DataFrame), label + " is not a DataFrame.")
        require(
            len(df.columns) == len(set(df.columns)),
            label + " has duplicate column names.",
        )
        absent = sorted(set(columns) - set(df.columns))
        require(
            not absent,
            label + " missing columns: " + " | ".join(absent),
        )

    def reject(df, condition, message):
        require(df.filter(condition).limit(1).count() == 0, message)

    def blank(name):
        return F.col(name).isNull() | (F.trim(F.col(name)) == "")

    def asset_count(df, label):
        need(df, ["asset_key"], label)
        reject(df, blank("asset_key"), label + " has blank asset keys.")
        reject(
            df.groupBy("asset_key").count(),
            F.col("count") != 1,
            label + " is not one row per asset.",
        )
        return df.count()

    def same_assets(left, right, label):
        left_keys = left.select("asset_key")
        right_keys = right.select("asset_key")
        require(
            left_keys.join(right_keys, "asset_key", "left_anti")
            .limit(1).count() == 0
            and right_keys.join(left_keys, "asset_key", "left_anti")
            .limit(1).count() == 0,
            label + " has missing or orphan assets.",
        )

    def same_rows(left, right, columns, label):
        left_projection = left.select(*columns)
        right_projection = right.select(*columns)
        require(
            left_projection.exceptAll(right_projection).limit(1).count() == 0
            and right_projection.exceptAll(left_projection).limit(1).count() == 0,
            label + " changed.",
        )

    # -----------------------------------------------------------------------
    # 1. Validate exact parent and selected-family handoffs.
    # -----------------------------------------------------------------------

    need(
        parent,
        [
            "asset_key", "post_slug", "rcaip_run_id",
            "source_family", "source_mask_active",
            "c31_parent_cohort_id", "c31_history_candidate",
            "c33_resume_state",
        ],
        "Cell 33 parent",
    )
    require(
        not any(name.startswith(("c34_", "c35_")) for name in parent.columns),
        "Cell 33 parent unexpectedly contains later-cell annotations.",
    )
    need(selected, parent.columns, "Cell 33 selected family")
    need(qualified, parent.columns, "Cell 34 qualified assets")
    require(
        selected.columns == parent.columns,
        "Cell 33 selected-family columns differ from its parent.",
    )
    need(
        prior_status,
        [
            "source_family", "asset_count", "source_masks",
            "analytical_state", "eligible_for_next_selection", "selected_next",
        ],
        "Cell 33 source-family status",
    )

    parent_count = asset_count(parent, "Cell 33 parent")
    selected_count = asset_count(selected, "Cell 33 selected family")
    qualified_count = asset_count(qualified, "Cell 34 qualified assets")

    for df, label in [
        (parent, "Cell 33 parent"),
        (selected, "Cell 33 selected family"),
        (qualified, "Cell 34 qualified assets"),
    ]:
        reject(
            df,
            ~F.col("post_slug").eqNullSafe(F.lit(post_slug))
            | ~F.col("rcaip_run_id").eqNullSafe(F.lit(run_id))
            | ~F.col("c31_parent_cohort_id").eqNullSafe(F.lit(parent_id)),
            label + " contains another or null Post/run/parent scope.",
        )

    reject(parent, blank("source_family"), "Parent has a blank source family.")
    require(
        selected_count > 0
        and selected_count == RCAIP_DIAG001_CELL33_NEXT_ASSET_COUNT
        and selected_count == RCAIP_DIAG001_CELL34_STARTING_ASSET_COUNT
        and selected_count == qualified_count,
        "Selected, starting, and qualified denominators disagree.",
    )

    expected_selected = parent.filter(
        F.col("source_family") == processed_family
    )
    same_assets(selected, expected_selected, "Cell 33 selected membership")
    same_assets(qualified, selected, "Cell 34 selected membership")
    same_rows(
        selected, expected_selected, parent.columns,
        "Cell 33 selected parent fields",
    )
    same_rows(
        qualified, selected, parent.columns,
        "Cell 34 inherited parent fields",
    )

    annotation_columns = [
        name for name in qualified.columns if name not in parent.columns
    ]
    require(
        bool(annotation_columns)
        and all(name.startswith("c34_") for name in annotation_columns),
        "Cell 34 must publish only c34_-prefixed additive fields.",
    )

    # -----------------------------------------------------------------------
    # 2. Validate Cell 34's published summary without rerunning its analysis.
    # -----------------------------------------------------------------------

    need(
        qualification_summary,
        ["asset_count", "c34_qualification_state"],
        "Cell 34 qualification summary",
    )
    summary_dimensions = [
        name for name in qualification_summary.columns
        if name != "asset_count"
    ]
    need(qualified, summary_dimensions, "Cell 34 summary dimensions")
    require(bool(summary_dimensions), "Cell 34 summary lacks dimensions.")

    # Cell 34 publishes only dimensions plus count-of-assets. Use those exact
    # dimensions, including raw coverage and all published context dimensions.
    recomputed_summary = qualified.groupBy(*summary_dimensions).agg(
        F.count(F.lit(1)).alias("asset_count")
    )
    same_rows(
        recomputed_summary,
        qualification_summary,
        summary_dimensions + ["asset_count"],
        "Exact Cell 34 qualification summary accounting",
    )

    summary_total = qualification_summary.agg(
        F.sum("asset_count").alias("asset_count")
    ).collect()[0]["asset_count"]
    require(
        summary_total == qualified_count,
        "Cell 34 summary does not reconcile to its qualified denominator.",
    )

    # Original Cell 34 summary remains untouched and is not republished.
    # No coverage/qualification enum is remapped or required to be resolved.

    # -----------------------------------------------------------------------
    # 3. Certify existing source-family membership and completion authority.
    # -----------------------------------------------------------------------

    reject(
        prior_status, blank("source_family"),
        "Cell 33 status has a blank source family.",
    )
    reject(
        prior_status.groupBy("source_family").count(),
        F.col("count") != 1,
        "Cell 33 status is not one row per source family.",
    )

    membership = parent.groupBy("source_family").agg(
        F.count(F.lit(1)).alias("asset_count"),
        F.sort_array(F.collect_set("source_mask_active")).alias("source_masks"),
    )
    same_rows(
        membership, prior_status,
        ["source_family", "asset_count", "source_masks"],
        "Existing source-family accounting",
    )

    prior_rows = prior_status.collect()
    require(
        all(
            row["analytical_state"] in (completed, awaiting)
            and row["eligible_for_next_selection"]
            == (row["analytical_state"] == awaiting)
            and row["selected_next"]
            == (row["source_family"] == processed_family)
            for row in prior_rows
        ),
        "Existing family states or selected-family flags are inconsistent.",
    )
    processed_rows = [
        row for row in prior_rows
        if row["source_family"] == processed_family
    ]
    require(
        len(processed_rows) == 1
        and processed_rows[0]["analytical_state"] == awaiting
        and processed_rows[0]["asset_count"] == selected_count,
        "Processed family was not the selected awaiting family.",
    )

    parent_state_check = parent.join(
        prior_status.select(
            "source_family",
            F.col("analytical_state").alias("_c35_prior_state"),
        ),
        "source_family",
        "left",
    )
    reject(
        parent_state_check,
        ~F.col("c33_resume_state").eqNullSafe(F.col("_c35_prior_state")),
        "Cell 33 parent and source-family analytical states disagree.",
    )

    completed_before = sum(
        int(row["asset_count"]) for row in prior_rows
        if row["analytical_state"] == completed
    )

    # Successful Cell 34 handoff authorizes completion of this qualification
    # step only. Its analytical outcomes do not control completion/selection.
    family_status = (
        prior_status
        .withColumn(
            "analytical_state",
            F.when(
                F.col("source_family") == processed_family,
                F.lit(completed),
            ).otherwise(F.col("analytical_state")),
        )
        .withColumn(
            "eligible_for_next_selection",
            F.col("analytical_state") == awaiting,
        )
    )

    remaining_rows = (
        family_status
        .filter(F.col("eligible_for_next_selection"))
        .orderBy(F.desc("asset_count"), F.asc("source_family"))
        .collect()
    )
    next_family = remaining_rows[0]["source_family"] if remaining_rows else None
    next_count = int(remaining_rows[0]["asset_count"]) if remaining_rows else 0
    next_gate = (
        "SOURCE_FAMILY_ATTRIBUTION_QUALIFICATION"
        if next_family is not None
        else "SOURCE_FAMILY_QUALIFICATION_COMPLETE"
    )
    next_condition = (
        F.col("source_family") == F.lit(next_family)
        if next_family is not None else F.lit(False)
    )

    family_status = (
        family_status
        .withColumn("selected_next", next_condition)
        .orderBy(F.desc("asset_count"), F.asc("source_family"))
    )

    # -----------------------------------------------------------------------
    # 4. Attach exact additive fields to the authoritative parent.
    # -----------------------------------------------------------------------

    parent_resume = (
        parent
        .join(
            qualified.select("asset_key", *annotation_columns),
            "asset_key",
            "left",
        )
        .join(
            family_status.select(
                "source_family",
                F.col("analytical_state").alias("c35_resume_state"),
            ),
            "source_family",
            "left",
        )
        .select(*parent.columns, *annotation_columns, "c35_resume_state")
    )
    next_df = parent_resume.filter(next_condition)

    # Historical c31/c33 fields remain unchanged. c35_resume_state records
    # this new resume boundary. No source products or earlier globals mutate.

    # -----------------------------------------------------------------------
    # 5. Certify preservation, status transition, overlay, and next selection.
    # -----------------------------------------------------------------------

    ending_count = asset_count(parent_resume, "Cell 35 resumed parent")
    next_actual_count = asset_count(next_df, "Cell 35 next family")
    require(ending_count == parent_count, "Parent denominator changed.")
    same_assets(parent_resume, parent, "Parent conservation")
    same_rows(parent_resume, parent, parent.columns, "Every original parent field")

    resumed_processed = parent_resume.filter(
        F.col("source_family") == processed_family
    )
    same_assets(resumed_processed, qualified, "Processed-family conservation")
    same_rows(
        resumed_processed, qualified, qualified.columns,
        "Every Cell 34 inherited and additive field",
    )
    same_rows(
        resumed_processed.groupBy(*summary_dimensions).agg(
            F.count(F.lit(1)).alias("asset_count")
        ),
        qualification_summary,
        summary_dimensions + ["asset_count"],
        "Preserved Cell 34 summary after parent attachment",
    )

    annotations_present = F.lit(False)
    for name in annotation_columns:
        annotations_present = annotations_present | F.col(name).isNotNull()
    reject(
        parent_resume.filter(F.col("source_family") != processed_family),
        annotations_present,
        "Cell 34 annotations appeared outside its exact processed membership.",
    )

    # Preserve all source-family fields except the explicitly updated state
    # and selection flags. Nonprocessed analytical states must be identical.
    unchanged_status_columns = [
        name for name in prior_status.columns
        if name not in {
            "analytical_state", "eligible_for_next_selection", "selected_next"
        }
    ]
    same_rows(
        family_status, prior_status, unchanged_status_columns,
        "Original source-family accounting fields",
    )
    same_rows(
        family_status.filter(F.col("source_family") != processed_family),
        prior_status.filter(F.col("source_family") != processed_family),
        ["source_family", "analytical_state"],
        "Nonprocessed source-family analytical states",
    )
    reject(
        parent_resume.filter(F.col("source_family") == processed_family),
        ~F.col("c35_resume_state").eqNullSafe(F.lit(completed)),
        "Processed family was not qualification-preserved/parent-resumed.",
    )
    reject(
        parent_resume.filter(F.col("source_family") != processed_family),
        ~F.col("c35_resume_state").eqNullSafe(F.col("c33_resume_state")),
        "An earlier completed or remaining family changed analytical state.",
    )
    reject(
        parent_resume,
        F.col("c35_resume_state").isNull(),
        "A parent asset lacks its current resume state.",
    )

    history_before = parent.filter(F.col("c31_history_candidate"))
    history_after = parent_resume.filter(F.col("c31_history_candidate"))
    same_assets(history_after, history_before, "Parked history overlay membership")
    history_count = history_before.count()
    require(
        history_after.count() == history_count,
        "Parked history overlay count changed.",
    )

    family_rows = family_status.collect()
    completed_count = sum(
        int(row["asset_count"]) for row in family_rows
        if row["analytical_state"] == completed
    )
    remaining_count = sum(
        int(row["asset_count"]) for row in family_rows
        if row["analytical_state"] == awaiting
    )
    require(
        completed_count == completed_before + selected_count,
        "Completion accounting differs from prior completion plus Cell 34.",
    )
    require(
        completed_count + remaining_count == parent_count,
        "Completed and remaining family counts do not reconcile to the parent.",
    )
    require(
        next_actual_count == next_count,
        "Next-family output differs from source-family accounting.",
    )
    same_assets(
        next_df,
        parent.filter(next_condition),
        "Next selection / existing source-family membership",
    )

    # No-family-remains is an analytical handoff, not attribution closure.
    require(
        next_family is not None or (
            next_count == 0
            and remaining_count == 0
            and next_gate == "SOURCE_FAMILY_QUALIFICATION_COMPLETE"
        ),
        "Empty remaining-family continuation is inconsistent.",
    )

    print("RCAIP DIAG 001 - CELL 35 CERTIFICATION")
    print("Status: PASS - resume/accounting only")
    print("Starting / preserved parent assets:", parent_count, ending_count)
    print("Qualification-preserved before Cell 34:", completed_before)
    print("Cell 34 processed family:", processed_family)
    print("Cell 34 selected / qualified assets:", selected_count, qualified_count)
    print("Qualification-preserved after resume:", completed_count)
    print("Assets awaiting source-family qualification:", remaining_count)
    print("Separate parked MDE-history overlay retained:", history_count)
    for row in family_rows:
        print(
            "Source family:",
            row["source_family"],
            row["asset_count"],
            row["analytical_state"],
        )
    print("Exact Cell 34 summary accounting: PASS; original object retained")
    print("Every original parent and Cell 34 field preserved: YES")
    print("Cell 34 annotations outside processed family: NONE")
    print("Duplicate / lost / orphan assets: NONE")
    print("Coverage-gap / outside-contract / review semantics rewritten: NO")
    print("Unresolved qualification blocks resume: NO")
    print("MDE-history overlay influences completion or selection: NO")
    print("Next source family:", next_family)
    print("Next source-family assets:", next_count)
    print("Next gate:", next_gate)
    print("Parent attribution / wider attribution branch closed: NO / NO")
    print("Source reads / writes / matching / recovery: NONE")
    print("Routing / workload / cases / findings / tickets / remediation: NONE")
    print("Would this exact Cell 35 logic run for Paris? YES")

    return {
        "RCAIP_DIAG001_CELL35_POST_SLUG": post_slug,
        "RCAIP_DIAG001_CELL35_RUN_ID": run_id,
        "RCAIP_DIAG001_CELL35_PARENT_COHORT_ID": parent_id,
        "RCAIP_DIAG001_CELL35_PARENT_RESUME_DF": parent_resume,
        "RCAIP_DIAG001_CELL35_SOURCE_FAMILY_STATUS_DF": family_status,
        "RCAIP_DIAG001_CELL35_NEXT_SOURCE_FAMILY": next_family,
        "RCAIP_DIAG001_CELL35_NEXT_ASSET_COUNT": next_count,
        "RCAIP_DIAG001_CELL35_NEXT_SOURCE_FAMILY_DF": next_df,
        "RCAIP_DIAG001_CELL35_NEXT_GATE": next_gate,
    }


_c35_publications = _build_cell35()
globals().update(_c35_publications)
RCAIP_DIAG001_CELL35_READY = True

del _c35_publications
del _build_cell35
# COMMAND ----------
# ============================================================================
# RCAIP DIAG 001
# Cell 36 - Tenable-Only Attribution / Observation Qualification
#
# Sole candidate authority:
#   Exact Cell 35 selected-family DataFrame, one row per asset_key.
#
# TENABLE_ONLY is an applicability guard, not a selection rule.
# Cell 35 already selected the next source family dynamically.
#
# Evidence:
#   Existing certified handoff fields only.
#   No Tenable/source reads, vulnerability/plugin analysis, or matching.
#
# Grain:
#   Candidates/output: one row per selected asset_key.
#   Parent comparison: exact existing asset_key membership and original fields.
#   Summary: each asset contributes once to its qualification/context group.
#   No evidence joins, multiplicity collapse, or arbitrary first-row selection.
#
# Preserve Cell 26 Discovery 002 coverage directly; never reconstruct it.
# Required-column absence is a contract failure, not unavailable evidence.
# Outside-contract coverage is valid and is not an evidence failure.
#
# Active Tenable presence != independent enterprise identity.
# Operational boundary != Post ownership.
# Management context != current physical presence.
# Historical evidence remains historical.
# Absence from an active/stale mask does not prove absolute historical absence.
#
# No source reads, new confidence scores, IP-only identity inference, raw
# acquisition, Nmap/MDE work, Delta writes, Asset Plane mutation, identity merge,
# routing, workload promotion, cases, findings, tickets, remediation, or recovery.
#
# Would this exact Cell 36 logic run for Paris if Cell 35 selected this family?
# YES. Counts, candidates, and evidence values are runtime data.
# ============================================================================

from pyspark.sql import DataFrame
from pyspark.sql import functions as F


for _c36_name in tuple(globals()):
    if _c36_name.startswith("RCAIP_DIAG001_CELL36_"):
        del globals()[_c36_name]
del _c36_name

RCAIP_DIAG001_CELL36_READY = False


def _build_cell36():
    def require(condition, message):
        if not condition:
            raise RuntimeError("Cell 36 STOP: " + message)

    required = [
        "RCAIP_DIAG001_CELL35_READY",
        "RCAIP_DIAG001_CELL35_POST_SLUG",
        "RCAIP_DIAG001_CELL35_RUN_ID",
        "RCAIP_DIAG001_CELL35_PARENT_COHORT_ID",
        "RCAIP_DIAG001_CELL35_PARENT_RESUME_DF",
        "RCAIP_DIAG001_CELL35_SOURCE_FAMILY_STATUS_DF",
        "RCAIP_DIAG001_CELL35_NEXT_SOURCE_FAMILY",
        "RCAIP_DIAG001_CELL35_NEXT_ASSET_COUNT",
        "RCAIP_DIAG001_CELL35_NEXT_SOURCE_FAMILY_DF",
        "RCAIP_DIAG001_CELL35_NEXT_GATE",
    ]
    missing = sorted(name for name in required if name not in globals())
    require(not missing, "Missing runtime objects: " + " | ".join(missing))
    require(RCAIP_DIAG001_CELL35_READY is True, "Cell 35 is not ready.")
    require(
        RCAIP_DIAG001_CELL35_NEXT_GATE
        == "SOURCE_FAMILY_ATTRIBUTION_QUALIFICATION",
        "Unexpected Cell 35 continuation gate.",
    )

    family = RCAIP_DIAG001_CELL35_NEXT_SOURCE_FAMILY
    require(
        family == "TENABLE_ONLY",
        "Selected family requires a different analytical continuation.",
    )

    post_slug = RCAIP_DIAG001_CELL35_POST_SLUG
    run_id = RCAIP_DIAG001_CELL35_RUN_ID
    parent_id = RCAIP_DIAG001_CELL35_PARENT_COHORT_ID
    require(
        bool(post_slug) and bool(run_id) and bool(parent_id),
        "Blank Cell 35 scope.",
    )

    candidates = RCAIP_DIAG001_CELL35_NEXT_SOURCE_FAMILY_DF
    parent = RCAIP_DIAG001_CELL35_PARENT_RESUME_DF
    family_status = RCAIP_DIAG001_CELL35_SOURCE_FAMILY_STATUS_DF

    def need(df, columns, label):
        require(isinstance(df, DataFrame), label + " is not a DataFrame.")
        require(
            len(df.columns) == len(set(df.columns)),
            label + " has duplicate column names.",
        )
        absent = sorted(set(columns) - set(df.columns))
        require(
            not absent,
            label + " missing required columns: " + " | ".join(absent),
        )

    def reject(df, condition, message):
        require(df.filter(condition).limit(1).count() == 0, message)

    def asset_count(df, label):
        need(df, ["asset_key"], label)
        reject(
            df,
            F.col("asset_key").isNull()
            | (F.trim(F.col("asset_key")) == ""),
            label + " has a blank asset_key.",
        )
        reject(
            df.groupBy("asset_key").count(),
            F.col("count") != 1,
            label + " is not one row per asset_key.",
        )
        return df.count()

    def same_assets(left, right, label):
        left_keys = left.select("asset_key")
        right_keys = right.select("asset_key")
        require(
            left_keys.join(right_keys, "asset_key", "left_anti")
            .limit(1).count() == 0
            and right_keys.join(left_keys, "asset_key", "left_anti")
            .limit(1).count() == 0,
            label + " has missing or additional assets.",
        )

    def same_rows(left, right, columns, label):
        left_projection = left.select(*columns)
        right_projection = right.select(*columns)
        require(
            left_projection.exceptAll(right_projection).limit(1).count() == 0
            and right_projection.exceptAll(left_projection).limit(1).count() == 0,
            label + " changed.",
        )

    # These columns are guaranteed by the inherited DIAG feature/IP-005
    # projection contracts. Null contextual values remain permissible.
    context_columns = [
        "source_mask_raw",
        "source_mask_stale",
        "current_observation_status",
        "identity_basis",
        "identity_strength",
        "operational_boundary",
        "operational_boundary_confidence",
        "management_model",
        "management_owner",
        "attribution_confidence",
        "attribution_conflict_flag",
        "conflict_count",
        "ip005_primary_case_type",
        "ip005_cmdb_present_flag",
        "ip005_current_evidence_flag",
        "ip005_stale_evidence_flag",
    ]
    required_columns = [
        "asset_key",
        "post_slug",
        "rcaip_run_id",
        "source_family",
        "source_mask_active",
        "c31_parent_cohort_id",
        "c35_resume_state",
        "discovery002_coverage_state",
        "_d002_present",
        "d002_attribution_evidence_status",
    ] + context_columns

    need(parent, required_columns, "Cell 35 parent")
    need(candidates, required_columns, "Cell 35 selected candidates")
    require(
        candidates.columns == parent.columns,
        "Selected candidates do not retain the exact parent column contract.",
    )
    require(
        not any(name.startswith("c36_") for name in candidates.columns),
        "Candidates already contain Cell 36 annotations.",
    )
    need(
        family_status,
        [
            "source_family", "asset_count", "source_masks",
            "analytical_state", "eligible_for_next_selection", "selected_next",
        ],
        "Cell 35 source-family status",
    )

    types = {
        item.name: item.dataType.simpleString()
        for item in candidates.schema.fields
    }
    for name in [
        "source_mask_active",
        "source_mask_stale",
        "discovery002_coverage_state",
        "d002_attribution_evidence_status",
        "ip005_primary_case_type",
    ]:
        require(
            types[name] == "string",
            name + " must retain its certified string contract.",
        )
    require(
        types["_d002_present"] == "boolean"
        and types["attribution_conflict_flag"] == "boolean",
        "Disposition/conflict flags must retain their boolean contracts.",
    )

    # -----------------------------------------------------------------------
    # 1. Exact selected denominator and existing branch applicability.
    # -----------------------------------------------------------------------

    parent_count = asset_count(parent, "Cell 35 parent")
    starting = asset_count(candidates, "Cell 35 selected candidates")
    require(
        starting > 0
        and starting == RCAIP_DIAG001_CELL35_NEXT_ASSET_COUNT,
        "Selected scalar and candidate denominator disagree.",
    )

    for df, label in [(parent, "Parent"), (candidates, "Candidates")]:
        reject(
            df,
            ~F.col("post_slug").eqNullSafe(F.lit(post_slug))
            | ~F.col("rcaip_run_id").eqNullSafe(F.lit(run_id))
            | ~F.col("c31_parent_cohort_id").eqNullSafe(F.lit(parent_id)),
            label + " contains another or null Post/run/parent scope.",
        )

    expected_candidates = parent.filter(F.col("source_family") == family)
    same_assets(candidates, expected_candidates, "Selected-family membership")
    same_rows(
        candidates, expected_candidates, parent.columns,
        "Selected original parent fields",
    )
    reject(
        candidates,
        ~F.col("c35_resume_state").eqNullSafe(
            F.lit("AWAITING_SOURCE_FAMILY_QUALIFICATION")
        ),
        "Selected candidates are not awaiting source-family qualification.",
    )
    reject(
        candidates,
        ~F.upper(F.trim(F.col("source_mask_active")))
        .eqNullSafe(F.lit("TENABLE")),
        "Candidate mask violates the existing TENABLE_ONLY contract.",
    )

    selected_status_rows = family_status.filter(
        F.col("selected_next") == True
    ).collect()
    require(
        len(selected_status_rows) == 1,
        "Cell 35 does not identify exactly one selected family.",
    )
    selected_status = selected_status_rows[0]
    require(
        selected_status["source_family"] == family
        and selected_status["asset_count"] == starting
        and selected_status["eligible_for_next_selection"] is True
        and selected_status["analytical_state"]
        == "AWAITING_SOURCE_FAMILY_QUALIFICATION",
        "Cell 35 selected-family status disagrees with its candidates.",
    )
    actual_masks = [
        row["source_mask_active"]
        for row in candidates.select("source_mask_active").distinct().collect()
    ]
    require(
        sorted(actual_masks) == sorted(selected_status["source_masks"] or []),
        "Selected mask values differ from Cell 35 family accounting.",
    )

    # -----------------------------------------------------------------------
    # 2. Consume existing Discovery 002 coverage; no taxonomy reconstruction.
    # -----------------------------------------------------------------------

    present = "DISCOVERY002_DISPOSITION_PRESENT"
    gap = "DISCOVERY002_EXPECTED_BUT_MISSING"
    outside = "OUTSIDE_DISCOVERY002_CANDIDATE_CONTRACT"
    coverage_review = "DISCOVERY002_COVERAGE_STATE_REQUIRES_REVIEW"

    known_statuses = [
        "CONSISTENT_MULTI_SOURCE_ATTRIBUTION_SEED",
        "MULTI_SOURCE_PRIMARY_WITH_SECONDARY_VARIANCE",
        "CROSS_SOURCE_ATTRIBUTION_CONFLICT",
        "STRONG_SINGLE_SOURCE_ATTRIBUTION_SEED",
        "MODERATE_SINGLE_SOURCE_ATTRIBUTION_EVIDENCE",
        "NO_USABLE_ATTRIBUTION_SIGNAL",
    ]

    coverage = F.col("discovery002_coverage_state")
    recorded_status = F.col("d002_attribution_evidence_status")
    present_flag = F.col("_d002_present")

    # Consistency only: never use this flag or IP-005 to regenerate coverage.
    reject(
        candidates,
        (coverage == present)
        & ~present_flag.eqNullSafe(F.lit(True)),
        "Present coverage disagrees with _d002_present.",
    )
    reject(
        candidates,
        coverage.isin(gap, outside)
        & present_flag.eqNullSafe(F.lit(True)),
        "Non-present coverage incorrectly claims a present disposition.",
    )

    boundary_state = (
        F.when(coverage == present, F.lit("DISCOVERY002_ASSESSMENT_PRESENT"))
        .when(coverage == gap, F.lit("DISCOVERY002_EXPECTED_COVERAGE_GAP"))
        .when(coverage == outside, F.lit(outside))
        .otherwise(F.lit(coverage_review))
    )
    boundary_reason = (
        F.when(
            (coverage == present) & recorded_status.isin(*known_statuses),
            F.lit("EXISTING_CERTIFIED_DISCOVERY002_ASSESSMENT_PRESERVED"),
        )
        .when(
            coverage == present,
            F.lit("DISPOSITION_PRESENT_WITH_BLANK_OR_UNRECOGNIZED_STATUS"),
        )
        .when(
            coverage == gap,
            F.lit("CELL26_EXPECTED_COVERAGE_WITHOUT_CERTIFIED_DISPOSITION"),
        )
        .when(
            coverage == outside,
            F.lit("DISPOSITION_NOT_REQUIRED_BY_DISCOVERY002_CANDIDATE_CONTRACT"),
        )
        .otherwise(F.lit("NULL_OR_UNRECOGNIZED_CELL26_COVERAGE_STATE"))
    )
    qualification_state = (
        F.when(
            (coverage == present) & recorded_status.isin(*known_statuses),
            recorded_status,
        )
        .when(
            coverage == present,
            F.lit("ATTRIBUTION_STATUS_REQUIRES_REVIEW"),
        )
        .when(coverage == gap, F.lit("DISCOVERY002_COVERAGE_GAP"))
        .when(coverage == outside, F.lit(outside))
        .otherwise(F.lit(coverage_review))
    )

    # -----------------------------------------------------------------------
    # 3. Orthogonal context. No new attribution or confidence inference.
    # -----------------------------------------------------------------------

    context_notes = []
    for name in context_columns:
        value = F.col(name).cast("string")
        context_notes.append(
            F.when(
                value.isNull() | (F.length(F.trim(value)) == 0),
                F.lit("VALUE_NOT_POPULATED:" + name),
            )
        )
    context_limitations = F.filter(
        F.array(*context_notes), lambda value: value.isNotNull()
    )

    review_context = (
        F.when(
            F.col("attribution_conflict_flag") == True,
            F.lit("ATTRIBUTION_CONFLICT_RECORDED"),
        )
        .when(
            F.col("conflict_count") > 0,
            F.lit("OTHER_CONFLICT_CONTEXT_RECORDED"),
        )
        .when(
            F.col("attribution_conflict_flag").isNull()
            | F.col("conflict_count").isNull(),
            F.lit("CONFLICT_CONTEXT_INCOMPLETE"),
        )
        .otherwise(F.lit("NO_CONFLICT_RECORDED_IN_CONSUMED_FIELDS"))
    )

    qualified = (
        candidates
        .withColumn(
            "c36_discovery002_coverage_state",
            F.col("discovery002_coverage_state"),
        )
        .withColumn(
            "c36_observation_context",
            F.lit("TENABLE_ACTIVE_SOURCE_OBSERVATION_ONLY"),
        )
        .withColumn("c36_attribution_evidence_boundary_state", boundary_state)
        .withColumn("c36_attribution_evidence_boundary_reason", boundary_reason)
        .withColumn("c36_qualification_state", qualification_state)
        .withColumn("c36_existing_review_context", review_context)
        .withColumn("c36_context_limitations", context_limitations)
        .withColumn(
            "c36_independent_identity_corroboration_state",
            F.lit("NOT_ASSESSED_FROM_SOURCE_PRESENCE"),
        )
        .withColumn(
            "c36_post_attribution_state",
            F.lit("NOT_ESTABLISHED_BY_THIS_CELL"),
        )
        .withColumn(
            "c36_interpretation_limit",
            F.lit(
                "Tenable-only describes the active source mask. It does not "
                "establish independent identity, Post ownership, management "
                "absence, registration absence, vulnerability, or control "
                "failure. Raw/stale masks and lifecycle context remain "
                "historical evidence; their absence does not prove that "
                "another source never observed the asset."
            ),
        )
        .withColumn("c36_customer_routing_performed", F.lit(False))
        .withColumn("c36_workload_promotion_authorized", F.lit(False))
    )

    summary_dimensions = [
        "source_family",
        "source_mask_active",
        "c36_discovery002_coverage_state",
        "c36_attribution_evidence_boundary_state",
        "c36_attribution_evidence_boundary_reason",
        "c36_qualification_state",
        "c36_observation_context",
        "c36_existing_review_context",
    ] + context_columns

    summary = (
        qualified.groupBy(*summary_dimensions)
        .agg(F.count(F.lit(1)).alias("asset_count"))
        .orderBy("source_mask_active", "c36_qualification_state")
    )

    # -----------------------------------------------------------------------
    # 4. Candidate conservation and qualification-semantic certification.
    # -----------------------------------------------------------------------

    ending = asset_count(qualified, "Cell 36 qualified output")
    require(ending == starting, "Selected denominator changed.")
    same_assets(qualified, candidates, "Cell 36 candidate conservation")
    same_rows(
        qualified, candidates, candidates.columns,
        "Every inherited candidate field, including source_mask_stale",
    )

    additive_columns = [
        name for name in qualified.columns if name not in candidates.columns
    ]
    require(
        bool(additive_columns)
        and all(name.startswith("c36_") for name in additive_columns),
        "Cell 36 introduced an unexpected additive-field contract.",
    )
    reject(
        qualified,
        ~F.col("c36_discovery002_coverage_state").eqNullSafe(coverage),
        "Raw Discovery 002 coverage was changed.",
    )

    output_state = F.col("c36_qualification_state")
    output_boundary = F.col("c36_attribution_evidence_boundary_state")
    recognized_status = F.coalesce(
        recorded_status.isin(*known_statuses), F.lit(False)
    )
    recognized_coverage = F.coalesce(
        coverage.isin(present, gap, outside), F.lit(False)
    )
    allowed_states = known_statuses + [
        "ATTRIBUTION_STATUS_REQUIRES_REVIEW",
        "DISCOVERY002_COVERAGE_GAP",
        outside,
        coverage_review,
    ]
    reject(
        qualified,
        output_state.isNull() | ~output_state.isin(*allowed_states),
        "A candidate lacks an explicit qualification.",
    )
    reject(
        qualified,
        output_state.isin(*known_statuses)
        & (
            ~coverage.eqNullSafe(F.lit(present))
            | ~output_state.eqNullSafe(recorded_status)
        ),
        "An existing attribution status was invented or rewritten.",
    )
    reject(
        qualified,
        (coverage == present)
        & recognized_status
        & ~output_state.eqNullSafe(recorded_status),
        "A recognized present-disposition status was not preserved.",
    )
    reject(
        qualified,
        (coverage == present)
        & ~recognized_status
        & ~output_state.eqNullSafe(
            F.lit("ATTRIBUTION_STATUS_REQUIRES_REVIEW")
        ),
        "Blank/unrecognized attribution status was not retained as review.",
    )

    coverage_checks = [
        (
            coverage == present,
            output_boundary.eqNullSafe(F.lit("DISCOVERY002_ASSESSMENT_PRESENT")),
            "Present assessment boundary changed.",
        ),
        (
            coverage == gap,
            output_state.eqNullSafe(F.lit("DISCOVERY002_COVERAGE_GAP"))
            & output_boundary.eqNullSafe(
                F.lit("DISCOVERY002_EXPECTED_COVERAGE_GAP")
            ),
            "Expected-but-missing coverage lost its coverage-gap meaning.",
        ),
        (
            coverage == outside,
            output_state.eqNullSafe(F.lit(outside))
            & output_boundary.eqNullSafe(F.lit(outside)),
            "Outside-contract coverage was converted into a gap or failure.",
        ),
        (
            ~recognized_coverage,
            output_state.eqNullSafe(F.lit(coverage_review))
            & output_boundary.eqNullSafe(F.lit(coverage_review)),
            "Null/unrecognized coverage was not retained as explicit review.",
        ),
    ]
    for applies, valid, message in coverage_checks:
        reject(qualified, applies & ~valid, message)

    reject(
        qualified,
        ~F.col("c36_independent_identity_corroboration_state").eqNullSafe(
            F.lit("NOT_ASSESSED_FROM_SOURCE_PRESENCE")
        )
        | ~F.col("c36_post_attribution_state").eqNullSafe(
            F.lit("NOT_ESTABLISHED_BY_THIS_CELL")
        )
        | ~F.col("c36_customer_routing_performed").eqNullSafe(F.lit(False))
        | ~F.col("c36_workload_promotion_authorized").eqNullSafe(F.lit(False)),
        "Observation qualification exceeded its semantic boundary.",
    )

    summary_total = summary.agg(
        F.sum("asset_count").alias("asset_count")
    ).collect()[0]["asset_count"]
    require(summary_total == starting, "Qualification summary does not reconcile.")

    state_rows = (
        qualified.groupBy(
            "c36_discovery002_coverage_state",
            "c36_qualification_state",
        )
        .agg(F.count(F.lit(1)).alias("asset_count"))
        .orderBy(
            "c36_discovery002_coverage_state",
            "c36_qualification_state",
        )
        .collect()
    )
    require(
        sum(int(row["asset_count"]) for row in state_rows) == starting,
        "Qualification populations do not account for every selected asset.",
    )

    # Parent and family-status objects remain unchanged. Cell 37 performs
    # parent reconciliation/resume; this cell does not mark families complete.
    print("RCAIP DIAG 001 - CELL 36 CERTIFICATION")
    print("Status: PASS - inherited-evidence qualification only")
    print("Source family:", family)
    print("Starting / accounted selected assets:", starting, ending)
    print("Other assets retained in Cell 35 parent:", parent_count - starting)
    print("Runtime active-mask values:", sorted(actual_masks))
    for row in state_rows:
        print(
            "Qualification:",
            row["c36_discovery002_coverage_state"],
            row["c36_qualification_state"],
            row["asset_count"],
        )
    print("Original candidate fields and stale-source mask preserved: YES")
    print("Discovery 002 coverage/status semantics preserved: YES")
    print("Outside-contract interpreted as evidence failure: NO")
    print("Unresolved/review qualifications remain valid outcomes: YES")
    print("Duplicate / lost / additional candidates: NONE")
    print("Independent identity / Post ownership newly established: NO / NO")
    print("Absolute historical source-absence claim introduced: NO")
    print("Parent / family-status objects modified: NO / NO")
    print("Source reads / matching / vulnerability analysis / writes: NONE")
    print("Routing / workload / cases / findings / tickets / remediation: NONE")
    print("Next gate: ATTRIBUTION_COHORT_RESUME")
    print("Would this exact Cell 36 logic run for Paris? YES, on this branch.")

    return {
        "RCAIP_DIAG001_CELL36_POST_SLUG": post_slug,
        "RCAIP_DIAG001_CELL36_RUN_ID": run_id,
        "RCAIP_DIAG001_CELL36_SOURCE_FAMILY": family,
        "RCAIP_DIAG001_CELL36_STARTING_ASSET_COUNT": starting,
        "RCAIP_DIAG001_CELL36_QUALIFIED_DF": qualified,
        "RCAIP_DIAG001_CELL36_QUALIFICATION_SUMMARY_DF": summary,
        "RCAIP_DIAG001_CELL36_NEXT_GATE": "ATTRIBUTION_COHORT_RESUME",
    }


_c36_publications = _build_cell36()
globals().update(_c36_publications)
RCAIP_DIAG001_CELL36_READY = True

del _c36_publications
del _build_cell36
# COMMAND ----------
# ============================================================================
# RCAIP DIAG 001
# Cell 37 - Final Attribution Source-Family Resume
#
# Runtime handoffs only. ZERO new analytical qualification.
#
# Parent authority:
#   Exact Cell 35 parent/resume DataFrame, one row per asset_key.
#
# Completion authority:
#   Successful Cell 36 qualification handoff for the exact selected family.
#
# Preserve every original parent field and every additive Cell 36 field.
# Preserve original Cell 36 summary; validate its exact published dimensions.
# Add c37_resume_state without rewriting historical resume fields.
#
# QUALIFICATION_PRESERVED_PARENT_RESUMED means only that the assigned
# source-family qualification step completed and its result is preserved.
#
# SOURCE_FAMILY_QUALIFICATION_COMPLETE does NOT establish affirmative
# attribution, Post ownership, resolved coverage gaps/conflicts/review,
# customer assignment, cases, findings, workload, or attribution closure.
#
# No source reads, evidence analysis, matching, raw acquisition, MDE work,
# writes, Asset Plane mutation, identity merging, attribution/ownership
# inference, routing, workload, cases, findings, tickets, remediation, or recovery.
#
# Would this exact Cell 37 logic run for Paris?
# YES. Processed family and completion come from runtime handoffs/status.
# Population size sequences analytical work only.
# ============================================================================

from pyspark.sql import DataFrame
from pyspark.sql import functions as F


for _c37_name in tuple(globals()):
    if _c37_name.startswith("RCAIP_DIAG001_CELL37_"):
        del globals()[_c37_name]
del _c37_name

RCAIP_DIAG001_CELL37_READY = False


def _build_cell37():
    def require(condition, message):
        if not condition:
            raise RuntimeError("Cell 37 STOP: " + message)

    required = [
        "RCAIP_DIAG001_CELL35_READY",
        "RCAIP_DIAG001_CELL35_POST_SLUG",
        "RCAIP_DIAG001_CELL35_RUN_ID",
        "RCAIP_DIAG001_CELL35_PARENT_COHORT_ID",
        "RCAIP_DIAG001_CELL35_PARENT_RESUME_DF",
        "RCAIP_DIAG001_CELL35_SOURCE_FAMILY_STATUS_DF",
        "RCAIP_DIAG001_CELL35_NEXT_SOURCE_FAMILY",
        "RCAIP_DIAG001_CELL35_NEXT_ASSET_COUNT",
        "RCAIP_DIAG001_CELL35_NEXT_SOURCE_FAMILY_DF",
        "RCAIP_DIAG001_CELL36_READY",
        "RCAIP_DIAG001_CELL36_POST_SLUG",
        "RCAIP_DIAG001_CELL36_RUN_ID",
        "RCAIP_DIAG001_CELL36_SOURCE_FAMILY",
        "RCAIP_DIAG001_CELL36_STARTING_ASSET_COUNT",
        "RCAIP_DIAG001_CELL36_QUALIFIED_DF",
        "RCAIP_DIAG001_CELL36_QUALIFICATION_SUMMARY_DF",
        "RCAIP_DIAG001_CELL36_NEXT_GATE",
    ]
    missing = sorted(name for name in required if name not in globals())
    require(not missing, "Missing runtime objects: " + " | ".join(missing))
    require(RCAIP_DIAG001_CELL35_READY is True, "Cell 35 is not ready.")
    require(RCAIP_DIAG001_CELL36_READY is True, "Cell 36 is not ready.")

    post_slug = RCAIP_DIAG001_CELL35_POST_SLUG
    run_id = RCAIP_DIAG001_CELL35_RUN_ID
    parent_id = RCAIP_DIAG001_CELL35_PARENT_COHORT_ID
    processed_family = RCAIP_DIAG001_CELL36_SOURCE_FAMILY

    require(
        bool(post_slug) and bool(run_id) and bool(parent_id)
        and bool(processed_family),
        "Blank scope or processed family.",
    )
    require(
        RCAIP_DIAG001_CELL36_POST_SLUG == post_slug
        and RCAIP_DIAG001_CELL36_RUN_ID == run_id,
        "Cell 35 and Cell 36 Post/run scopes disagree.",
    )
    require(
        processed_family == RCAIP_DIAG001_CELL35_NEXT_SOURCE_FAMILY,
        "Cell 36 did not process the Cell 35 selected family.",
    )
    require(
        RCAIP_DIAG001_CELL36_NEXT_GATE == "ATTRIBUTION_COHORT_RESUME",
        "Unexpected Cell 36 continuation gate.",
    )

    parent = RCAIP_DIAG001_CELL35_PARENT_RESUME_DF
    selected = RCAIP_DIAG001_CELL35_NEXT_SOURCE_FAMILY_DF
    prior_status = RCAIP_DIAG001_CELL35_SOURCE_FAMILY_STATUS_DF
    qualified = RCAIP_DIAG001_CELL36_QUALIFIED_DF
    original_summary = RCAIP_DIAG001_CELL36_QUALIFICATION_SUMMARY_DF

    completed = "QUALIFICATION_PRESERVED_PARENT_RESUMED"
    awaiting = "AWAITING_SOURCE_FAMILY_QUALIFICATION"

    def need(df, columns, label):
        require(isinstance(df, DataFrame), label + " is not a DataFrame.")
        require(
            len(df.columns) == len(set(df.columns)),
            label + " has duplicate column names.",
        )
        absent = sorted(set(columns) - set(df.columns))
        require(
            not absent,
            label + " missing columns: " + " | ".join(absent),
        )

    def reject(df, condition, message):
        require(df.filter(condition).limit(1).count() == 0, message)

    def blank(name):
        return F.col(name).isNull() | (F.trim(F.col(name)) == "")

    def asset_count(df, label):
        need(df, ["asset_key"], label)
        reject(df, blank("asset_key"), label + " has blank asset keys.")
        reject(
            df.groupBy("asset_key").count(),
            F.col("count") != 1,
            label + " is not one row per asset.",
        )
        return df.count()

    def same_assets(left, right, label):
        left_keys = left.select("asset_key")
        right_keys = right.select("asset_key")
        require(
            left_keys.join(right_keys, "asset_key", "left_anti")
            .limit(1).count() == 0
            and right_keys.join(left_keys, "asset_key", "left_anti")
            .limit(1).count() == 0,
            label + " has missing or additional assets.",
        )

    def same_rows(left, right, columns, label):
        left_projection = left.select(*columns)
        right_projection = right.select(*columns)
        require(
            left_projection.exceptAll(right_projection).limit(1).count() == 0
            and right_projection.exceptAll(left_projection).limit(1).count() == 0,
            label + " changed.",
        )

    # -----------------------------------------------------------------------
    # 1. Exact parent, candidate membership, and inherited-field conservation.
    # -----------------------------------------------------------------------

    need(
        parent,
        [
            "asset_key", "post_slug", "rcaip_run_id",
            "source_family", "source_mask_active",
            "c31_parent_cohort_id", "c31_history_candidate",
            "c35_resume_state",
        ],
        "Cell 35 parent",
    )
    require(
        not any(name.startswith(("c36_", "c37_")) for name in parent.columns),
        "Cell 35 parent unexpectedly contains later-cell annotations.",
    )
    need(selected, parent.columns, "Cell 35 selected family")
    need(qualified, parent.columns, "Cell 36 qualified assets")
    require(
        selected.columns == parent.columns,
        "Selected-family columns differ from the authoritative parent.",
    )
    need(
        prior_status,
        [
            "source_family", "asset_count", "source_masks",
            "analytical_state", "eligible_for_next_selection", "selected_next",
        ],
        "Cell 35 source-family status",
    )

    parent_count = asset_count(parent, "Cell 35 parent")
    selected_count = asset_count(selected, "Cell 35 selected family")
    qualified_count = asset_count(qualified, "Cell 36 qualified assets")

    for df, label in [
        (parent, "Cell 35 parent"),
        (selected, "Cell 35 selected family"),
        (qualified, "Cell 36 qualified assets"),
    ]:
        reject(
            df,
            ~F.col("post_slug").eqNullSafe(F.lit(post_slug))
            | ~F.col("rcaip_run_id").eqNullSafe(F.lit(run_id))
            | ~F.col("c31_parent_cohort_id").eqNullSafe(F.lit(parent_id)),
            label + " contains another or null Post/run/parent scope.",
        )

    reject(parent, blank("source_family"), "Parent has a blank source family.")
    require(
        selected_count > 0
        and selected_count == RCAIP_DIAG001_CELL35_NEXT_ASSET_COUNT
        and selected_count == RCAIP_DIAG001_CELL36_STARTING_ASSET_COUNT
        and selected_count == qualified_count,
        "Selected, starting, and qualified denominators disagree.",
    )

    expected_selected = parent.filter(
        F.col("source_family") == processed_family
    )
    same_assets(selected, expected_selected, "Cell 35 selected membership")
    same_assets(qualified, selected, "Cell 36 selected membership")
    same_rows(
        selected, expected_selected, parent.columns,
        "Selected original parent fields",
    )
    same_rows(
        qualified, selected, parent.columns,
        "Cell 36 inherited parent fields",
    )

    annotation_columns = [
        name for name in qualified.columns if name not in parent.columns
    ]
    require(
        bool(annotation_columns)
        and all(name.startswith("c36_") for name in annotation_columns),
        "Cell 36 must publish c36_-prefixed additive fields.",
    )

    # -----------------------------------------------------------------------
    # 2. Exact published summary dimensions; accounting only.
    # -----------------------------------------------------------------------

    need(
        original_summary,
        ["asset_count", "c36_qualification_state"],
        "Cell 36 qualification summary",
    )
    summary_dimensions = [
        name for name in original_summary.columns if name != "asset_count"
    ]
    require(bool(summary_dimensions), "Cell 36 summary lacks dimensions.")
    need(qualified, summary_dimensions, "Cell 36 summary dimensions")

    def verify_summary(df, label):
        reconstructed_counts = df.groupBy(*summary_dimensions).agg(
            F.count(F.lit(1)).alias("asset_count")
        )
        same_rows(
            reconstructed_counts,
            original_summary,
            summary_dimensions + ["asset_count"],
            label,
        )

    verify_summary(qualified, "Cell 36 summary before attachment")
    summary_total = original_summary.agg(
        F.sum("asset_count").alias("asset_count")
    ).collect()[0]["asset_count"]
    require(
        summary_total == qualified_count,
        "Cell 36 summary does not reconcile to its denominator.",
    )

    # The original summary is neither changed nor republished.
    # Qualification/coverage values are never interpreted or remapped here.

    # -----------------------------------------------------------------------
    # 3. Existing family authority and the single authorized state transition.
    # -----------------------------------------------------------------------

    reject(
        prior_status, blank("source_family"),
        "Family status has a blank source family.",
    )
    reject(
        prior_status.groupBy("source_family").count(),
        F.col("count") != 1,
        "Family status is not one row per source family.",
    )

    membership = parent.groupBy("source_family").agg(
        F.count(F.lit(1)).alias("asset_count"),
        F.sort_array(F.collect_set("source_mask_active")).alias("source_masks"),
    )
    same_rows(
        membership, prior_status,
        ["source_family", "asset_count", "source_masks"],
        "Existing family membership/count/masks",
    )

    prior_rows = prior_status.collect()
    require(
        all(
            row["analytical_state"] in (completed, awaiting)
            and row["eligible_for_next_selection"]
            == (row["analytical_state"] == awaiting)
            and row["selected_next"]
            == (row["source_family"] == processed_family)
            for row in prior_rows
        ),
        "Existing family state or selection flags are inconsistent.",
    )
    processed_rows = [
        row for row in prior_rows
        if row["source_family"] == processed_family
    ]
    require(
        len(processed_rows) == 1
        and processed_rows[0]["analytical_state"] == awaiting
        and processed_rows[0]["asset_count"] == selected_count,
        "Processed family was not the selected awaiting family.",
    )

    prior_state_check = parent.join(
        prior_status.select(
            "source_family",
            F.col("analytical_state").alias("_c37_prior_state"),
        ),
        "source_family",
        "left",
    )
    reject(
        prior_state_check,
        ~F.col("c35_resume_state").eqNullSafe(F.col("_c37_prior_state")),
        "Parent and existing source-family analytical states disagree.",
    )

    completed_before = sum(
        int(row["asset_count"]) for row in prior_rows
        if row["analytical_state"] == completed
    )

    # Completion authority is successful Cell 36 handoff, not an affirmative
    # attribution result, absence of review, or any particular population size.
    family_status = (
        prior_status
        .withColumn(
            "analytical_state",
            F.when(
                F.col("source_family") == processed_family,
                F.lit(completed),
            ).otherwise(F.col("analytical_state")),
        )
        .withColumn(
            "eligible_for_next_selection",
            F.col("analytical_state") == awaiting,
        )
    )

    remaining_rows = (
        family_status
        .filter(F.col("eligible_for_next_selection"))
        .orderBy(F.desc("asset_count"), F.asc("source_family"))
        .collect()
    )
    next_family = remaining_rows[0]["source_family"] if remaining_rows else None
    next_count = int(remaining_rows[0]["asset_count"]) if remaining_rows else 0
    next_gate = (
        "SOURCE_FAMILY_ATTRIBUTION_QUALIFICATION"
        if next_family is not None
        else "SOURCE_FAMILY_QUALIFICATION_COMPLETE"
    )
    next_condition = (
        F.col("source_family") == F.lit(next_family)
        if next_family is not None else F.lit(False)
    )
    family_status = (
        family_status
        .withColumn("selected_next", next_condition)
        .orderBy(F.desc("asset_count"), F.asc("source_family"))
    )

    # -----------------------------------------------------------------------
    # 4. Attach exact asset annotations and publish a new resume boundary.
    # -----------------------------------------------------------------------

    parent_resume = (
        parent
        .join(
            qualified.select("asset_key", *annotation_columns),
            "asset_key",
            "left",
        )
        .join(
            family_status.select(
                "source_family",
                F.col("analytical_state").alias("c37_resume_state"),
            ),
            "source_family",
            "left",
        )
        .select(*parent.columns, *annotation_columns, "c37_resume_state")
    )
    next_df = parent_resume.filter(next_condition)

    # No upstream runtime object, historical field, or separate parked
    # history handoff is overwritten.

    # -----------------------------------------------------------------------
    # 5. Final preservation and source-family completion certification.
    # -----------------------------------------------------------------------

    ending_count = asset_count(parent_resume, "Cell 37 resumed parent")
    next_actual_count = asset_count(next_df, "Cell 37 next family")
    require(ending_count == parent_count, "Parent denominator changed.")
    same_assets(parent_resume, parent, "Parent conservation")
    same_rows(
        parent_resume, parent, parent.columns,
        "Every original Cell 35 parent field",
    )

    resumed_processed = parent_resume.filter(
        F.col("source_family") == processed_family
    )
    same_assets(resumed_processed, qualified, "Processed-family conservation")
    same_rows(
        resumed_processed, qualified, qualified.columns,
        "Every inherited and additive Cell 36 field",
    )
    verify_summary(resumed_processed, "Cell 36 summary after attachment")

    annotations_present = F.lit(False)
    for name in annotation_columns:
        annotations_present = annotations_present | F.col(name).isNotNull()
    reject(
        parent_resume.filter(F.col("source_family") != processed_family),
        annotations_present,
        "Cell 36 annotations appeared outside processed membership.",
    )

    unchanged_status_columns = [
        name for name in prior_status.columns
        if name not in {
            "analytical_state", "eligible_for_next_selection", "selected_next"
        }
    ]
    same_rows(
        family_status, prior_status, unchanged_status_columns,
        "Original source-family accounting fields",
    )
    same_rows(
        family_status.filter(F.col("source_family") != processed_family),
        prior_status.filter(F.col("source_family") != processed_family),
        ["source_family", "analytical_state"],
        "Nonprocessed source-family analytical states",
    )
    reject(
        family_status.filter(F.col("source_family") == processed_family),
        ~F.col("analytical_state").eqNullSafe(F.lit(completed)),
        "Processed family was not qualification-preserved/parent-resumed.",
    )

    current_state_check = parent_resume.join(
        family_status.select(
            "source_family",
            F.col("analytical_state").alias("_c37_expected_state"),
        ),
        "source_family",
        "left",
    )
    reject(
        current_state_check,
        F.col("c37_resume_state").isNull()
        | ~F.col("c37_resume_state").eqNullSafe(F.col("_c37_expected_state")),
        "Current resume state differs from family state for a parent asset.",
    )
    reject(
        parent_resume.filter(F.col("source_family") != processed_family),
        ~F.col("c37_resume_state").eqNullSafe(F.col("c35_resume_state")),
        "An earlier completed or unprocessed family changed state.",
    )

    history_before = parent.filter(F.col("c31_history_candidate"))
    history_after = parent_resume.filter(F.col("c31_history_candidate"))
    same_assets(history_after, history_before, "Parked history membership")
    history_count = history_before.count()
    require(
        history_after.count() == history_count,
        "Parked history membership count changed.",
    )

    family_rows = family_status.collect()
    completed_count = sum(
        int(row["asset_count"]) for row in family_rows
        if row["analytical_state"] == completed
    )
    remaining_count = sum(
        int(row["asset_count"]) for row in family_rows
        if row["analytical_state"] == awaiting
    )
    require(
        completed_count == completed_before + selected_count,
        "Completion differs from prior completion plus the processed family.",
    )
    require(
        completed_count + remaining_count == parent_count,
        "Completed and remaining counts do not reconcile to the parent.",
    )
    require(
        all(
            row["eligible_for_next_selection"]
            == (row["analytical_state"] == awaiting)
            and row["selected_next"]
            == (next_family is not None and row["source_family"] == next_family)
            for row in family_rows
        ),
        "Updated eligibility or next-selection flags are inconsistent.",
    )
    require(
        next_actual_count == next_count,
        "Next-family output differs from existing family accounting.",
    )
    require(
        next_df.schema == parent_resume.schema,
        "Next-family slice does not retain the exact resumed-parent schema.",
    )
    same_assets(
        next_df, parent.filter(next_condition),
        "Next selection / existing family membership",
    )

    if next_family is None:
        require(
            not remaining_rows
            and remaining_count == 0
            and completed_count == parent_count
            and next_count == 0
            and next_actual_count == 0
            and next_gate == "SOURCE_FAMILY_QUALIFICATION_COMPLETE",
            "No-family-remains completion contract is inconsistent.",
        )
    else:
        require(
            remaining_count > 0
            and next_count > 0
            and next_gate == "SOURCE_FAMILY_ATTRIBUTION_QUALIFICATION",
            "Remaining-family continuation contract is inconsistent.",
        )

    print("RCAIP DIAG 001 - CELL 37 CERTIFICATION")
    print("Status: PASS - resume/accounting/completion certification only")
    print("Starting / preserved parent assets:", parent_count, ending_count)
    print("Qualification-preserved before Cell 36:", completed_before)
    print("Cell 36 processed family:", processed_family)
    print("Cell 36 selected / qualified assets:", selected_count, qualified_count)
    print("Qualification-preserved after resume:", completed_count)
    print("Awaiting source-family assets:", remaining_count)
    print("Awaiting source-family count:", len(remaining_rows))
    for row in family_rows:
        print(
            "Source family:",
            row["source_family"],
            row["asset_count"],
            row["analytical_state"],
        )
    print("Cell 36 summary before / after attachment: PASS / PASS")
    print("Original Cell 36 summary retained without replacement: YES")
    print("Every historical parent and Cell 36 additive field preserved: YES")
    print("Current resume field agrees with every asset's family state: YES")
    print("Cell 36 annotations outside processed family: NONE")
    print("Duplicate / lost / additional parent assets: NONE")
    print("Separate parked MDE-history members preserved:", history_count)
    print("History overlay influences completion or selection: NO")
    print("Unresolved / review / gap / outside-contract states block resume: NO")
    print("Next source family:", next_family)
    print("Next source-family assets:", next_count)
    print("Next gate:", next_gate)
    print("New analytical qualification performed: NONE")
    print("Source-family completion means attribution resolution: NO")
    print("Affirmative identity / Post ownership newly established: NO / NO")
    print("Coverage gaps / conflicts / review states declared resolved: NO")
    print("Parent attribution / wider attribution branch closed: NO / NO")
    print("Next substantive analytical treatment selected by this cell: NO")
    print("Source reads / writes / matching / recovery: NONE")
    print("Routing / workload / cases / findings / tickets / remediation: NONE")
    print("Would this exact Cell 37 logic run for Paris? YES")

    return {
        "RCAIP_DIAG001_CELL37_POST_SLUG": post_slug,
        "RCAIP_DIAG001_CELL37_RUN_ID": run_id,
        "RCAIP_DIAG001_CELL37_PARENT_COHORT_ID": parent_id,
        "RCAIP_DIAG001_CELL37_PARENT_RESUME_DF": parent_resume,
        "RCAIP_DIAG001_CELL37_SOURCE_FAMILY_STATUS_DF": family_status,
        "RCAIP_DIAG001_CELL37_NEXT_SOURCE_FAMILY": next_family,
        "RCAIP_DIAG001_CELL37_NEXT_ASSET_COUNT": next_count,
        "RCAIP_DIAG001_CELL37_NEXT_SOURCE_FAMILY_DF": next_df,
        "RCAIP_DIAG001_CELL37_NEXT_GATE": next_gate,
    }


_c37_publications = _build_cell37()
globals().update(_c37_publications)
RCAIP_DIAG001_CELL37_READY = True

del _c37_publications
del _build_cell37

# COMMAND ----------

# ============================================================================
# Cell 38 - Attribution Parent Treatment Segmentation
#
# Existing authority: Cell 26 parent, Cell 29 Intune continuations preserved by
# Cell 31, and Cell 37 completion. D0027/D0033 preserve evidence; D0029/D0034
# defer customer routing and case formation. No new decision is made here.
#
# Segmentation only: the umbrella lookup/corroboration gate is NOT executed.
# History execution remains PARKED and nonblocking for Asset delivery / Paris.
# Would this exact Cell 38 logic run for Paris?
# YES. Runtime contracts determine membership; recorded counts only describe
# historical expectations and never control qualification or readiness.
# ============================================================================

# Invalidate only this cell's previous publications before any fallible work.
for _c38_name in tuple(globals()):
    if _c38_name.startswith("RCAIP_DIAG001_CELL38_"):
        del globals()[_c38_name]
del _c38_name
RCAIP_DIAG001_CELL38_READY = False

from pyspark.sql import DataFrame
from pyspark.sql import functions as F


def _build_cell38():
    def require(condition, message):
        if not condition:
            raise RuntimeError("Cell 38 CONTRACT INTEGRITY STOP: " + message)

    required_objects = [
        "RCAIP_DIAG001_CELL37_READY",
        "RCAIP_DIAG001_CELL37_POST_SLUG",
        "RCAIP_DIAG001_CELL37_RUN_ID",
        "RCAIP_DIAG001_CELL37_PARENT_COHORT_ID",
        "RCAIP_DIAG001_CELL37_PARENT_RESUME_DF",
        "RCAIP_DIAG001_CELL37_SOURCE_FAMILY_STATUS_DF",
        "RCAIP_DIAG001_CELL37_NEXT_SOURCE_FAMILY",
        "RCAIP_DIAG001_CELL37_NEXT_ASSET_COUNT",
        "RCAIP_DIAG001_CELL37_NEXT_SOURCE_FAMILY_DF",
        "RCAIP_DIAG001_CELL37_NEXT_GATE",
    ]
    missing = sorted(set(required_objects) - set(globals()))
    require(not missing, "Missing runtime objects: " + " | ".join(missing))
    require(RCAIP_DIAG001_CELL37_READY is True, "Cell 37 is not ready.")
    require(
        RCAIP_DIAG001_CELL37_NEXT_GATE == "SOURCE_FAMILY_QUALIFICATION_COMPLETE",
        "Source-family qualification is not complete.",
    )
    require(
        RCAIP_DIAG001_CELL37_NEXT_SOURCE_FAMILY is None
        and type(RCAIP_DIAG001_CELL37_NEXT_ASSET_COUNT) is int
        and RCAIP_DIAG001_CELL37_NEXT_ASSET_COUNT == 0,
        "Cell 37 still selects a family or has an invalid next count.",
    )

    parent = RCAIP_DIAG001_CELL37_PARENT_RESUME_DF
    status = RCAIP_DIAG001_CELL37_SOURCE_FAMILY_STATUS_DF
    next_df = RCAIP_DIAG001_CELL37_NEXT_SOURCE_FAMILY_DF
    post_slug = RCAIP_DIAG001_CELL37_POST_SLUG
    run_id = RCAIP_DIAG001_CELL37_RUN_ID
    parent_id = RCAIP_DIAG001_CELL37_PARENT_COHORT_ID
    require(
        all(isinstance(value, str) and value.strip()
            for value in (post_slug, run_id, parent_id)),
        "Blank or invalid Post/run/parent scope.",
    )

    umbrella = "ENTERPRISE_ATTRIBUTION_LOOKUP_OR_BOUNDED_POST_CORROBORATION"
    no_signal = "NO_USABLE_ATTRIBUTION_SIGNAL"
    present = "DISCOVERY002_DISPOSITION_PRESENT"
    completed = "QUALIFICATION_PRESERVED_PARENT_RESUMED"
    unresolved_history = "UNRESOLVED_ENGINEERING_EVIDENCE_BOUNDARY"
    outside_history = "OUTSIDE_CELL30_HISTORY_OVERLAY"
    history_gate = "GOVERNED_MDE_HISTORY_PREFLIGHT"
    intune_basis = "CELL29_INTUNE_QUALIFICATION_PRESERVED_BY_CELL31"
    parent_basis = "CELL26_PARENT_UMBRELLA_GATE"

    # Ordered Cell 29 label-to-continuation mapping. Its original identity and
    # platform predicates are NOT reconstructed or executed.
    child_gates = {
        "INTUNE_SHARED_SERIAL_IDENTITY_REVIEW":
            "INTUNE_SOURCE_IDENTITY_RECONCILIATION",
        "INTUNE_IOS_IPADOS_MANAGED_MOBILE_CONTEXT":
            "MOBILE_APPLICABILITY_AND_OPERATIONAL_ATTRIBUTION_CONTEXT",
        "WINDOWS_EXISTING_MDE_CONTEXT":
            "REUSE_EXISTING_MDE_REDISCOVERY_EVIDENCE",
        "WINDOWS_HISTORICAL_MDE_RECONCILIATION_CANDIDATE":
            history_gate,
        "PLATFORM_CONTEXT_REVIEW_REQUIRED":
            "PLATFORM_SEMANTIC_REVIEW",
    }

    def need(df, columns, label):
        require(isinstance(df, DataFrame), label + " is not a DataFrame.")
        require(
            len(df.columns) == len(set(df.columns)),
            label + " contains duplicate column names.",
        )
        absent = sorted(set(columns) - set(df.columns))
        require(not absent, label + " missing fields: " + " | ".join(absent))

    def reject(df, condition, message, details=()):
        # Null/unknown validation results must not silently pass.
        bad = df.filter(F.coalesce(condition, F.lit(True)))
        keys = [name for name in ("asset_key", "source_family")
                if name in df.columns]
        columns = list(dict.fromkeys(keys + list(details)))
        sample_df = bad.select(*columns) if columns else bad
        if keys:
            sample_df = sample_df.orderBy(*keys)
        sample = sample_df.limit(20).collect()
        if sample:
            print("Cell 38 failed invariant:", message)
            print("Affected rows:", bad.count())
            print("Diagnostic sample (at most 20):")
            for row in sample:
                print(row.asDict(recursive=True))
            require(False, message)

    def blank(name):
        return F.col(name).isNull() | (F.trim(F.col(name).cast("string")) == "")

    def norm(name):
        # Exact Cell 26 normalization; the inherited value is never replaced.
        return F.upper(F.trim(F.coalesce(F.col(name).cast("string"), F.lit(""))))

    def exact(df, name, expected, label):
        reject(
            df, ~F.col(name).eqNullSafe(F.lit(expected)),
            label + ": " + name, [name],
        )

    def boolean_field(df, name, label):
        require(
            df.schema[name].dataType.simpleString() == "boolean",
            label + ": " + name + " must retain boolean type.",
        )

    def asset_count(df, label):
        need(df, ["asset_key"], label)
        reject(df, blank("asset_key"), label + ": blank asset_key")
        reject(
            df.groupBy("asset_key").count(), F.col("count") != 1,
            label + ": duplicate asset_key", ["count"],
        )
        return df.count()

    def same_assets(left, right, label):
        left_keys = left.select("asset_key")
        right_keys = right.select("asset_key")
        reject(
            left_keys.join(right_keys, "asset_key", "left_anti"),
            F.lit(True), label + ": extra asset",
        )
        reject(
            right_keys.join(left_keys, "asset_key", "left_anti"),
            F.lit(True), label + ": missing asset",
        )

    def same_rows(left, right, columns, label):
        lhs = left.select(*columns)
        rhs = right.select(*columns)
        reject(lhs.exceptAll(rhs), F.lit(True), label + ": changed/extra row")
        reject(rhs.exceptAll(lhs), F.lit(True), label + ": missing/changed row")

    base_columns = [
        "asset_key", "post_slug", "rcaip_run_id",
        "source_family", "source_mask_active",
        "qualification_class", "qualification_next_gate",
        "d002_attribution_evidence_status", "_d002_present",
        "discovery002_coverage_state", "boundary_semantic_class",
        "qualification_evidence_basis", "workload_promotion_state",
        "operational_boundary", "operational_boundary_confidence",
        "management_model", "existing_validation_responsibility",
        "c31_parent_cohort_id", "c31_intune_qualification_class",
        "c31_history_candidate", "c31_history_dependency", "c37_resume_state",
    ]
    status_columns = [
        "source_family", "asset_count", "source_masks", "analytical_state",
        "eligible_for_next_selection", "selected_next",
    ]
    need(parent, base_columns, "Cell 37 parent")
    need(status, status_columns, "Cell 37 family status")
    need(next_df, parent.columns, "Cell 37 next family")
    require(
        not any(name.startswith("c38_") for name in parent.columns),
        "The authoritative input already contains Cell 38 annotations.",
    )
    require(
        "primary_customer" not in parent.columns,
        "Unexpected final-customer field in the pre-routing parent; reconcile "
        "the handoff rather than discard it or republish customer routing.",
    )
    require(next_df.schema == parent.schema, "Next-family schema differs.")
    require(next_df.limit(1).count() == 0, "Next-family DataFrame is not empty.")

    starting = asset_count(parent, "Cell 37 parent")
    require(starting > 0, "The selected parent is empty.")
    for name, value in (
        ("post_slug", post_slug),
        ("rcaip_run_id", run_id),
        ("c31_parent_cohort_id", parent_id),
    ):
        exact(parent, name, value, "Scope disagreement")
    reject(parent, blank("source_family"), "Blank source family")
    boolean_field(parent, "_d002_present", "Parent")
    boolean_field(parent, "c31_history_candidate", "Parent")

    # -----------------------------------------------------------------------
    # 1. Validate the original parent contract; do not reclassify any row.
    # -----------------------------------------------------------------------
    exact_invariants = {
        "qualification_class": "DISC002_NO_USABLE_ATTRIBUTION_SIGNAL",
        "qualification_next_gate": umbrella,
        "_d002_present": True,
        "discovery002_coverage_state": present,
        "boundary_semantic_class": "EXPECTED_IP006_LOW_BOUNDARY_STAGING_STATE",
        "qualification_evidence_basis":
            "DISCOVERY002_DURABLE_ATTRIBUTION_DISPOSITION",
        "workload_promotion_state": "NOT_READY_FOR_CASE_FORMATION",
    }
    for name, value in exact_invariants.items():
        exact(parent, name, value, "Cell 26 exact invariant")

    normalized_invariants = {
        "d002_attribution_evidence_status": no_signal,
        "operational_boundary": "OBSERVED_IN_POST_SCOPE",
        "operational_boundary_confidence": "LOW",
        "management_model": "UNMANAGED_OR_UNKNOWN",
    }
    for name, value in normalized_invariants.items():
        reject(
            parent, ~norm(name).eqNullSafe(F.lit(value)),
            "Cell 26 normalized invariant: " + name, [name],
        )

    # -----------------------------------------------------------------------
    # 2. Validate the complete family-status handoff from runtime membership.
    # -----------------------------------------------------------------------
    reject(status, blank("source_family"), "Blank family-status key")
    reject(
        status.groupBy("source_family").count(), F.col("count") != 1,
        "Duplicate family-status key", ["count"],
    )
    for name in ("eligible_for_next_selection", "selected_next"):
        boolean_field(status, name, "Family status")
        exact(status, name, False, "Family is still eligible/selected")
    exact(status, "analytical_state", completed, "Incomplete source family")
    exact(parent, "c37_resume_state", completed, "Incomplete asset handoff")

    membership = parent.groupBy("source_family").agg(
        F.count(F.lit(1)).alias("asset_count"),
        F.sort_array(F.collect_set("source_mask_active")).alias("source_masks"),
    )
    same_rows(
        membership, status, ["source_family", "asset_count", "source_masks"],
        "Family membership/count/source-mask conservation",
    )
    family_rows = membership.orderBy("source_family").collect()
    require(
        sum(int(row["asset_count"]) for row in family_rows) == starting,
        "Family populations do not account for the parent.",
    )
    family_names = {row["source_family"] for row in family_rows}

    # -----------------------------------------------------------------------
    # 3. Validate applicable inherited annotations; never invent child gates.
    # -----------------------------------------------------------------------
    family_annotations = {
        "NMAP_ONLY": ("c32_", [
            "c32_qualification_state",
            "c32_host_attribution_boundary_state",
            "c32_host_attribution_boundary_reason",
            "c32_relationship_evaluation_performed",
            "c32_evidence_limitations",
            "c32_post_attribution_state",
            "c32_customer_routing_performed",
            "c32_workload_promotion_authorized",
        ]),
        "NMAP_MULTI_SOURCE": ("c34_", [
            "c34_discovery002_coverage_state",
            "c34_qualification_state",
            "c34_attribution_evidence_boundary_state",
            "c34_attribution_evidence_boundary_reason",
            "c34_post_attribution_state",
            "c34_customer_routing_performed",
            "c34_workload_promotion_authorized",
        ]),
        "TENABLE_ONLY": ("c36_", [
            "c36_discovery002_coverage_state",
            "c36_qualification_state",
            "c36_attribution_evidence_boundary_state",
            "c36_attribution_evidence_boundary_reason",
            "c36_post_attribution_state",
            "c36_customer_routing_performed",
            "c36_workload_promotion_authorized",
        ]),
    }
    for family, (prefix, columns) in family_annotations.items():
        applicable = parent.filter(F.col("source_family") == family)
        if family in family_names:
            need(parent, columns, family + " annotations")
            exact(
                applicable, prefix + "post_attribution_state",
                "NOT_ESTABLISHED_BY_THIS_CELL", family,
            )
            for suffix in (
                "customer_routing_performed", "workload_promotion_authorized"
            ):
                boolean_field(parent, prefix + suffix, family)
                exact(applicable, prefix + suffix, False, family)

        # The existing resume cells attach these fields only to their family.
        for name in parent.columns:
            if name.startswith(prefix):
                reject(
                    parent.filter(F.col("source_family") != family),
                    F.col(name).isNotNull(),
                    "Annotation outside its originating family: " + name,
                    [name],
                )

        if family not in family_names:
            continue
        if prefix in ("c34_", "c36_"):
            exact(applicable, prefix + "discovery002_coverage_state", present, family)
            exact(
                applicable, prefix + "attribution_evidence_boundary_state",
                "DISCOVERY002_ASSESSMENT_PRESENT", family,
            )
            # Cells 34/36 inspected the RAW status. A valid Cell 26-normalized
            # spelling variant therefore carries their existing review label.
            # Preserve and check that producer behavior, without a new segment
            # or a stricter raw-string requirement on the Cell 26 parent.
            raw_canonical = F.col("d002_attribution_evidence_status").eqNullSafe(
                F.lit(no_signal)
            )
            expected_state = F.when(
                raw_canonical, F.lit(no_signal)
            ).otherwise(F.lit("ATTRIBUTION_STATUS_REQUIRES_REVIEW"))
            expected_reason = F.when(
                raw_canonical,
                F.lit("EXISTING_CERTIFIED_DISCOVERY002_ASSESSMENT_PRESERVED"),
            ).otherwise(F.lit("DISPOSITION_PRESENT_WITH_BLANK_OR_UNRECOGNIZED_STATUS"))
            reject(
                applicable,
                ~F.col(prefix + "qualification_state").eqNullSafe(expected_state)
                | ~F.col(prefix + "attribution_evidence_boundary_reason")
                .eqNullSafe(expected_reason),
                family + " annotations contradict the existing producer contract",
                [
                    "d002_attribution_evidence_status",
                    prefix + "qualification_state",
                    prefix + "attribution_evidence_boundary_reason",
                ],
            )
        else:
            known_network_states = [
                "NETWORK_ATTRIBUTION_EVIDENCE_UNAVAILABLE",
                "NO_CERTIFIED_OBSERVATION_LINK",
                "OBSERVATION_CONTEXT_INCOMPLETE",
                "CERTIFIED_NETWORK_REVIEW_CONTEXT",
                "INDEPENDENT_NETWORK_ATTRIBUTION_CONTEXT",
                "PARTIAL_INDEPENDENT_NETWORK_ATTRIBUTION_CONTEXT",
                "STRUCTURAL_OBSERVATION_CONTEXT_ONLY",
            ]
            reject(
                applicable, ~F.col("c32_qualification_state").isin(*known_network_states),
                "Unrecognized Cell 32 qualification", ["c32_qualification_state"],
            )
            boolean_field(parent, "c32_relationship_evaluation_performed", family)
            evaluated = F.col("c32_relationship_evaluation_performed")
            unavailable = "NETWORK_ATTRIBUTION_EVIDENCE_UNAVAILABLE"
            expected_boundary = F.when(
                evaluated, F.lit("AVAILABLE_FOR_CURRENT_RUN")
            ).otherwise(F.lit(unavailable))
            reject(
                applicable,
                evaluated.isNull()
                | ~F.col("c32_host_attribution_boundary_state")
                .eqNullSafe(expected_boundary)
                | ~F.col("c32_qualification_state").eqNullSafe(F.lit(unavailable))
                .eqNullSafe(~evaluated),
                "Cell 32 availability/evaluation meanings disagree",
                [
                    "c32_qualification_state",
                    "c32_host_attribution_boundary_state",
                    "c32_relationship_evaluation_performed",
                ],
            )

    # -----------------------------------------------------------------------
    # 4. Validate carried Intune qualification and the independent overlay.
    # -----------------------------------------------------------------------
    is_intune = F.col("source_family") == "INTUNE_ONLY"
    intune_class = F.col("c31_intune_qualification_class")
    history_member = F.col("c31_history_candidate")

    reject(
        parent.filter(is_intune), ~intune_class.isin(*child_gates),
        "Intune member lacks one recognized existing qualification",
        ["c31_intune_qualification_class"],
    )
    reject(
        parent.filter(~is_intune), intune_class.isNotNull(),
        "Cell 31 requires null Intune qualification outside INTUNE_ONLY",
        ["c31_intune_qualification_class"],
    )
    reject(parent, history_member.isNull(), "Null history membership")
    reject(
        parent.filter(~is_intune), history_member,
        "History membership outside the authorized Intune population",
        ["c31_history_candidate"],
    )
    expected_dependency = F.when(
        is_intune,
        F.when(history_member, F.lit(unresolved_history))
        .otherwise(F.lit(outside_history)),
    ).otherwise(F.lit(None).cast("string"))
    reject(
        parent,
        ~F.col("c31_history_dependency").eqNullSafe(expected_dependency),
        "Carried Cell 31 history dependency disagrees with its membership",
        ["c31_history_candidate", "c31_history_dependency"],
    )
    reject(
        parent,
        history_member & intune_class.isin(
            "INTUNE_SHARED_SERIAL_IDENTITY_REVIEW",
            "WINDOWS_EXISTING_MDE_CONTEXT",
        ),
        "Excluded Intune qualification entered the history overlay",
        ["c31_intune_qualification_class", "c31_history_candidate"],
    )
    # Cell 31 checked additional source-native existing-MDE flags. They are
    # not all carried in this parent. Do not claim to re-prove those flags,
    # reopen earlier runtime objects, or infer membership from platform.
    history_count = parent.filter(history_member).count()
    intune_rows = (
        parent.filter(is_intune)
        .groupBy("c31_intune_qualification_class")
        .agg(F.count(F.lit(1)).alias("asset_count"))
        .orderBy("c31_intune_qualification_class")
        .collect()
    )
    intune_count = parent.filter(is_intune).count()
    require(
        sum(int(row["asset_count"]) for row in intune_rows) == intune_count,
        "Exclusive Intune qualifications do not account for Intune membership.",
    )

    # -----------------------------------------------------------------------
    # 5. Add four fields. No inherited field or evidence dimension is replaced.
    # -----------------------------------------------------------------------
    mapping_items = []
    for qualification, gate in child_gates.items():
        mapping_items.extend([F.lit(qualification), F.lit(gate)])
    mapped_child = F.element_at(F.create_map(*mapping_items), intune_class)
    qualified_gate = F.when(is_intune, mapped_child).otherwise(
        F.col("qualification_next_gate")
    )
    continuation_basis = F.when(is_intune, F.lit(intune_basis)).otherwise(
        F.lit(parent_basis)
    )
    additive_columns = [
        "c38_parent_contract_state",
        "c38_qualified_continuation_gate",
        "c38_continuation_basis",
        "c38_customer_determination_state",
    ]
    treatment = (
        parent
        .withColumn("c38_parent_contract_state", F.lit("CELL26_PARENT_CONTRACT_VALIDATED"))
        .withColumn("c38_qualified_continuation_gate", qualified_gate)
        .withColumn("c38_continuation_basis", continuation_basis)
        .withColumn("c38_customer_determination_state", F.lit("NOT_YET_DETERMINED"))
        .select(*parent.columns, *additive_columns)
    )

    # -----------------------------------------------------------------------
    # 6. Certify conservation and exact authorized continuation assignment.
    # -----------------------------------------------------------------------
    ending = asset_count(treatment, "Cell 38 treatment")
    require(ending == starting, "Parent denominator changed.")
    require(
        treatment.columns == parent.columns + additive_columns
        and treatment.select(*parent.columns).schema == parent.schema,
        "Inherited schema changed or unexpected fields were added.",
    )
    same_assets(treatment, parent, "Parent membership")
    same_rows(treatment, parent, parent.columns, "All inherited parent evidence")
    same_rows(
        treatment.filter(F.col("c31_history_candidate")),
        parent.filter(F.col("c31_history_candidate")),
        ["asset_key", "c31_history_candidate", "c31_history_dependency"],
        "Exact history overlay",
    )
    exact(
        treatment, "c38_parent_contract_state",
        "CELL26_PARENT_CONTRACT_VALIDATED", "Output parent contract",
    )
    exact(
        treatment, "c38_customer_determination_state",
        "NOT_YET_DETERMINED", "Output customer state",
    )
    exact(treatment, "qualification_next_gate", umbrella, "Original umbrella")
    exact(
        treatment, "workload_promotion_state",
        "NOT_READY_FOR_CASE_FORMATION", "Inherited workload readiness",
    )
    reject(
        treatment,
        F.col("c38_qualified_continuation_gate").isNull()
        | ~F.col("c38_qualified_continuation_gate").eqNullSafe(qualified_gate)
        | ~F.col("c38_continuation_basis").eqNullSafe(continuation_basis),
        "Missing or unauthorized continuation/basis",
        ["c31_intune_qualification_class", *additive_columns],
    )
    # Neither expression selecting continuation/basis references history.
    # Original fields, including validation responsibility, remain unchanged.

    # -----------------------------------------------------------------------
    # 7. Exclusive analytical accounting and separate dependency cross-tab.
    # -----------------------------------------------------------------------
    summary_dimensions = [
        "qualification_next_gate", "source_family",
        "c31_intune_qualification_class", "c38_qualified_continuation_gate",
        "c38_continuation_basis", "c38_customer_determination_state",
        "workload_promotion_state",
    ]
    summary = (
        treatment.groupBy(*summary_dimensions)
        .agg(F.count(F.lit(1)).alias("asset_count"))
        .orderBy(*summary_dimensions)
    )
    history_dimensions = [
        "c38_qualified_continuation_gate",
        "c31_history_candidate", "c31_history_dependency",
    ]
    history_summary = (
        treatment.groupBy(*history_dimensions)
        .agg(F.count(F.lit(1)).alias("asset_count"))
        .withColumn(
            "c38_history_execution_state",
            F.when(
                F.col("c31_history_candidate")
                | (F.col("c38_qualified_continuation_gate") == history_gate),
                F.lit("PARKED"),
            ).otherwise(F.lit("NOT_APPLICABLE")),
        )
        .withColumn("c38_history_blocks_delivery", F.lit(False))
        .orderBy(*history_dimensions)
    )

    def total(df):
        value = df.agg(F.sum("asset_count").alias("total")).collect()[0]["total"]
        return 0 if value is None else int(value)

    require(total(summary) == starting, "Treatment summary denominator differs.")
    require(total(history_summary) == starting, "History cross-tab denominator differs.")
    require(
        total(history_summary.filter(F.col("c31_history_candidate"))) == history_count,
        "History cross-tab lost or added candidate members.",
    )
    same_rows(
        summary.groupBy("source_family").agg(
            F.sum("asset_count").alias("asset_count")
        ),
        membership, ["source_family", "asset_count"],
        "Treatment summary family accounting",
    )
    same_rows(
        summary.groupBy("c38_qualified_continuation_gate").agg(
            F.sum("asset_count").alias("asset_count")
        ),
        history_summary.groupBy("c38_qualified_continuation_gate").agg(
            F.sum("asset_count").alias("asset_count")
        ),
        ["c38_qualified_continuation_gate", "asset_count"],
        "Treatment/history continuation reconciliation",
    )
    exact(
        history_summary, "c38_history_blocks_delivery", False,
        "History delivery dependency",
    )

    # -----------------------------------------------------------------------
    # 8. Certification; historical expectations are display-only comparisons.
    # -----------------------------------------------------------------------
    print("RCAIP DIAG 001 - CELL 38 CERTIFICATION")
    print("Status: PASS - segmentation / treatment qualification only")
    print("Post / run / parent:", post_slug, run_id, parent_id)
    print("Starting / preserved parent assets:", starting, ending)
    print("Cell 37 complete / next family / next count:", True, None, 0)
    print("Next-family DataFrame: empty, exact parent schema")
    print("Cell 26 exact and normalized parent invariants: PASS")
    print("Applicable source annotations / carried history contract: PASS")
    print("Family counts / source masks / completed unselected states: PASS")
    print("Every inherited column and exact asset membership preserved: YES")
    print("Intune assets / exclusive qualification total:", intune_count, intune_count)
    print("History overlay assets (overlapping, never added to parent):", history_count)
    print("Treatment summary / history cross-tab totals:", total(summary), total(history_summary))
    print("History execution / delivery effect: PARKED / NONBLOCKING")
    print("Customer determination:", "NOT_YET_DETERMINED")
    print("Workload state:", "NOT_READY_FOR_CASE_FORMATION")
    print("Lookup/corroboration performed / attribution closed: NO / NO")
    print("Explicit source access / new evidence / durable output: NONE")
    print("Routing / workload / cases / findings / tickets / remediation: NONE")
    print("Sibling cohorts consumed: NONE")
    print("Next parent gate:", umbrella)
    print("Would this exact Cell 38 logic run for Paris? YES")

    actual_families = {row["source_family"]: int(row["asset_count"]) for row in family_rows}
    actual_intune = {
        row["c31_intune_qualification_class"]: int(row["asset_count"])
        for row in intune_rows
    }
    print("Actual runtime family counts:", actual_families)
    print("Actual runtime exclusive Intune counts:", actual_intune)
    print("Actual runtime treatment accounting:")
    for row in summary.collect():
        print(row.asDict(recursive=True))
    print("Actual runtime history dependency cross-tab:")
    for row in history_summary.collect():
        print(row.asDict(recursive=True))

    # These literals are used ONLY in this reporting section. They cannot
    # affect input checks, continuation assignment, outputs, or readiness.
    comparisons = [
        ("parent", starting, 1989),
        ("history overlay", history_count, 592),
    ]
    recorded_families = {
        "INTUNE_ONLY": 595, "NMAP_ONLY": 702,
        "NMAP_MULTI_SOURCE": 677, "TENABLE_ONLY": 15,
    }
    recorded_intune = {
        "INTUNE_IOS_IPADOS_MANAGED_MOBILE_CONTEXT": 447,
        "WINDOWS_HISTORICAL_MDE_RECONCILIATION_CANDIDATE": 145,
        "WINDOWS_EXISTING_MDE_CONTEXT": 1,
        "INTUNE_SHARED_SERIAL_IDENTITY_REVIEW": 2,
    }
    comparisons.extend(
        ("family " + name, actual_families.get(name, 0), expected)
        for name, expected in recorded_families.items()
    )
    comparisons.extend(
        ("Intune " + name, actual_intune.get(name, 0), expected)
        for name, expected in recorded_intune.items()
    )
    print("Recorded example_post_a comparisons ONLY; delta is not a certification predicate:")
    for label, actual, expected in comparisons:
        print(label, "actual=", actual, "recorded=", expected, "delta=", actual - expected)
    print("Other runtime families:",
          sorted(set(actual_families) - set(recorded_families)))
    print("Other runtime Intune qualifications:",
          sorted(set(actual_intune) - set(recorded_intune)))
    print("Historical wider branch / siblings (not consumed or certified):", 2803, 501, 313)

    return {
        "RCAIP_DIAG001_CELL38_POST_SLUG": post_slug,
        "RCAIP_DIAG001_CELL38_RUN_ID": run_id,
        "RCAIP_DIAG001_CELL38_PARENT_COHORT_ID": parent_id,
        "RCAIP_DIAG001_CELL38_PARENT_ASSET_COUNT": starting,
        "RCAIP_DIAG001_CELL38_TREATMENT_DF": treatment,
        "RCAIP_DIAG001_CELL38_TREATMENT_SUMMARY_DF": summary,
        "RCAIP_DIAG001_CELL38_HISTORY_DEPENDENCY_SUMMARY_DF": history_summary,
        "RCAIP_DIAG001_CELL38_NEXT_GATE": umbrella,
    }


_c38_publications = _build_cell38()
globals().update(_c38_publications)
RCAIP_DIAG001_CELL38_READY = True
del _c38_publications
del _build_cell38
